INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_360_breathing', '360-breathing', '360 Breathing', '360 ademhaling', 'mobility', '["diaphragm","pelvic_floor","intercostals"]', NULL, '["pelvic_floor","breathing","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit with hands on ribcage, thumbs at back","Inhale: feel ribs expand in all directions — front, sides, back","Exhale: ribs draw in, pelvic floor gently lifts","Do 8 slow breaths"],"cues":["Think of breathing into your whole torso","Back ribs expanding is the key sensation","Calming for third trimester breathlessness"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Ga zitten met je handen op je ribbenkast, duimen aan de achterkant","Adem in: voel je ribben alle kanten op uitzetten — voor, opzij en achter","Adem uit: je ribben trekken naar binnen, je bekkenbodem tilt zachtjes op","Doe 8 langzame ademhalingen"],"cues_nl":["Adem als het ware in je hele romp","Voel vooral je achterste ribben uitzetten","Werkt kalmerend bij kortademigheid in het derde trimester"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["exhalation-core-engagement","pelvic-floor-breathing","inner-thigh-squeeze","kegel-elevator","kegel-hold"]}', 1, 1742860800000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_4_7_8_breathing', '4-7-8-breathing', '4-7-8 Breathing', NULL, 'recovery', '["diaphragm","nervous_system"]', NULL, '["breathing","recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit comfortably, tip of tongue behind upper front teeth","Exhale completely through the mouth","Close mouth and inhale through nose for 4 counts","Hold breath for 7 counts","Exhale through mouth for 8 counts","This is one cycle — repeat 4 times"],"cues":["Powerful nervous system reset","May feel dizzy at first — reduce hold to 4-4-6","Excellent before sleep"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery"}', NULL, '{"supports":["reps","time"]}', NULL, 0, 1742860800000, 1793483543000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_5_senses_grounding', '5-senses-grounding', '5 Senses Grounding', 'Gronding met 5 zintuigen', 'recovery', '["nervous_system"]', NULL, '["recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit or stand comfortably and name 5 things you can see","Notice 4 things you can physically feel","Listen for 3 things you can hear","Notice 2 things you can smell","Notice 1 thing you can taste","Finish with one long slow breath"],"cues":["Also called 5-4-3-2-1 grounding","Brings you back to the present moment","Can help when you feel anxious during pregnancy"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga comfortabel zitten of staan en benoem 5 dingen die je ziet","Merk 4 dingen op die je lichamelijk voelt","Luister naar 3 dingen die je hoort","Merk 2 dingen op die je ruikt","Merk 1 ding op dat je proeft","Sluit af met één lange, langzame ademhaling"],"cues_nl":["Ook wel 5-4-3-2-1-gronding genoemd","Brengt je terug naar het hier en nu","Kan helpen als je je angstig voelt tijdens de zwangerschap"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["supported-side-lying-rest","eye-palming","gratitude-reflection","savasana"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_alternate_nostril', 'alternate-nostril-breathing', 'Alternate Nostril Breathing', 'Wisselende neusgatademhaling', 'recovery', '["diaphragm","nervous_system"]', NULL, '["breathing","recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit comfortably and raise your right hand to your face","Close your right nostril with your right thumb and inhale through the left","Close your left nostril with your ring finger, release your thumb and exhale through the right","Inhale through the right nostril","Close the right nostril, release the left and exhale through the left","That is one cycle — repeat 5–10 times, then lower your hand and breathe normally"],"cues":["Keep the breath slow and even on both sides","Many people find it calming and good for focus","Avoid retention (holding) during pregnancy"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga comfortabel zitten en breng je rechterhand naar je gezicht","Sluit je rechterneusgat met je rechterduim en adem in door links","Sluit je linkerneusgat met je ringvinger, laat je duim los en adem uit door rechts","Adem in door je rechterneusgat","Sluit rechts, laat links los en adem uit door links","Dat is één cyclus — herhaal 5–10 keer, laat dan je hand zakken en adem gewoon door"],"cues_nl":["Houd je adem aan beide kanten rustig en gelijkmatig","Veel mensen worden er rustig en geconcentreerd van","Houd je adem niet vast tijdens de zwangerschap"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["478-breathing","breath-counting","cooling-breath","humming-bee-breath","labour-breathing-prep"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_ankle_mobility', 'ankle-mobility-circles', 'Ankle Mobility Circles', 'Enkelcirkels', 'mobility', '["ankles","calves","tibialis_anterior"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_ankle"]', '["none"]', NULL, '{"steps":["Sit or stand, lift one foot off the floor","Draw large circles with your foot clockwise 10 times","Reverse 10 times","Switch feet"],"cues":["Point and flex through the full range","Helps with pregnancy swelling and circulation","Also do toe spells (trace letters with toes) for variety"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Ga zitten of staan en til één voet van de vloer.","Maak 10 keer grote cirkels met je voet, met de klok mee.","Draai 10 keer de andere kant op.","Wissel van voet."],"cues_nl":["Strek en buig je voet door de volle bewegingsuitslag.","Helpt bij vocht vasthouden en doorbloeding tijdens de zwangerschap.","Schrijf voor de afwisseling ook letters met je tenen."]}', '{"images":["/exercise-media/ankle-mobility-circles/0.jpg","/exercise-media/ankle-mobility-circles/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","time"]}', '{"substitutions": ["calf-stretch-wall", "foam-roll-calves"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_ankle_pumps', 'ankle-pumps', 'Ankle Pumps', 'Enkelpompen', 'recovery', '["calves","ankles","tibialis_anterior"]', NULL, '["recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_ankle"]', '["none"]', NULL, '{"steps":["Sit or lie with legs extended, or elevate feet on a pillow","Flex feet — pull toes toward you","Point feet — push toes away","Alternate in steady rhythm, 20 to 30 pumps","Then do ankle circles in each direction"],"cues":["Stimulates the calf muscle pump","Essential during pregnancy to prevent DVT","Do this every 30 to 60 minutes when sitting for long periods"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga zitten of liggen met gestrekte benen, of leg je voeten omhoog op een kussen","Buig je voeten — trek je tenen naar je toe","Strek je voeten — duw je tenen van je af","Wissel af in een rustig ritme, 20 tot 30 keer","Draai daarna met je enkels cirkels in beide richtingen"],"cues_nl":["Zet de kuitspierpomp aan het werk","Onmisbaar tijdens de zwangerschap om trombose te voorkomen","Doe dit elke 30 tot 60 minuten als je lang zit"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["calf-stretch-wall","self-massage-feet"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_breath_counting', 'breath-counting', 'Breath Counting', 'Ademhalingen tellen', 'recovery', '["diaphragm","nervous_system"]', NULL, '["breathing","recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit comfortably, eyes closed","Breathe naturally — don''t control it","Count each exhale from 1 to 10","When you reach 10, start again from 1","If you lose count, simply begin at 1 again"],"cues":["A simple mindfulness anchor","Losing count is normal — just restart without judgment","5 minutes is plenty"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga comfortabel zitten met je ogen dicht","Adem vanzelf — stuur je adem niet","Tel elke uitademing, van 1 tot 10","Ben je bij 10, begin dan weer bij 1","Raak je de tel kwijt, begin dan gewoon weer bij 1"],"cues_nl":["Een eenvoudig anker voor je aandacht","De tel kwijtraken is normaal — begin opnieuw, zonder oordeel","5 minuten is ruim voldoende"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["478-breathing","alternate-nostril-breathing"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_cat_cow_pregnancy', 'cat-cow-pregnancy', 'Cat-Cow (Pregnancy-Friendly)', 'Kat-koe (zwangerschap)', 'mobility', '["spine","lower_back","core","pelvic_floor"]', NULL, '["bodyweight","floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","pelvic_floor","loads_lower_back"]', '["none"]', NULL, '{"steps":["Start on all fours with your wrists under your shoulders and your knees under your hips","Inhale: gently let belly drop, lift tailbone and head (Cow)","Exhale: round spine gently toward ceiling, tuck chin and tailbone (Cat)","Move slowly and deliberately, following your breath"],"cues":["Much gentler version — do not overdo the arch","On all fours is comfortable for the belly","Syncing breath with movement calms the nervous system"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Begin op handen en knieën met je polsen onder je schouders en je knieën onder je heupen","Adem in: laat je buik rustig zakken en til je stuitje en hoofd op (koe)","Adem uit: maak je rug rustig bol richting het plafond en trek je kin en stuitje in (kat)","Beweeg langzaam en bewust, op het ritme van je ademhaling"],"cues_nl":["Een veel zachtere versie — maak je rug niet te hol","Op handen en knieën is comfortabel voor je buik","Ademhaling en beweging op elkaar afstemmen kalmeert je zenuwstelsel"]}', '{"images":["/exercise-media/cat-cow-pregnancy/0.jpg","/exercise-media/cat-cow-pregnancy/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","time"]}', '{"substitutions":["cat-cow-flow","seated-pelvic-roll","standing-pelvic-rock"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_chest_opener', 'chest-opener-arms', 'Chest Opener', 'Borstopener', 'mobility', '["chest","anterior_deltoids","biceps"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","sport_support:swimming","sport_mobility:cycling","sport_mobility:swimming","sport_mobility:crossfit","loads_shoulder"]', '["none"]', NULL, '{"steps":["Stand tall with your feet hip-width apart","Interlace your fingers behind your back (or hold a strap or towel)","Gently squeeze your shoulder blades together","Lift your arms slightly and open your chest upward","Hold for 20–30 seconds while breathing deeply, then lower your arms"],"cues":["Don''t hyperextend neck","Feel the front of chest and shoulders stretch","Perfect for counteracting rounded posture"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Sta rechtop met je voeten op heupbreedte","Vouw je vingers achter je rug in elkaar (of houd een band of handdoek vast)","Knijp je schouderbladen zachtjes samen","Til je armen iets op en open je borst naar boven","Houd 20–30 seconden vast en adem diep, laat dan je armen zakken"],"cues_nl":["Trek je nek niet te ver naar achteren.","Voel de rek aan de voorkant van je borst en schouders.","Perfect tegen een ronde houding."]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["shoulder-circles-active","foam-roll-lats","wall-chest-stretch"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_clamshell', 'clamshell', 'Clamshell', 'Clamshell', 'mobility', '["glutes","hip_abductors","pelvic_floor"]', NULL, '["pelvic_floor","floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Lie on your side with your hips stacked and your knees bent to 45°","Keep your feet together","Rotate your top knee upward like a clamshell opening","Hold for 2 seconds at the top","Lower slowly and do 12 reps on each side"],"cues":["Don''t let hips roll back","Think of leading with your knee","Strengthens hips and pelvic stability"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Lig op je zij met je heupen recht boven elkaar en je knieën 45° gebogen","Houd je voeten tegen elkaar","Draai je bovenste knie omhoog, zoals een schelp die opengaat","Houd bovenaan 2 seconden vast","Zak langzaam terug en doe 12 herhalingen per kant"],"cues_nl":["Laat je heupen niet naar achteren rollen","Laat je knie de beweging leiden","Versterkt je heupen en de stabiliteit van je bekken"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["side-lying-hip-abduction","supported-glute-bridge"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_cobra_press_up', 'cobra-press-up', 'Cobra Press-up', 'Cobra', 'strength', '["lower_back","glutes","core"]', NULL, '["bodyweight","floor","low_impact","prone","loads_shoulder","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie face down with your hands under your shoulders","Press through your hands to lift your chest off the floor","Keep your pelvis on the floor","Hold for 1–2 seconds","Lower slowly"],"cues":["Squeeze glutes at top","Only go as high as comfortable","Strengthens posterior chain"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Ga op je buik liggen met je handen onder je schouders","Duw door je handen om je borst van de vloer te tillen","Houd je bekken op de vloer","Houd 1–2 seconden vast","Zak langzaam"],"cues_nl":["Span bovenin je bilspieren aan","Ga alleen zo hoog als prettig voelt","Versterkt de achterkant van je lichaam"]}', NULL, '{"supports":["reps","sets","time"]}', '{"substitutions":["bird-dog","donkey-kick"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_cooling_breath', 'cooling-breath', 'Cooling Breath (Sitali)', 'Verkoelende ademhaling (Sitali)', 'recovery', '["diaphragm","nervous_system"]', NULL, '["breathing","recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit comfortably","Roll the tongue into a tube (or if you can''t, teeth slightly apart, tongue behind)","Inhale through the rolled/open tongue — feel the cool air","Close mouth and exhale through the nose","Repeat 6–10 times"],"cues":["Genuinely cooling — good in hot weather or nausea","Works even without tongue rolling","Helps with pregnancy overheating"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga comfortabel zitten","Rol je tong tot een buisje (lukt dat niet: tanden iets van elkaar, tong erachter)","Adem in door je gerolde tong of open mond — voel de koele lucht","Sluit je mond en adem uit door je neus","Herhaal 6–10 keer"],"cues_nl":["Werkt echt verkoelend — fijn bij warm weer of misselijkheid","Werkt ook als je je tong niet kunt rollen","Helpt als je het tijdens de zwangerschap snel te warm hebt"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["478-breathing","alternate-nostril-breathing"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_shoulder_cross_body', 'cross-body-shoulder-stretch', 'Cross-Body Shoulder Stretch', 'Schouderstretch (arm over borst)', 'mobility', '["rear_deltoids","rotator_cuff"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","sport_support:swimming","sport_mobility:swimming","loads_shoulder"]', '["none"]', NULL, '{"steps":["Stand tall with your arms relaxed at your sides","Bring your right arm straight across your chest","Use your left hand or forearm to gently press your right arm closer to your chest","Hold the stretch for 20–30 seconds","Release your arm and repeat on the other side"],"cues":["Keep shoulder down, away from ear","Don''t rotate — stay square","Good for carrying-related shoulder tension"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Sta rechtop met je armen ontspannen langs je lichaam","Breng je rechterarm gestrekt voor je borst langs","Duw je rechterarm met je linkerhand of linkeronderarm zachtjes dichter naar je borst","Houd de rek 20–30 seconden vast","Laat je arm los en herhaal aan de andere kant"],"cues_nl":["Houd je schouder laag, weg van je oor","Niet meedraaien — blijf recht naar voren staan","Goed tegen schouderspanning door veel tillen en dragen"]}', '{"images":["/exercise-media/cross-body-shoulder-stretch/0.jpg","/exercise-media/cross-body-shoulder-stretch/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["shoulder-roll-stretch","thread-the-needle"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_curtsy_lunge', 'curtsy-lunge', 'Curtsy Lunge', 'Kruislingse uitvalspas (curtsy)', 'strength', '["glutes","quadriceps","adductors"]', NULL, '["bodyweight","no_floor","low_impact","loads_knee","loads_knee"]', '["none"]', NULL, '{"steps":["Stand with your feet hip-width apart","Step your right foot behind you and across to the left","Bend both knees to lower into a lunge","Push back up to the start position","Alternate sides"],"cues":["Keep front knee stable","Great glute med target","Modify by reducing depth"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Sta met je voeten op heupbreedte","Stap met je rechtervoet schuin naar achteren, kruislings achter je linkerbeen","Buig beide knieën en zak in een uitvalspas","Duw jezelf terug naar de beginpositie","Wissel van kant"],"cues_nl":["Houd je voorste knie stabiel","Pakt de gluteus medius goed aan","Maak het lichter door minder diep te gaan"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["dumbbell-side-lunge","lateral-lunge"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_transverse_activation', 'deep-core-activation', 'Deep Core Activation', 'Diepe core-activatie', 'mobility', '["transverse_abdominis","pelvic_floor"]', NULL, '["pelvic_floor","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit or stand tall with your shoulders relaxed","Place your fingertips just inside your hip bones","Exhale slowly and feel the muscle under your fingers gently tighten (do not suck in or push out)","Hold this gentle engagement for 5 breaths","Release completely, then repeat"],"cues":["Imagine zipping up low-rise jeans very gently","Don''t hold breath","Foundation exercise for all postnatal core work"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Zit of sta rechtop met ontspannen schouders","Leg je vingertoppen net aan de binnenkant van je heupbotten","Adem langzaam uit en voel de spier onder je vingers zachtjes aanspannen (niet intrekken, niet naar buiten duwen)","Houd die lichte spanning 5 ademhalingen vast","Laat helemaal los en herhaal"],"cues_nl":["Stel je voor dat je heel voorzichtig een laag uitgesneden spijkerbroek dichtritst","Houd je adem niet in","De basisoefening voor alle core-training na de bevalling"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["supported-glute-bridge","exhalation-core-engagement"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_donkey_kick', 'donkey-kick', 'Donkey Kick', 'Donkey kick', 'strength', '["glutes","hamstrings","core"]', NULL, '["bodyweight","floor","low_impact","quiet","pregnancy_safe","postnatal_safe","sport_support:running","loads_shoulder"]', '["none"]', NULL, '{"steps":["Start on all fours with your wrists under your shoulders and your knees under your hips","Keep right knee bent 90°","Kick right foot toward ceiling, squeezing glute at top","Lower without touching floor","Do 15 reps on each side"],"cues":["Hips stay square — don''t twist","Drive heel toward ceiling","All-fours position great for pregnancy belly"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Begin op handen en knieën, polsen onder je schouders, knieën onder je heupen","Houd je rechterknie in 90° gebogen.","Trap je rechtervoet richting het plafond en span bovenin je bilspier aan.","Zak zonder de vloer te raken.","Doe 15 herhalingen per kant"],"cues_nl":["Houd je heupen recht: niet draaien.","Duw je hiel naar het plafond.","Op handen en knieën is ideaal met een zwangerschapsbuik."]}', '{"images":["/exercise-media/donkey-kick/0.jpg","/exercise-media/donkey-kick/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions":["fire-hydrant","modified-plank"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_db_farmers_walk', 'dumbbell-farmers-walk', 'Dumbbell Farmers Walk', 'Dumbbell farmer''s walk', 'strength', '["forearms","traps","core","legs"]', NULL, '["dumbbell","no_floor","low_impact","loads_shoulder","loads_knee","loads_lower_back","loads_ankle"]', '["dumbbell"]', NULL, '{"steps":["Hold a heavy dumbbell in each hand at your sides","Walk steadily for distance or time","Keep your chest tall and your shoulders back and down","Take short, controlled steps, then set the dumbbells down to finish"],"cues":["Don''t let weights pull shoulders down","Great grip + full-body challenge","Adapt to walking in place if space is limited"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Houd in elke hand een zware dumbbell langs je zij","Loop rustig door voor de afstand of de tijd","Houd je borst omhoog en je schouders naar achteren en omlaag","Maak korte, gecontroleerde passen en zet de dumbbells aan het eind neer"],"cues_nl":["Laat de gewichten je schouders niet omlaag trekken","Sterke uitdaging voor je grip en je hele lichaam","Loop op de plaats als je weinig ruimte hebt"]}', NULL, '{"supports":["time","reps","weight"],"load_type":"dumbbell_single"}', '{"substitutions":["dumbbell-suitcase-carry","kettlebell-farmers-carry"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_db_front_raise', 'dumbbell-front-raise', 'Dumbbell Front Raise', 'Dumbbell voorwaarts heffen', 'strength', '["anterior_deltoids","upper_chest"]', NULL, '["dumbbell","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_shoulder","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Stand holding the dumbbells in front of your thighs, palms facing down","Raise both arms to shoulder height","Hold for 1 second","Lower slowly"],"cues":["Keep a slight elbow bend","Don''t swing — control the weight","Alternative: one arm at a time"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta rechtop met de dumbbells voor je bovenbenen, handpalmen naar beneden","Til beide armen tot schouderhoogte","Houd 1 seconde vast","Laat langzaam zakken"],"cues_nl":["Houd je ellebogen licht gebogen","Niet zwaaien — houd het gewicht onder controle","Alternatief: één arm tegelijk"]}', '{"images":["/exercise-media/dumbbell-front-raise/0.jpg","/exercise-media/dumbbell-front-raise/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions":["dumbbell-lateral-raise","dumbbell-incline-chest-press"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_db_hammer_curl', 'dumbbell-hammer-curl', 'Dumbbell Hammer Curl', 'Dumbbell hammer curl', 'strength', '["biceps","brachioradialis","forearms"]', NULL, '["dumbbell","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Stand or sit with a dumbbell in each hand at your sides, palms facing each other (neutral grip)","Curl the weights to your shoulders","Squeeze your biceps at the top","Lower slowly"],"cues":["Neutral grip = thumbs up","Targets outer bicep head","Keep elbows fixed at sides"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta of zit met in elke hand een dumbbell langs je zij, handpalmen naar elkaar toe (neutrale greep)","Curl de gewichten naar je schouders","Span bovenin je biceps aan","Laat langzaam zakken"],"cues_nl":["Neutrale greep = duimen omhoog","Traint de buitenste kop van je biceps","Houd je ellebogen vast tegen je zij"]}', '{"images":["/exercise-media/dumbbell-hammer-curl/0.jpg","/exercise-media/dumbbell-hammer-curl/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions": ["dumbbell-concentration-curl", "dumbbell-reverse-curl", "band-bicep-curl"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_dumbbell_chest_press_incline', 'dumbbell-incline-chest-press', 'Dumbbell Incline Chest Press', 'Dumbbell chest press op schuine bank', 'strength', '["upper_chest","anterior_deltoids","triceps"]', NULL, '["dumbbell","floor","low_impact","loads_shoulder","loads_shoulder"]', '["dumbbell","chair"]', NULL, '{"steps":["Sit at an incline (on sofa arm, against wall, or on inclined surface)","Hold dumbbells at chest height, palms forward","Press dumbbells up and slightly in until arms nearly straight","Lower slowly to start"],"cues":["Incline targets upper chest","More comfortable than flat press for many people","Avoid flat supine press after 16 weeks pregnancy"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga schuin achterover zitten (op de armleuning van de bank, tegen een muur of op een schuin oppervlak)","Houd de dumbbells op borsthoogte, handpalmen naar voren","Druk de dumbbells omhoog en iets naar binnen tot je armen bijna gestrekt zijn","Laat langzaam zakken naar de beginpositie"],"cues_nl":["Schuin drukken traint het bovenste deel van je borst","Voor veel mensen prettiger dan plat drukken","Druk na 16 weken zwangerschap niet meer plat op je rug"]}', '{"images":["/exercise-media/dumbbell-incline-chest-press/0.jpg","/exercise-media/dumbbell-incline-chest-press/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions": ["dumbbell-floor-chest-fly", "dumbbell-chest-press-floor"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_db_lunge', 'dumbbell-lunge', 'Dumbbell Lunge', 'Dumbbell uitvalspas', 'strength', '["quadriceps","glutes","hamstrings"]', NULL, '["dumbbell","no_floor","low_impact","loads_knee","loads_knee"]', '["dumbbell"]', NULL, '{"steps":["Stand holding dumbbells at sides","Step forward with right foot, lower back knee toward floor","Push through front foot to return","Alternate legs"],"cues":["Keep front knee over ankle","Stay upright","Dumbbells add load to bodyweight lunge"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta rechtop met dumbbells langs je zij","Stap met je rechtervoet naar voren en laat je achterste knie richting de vloer zakken","Duw door je voorste voet om terug te komen","Wissel van been"],"cues_nl":["Houd je voorste knie boven je enkel","Blijf rechtop","De dumbbells maken de uitvalspas zwaarder dan met alleen lichaamsgewicht"]}', '{"images":["/exercise-media/dumbbell-lunge/0.jpg","/exercise-media/dumbbell-lunge/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions": ["walking-lunge", "dumbbell-bulgarian-split-squat", "dumbbell-side-lunge"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_db_overhead_tricep_ext', 'dumbbell-overhead-tricep-ext', 'Dumbbell Overhead Tricep Extension', 'Dumbbell triceps extensie boven hoofd', 'strength', '["triceps"]', NULL, '["dumbbell","no_floor","low_impact","quiet","pregnancy_safe","postnatal_safe","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Hold one dumbbell with both hands overhead","Bend elbows to lower dumbbell behind head","Extend arms to return","Keep elbows pointing forward"],"cues":["Elbows stay close to head","Control the descent","Keep core braced"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Houd één dumbbell met beide handen boven je hoofd","Buig je ellebogen en laat de dumbbell achter je hoofd zakken","Strek je armen om terug te komen","Houd je ellebogen naar voren gericht"],"cues_nl":["Je ellebogen blijven dicht bij je hoofd","Zak gecontroleerd","Houd je core aangespannen"]}', '{"images":["/exercise-media/dumbbell-overhead-tricep-ext/0.jpg","/exercise-media/dumbbell-overhead-tricep-ext/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions":["knee-push-up","wall-push-up"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_db_rear_delt_fly', 'dumbbell-rear-delt-fly', 'Dumbbell Rear Delt Fly', 'Dumbbell rear delt fly', 'strength', '["rear_deltoids","rhomboids","traps"]', NULL, '["dumbbell","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_shoulder","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Hold a dumbbell in each hand and hinge forward at the hips to 45°, or sit and hinge over your thighs","Let your arms hang straight down with a slight bend in the elbows","Raise your arms out to the sides to shoulder height","Squeeze your shoulder blades together at the top","Lower the dumbbells slowly to the start"],"cues":["Lead with elbows","Light weight — this is harder than it looks","Great for counteracting forward shoulder roll in pregnancy"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Pak in elke hand een dumbbell en scharnier vanuit je heupen 45° naar voren, of ga zitten en buig over je bovenbenen","Laat je armen recht naar beneden hangen met licht gebogen ellebogen","Til je armen zijwaarts op tot schouderhoogte","Knijp bovenin je schouderbladen samen","Laat de dumbbells langzaam terugzakken naar de start"],"cues_nl":["Leid met je ellebogen","Licht gewicht — dit is zwaarder dan het lijkt","Goed tegenwicht voor schouders die tijdens de zwangerschap naar voren trekken"]}', '{"images":["/exercise-media/dumbbell-rear-delt-fly/0.jpg","/exercise-media/dumbbell-rear-delt-fly/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions": ["band-pull-apart", "band-face-pull"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_db_romanian_dl', 'dumbbell-romanian-deadlift', 'Dumbbell Romanian Deadlift', 'Dumbbell Romanian deadlift', 'strength', '["hamstrings","glutes","lower_back"]', NULL, '["dumbbell","no_floor","low_impact","pregnancy_safe","loads_lower_back","sport_support:running","sport_support:rowing","sport_support:football","loads_lower_back","loads_knee"]', '["dumbbell"]', NULL, '{"steps":["Stand tall holding the dumbbells in front of your thighs, palms facing you","Hinge at the hips, sending them back, and lower the weights along your legs","Stop when you feel a stretch in your hamstrings (shin level for most)","Drive your hips forward to stand up and squeeze your glutes at the top"],"cues":["Keep dumbbells close to legs","Neutral spine throughout","Lighter load appropriate during pregnancy"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta rechtop met de dumbbells voor je bovenbenen, handpalmen naar je toe","Scharnier vanuit je heupen, duw ze naar achteren en laat de gewichten langs je benen zakken","Stop zodra je rek voelt in je hamstrings (voor de meesten op scheenhoogte)","Duw je heupen naar voren om rechtop te komen en span bovenin je bilspieren aan"],"cues_nl":["Houd de dumbbells dicht bij je benen","Houd je rug de hele beweging neutraal","Kies tijdens de zwangerschap een lichter gewicht"]}', '{"images":["/exercise-media/dumbbell-romanian-deadlift/0.jpg","/exercise-media/dumbbell-romanian-deadlift/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions": ["dumbbell-single-leg-rdl", "kettlebell-swing", "kettlebell-single-leg-rdl", "kettlebell-deadlift", "nordic-hamstring-curl"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_db_seated_press', 'dumbbell-seated-overhead-press', 'Dumbbell Seated Overhead Press', 'Dumbbell schouderpress zittend', 'strength', '["shoulders","triceps"]', NULL, '["dumbbell","no_floor","low_impact","quiet","pregnancy_safe","postnatal_safe","loads_shoulder","loads_shoulder"]', '["dumbbell","chair"]', NULL, '{"steps":["Sit upright on a sturdy chair, dumbbells at shoulder height, palms forward","Press dumbbells overhead until arms nearly straight","Lower with control"],"cues":["Sitting removes lower back strain","Don''t arch back at the top","Safe alternative to standing press during pregnancy"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga rechtop op een stevige stoel zitten met de dumbbells op schouderhoogte, handpalmen naar voren","Druk de dumbbells boven je hoofd tot je armen bijna gestrekt zijn","Laat gecontroleerd zakken"],"cues_nl":["Zittend ontlast je je onderrug","Maak bovenin geen holle rug","Veilig alternatief voor de staande press tijdens de zwangerschap"]}', '{"images":["/exercise-media/dumbbell-seated-overhead-press/0.jpg","/exercise-media/dumbbell-seated-overhead-press/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions": ["dumbbell-arnold-press", "band-overhead-press"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_db_shrug', 'dumbbell-shrug', 'Dumbbell Shrug', 'Dumbbell shrug', 'strength', '["traps","neck"]', NULL, '["dumbbell","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Stand holding dumbbells at sides","Elevate shoulders straight up toward ears","Hold 1 second at top","Lower slowly"],"cues":["Don''t roll shoulders — straight up and down","Squeeze traps at top","Helps with upper back tension from carrying"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta rechtop met de dumbbells langs je lichaam","Trek je schouders recht omhoog richting je oren","Houd bovenin 1 seconde vast","Laat langzaam zakken"],"cues_nl":["Rol niet met je schouders — recht omhoog en omlaag","Span bovenin je monnikskapspier aan","Helpt bij spanning in je bovenrug door tillen en dragen"]}', '{"images":["/exercise-media/dumbbell-shrug/0.jpg","/exercise-media/dumbbell-shrug/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions": ["dumbbell-upright-row", "high-pull"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_db_sumo_deadlift', 'dumbbell-sumo-deadlift', 'Dumbbell Sumo Deadlift', 'Dumbbell sumo deadlift', 'strength', '["adductors","glutes","hamstrings","quadriceps"]', NULL, '["dumbbell","no_floor","low_impact","pregnancy_safe","loads_lower_back","loads_lower_back","loads_knee"]', '["dumbbell"]', NULL, '{"steps":["Stand with your feet wide and toes turned out 45°, holding one dumbbell vertically between your legs","Hinge at the hips and bend your knees to lower the weight toward the floor","Drive through your heels and hips to stand up","Squeeze your glutes at the top"],"cues":["Keeps weight between legs — great for pregnancy","Chest stays tall","Sumo stance gives belly room"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta met je voeten wijd en je tenen 45° naar buiten, en houd één dumbbell verticaal tussen je benen","Scharnier vanuit je heupen en buig je knieën om het gewicht richting de vloer te laten zakken","Duw via je hielen en heupen omhoog tot je staat","Span bovenin je bilspieren aan"],"cues_nl":["Het gewicht blijft tussen je benen — fijn tijdens de zwangerschap","Houd je borst omhoog","De sumostand geeft je buik de ruimte"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions":["dumbbell-goblet-squat","glute-bridge"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_db_wood_chop', 'dumbbell-wood-chop', 'Dumbbell Wood Chop', 'Dumbbell wood chop', 'strength', '["obliques","core","shoulders"]', NULL, '["dumbbell","no_floor","low_impact","loads_lower_back","loads_lower_back","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Stand and hold one dumbbell with both hands at shoulder height on your right side","Rotate and pull the weight diagonally down to your left hip","Return to the start","Complete all reps, then switch sides"],"cues":["Rotate through torso","Keep hips stable","Avoid after first trimester — rotational load on core"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga staan en houd één dumbbell met beide handen op schouderhoogte aan je rechterkant","Draai en trek het gewicht diagonaal omlaag naar je linkerheup","Kom terug naar de start","Doe alle herhalingen en wissel dan van kant"],"cues_nl":["Draai vanuit je romp","Houd je heupen stabiel","Niet doen na het eerste trimester — draaibelasting op je core"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions":["dumbbell-suitcase-carry","modified-plank"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_exhalation_core', 'exhalation-core-engagement', 'Exhalation Core Engagement', 'Core aanspannen bij uitademing', 'mobility', '["transverse_abdominis","pelvic_floor","intercostals"]', NULL, '["pelvic_floor","breathing","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit or stand in a comfortable, upright position","Take a natural breath in","As you exhale slowly through pursed lips, feel your lower belly gently drawing inward","Add a light pelvic floor lift on the exhale","Repeat for 8–10 breaths"],"cues":["Exhale should be 4–6 seconds","Don''t force — let exhale do the work","The exhale IS the core exercise"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Ga comfortabel rechtop zitten of staan","Adem rustig in.","Adem langzaam uit door getuite lippen en voel je onderbuik zachtjes naar binnen trekken.","Til bij de uitademing je bekkenbodem licht op.","Herhaal 8–10 ademhalingen."],"cues_nl":["Je uitademing duurt 4–6 seconden.","Niet forceren: laat de uitademing het werk doen.","De uitademing ÍS de core-oefening."]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["360-breathing","supported-glute-bridge","deep-core-activation","pelvic-floor-breathing"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_eye_palming', 'eye-palming', 'Eye Palming', 'Ogen palmen', 'recovery', '["eyes","nervous_system"]', NULL, '["recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Rub palms together briskly for 10 seconds until warm","Cup warm palms gently over closed eyes — no pressure on eyeballs","Breathe slowly and let eyes completely relax in the darkness","Hold for 60–90 seconds","Repeat 2–3 times"],"cues":["Relieves eye strain and screen fatigue","The warmth and darkness are very soothing","Add a couple drops of lavender to palms for added calm"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Wrijf je handpalmen 10 seconden stevig tegen elkaar tot ze warm zijn","Leg je warme handpalmen als een kommetje over je gesloten ogen — geen druk op je oogbollen","Adem rustig en laat je ogen in het donker helemaal ontspannen","Houd 60–90 seconden vast","Herhaal 2–3 keer"],"cues_nl":["Verlicht vermoeide ogen na schermwerk","De warmte en het donker werken heel rustgevend","Doe een paar druppels lavendel op je handpalmen voor extra rust"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["supported-side-lying-rest","5-senses-grounding"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_fire_hydrant', 'fire-hydrant', 'Fire Hydrant', 'Fire hydrant', 'strength', '["hip_abductors","glutes","core"]', NULL, '["bodyweight","floor","low_impact","quiet","pregnancy_safe","postnatal_safe","sport_support:running","loads_shoulder"]', '["none"]', NULL, '{"steps":["Get on all fours with your wrists under your shoulders","Keeping your knee bent, lift your right knee out to the side to hip height","Hold for 1 second","Lower without touching the floor","Do 15 reps on each side"],"cues":["Keep core stable","Don''t rotate the spine","Great hip mobility + strength combo"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Ga op handen en knieën zitten met je polsen onder je schouders","Til je rechterknie gebogen zijwaarts op tot heuphoogte","Houd 1 seconde vast","Laat zakken zonder de vloer te raken","Doe 15 herhalingen per kant"],"cues_nl":["Houd je core stabiel","Draai je rug niet mee","Mooie combinatie van heupmobiliteit en kracht"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["standing-hip-abduction","donkey-kick"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_forearm_wrist_stretch', 'forearm-wrist-stretch', 'Forearm & Wrist Stretch', 'Onderarm- en polsstretch', 'mobility', '["forearms","wrists","biceps"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Extend your right arm straight in front of you with your palm facing up","Use your left hand to gently pull your fingers down toward the floor","Hold for 20 seconds and feel the stretch along the underside of your forearm","Turn your palm down, gently pull your fingers up and hold for 20 seconds","Switch arms and repeat"],"cues":["Gentle pressure only","Helps with wrist swelling in pregnancy (carpal tunnel)","Essential for new parents carrying a baby"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Strek je rechterarm recht voor je uit met je handpalm naar boven","Trek met je linkerhand je vingers zachtjes omlaag richting de vloer","Houd 20 seconden vast en voel de rek aan de onderkant van je onderarm","Draai je handpalm naar beneden, trek je vingers zachtjes omhoog en houd 20 seconden vast","Wissel van arm en herhaal"],"cues_nl":["Alleen zachte druk","Helpt bij gezwollen polsen tijdens de zwangerschap (carpaletunnelklachten)","Onmisbaar voor kersverse ouders die veel een baby dragen"]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["wrist-flexor-stretch","neck-stretch"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_glute_piriformis_stretch', 'glute-piriformis-stretch', 'Glute & Piriformis Stretch', 'Bil- en piriformisstretch', 'mobility', '["glutes","piriformis","hip_external_rotators"]', NULL, '["bodyweight","floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","sport_mobility:running","sport_mobility:football"]', '["none"]', NULL, '{"steps":["Lie on your back with your knees bent","Cross your right ankle over your left knee","Flex your right foot","Stay here, or reach through your legs to hold your left thigh","Gently draw your left leg toward your chest","Hold for 30–60 seconds, then switch sides"],"cues":["Flex the top foot to protect the knee","A figure-four stretch lying down","Excellent for sciatic nerve tension"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Lig op je rug met je knieën gebogen","Leg je rechterenkel over je linkerknie","Trek de tenen van je rechtervoet naar je toe","Blijf zo liggen, of reik tussen je benen door en pak je linkerdij vast","Trek je linkerbeen rustig naar je borst","Houd 30–60 seconden vast en wissel dan van kant"],"cues_nl":["Houd je bovenste voet aangespannen om je knie te beschermen","Een figuur-4 stretch, maar dan liggend","Heel fijn bij spanning rond de heupzenuw"]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions": ["supine-figure-four", "foam-roll-it-band", "foam-roll-glutes"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_good_morning', 'good-morning-bodyweight', 'Good Morning', 'Good morning', 'strength', '["hamstrings","lower_back","glutes"]', NULL, '["bodyweight","no_floor","low_impact","quiet","pregnancy_safe","loads_lower_back","sport_support:running","sport_support:rowing","loads_lower_back"]', '["none"]', NULL, '{"steps":["Stand with your feet hip-width apart, hands behind your head or crossed on your chest","Keep a soft bend in your knees","Hinge forward from your hips, pushing them back","Lower your torso until it is parallel to the floor or your hamstrings feel the stretch","Drive your hips forward to return to standing"],"cues":["Flat back throughout","Feel the hamstring stretch","Great hip hinge pattern for everyday movement"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Zet je voeten op heupbreedte, handen achter je hoofd of gekruist op je borst.","Buig je knieën licht.","Scharnier vanuit je heupen naar voren en duw ze naar achteren.","Laat je romp zakken tot hij horizontaal is of je je hamstrings voelt rekken.","Duw je heupen naar voren om terug te komen."],"cues_nl":["Houd je rug de hele tijd recht.","Voel de rek in je hamstrings.","Een prima heupscharnier voor alledaagse bewegingen."]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["dumbbell-single-leg-rdl","kettlebell-swing","nordic-hamstring-curl","glute-bridge"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_grapevine', 'grapevine-step', 'Grapevine Step', 'Grapevine', 'cardio', '["legs","glutes","core"]', NULL, '["bodyweight","no_floor","low_impact","quiet","pregnancy_safe","postnatal_safe","loads_ankle","loads_ankle","loads_knee"]', '["none"]', NULL, '{"steps":["Step right foot to the right","Cross left foot behind right","Step right foot to the right again","Tap left foot next to right","Reverse direction"],"cues":["Side-to-side stepping pattern","Add arm swings for intensity","Coordination + cardio combined"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Stap met je rechtervoet naar rechts","Kruis je linkervoet achter je rechtervoet","Stap opnieuw met je rechtervoet naar rechts","Tik je linkervoet naast je rechtervoet","Ga de andere kant op"],"cues_nl":["Stappatroon van links naar rechts","Zwaai je armen mee voor meer intensiteit","Coördinatie en cardio in één"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions": ["speed-skater", "cross-country-ski-step", "lateral-shuffle-drill"]}', 1, 1742860800000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_gratitude_reflection', 'gratitude-reflection', 'Gratitude Reflection', 'Dankbaarheidsreflectie', 'recovery', '["nervous_system"]', NULL, '["recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit comfortably with eyes closed","Bring to mind 3 specific things you are grateful for today","For each one, sit with the feeling for 10–15 seconds","Notice any physical sensation of warmth or ease","Open eyes slowly"],"cues":["Specificity matters — ''my hot coffee'' not just ''coffee''","Research shows this lowers cortisol","A powerful emotional recovery tool"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga comfortabel zitten met je ogen dicht","Denk aan 3 concrete dingen waar je vandaag dankbaar voor bent","Blijf bij elk ding 10–15 seconden bij het gevoel","Merk op of je ergens warmte of ontspanning in je lichaam voelt","Open langzaam je ogen"],"cues_nl":["Hoe concreter, hoe beter — ''mijn warme koffie'' en niet alleen ''koffie''","Onderzoek laat zien dat dit cortisol verlaagt","Een krachtig hulpmiddel voor emotioneel herstel"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["supported-side-lying-rest","5-senses-grounding"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_half_kneeling_hip_opener', 'half-kneeling-hip-opener', 'Half Kneeling Hip Opener', 'Heupopener halfknielend', 'mobility', '["hip_flexors","adductors","glutes"]', NULL, '["bodyweight","floor","low_impact","no_sweat","quiet","pregnancy_safe","sport_mobility:running","sport_mobility:football","loads_knee"]', '["none"]', NULL, '{"steps":["Kneel on right knee, left foot forward in a 90° lunge","Keep right knee on floor, left knee over ankle","Shift weight forward gently until you feel the right hip flexor stretch","Add a gentle side reach for extra thoracic opening","Hold 30 seconds each side"],"cues":["Tall spine throughout","Squeeze right glute for deeper hip flexor stretch","Great for hip flexor tightness from sitting"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Kniel op je rechterknie, linkervoet voor je in een uitvalspas van 90°.","Houd je rechterknie op de vloer en je linkerknie boven je enkel.","Breng je gewicht rustig naar voren tot je de rek in je rechter heupbuiger voelt.","Reik eventueel zachtjes opzij om je bovenrug extra te openen.","Houd 30 seconden per kant vast."],"cues_nl":["Houd je rug de hele tijd lang.","Span je rechterbilspier aan voor een diepere rek in je heupbuiger.","Ideaal tegen stijve heupbuigers door veel zitten."]}', '{"images":["/exercise-media/half-kneeling-hip-opener/0.jpg","/exercise-media/half-kneeling-hip-opener/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions": ["ninety-ninety-hip-switch", "couch-stretch", "deep-squat-hold"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_heel_dig_march', 'heel-dig-march', 'Heel Dig March', 'Mars met hieltik', 'cardio', '["tibialis_anterior","calves","legs"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand tall, feet hip-width","Alternate tapping your heel forward on the floor","Swing opposite arm forward","Keep a bouncy rhythm — 30–60 seconds"],"cues":["Like marching but heel-first","Good music makes this feel effortless","Gentle enough for any stage"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta rechtop, voeten op heupbreedte","Tik afwisselend je hiel voor je op de vloer","Zwaai je andere arm naar voren","Houd een veerkrachtig ritme aan — 30–60 seconden"],"cues_nl":["Zoals marcheren, maar met je hiel eerst","Met goede muziek gaat dit vanzelf","Rustig genoeg voor elke fase"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["high-knees","march-in-place","standing-twist-march"]}', 1, 1742860800000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_heel_slides', 'heel-slides', 'Heel Slides', 'Hielschuiven', 'mobility', '["transverse_abdominis","hip_flexors","pelvic_floor"]', NULL, '["pelvic_floor","floor","low_impact","no_sweat","quiet","supine","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Lie on your back with your knees bent","Exhale and gently brace your core","Slowly slide one heel along the floor until your leg is nearly straight","Slide your heel back in to the start position","Alternate legs and do 8 reps per side"],"cues":["Keep lower back still throughout","Breathe continuously","Great early postnatal core reconnection exercise"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Lig op je rug met je knieën gebogen","Adem uit en span je core licht aan","Schuif één hiel langzaam over de vloer tot je been bijna gestrekt is","Schuif je hiel terug naar de beginpositie","Wissel van been en doe 8 herhalingen per kant"],"cues_nl":["Houd je onderrug de hele tijd stil","Blijf doorademen","Fijne oefening om na de bevalling weer contact te maken met je core"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["flutter-kicks","supported-glute-bridge"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_humming_breath', 'humming-bee-breath', 'Humming Bee Breath', 'Bijenademhaling (Bhramari)', 'recovery', '["diaphragm","vocal_cords","nervous_system"]', NULL, '["breathing","recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit comfortably, close eyes if you wish","Inhale fully through nose","On the exhale, make a gentle humming sound (like a bee)","Feel the vibration in your lips, nose, and skull","Repeat 6–8 times"],"cues":["The humming triggers the vagus nerve","Deeply calming — great for stress and nausea","Sound can be soft — you don''t need to be loud"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga comfortabel zitten en sluit je ogen als je wilt","Adem volledig in door je neus","Maak bij de uitademing een zacht zoemend geluid (als een bij)","Voel de trilling in je lippen, neus en schedel","Herhaal 6–8 keer"],"cues_nl":["Het zoemen prikkelt de nervus vagus","Diep kalmerend — fijn bij stress en misselijkheid","Het geluid mag zacht zijn — je hoeft niet hard te zoemen"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["478-breathing","alternate-nostril-breathing"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_inner_thigh_squeeze', 'inner-thigh-squeeze', 'Inner Thigh Squeeze', 'Binnenkant dij aanspannen', 'mobility', '["adductors","pelvic_floor"]', NULL, '["pelvic_floor","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit on a chair with a soft ball, rolled towel or pillow between your knees","Exhale and gently squeeze your knees together","Contract your pelvic floor at the same time as you squeeze","Hold for 5 seconds, then release fully","Repeat 10 times"],"cues":["No ball? Just imagine squeezing","Coordinate with pelvic floor lift","Good seated desk-break exercise"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Ga op een stoel zitten met een zachte bal, opgerolde handdoek of kussen tussen je knieën","Adem uit en knijp je knieën zachtjes naar elkaar toe","Span tegelijk met het knijpen je bekkenbodem aan","Houd 5 seconden vast en laat dan helemaal los","Herhaal 10 keer"],"cues_nl":["Geen bal? Doe dan alsof je knijpt","Combineer het met het optillen van je bekkenbodem","Goede oefening voor een pauze achter je bureau"]}', NULL, '{"supports":["reps","sets","time"]}', '{"substitutions":["supported-glute-bridge","360-breathing"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_jump_rope_sim', 'jump-rope-simulation', 'Jump Rope (Simulated)', 'Touwspringen zonder touw', 'cardio', '["calves","shoulders","calves","core"]', NULL, '["bodyweight","no_floor","high_impact","loud","loads_shoulder","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with feet together, arms at sides","Simulate turning a rope with wrists while hopping lightly on balls of feet","Alternate feet or keep together"],"cues":["Great cardio without equipment","High impact — avoid in pregnancy and early postnatal","Low ceilings not an issue — no real rope!"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta met je voeten tegen elkaar, armen langs je lichaam","Draai een denkbeeldig touw met je polsen en spring licht op je voorvoeten","Wissel van voet of houd je voeten samen"],"cues_nl":["Prima cardio zonder materiaal","Hoge impact — niet doen tijdens de zwangerschap en vlak na de bevalling","Een laag plafond is geen probleem — er is geen echt touw!"]}', NULL, '{"supports": ["time"], "base_duration_sec": 30}', '{"substitutions":["jumping-jack","high-knees"]}', 1, 1742860800000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_jump_squat', 'jump-squat', 'Jump Squat', 'Jump squat', 'cardio', '["quadriceps","glutes","calves"]', NULL, '["bodyweight","no_floor","high_impact","loud","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Lower into squat position","Explosively jump upward, arms swinging overhead","Land softly, absorbing impact through knees and hips","Flow immediately into next rep"],"cues":["Soft landing — knees bent, not locked","Land ball-heel, not heel-first","Avoid during pregnancy"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Zak in een squat","Spring explosief omhoog en zwaai je armen boven je hoofd","Land zacht en vang de klap op met je knieën en heupen","Ga direct door naar de volgende herhaling"],"cues_nl":["Zachte landing — knieën gebogen, niet op slot","Land van voorvoet naar hiel, niet op je hiel","Niet doen tijdens de zwangerschap"]}', '{"images":["/exercise-media/jump-squat/0.jpg","/exercise-media/jump-squat/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","time"]}', '{"substitutions": ["broad-jump", "power-step-up-jump", "squat", "scissor-jump", "counter-movement-jump"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_kegel_elevator', 'kegel-elevator', 'Kegel Elevator', 'Kegel lift', 'mobility', '["pelvic_floor"]', NULL, '["pelvic_floor","kegel","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit comfortably and imagine your pelvic floor is an elevator","Go to floor 1 with a gentle squeeze","Rise to floor 2 by squeezing a little more","Rise to floor 3 with your maximum gentle lift","Slowly descend floor by floor","Rest completely before repeating"],"cues":["No rushing — slow and deliberate","Notice each level of engagement","Great for body awareness"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Ga comfortabel zitten en stel je voor dat je bekkenbodem een lift is","Ga naar verdieping 1 door licht aan te spannen","Ga naar verdieping 2 door iets meer aan te spannen","Ga naar verdieping 3 met je hoogste, nog steeds zachte spanning","Zak langzaam weer af, verdieping voor verdieping","Ontspan helemaal voor je herhaalt"],"cues_nl":["Niet haasten — langzaam en bewust","Voel elk niveau van aanspanning","Goed voor je lichaamsbewustzijn"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["supported-glute-bridge","360-breathing"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_kegel_hold', 'kegel-hold', 'Kegel Hold', 'Kegel houden', 'mobility', '["pelvic_floor"]', NULL, '["pelvic_floor","kegel","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit, stand, or lie comfortably","Identify your pelvic floor muscles (the ones you use to stop urination)","Squeeze and lift them upward","Hold for 5–10 seconds","Slowly release and rest for equal time","Repeat 10 times"],"cues":["Don''t hold your breath","Keep buttocks and thighs relaxed","Quality over quantity"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Ga comfortabel zitten, staan of liggen","Zoek je bekkenbodemspieren op (de spieren waarmee je het plassen ophoudt)","Span ze aan en til ze omhoog","Houd 5–10 seconden vast","Laat langzaam los en neem even lang rust","Herhaal 10 keer"],"cues_nl":["Houd je adem niet in","Houd je billen en bovenbenen ontspannen","Kwaliteit boven kwantiteit"]}', NULL, '{"supports":["reps","sets","time"]}', '{"substitutions":["supported-glute-bridge","360-breathing"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_kegel_pulses', 'kegel-pulses', 'Kegel Pulses', 'Kegel pulseren', 'mobility', '["pelvic_floor"]', NULL, '["pelvic_floor","kegel","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit or stand comfortably","Quickly contract and release pelvic floor in short pulses","Aim for 1 second on, 1 second off","Do 10–20 pulses","Rest and repeat 3 times"],"cues":["Fast and light contractions","Don''t bear down on release","Breathe normally throughout"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Ga comfortabel zitten of staan","Span je bekkenbodem snel aan en laat weer los, in korte pulsen","Mik op 1 seconde aan, 1 seconde los","Doe 10–20 pulsen","Neem rust en herhaal 3 keer"],"cues_nl":["Snel en licht aanspannen","Pers niet naar beneden bij het loslaten","Blijf de hele tijd normaal ademen"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["supported-glute-bridge","360-breathing"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_knee_push_up', 'knee-push-up', 'Knee Push-up', 'Opdrukken op de knieën', 'strength', '["chest","triceps","shoulders"]', NULL, '["bodyweight","floor","low_impact","quiet","pregnancy_safe","postnatal_safe","loads_shoulder","measurable"]', '["none"]', NULL, '{"steps":["Kneel on the floor with your hands shoulder-width apart and your hips forward (not piked)","Keep your body in a straight line from knees to head","Lower your chest to the floor with your elbows at 45°","Push back up"],"cues":["Great stepping stone to full push-up","Keep core engaged","For pregnancy: excellent alternative in T2-T3"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Kniel op de vloer met je handen op schouderbreedte en je heupen naar voren (billen niet omhoog)","Houd je lichaam in een rechte lijn van knieën tot hoofd","Laat je borst naar de vloer zakken met je ellebogen in 45°","Druk jezelf weer omhoog"],"cues_nl":["Mooie tussenstap naar de volledige push-up","Houd je core aangespannen","Tijdens de zwangerschap: een uitstekend alternatief in het tweede en derde trimester"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["push-up","hand-release-push-up","wall-push-up"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_labour_breathing', 'labour-breathing-prep', 'Labour Breathing Preparation', 'Voorbereiding bevallingsademhaling', 'recovery', '["diaphragm","pelvic_floor","nervous_system"]', NULL, '["breathing","pelvic_floor","recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe"]', '["none"]', NULL, '{"steps":["Sit or kneel comfortably, or find your most comfortable position","Inhale slowly and deeply through your nose for 4–6 counts","Exhale long and controlled through a softly open mouth for 6–8 counts","On the exhale, let your jaw, face, shoulders and pelvic floor all release","Repeat for 5–10 minutes"],"cues":["This IS the most useful thing to practice in T3","Exhale is the tool — the release is everything","Practice daily from 36 weeks"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Pelvic Floor","steps_nl":["Ga comfortabel zitten of knielen, of zoek de houding die voor jou het prettigst is","Adem langzaam en diep in door je neus in 4–6 tellen","Adem lang en beheerst uit door een zacht geopende mond in 6–8 tellen","Laat bij de uitademing je kaak, gezicht, schouders en bekkenbodem helemaal los","Herhaal 5–10 minuten"],"cues_nl":["Dit is hét nuttigste om te oefenen in het derde trimester","De uitademing is je gereedschap — loslaten is alles","Oefen dagelijks vanaf 36 weken"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["478-breathing","alternate-nostril-breathing"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_lateral_knee_raise', 'lateral-knee-raise', 'Lateral Knee Raise', 'Knie zijwaarts heffen', 'cardio', '["hip_abductors","core","legs"]', NULL, '["bodyweight","no_floor","low_impact","quiet","pregnancy_safe","postnatal_safe","loads_knee"]', '["none"]', NULL, '{"steps":["Stand tall with your feet hip-width apart","Shift weight left, lift right knee out to the side (hip height)","Return foot to floor, shift weight right","Lift left knee out to the side","Alternate in steady rhythm"],"cues":["Control the lift — don''t swing","Keep standing leg slightly bent","Hip stability + light cardio"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta rechtop met je voeten op heupbreedte","Breng je gewicht naar links en til je rechterknie zijwaarts op (heuphoogte)","Zet je voet terug en breng je gewicht naar rechts","Til je linkerknie zijwaarts op","Wissel af in een rustig ritme"],"cues_nl":["Til gecontroleerd — niet zwaaien","Houd je standbeen licht gebogen","Heupstabiliteit en lichte cardio"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions": ["alternating-front-kick", "reverse-lunge-kick"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_lateral_lunge', 'lateral-lunge', 'Lateral Lunge', 'Zijwaartse uitvalspas', 'strength', '["adductors","glutes","quadriceps"]', NULL, '["bodyweight","no_floor","low_impact","loads_knee","loads_knee"]', '["none"]', NULL, '{"steps":["Stand with feet together","Step wide to the right, bending right knee and sitting back","Keep left leg straight","Push off right foot to return","Alternate sides"],"cues":["Keep chest tall","Knee tracks over toes","Targets often-neglected lateral strength"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Sta met je voeten tegen elkaar.","Stap breed naar rechts, buig je rechterknie en zak naar achteren.","Houd je linkerbeen gestrekt.","Duw je af met je rechtervoet om terug te komen.","Wissel van kant."],"cues_nl":["Houd je borst omhoog.","Je knie wijst in de richting van je tenen.","Traint zijwaartse kracht die vaak wordt vergeten."]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["dumbbell-side-lunge","pistol-squat-assist","lunge","curtsy-lunge"]}', 1, 1742860800000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_legs_up_wall', 'legs-up-wall', 'Legs Up the Wall', 'Benen omhoog tegen de muur', 'recovery', '["hamstrings","lower_back","nervous_system"]', NULL, '["recovery","floor","low_impact","no_sweat","quiet","supine","inversion","postnatal_safe","loads_lower_back"]', '["none"]', NULL, '{"steps":["Sit sideways against a wall","Swing your legs up to rest against the wall as you lie back","Rest your arms out to the sides with your palms up","Stay for 5–15 minutes","To come out, bend your knees, roll onto your side and sit up slowly"],"cues":["Excellent for swollen legs and feet","Mild inversion — avoid in late pregnancy (use supported side-lying instead)","One of the most restorative postures there is"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga zijwaarts tegen een muur zitten","Zwaai je benen omhoog tegen de muur terwijl je achterover gaat liggen","Leg je armen opzij met je handpalmen omhoog","Blijf 5–15 minuten liggen","Kom eruit door je knieën te buigen, op je zij te rollen en rustig rechtop te komen"],"cues_nl":["Heerlijk bij gezwollen benen en voeten","Lichte omkeerhouding — niet doen laat in de zwangerschap (kies dan voor ondersteund rusten op de zij)","Een van de meest herstellende houdingen die er zijn"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["supine-knee-to-chest","supported-side-lying-rest"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_low_impact_jacks', 'low-impact-jumping-jacks', 'Low Impact Jumping Jacks', 'Jumping jack zonder springen', 'cardio', '["legs","glutes","shoulders"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_knee","loads_knee","loads_shoulder","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with feet together, arms at sides","Step right foot out while raising arms overhead","Step right foot back in while lowering arms","Step left foot out, raise arms","Alternate in a steady rhythm"],"cues":["One foot always on the ground","No jumping — same cardio benefit, no impact","Great first-trimester and postnatal cardio"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta met je voeten tegen elkaar, armen langs je lichaam.","Stap je rechtervoet opzij en breng je armen boven je hoofd.","Stap je rechtervoet terug en laat je armen zakken.","Stap je linkervoet opzij en breng je armen omhoog.","Wissel af in een rustig, gelijkmatig ritme."],"cues_nl":["Er staat altijd één voet op de grond.","Niet springen: hetzelfde cardio-effect, zonder impact.","Ideale cardio in het eerste trimester en na de bevalling."]}', NULL, '{"supports":["time","reps"]}', '{"substitutions":["jumping-jack","step-touch"]}', 1, 1742860800000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_mindful_body_check', 'mindful-body-check', 'Mindful Body Check', 'Mindful lichaamscheck', 'recovery', '["nervous_system"]', NULL, '["recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit or lie comfortably","Bring attention to your feet — what do you notice? Temperature, pressure, sensation","Slowly move attention up: ankles, calves, knees, thighs...","Continue through the whole body to the crown of the head","Notice without judgment — there''s no right or wrong to feel"],"cues":["Lighter than a body scan — just noticing","3–5 minutes is plenty","Great postural awareness practice"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga comfortabel zitten of liggen","Breng je aandacht naar je voeten — wat merk je op? Temperatuur, druk, gevoel","Ga langzaam met je aandacht omhoog: enkels, kuiten, knieën, bovenbenen...","Ga zo door je hele lichaam tot aan je kruin","Merk op zonder oordeel — je kunt niets goed of fout voelen"],"cues_nl":["Lichter dan een bodyscan — alleen opmerken","3–5 minuten is ruim voldoende","Goede oefening om je bewust te worden van je houding"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["progressive-relaxation-body","supported-side-lying-rest"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_modified_burpee', 'modified-burpee', 'Modified Burpee (No Jump)', 'Burpee zonder sprong', 'cardio', '["full_body","legs","core","shoulders"]', NULL, '["bodyweight","floor","low_impact","loads_knee","loads_ankle","loads_knee","loads_ankle","loads_shoulder","loads_lower_back"]', '["none"]', NULL, '{"steps":["Stand, then place hands on floor","Walk feet back to plank","Walk feet back to hands","Stand up — no jumping"],"cues":["A full-body movement without the impact","Can also step with one foot at a time","Great stepping stone to full burpees"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta rechtop en zet dan je handen op de vloer","Loop met je voeten naar achteren tot je in een plank staat","Loop met je voeten terug naar je handen","Kom overeind — zonder te springen"],"cues_nl":["Een beweging voor je hele lichaam, zonder de impact","Je kunt ook voet voor voet stappen","Mooie opstap naar de volledige burpee"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["low-impact-jumping-jacks","seated-cardio-punch"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_modified_plank', 'modified-plank', 'Modified Plank (Knees)', 'Plank op de knieën', 'strength', '["core","shoulders","transverse_abdominis"]', NULL, '["bodyweight","floor","low_impact","quiet","pregnancy_safe","postnatal_safe","loads_shoulder","loads_shoulder"]', '["none"]', NULL, '{"steps":["Kneel on the floor and lower yourself onto your forearms","Bring your body into a straight line from your knees to your head","Hold the position and breathe normally"],"cues":["Don''t let hips sag or pike","Brace core gently throughout","Great entry point for postnatal core work"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Kniel op de vloer en zak op je onderarmen","Breng je lichaam in een rechte lijn van knieën tot hoofd","Houd deze positie vast en adem normaal door"],"cues_nl":["Laat je heupen niet doorzakken of omhoogkomen","Span je core de hele tijd licht aan","Mooie instap voor core-training na de bevalling"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["hollow-body-hold","knee-push-up"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_neck_shoulder_massage', 'neck-shoulder-self-massage', 'Neck & Shoulder Self-Massage', 'Nek- en schouderzelfmassage', 'recovery', '["traps","neck","shoulders"]', NULL, '["recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_shoulder"]', '["none"]', NULL, '{"steps":["Sit comfortably","Use right hand to squeeze and release left trapezius muscle (top of shoulder)","Work from the base of skull down toward the shoulder","Switch sides","Use fingertips to gently press base of skull — hold each point 10–20 seconds"],"cues":["Pressure should feel like pleasant relief","Good for feeding-posture tension in postnatal period","Can do with a warm compress first"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga comfortabel zitten","Knijp met je rechterhand in je linker trapeziusspier (bovenop je schouder) en laat weer los","Werk van je schedelrand omlaag richting je schouder","Wissel van kant","Druk met je vingertoppen zacht op je schedelrand — houd elk punt 10–20 seconden vast"],"cues_nl":["De druk moet aanvoelen als prettige verlichting","Fijn bij spanning door de voedingshouding na de bevalling","Kan ook na een warm kompres"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["shoulder-roll-stretch","neck-half-circles"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_ocean_breath', 'ocean-breath', 'Ocean Breath (Ujjayi)', 'Oceaanademhaling (Ujjayi)', 'recovery', '["diaphragm","throat","nervous_system"]', NULL, '["breathing","recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit or lie comfortably and breathe in through your nose","As you exhale through the nose, slightly constrict the back of your throat","Listen for a soft ocean wave or Darth Vader sound as the air passes","Keep the inhale and exhale slow and steady, 4–6 counts each","Repeat for 2–5 minutes"],"cues":["The sound means you''re doing it right","Keeps the mind anchored to breath","Popular in yoga and prenatal classes"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga comfortabel zitten of liggen en adem in door je neus","Knijp bij het uitademen door je neus de achterkant van je keel licht samen","Luister naar een zacht geluid als een golf in zee, of als Darth Vader","Houd je in- en uitademing langzaam en gelijkmatig, elk 4–6 tellen","Herhaal 2–5 minuten"],"cues_nl":["Hoor je het geluid, dan doe je het goed","Houdt je aandacht bij je adem","Populair bij yoga en zwangerschapslessen"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["478-breathing","alternate-nostril-breathing"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_overhead_reach_stretch', 'overhead-reach-stretch', 'Overhead Reach Stretch', 'Reiken boven het hoofd (stretch)', 'mobility', '["lats","shoulders","intercostals","spine"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_shoulder","loads_lower_back"]', '["none"]', NULL, '{"steps":["Stand or sit tall with your arms in front of you","Interlace your fingers and turn your palms toward the ceiling","Reach your arms overhead as high as is comfortable","Lengthen your whole spine","Hold for 20–30 seconds while breathing deeply, then lower your arms"],"cues":["Feel the whole side body lengthen","Good for creating space in the torso during T3","Can also do alternating single-arm reaches"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Sta of zit rechtop met je armen voor je","Vouw je vingers in elkaar en draai je handpalmen naar het plafond","Reik met je armen boven je hoofd, zo hoog als prettig voelt","Maak je hele rug lang","Houd 20–30 seconden vast, adem diep en laat dan je armen zakken"],"cues_nl":["Voel je hele zij lang worden","Fijn om ruimte in je romp te maken in het derde trimester","Je kunt ook afwisselend met één arm reiken"]}', '{"images":["/exercise-media/overhead-reach-stretch/0.jpg","/exercise-media/overhead-reach-stretch/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["side-lying-full-stretch","standing-side-stretch"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pelvic_floor_breathing', 'pelvic-floor-breathing', 'Pelvic Floor Breathing', 'Bekkenbodem ademhaling', 'mobility', '["pelvic_floor","diaphragm"]', NULL, '["pelvic_floor","breathing","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit tall or lie on your side","Inhale deeply — let belly expand and pelvic floor gently descend","Exhale — gently engage pelvic floor as air leaves","Repeat for 5–10 breaths"],"cues":["Pelvic floor and breath move together","On exhale: lift, not grip","On inhale: release completely"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Ga rechtop zitten of op je zij liggen.","Adem diep in: laat je buik uitzetten en je bekkenbodem zachtjes zakken.","Adem uit: span je bekkenbodem zachtjes aan terwijl de lucht eruit gaat.","Herhaal 5–10 ademhalingen."],"cues_nl":["Bekkenbodem en adem bewegen samen.","Bij uitademen: optillen, niet knijpen.","Bij inademen: helemaal loslaten."]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["360-breathing","exhalation-core-engagement"]}', 1, 1742860800000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pelvic_tilt_lying', 'pelvic-tilt-lying', 'Pelvic Tilt (Lying)', 'Bekken kantelen liggend', 'mobility', '["transverse_abdominis","lower_back","pelvic_floor"]', NULL, '["pelvic_floor","floor","low_impact","no_sweat","quiet","supine","pregnancy_safe","postnatal_safe","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie on your back with your knees bent and your feet flat on the floor","Inhale to prepare","Exhale and gently flatten your lower back into the floor by tilting your pelvis","Hold for 3 seconds, then release","Repeat 10 times"],"cues":["Small gentle movement only","Don''t squeeze glutes forcefully","Keep breathing throughout"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Lig op je rug met je knieën gebogen en je voeten plat op de vloer","Adem in ter voorbereiding","Adem uit en druk je onderrug zachtjes in de vloer door je bekken te kantelen","Houd 3 seconden vast en laat los","Herhaal 10 keer"],"cues_nl":["Alleen een kleine, zachte beweging","Knijp je bilspieren niet hard samen","Blijf doorademen"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["pelvic-tilt-standing","supported-glute-bridge"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pelvic_tilt_standing', 'pelvic-tilt-standing', 'Standing Pelvic Tilt', 'Bekken kantelen staand', 'mobility', '["transverse_abdominis","lower_back","pelvic_floor"]', NULL, '["pelvic_floor","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_lower_back"]', '["none"]', NULL, '{"steps":["Stand with your feet hip-width apart and your knees slightly bent","Place one hand on your belly and one on your lower back","Exhale, gently draw your lower belly in and tilt your pelvis slightly under","Hold for 3 seconds, then release","Repeat 10 times"],"cues":["Tiny movement — not a big tuck","Great against a wall for feedback","Perfect third-trimester posture exercise"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Sta met je voeten op heupbreedte en je knieën licht gebogen","Leg één hand op je buik en één op je onderrug","Adem uit, trek je onderbuik zachtjes in en kantel je bekken iets naar achteren","Houd 3 seconden vast en laat los","Herhaal 10 keer"],"cues_nl":["Een heel kleine beweging — geen grote kanteling","Doe het tegen een muur om goed te voelen wat je doet","Ideale houdingsoefening voor het derde trimester"]}', '{"images":["/exercise-media/pelvic-tilt-standing/0.jpg","/exercise-media/pelvic-tilt-standing/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions":["pelvic-tilt-lying","supported-glute-bridge"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pike_push_up', 'pike-push-up', 'Pike Push-up', 'Opdrukken pike', 'strength', '["shoulders","triceps","upper_back"]', NULL, '["bodyweight","floor","low_impact","loads_shoulder","loads_shoulder"]', '["none"]', NULL, '{"steps":["Start in downward dog position","Bend elbows to lower crown of head toward floor","Push back up to start","Keep hips high throughout"],"cues":["Hips stay elevated — this targets shoulders","Wider hands = easier","Builds toward handstand push-up"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Begin in de neerwaartse hond","Buig je ellebogen en breng je kruin richting de vloer","Duw terug omhoog naar de start","Houd je heupen de hele tijd hoog"],"cues_nl":["Heupen blijven hoog — zo train je je schouders","Handen breder = makkelijker","Opbouw naar de handstand push-up"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["knee-push-up","wall-push-up"]}', 1, 1742860800000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_plank_shoulder_tap', 'plank-shoulder-tap', 'Plank Shoulder Tap', 'Plank shoulder tap', 'strength', '["core","shoulders","transverse_abdominis"]', NULL, '["bodyweight","floor","low_impact","quiet","loads_shoulder","loads_shoulder"]', '["none"]', NULL, '{"steps":["Start in high plank (push-up position)","Without rotating hips, lift right hand to tap left shoulder","Return, then tap right shoulder with left hand","Alternate — 10 per side"],"cues":["Hips stay square — resist rotation","Feet wider = easier","Core anti-rotation challenge"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Start in een hoge plank (opdrukpositie).","Til zonder je heupen te draaien je rechterhand op en tik je linkerschouder aan.","Zet je hand terug en tik dan met je linkerhand je rechterschouder aan.","Wissel af: 10 per kant."],"cues_nl":["Houd je heupen recht en weersta de draaiing.","Voeten breder = makkelijker.","Een anti-rotatie-uitdaging voor je core."]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions": ["dumbbell-renegade-row", "bear-crawl"]}', 1, 1742860800000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_prone_hip_extension', 'prone-hip-extension', 'Prone Hip Extension', 'Heupextensie op de buik', 'mobility', '["glutes","hamstrings","lower_back"]', NULL, '["bodyweight","floor","low_impact","no_sweat","quiet","prone","loads_lower_back","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie face down on the floor with your arms extended or under your forehead","Keep both hips on the floor","Squeeze your right glute and lift your right leg a few inches","Hold for 2 seconds, then lower slowly","Do 12 reps on each side"],"cues":["Keep the hip of the working leg on the floor","Small range of motion is fine","Avoid in second/third trimester — use donkey kick instead"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Lig op je buik op de vloer met je armen gestrekt of onder je voorhoofd","Houd beide heupen op de vloer","Span je rechterbilspier aan en til je rechterbeen een paar centimeter op","Houd 2 seconden vast en zak langzaam terug","Doe 12 herhalingen per kant"],"cues_nl":["Houd de heup van je werkende been op de vloer","Een kleine beweging is prima","Niet doen in het tweede of derde trimester — doe dan de donkey kick"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["supported-glute-bridge","world-greatest-stretch"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pursed_lip_breathing', 'pursed-lip-breathing', 'Pursed Lip Breathing', 'Ademhaling met getuite lippen', 'recovery', '["diaphragm","lungs"]', NULL, '["breathing","recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit or stand comfortably","Inhale slowly through the nose for 2 counts","Pucker lips as if about to whistle","Exhale slowly through pursed lips for 4 counts","Repeat 5–10 times"],"cues":["Exhale should be twice as long as inhale","Reduces breathlessness — excellent for T3 pregnancy","Used by people with respiratory conditions too"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga comfortabel zitten of staan","Adem langzaam in door je neus in 2 tellen","Tuit je lippen alsof je gaat fluiten","Adem langzaam uit door je getuite lippen in 4 tellen","Herhaal 5–10 keer"],"cues_nl":["Je uitademing duurt twee keer zo lang als je inademing","Vermindert kortademigheid — heel geschikt in het derde trimester","Wordt ook gebruikt door mensen met luchtwegaandoeningen"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["478-breathing","alternate-nostril-breathing"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_savasana', 'savasana', 'Savasana (Corpse Pose)', 'Savasana (lijkhouding)', 'recovery', '["nervous_system","full_body"]', NULL, '["recovery","floor","low_impact","no_sweat","quiet","supine","postnatal_safe"]', '["none"]', NULL, '{"steps":["Lie flat on your back, arms slightly away from body, palms up","Close your eyes","Let feet fall naturally open","Allow the floor to hold all your weight","Remain still for 5–10 minutes"],"cues":["Completely passive — just receive","Best after a workout to let the nervous system integrate","After 16 weeks pregnancy: use left side-lying instead"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga plat op je rug liggen, armen iets van je lichaam af, handpalmen omhoog","Sluit je ogen","Laat je voeten vanzelf naar buiten vallen","Laat de vloer al je gewicht dragen","Blijf 5–10 minuten stil liggen"],"cues_nl":["Helemaal passief — je hoeft niets te doen","Het fijnst na een training, zodat je zenuwstelsel tot rust kan komen","Na 16 weken zwangerschap: ga in plaats hiervan op je linkerzij liggen"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["supported-side-lying-rest","5-senses-grounding"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_seated_butterfly', 'seated-butterfly', 'Seated Butterfly Stretch', 'Vlinderstretch zittend', 'mobility', '["adductors","hip_flexors","groin"]', NULL, '["bodyweight","floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit on the floor with the soles of your feet together","Let your knees fall naturally out to the sides","Hold your feet and sit tall","Gently press your knees toward the floor with your elbows","Hold for 30–60 seconds"],"cues":["Don''t force knees down — gravity is enough","Breathe into the hips","Excellent for inner thigh and groin opening — great during pregnancy"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Ga op de vloer zitten met je voetzolen tegen elkaar","Laat je knieën vanzelf naar buiten zakken","Pak je voeten vast en ga rechtop zitten","Duw je knieën met je ellebogen zachtjes richting de vloer","Houd 30–60 seconden vast"],"cues_nl":["Forceer je knieën niet omlaag — de zwaartekracht is genoeg","Adem naar je heupen toe","Heel fijn om je binnenbenen en liezen te openen — ook tijdens de zwangerschap"]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions": ["deep-squat-hold", "seated-straddle-stretch", "happy-baby-pose"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_seated_cardio_punch', 'seated-cardio-punch', 'Seated Cardio Punches', 'Zittend stoten (cardio)', 'cardio', '["shoulders","arms","core"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_shoulder"]', '["chair"]', NULL, '{"steps":["Sit on the edge of a sturdy chair, feet flat","Alternate throwing punches forward — jab, cross, hook","Add speed and rhythm","Keep punching without stopping for 30–60 seconds"],"cues":["Rotate torso with each punch","Elbows stay in on jab/cross","Great seated cardio option late pregnancy or early postnatal"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Ga op de rand van een stevige stoel zitten, voeten plat","Stoot afwisselend naar voren — jab, cross, hoek","Voer tempo en ritme op","Blijf 30–60 seconden onafgebroken stoten"],"cues_nl":["Draai je bovenlichaam mee bij elke stoot","Ellebogen blijven dicht bij je lichaam bij jab en cross","Prima cardio-optie zittend, laat in de zwangerschap of vlak na de bevalling"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions": ["speed-bag-simulation", "boxing-combination"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_seated_hamstring_stretch', 'seated-hamstring-stretch', 'Seated Hamstring Stretch', 'Hamstring stretch zittend', 'mobility', '["hamstrings","calves","lower_back"]', NULL, '["bodyweight","floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_lower_back","loads_ankle"]', '["none"]', NULL, '{"steps":["Sit on the floor with both legs extended straight in front of you","Sit tall from your hips (put a folded blanket under your sit bones if you are tight)","Hinge forward from your hips, not from your waist","Reach toward your feet or shins","Hold for 30–60 seconds, then sit back up"],"cues":["Keep back flat — this is a hip hinge, not a back round","Bend knees slightly if very tight","Flex feet for extra calf stretch"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Ga op de vloer zitten met beide benen gestrekt voor je","Zit rechtop vanuit je heupen (leg een opgevouwen deken onder je zitbotten als je stijf bent)","Buig naar voren vanuit je heupen, niet vanuit je taille","Reik naar je voeten of schenen","Houd 30–60 seconden vast en kom dan weer rechtop"],"cues_nl":["Houd je rug recht — je scharniert vanuit je heupen en maakt je rug niet bol","Buig je knieën iets als je erg stijf bent","Trek je tenen naar je toe voor extra rek in je kuiten"]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions": ["lying-hamstring-stretch", "seated-straddle-stretch", "foam-roll-hamstrings"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_seated_pelvic_roll', 'seated-pelvic-roll', 'Seated Pelvic Roll', 'Bekkencirkels zittend', 'mobility', '["lower_back","pelvic_floor","core","hips"]', NULL, '["pelvic_floor","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_lower_back"]', '["chair"]', NULL, '{"steps":["Sit on the edge of a chair with your feet flat on the floor","Make large circles with your hips clockwise 10 times","Reverse the direction and circle 10 times","Try figure-8 patterns as a variation"],"cues":["Very effective on an exercise ball","Great labour preparation","Loosens hips and lower back naturally"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Ga op de rand van een stoel zitten met je voeten plat op de vloer","Draai 10 grote cirkels met je heupen, met de klok mee","Draai de andere kant op en maak weer 10 cirkels","Probeer als variatie een achtje te draaien"],"cues_nl":["Werkt heel goed op een fitnessbal","Goede voorbereiding op de bevalling","Maakt je heupen en onderrug op een natuurlijke manier los"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["supported-glute-bridge","seated-spinal-twist"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_seated_thoracic_rotation', 'seated-thoracic-rotation', 'Seated Thoracic Rotation', 'Thoracale rotatie (zittend)', 'mobility', '["thoracic_spine","obliques"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","sport_support:cycling","sport_mobility:cycling","sport_mobility:rowing"]', '["chair"]', NULL, '{"steps":["Sit sideways on a chair with your feet flat on the floor","Cross your arms over your chest or hold the back of the chair","Gently rotate your upper body toward the chair back","Hold for 2 seconds, then return to the centre","Do 8 reps on each side"],"cues":["Rotate only as far as comfortable","Keep hips facing forward","Safe spinal rotation — not like a crunch"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Ga zijwaarts op een stoel zitten met je voeten plat op de vloer","Kruis je armen voor je borst of houd de rugleuning vast","Draai je bovenlichaam rustig naar de rugleuning toe","Houd 2 seconden vast en kom terug naar het midden","Doe 8 herhalingen per kant"],"cues_nl":["Draai alleen zo ver als prettig voelt","Houd je heupen recht naar voren","Veilige draaiing van je rug — anders dan een crunch"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions": ["cat-cow-flow", "active-thoracic-rotation"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_self_massage_feet', 'self-massage-feet', 'Self-Massage: Feet', 'Zelfmassage voeten', 'recovery', '["feet","plantar_fascia","calves"]', NULL, '["recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_ankle"]', '["none"]', NULL, '{"steps":["Sit comfortably and cross one foot over opposite knee","Use thumbs to apply firm pressure to the arch","Work from heel to ball of foot in small circles","Flex and point toes between each pass","Switch feet — 2 minutes each"],"cues":["Feels incredible after a long day or during pregnancy swelling","A tennis ball or small massage ball makes this easier","Don''t apply pressure to the ankle itself during pregnancy"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga comfortabel zitten en leg één voet over je andere knie","Geef met je duimen stevige druk op je voetholte","Werk in kleine cirkels van je hiel naar de bal van je voet","Buig en strek je tenen tussen elke baan","Wissel van voet — 2 minuten per voet"],"cues_nl":["Voelt heerlijk na een lange dag of bij gezwollen voeten in de zwangerschap","Met een tennisbal of kleine massagebal gaat dit makkelijker","Geef tijdens de zwangerschap geen druk op de enkel zelf"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["ankle-pumps","foam-roll-calves"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_shuffle_tap', 'shuffle-tap', 'Shuffle Tap', 'Zijpas met tik', 'cardio', '["legs","glutes","calves"]', NULL, '["bodyweight","no_floor","low_impact","quiet","pregnancy_safe","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with feet hip-width","Shuffle step right (step-together-step) and tap right foot","Shuffle step left (step-together-step) and tap left foot","Keep a steady rhythm, 30–60 seconds"],"cues":["Light on your feet","Arms swing naturally","Low-impact lateral cardio"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta met je voeten op heupbreedte","Maak een zijpas naar rechts (stap-sluit-stap) en tik met je rechtervoet","Maak een zijpas naar links (stap-sluit-stap) en tik met je linkervoet","Houd een vast ritme aan, 30–60 seconden"],"cues_nl":["Blijf licht op je voeten","Laat je armen vanzelf meezwaaien","Zijwaartse cardio met weinig impact"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions": ["cross-country-ski-step", "lateral-shuffle-drill"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_side_lying_stretch', 'side-lying-full-stretch', 'Side-Lying Full Body Stretch', 'Volledige stretch op de zij', 'mobility', '["spine","lats","hips","shoulders"]', NULL, '["bodyweight","floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_shoulder","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie on your side with your hips and knees gently stacked","Reach your bottom arm long overhead","Reach your top arm overhead to meet it","Feel the full length of your body stretch","Hold for 30 seconds on each side"],"cues":["Use a pillow between knees for comfort","Perfect with a pregnancy body pillow","Great for sciatic relief"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Lig op je zij met je heupen en knieën losjes boven elkaar","Strek je onderste arm lang boven je hoofd","Breng je bovenste arm ernaartoe, ook boven je hoofd","Voel je lichaam over de hele lengte rekken","Houd 30 seconden per kant vast"],"cues_nl":["Leg voor het comfort een kussen tussen je knieën","Ideaal met een zwangerschapskussen","Fijn bij klachten van je heupzenuw"]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["overhead-reach-stretch","seated-spinal-twist"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_side_lying_hip_abduction', 'side-lying-hip-abduction', 'Side-Lying Hip Abduction', 'Heupabductie op de zij', 'mobility', '["hip_abductors","glutes","pelvic_floor"]', NULL, '["pelvic_floor","floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Lie on your side with your body in a straight line","Keep your top leg straight and your foot flexed","Lift your top leg to hip height (about 45°)","Hold for 1 second","Lower slowly and do 12 reps on each side"],"cues":["Lead with the heel","No hip rolling forward","Supports hip stability during pregnancy"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Lig op je zij met je lichaam in één rechte lijn","Houd je bovenste been gestrekt en trek je tenen naar je toe","Til je bovenste been tot heuphoogte (ongeveer 45°)","Houd 1 seconde vast","Zak langzaam terug en doe 12 herhalingen per kant"],"cues_nl":["Laat je hiel de beweging leiden","Laat je heup niet naar voren rollen","Ondersteunt de stabiliteit van je heupen tijdens de zwangerschap"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["band-lateral-walk","band-hip-abduction-standing","clamshell"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_side_lying_quad_stretch', 'side-lying-quad-stretch', 'Side-Lying Quad Stretch', 'Quadriceps stretch op de zij', 'mobility', '["quadriceps","hip_flexors"]', NULL, '["bodyweight","floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_knee"]', '["none"]', NULL, '{"steps":["Lie on your right side","Bend your left knee and hold your left foot with your left hand","Gently draw your foot toward your buttock","Keep your knees together and your hips stacked","Hold for 20–30 seconds, then switch sides"],"cues":["Great pregnancy alternative to standing quad stretch","Keep core gently engaged","Side-lying is comfortable with a pregnancy pillow"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Ga op je rechterzij liggen","Buig je linkerknie en pak je linkervoet vast met je linkerhand","Trek je voet rustig naar je bil","Houd je knieën bij elkaar en je heupen recht boven elkaar","Houd 20–30 seconden vast en wissel dan van kant"],"cues_nl":["Goed alternatief voor de staande quadriceps stretch tijdens de zwangerschap","Houd je core licht aangespannen","Op je zij liggen is comfortabel met een zwangerschapskussen"]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["foam-roll-quads","standing-quad-stretch"]}', 1, 1742860800000, 1795305600000);
