  ('ex_side_plank', 'side-plank', 'Side Plank', 'Side plank', 'strength', '["obliques","core","hip_abductors"]', NULL, '["bodyweight","floor","low_impact","quiet","loads_shoulder","loads_shoulder"]', '["none"]', NULL, '{"steps":["Lie on your side, forearm on floor under shoulder","Stack feet or stagger them","Lift hips to form a straight line head to feet","Hold position","Repeat other side"],"cues":["Keep hips stacked","Don''t let hips sag or pike","Modify: drop bottom knee to floor"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Ga op je zij liggen met je onderarm op de vloer, onder je schouder","Leg je voeten op elkaar of zet ze achter elkaar","Til je heupen op tot je een rechte lijn vormt van hoofd tot voeten","Houd deze positie vast","Herhaal aan de andere kant"],"cues_nl":["Houd je heupen recht boven elkaar","Laat je heupen niet doorzakken of omhoogkomen","Makkelijker: zet je onderste knie op de vloer"]}', '{"images":["/exercise-media/side-plank/0.jpg","/exercise-media/side-plank/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["plank","modified-plank","side-plank-hip-dip"]}', 1, 1742860800000, 1795305600000);
