  ('ex_single_leg_calf_raise', 'single-leg-calf-raise', 'Single Leg Calf Raise', 'Kuitheffen op één been', 'strength', '["calves","soleus"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_ankle","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand on one foot (hold wall for balance)","Rise onto the ball of your foot","Hold 1 second at the top","Lower slowly","15 reps each side"],"cues":["Full range of motion","Slow descent for maximum effect","Helps with ankle circulation during pregnancy"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Sta op één voet (houd een muur vast voor balans)","Kom omhoog op je voorvoet","Houd bovenin 1 seconde vast","Zak langzaam terug","15 herhalingen per kant"],"cues_nl":["Maak de volledige beweging","Zak langzaam voor het meeste effect","Helpt de doorbloeding van je enkels tijdens de zwangerschap"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["calf-stretch-wall","bent-knee-calf-raise"]}', 1, 1742860800000, 1795305600000);
