  ('ex_single_leg_glute_bridge', 'single-leg-glute-bridge', 'Single Leg Glute Bridge', 'Heupbrug op één been', 'mobility', '["glutes","hamstrings","core","pelvic_floor"]', NULL, '["pelvic_floor","floor","low_impact","quiet","supine","postnatal_safe","sport_support:running","sport_support:football"]', '["none"]', NULL, '{"steps":["Lie on your back with your knees bent","Extend one leg straight","Exhale and lift your hips off the floor using the bent leg","Hold for 1 second","Lower your hips and repeat for 8 reps on each side"],"cues":["Keep hips level — don''t let one side drop","Builds single-leg stability","Progress from supported glute bridge"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Lig op je rug met je knieën gebogen","Strek één been","Adem uit en til je heupen van de vloer met je gebogen been","Houd 1 seconde vast","Laat je heupen zakken en herhaal: 8 herhalingen per kant"],"cues_nl":["Houd je heupen recht: laat geen kant zakken.","Bouwt stabiliteit op één been op.","De stap na de ondersteunde heupbrug."]}', '{"images":["/exercise-media/single-leg-glute-bridge/0.jpg","/exercise-media/single-leg-glute-bridge/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions": ["glute-bridge", "dumbbell-hip-thrust"]}', 1, 1742860800000, 1795305600000);
