  ('ex_sphinx_hold', 'sphinx-hold', 'Sphinx Hold', 'Sfinx houden', 'strength', '["lower_back","core","shoulders"]', NULL, '["bodyweight","floor","low_impact","no_sweat","quiet","prone","loads_shoulder","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie face down, prop on forearms, elbows under shoulders","Press forearms into floor and lift chest slightly","Look forward, neck neutral","Hold the position, breathe normally"],"cues":["Gentle backbend — not aggressive","Great for disc health","Avoid if prone position is uncomfortable"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Lig op je buik en steun op je onderarmen, ellebogen onder je schouders.","Duw je onderarmen in de vloer en til je borst iets op.","Kijk naar voren, nek neutraal.","Houd de positie vast en adem normaal."],"cues_nl":["Een zachte achteroverbuiging, niet geforceerd.","Goed voor je tussenwervelschijven.","Sla over als op je buik liggen oncomfortabel is."]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["superman-hold","cobra-press-up"]}', 1, 1742860800000, 1794873600000);
