  ('ex_sprint_in_place', 'sprint-in-place', 'Sprint in Place', 'Sprinten op de plaats', 'cardio', '["legs","glutes","core","calves"]', NULL, '["bodyweight","no_floor","high_impact","loud","loads_ankle","loads_ankle","loads_knee"]', '["none"]', NULL, '{"steps":["Drive knees up quickly, pumping arms","Lean slightly forward from ankles","Give maximum effort for 20–30 seconds","Rest and repeat"],"cues":["Push the pace — this should feel hard","High impact — not for pregnancy","Great HIIT finisher"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Breng je knieën snel omhoog en pomp met je armen","Leun licht naar voren vanuit je enkels","Geef 20–30 seconden alles","Rust en herhaal"],"cues_nl":["Ga voluit — dit moet zwaar voelen","Hoge impact — niet tijdens de zwangerschap","Ideale HIIT-afsluiter"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 30}', '{"substitutions":["easy-jog-warmup","march-in-place"]}', 1, 1742860800000, 1795305600000);
