  ('ex_squat_pulse', 'squat-pulse', 'Squat Pulse', 'Squat pulseren', 'cardio', '["quadriceps","glutes","calves"]', NULL, '["bodyweight","no_floor","low_impact","quiet","pregnancy_safe","postnatal_safe","loads_knee","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Lower into a squat position (parallel or above parallel)","Pulse up and down in small movements — about 5cm range","Keep the tension through the thighs","Pulse for 20–30 seconds"],"cues":["Don''t straighten up — stay in the range","Burns quickly!","Excellent for glute and quad endurance"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Zak in een squat (bovenbenen horizontaal of iets hoger)","Pulseer in kleine bewegingen op en neer — ongeveer 5 cm","Houd de spanning op je bovenbenen","Pulseer 20–30 seconden"],"cues_nl":["Kom niet helemaal omhoog — blijf in dat kleine bereik","Dit brandt snel!","Heel goed voor het uithoudingsvermogen van je bilspieren en bovenbenen"]}', NULL, '{"supports":["time","reps"]}', '{"substitutions":["march-in-place","step-touch"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_standing_bicycle', 'standing-bicycle', 'Standing Bicycle', 'Staande bicycle (knie naar elleboog)', 'cardio', '["obliques","hip_flexors","core"]', NULL, '["bodyweight","no_floor","low_impact","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Stand with hands behind head, elbows wide","Raise right knee while rotating left elbow toward it","Alternate sides in slow bicycle rhythm"],"cues":["Rotate from the waist, not just the elbow","Keep core gently braced","Much lower impact than floor crunches"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta met je handen achter je hoofd, ellebogen wijd","Til je rechterknie op en draai je linkerelleboog ernaartoe","Wissel van kant in een rustig fietsritme"],"cues_nl":["Draai vanuit je taille, niet alleen met je elleboog","Houd je core licht aangespannen","Veel minder belastend dan crunches op de vloer"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions": ["alternating-front-kick", "speed-bag-simulation", "bicycle-crunch"]}', 1, 1742860800000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_standing_figure_four', 'standing-figure-four', 'Standing Figure Four', 'Figuur-4 stretch staand', 'mobility', '["glutes","piriformis","hip_abductors"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Stand on your right foot and hold a wall for balance","Cross your left ankle over your right knee to form a 4 shape","Sit back as if sitting down in a chair","Feel the stretch in your left glute","Hold for 20–30 seconds, then switch sides"],"cues":["Stand tall — don''t hunch forward","Great alternative to pigeon pose during pregnancy","Piriformis target — helps sciatic discomfort"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Sta op je rechtervoet en houd je vast aan een muur voor balans","Leg je linkerenkel over je rechterknie, zodat je benen een 4 vormen","Zak naar achteren alsof je op een stoel gaat zitten","Voel de rek in je linkerbil","Houd 20–30 seconden vast en wissel dan van kant"],"cues_nl":["Blijf lang — krom je rug niet naar voren","Goed alternatief voor de duif tijdens de zwangerschap","Gericht op de piriformis — helpt bij ongemak rond de heupzenuw"]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["supine-figure-four","clamshell"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_standing_hamstring_stretch', 'standing-hamstring-stretch', 'Standing Hamstring Stretch', 'Hamstring stretch staand', 'mobility', '["hamstrings","calves"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand behind a chair and hold it for support","Extend one leg forward with your heel on the floor and your foot flexed","Hinge forward gently from your hips with a flat back","Feel the stretch behind your thigh","Hold for 20–30 seconds, then stand up and switch legs"],"cues":["Don''t round the back","Keep hips square","Great when bending to floor becomes uncomfortable in pregnancy"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Ga achter een stoel staan en houd die vast voor steun","Zet één been gestrekt naar voren met je hiel op de vloer en je tenen omhoog","Buig rustig naar voren vanuit je heupen met een rechte rug","Voel de rek aan de achterkant van je bovenbeen","Houd 20–30 seconden vast, kom omhoog en wissel van been"],"cues_nl":["Maak je rug niet bol","Houd je heupen recht naar voren","Fijn als bukken naar de vloer lastig wordt tijdens de zwangerschap"]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["lying-hamstring-stretch","seated-straddle-stretch"]}', 1, 1742860800000, 1795305600000);
