  ('ex_standing_hip_abduction', 'standing-hip-abduction', 'Standing Hip Abduction', 'Heupabductie staand', 'strength', '["hip_abductors","glutes"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Stand on one foot (hold wall for balance)","Slowly raise other leg out to the side to hip height","Hold 1 second","Lower slowly","12 reps each side"],"cues":["Keep pelvis level","Foot stays flexed","Excellent for pelvic stability during pregnancy"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Sta op één voet (houd een muur vast voor balans).","Til je andere been langzaam opzij tot heuphoogte.","Houd 1 seconde vast.","Laat langzaam zakken.","12 herhalingen per kant."],"cues_nl":["Houd je bekken recht.","Trek je tenen naar je toe.","Uitstekend voor een stabiel bekken tijdens de zwangerschap."]}', '{"images":["/exercise-media/standing-hip-abduction/0.jpg","/exercise-media/standing-hip-abduction/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions": ["band-lateral-walk", "band-hip-abduction-standing"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_standing_pelvic_rock', 'standing-pelvic-rock', 'Standing Pelvic Rock', 'Bekken wiegen staand', 'mobility', '["lower_back","pelvic_floor","core"]', NULL, '["pelvic_floor","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_lower_back"]', '["none"]', NULL, '{"steps":["Stand with your feet hip-width apart, knees slightly bent and hands on your hips","Gently rock your pelvis forward (arch your lower back slightly)","Then rock your pelvis backward (flatten your lower back)","Find a slow, rhythmic motion","Repeat for 30 to 60 seconds"],"cues":["Think of a gentle rocking motion","Good for lower back tension in pregnancy","Also used during labour for pain relief"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Sta met je voeten op heupbreedte, knieën licht gebogen en handen op je heupen","Kantel je bekken rustig naar voren (je onderrug wordt iets hol)","Kantel je bekken daarna naar achteren (je onderrug wordt vlak)","Zoek een langzame, ritmische beweging","Herhaal 30 tot 60 seconden"],"cues_nl":["Denk aan een zachte wiegende beweging","Goed bij een gespannen onderrug tijdens de zwangerschap","Wordt ook gebruikt tijdens de bevalling om pijn te verlichten"]}', '{"images":["/exercise-media/standing-pelvic-rock/0.jpg","/exercise-media/standing-pelvic-rock/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time","reps"]}', '{"substitutions":["seated-pelvic-roll","cat-cow-pregnancy"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_standing_side_stretch', 'standing-side-stretch', 'Standing Side Stretch', 'Zijstretch staand', 'mobility', '["obliques","lats","intercostals"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_shoulder"]', '["none"]', NULL, '{"steps":["Stand with your feet hip-width apart","Reach your right arm overhead and lean gently to the left","Feel the stretch along your right side from hip to fingertips","Hold for 20 seconds, then switch sides"],"cues":["Don''t rotate — pure side bend","Keep feet grounded","Feels wonderful as pregnancy belly grows"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Sta met je voeten op heupbreedte","Reik met je rechterarm boven je hoofd en leun rustig naar links","Voel de rek langs je rechterzij, van je heup tot je vingertoppen","Houd 20 seconden vast en wissel dan van kant"],"cues_nl":["Niet draaien — alleen opzij buigen","Houd je voeten stevig op de grond","Voelt heerlijk als je zwangere buik groeit"]}', '{"images":["/exercise-media/standing-side-stretch/0.jpg","/exercise-media/standing-side-stretch/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["thread-the-needle","cross-body-shoulder-stretch"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_standing_twist_march', 'standing-twist-march', 'Standing Twist March', 'Staande mars met draai', 'cardio', '["obliques","hip_flexors","core"]', NULL, '["bodyweight","no_floor","low_impact","quiet","pregnancy_safe","postnatal_safe","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with hands behind head","March in place, lifting knees high","As right knee comes up, rotate left shoulder gently toward it","Alternate, keeping rhythm moderate"],"cues":["Don''t crunch — rotate and march","Maintain tall posture","Excellent warm-up movement"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta rechtop met je handen achter je hoofd","Marcheer op de plaats en til je knieën hoog op","Draai je linkerschouder rustig naar je rechterknie als die omhoogkomt","Wissel af in een rustig tempo"],"cues_nl":["Niet crunchen — draaien en marcheren","Blijf lang en rechtop staan","Uitstekende warming-upoefening"]}', NULL, '{"supports":["time","reps"]}', '{"substitutions":["march-in-place","heel-dig-march"]}', 1, 1742860800000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_sumo_squat', 'sumo-squat', 'Sumo Squat', 'Sumo squat', 'strength', '["adductors","glutes","quadriceps"]', NULL, '["bodyweight","no_floor","low_impact","quiet","pregnancy_safe","postnatal_safe","loads_knee","loads_knee"]', '["none"]', NULL, '{"steps":["Stand with feet wider than shoulder-width, toes turned out 45°","Lower hips straight down, keeping knees tracking toes","Pause at bottom","Drive through heels to stand"],"cues":["Chest stays tall","Great inner thigh target","Very pregnancy-friendly — room for belly"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Zet je voeten breder dan schouderbreedte, tenen 45° naar buiten.","Laat je heupen recht omlaag zakken, knieën in lijn met je tenen.","Pauzeer onderin.","Duw via je hielen omhoog."],"cues_nl":["Houd je borst omhoog.","Traint goed je binnenkant dijen.","Heel geschikt tijdens de zwangerschap: ruimte voor je buik."]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["dumbbell-goblet-squat","band-squat","kettlebell-goblet-squat","squat","wall-sit"]}', 1, 1742860800000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_supported_glute_bridge', 'supported-glute-bridge', 'Supported Glute Bridge', 'Heupbrug ondersteund', 'mobility', '["glutes","hamstrings","pelvic_floor","transverse_abdominis"]', NULL, '["pelvic_floor","floor","low_impact","no_sweat","quiet","supine","postnatal_safe"]', '["none"]', NULL, '{"steps":["Lie on your back with your knees bent and your feet flat, hip-width apart","Exhale and engage your pelvic floor and core","Press through your heels to lift your hips until your knees, hips and shoulders form a straight line","Hold for 2 seconds at the top","Lower slowly through your spine"],"cues":["Don''t overextend the back","Squeeze glutes at top","Great postnatal posterior chain activation"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Pelvic Floor","steps_nl":["Lig op je rug met je knieën gebogen en je voeten plat op heupbreedte","Adem uit en span je bekkenbodem en core aan","Duw door je hielen en til je heupen op tot je knieën, heupen en schouders één rechte lijn vormen","Houd bovenaan 2 seconden vast","Zak langzaam terug, wervel voor wervel"],"cues_nl":["Maak je rug niet hol","Span bovenaan je bilspieren aan","Goede oefening om na de bevalling de achterkant van je lichaam te activeren"]}', '{"images":["/exercise-media/supported-glute-bridge/0.jpg","/exercise-media/supported-glute-bridge/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions": ["dumbbell-hip-thrust", "reverse-plank"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_supported_side_rest', 'supported-side-lying-rest', 'Supported Side-Lying Rest', 'Ondersteund rusten op de zij', 'recovery', '["nervous_system","full_body"]', NULL, '["recovery","floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Lie on your left side (preferred in pregnancy for circulation)","Place a pillow between your knees","Rest head on a pillow","Allow everything to soften","Stay 5–15 minutes"],"cues":["The pregnancy-safe savasana","Left side improves blood flow to the uterus","Great between contractions in labour too"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga op je linkerzij liggen (heeft in de zwangerschap de voorkeur voor de doorbloeding)","Leg een kussen tussen je knieën","Laat je hoofd op een kussen rusten","Laat alles zacht worden","Blijf 5–15 minuten liggen"],"cues_nl":["De zwangerschapsveilige savasana","Op je linkerzij verbetert de doorbloeding van de baarmoeder","Ook fijn tussen weeën tijdens de bevalling"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["savasana","body-scan-meditation"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_supported_wall_squat', 'supported-wall-squat', 'Supported Wall Squat', 'Squat tegen de muur (ondersteund)', 'mobility', '["quadriceps","glutes","hip_flexors","inner_thighs"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","loads_knee","loads_knee"]', '["none"]', NULL, '{"steps":["Stand with your back against a wall, feet hip-width apart and about 30 cm from the wall","Slide down the wall into a seated position (thighs parallel to the floor or higher)","Hold the position and breathe naturally","Slide back up the wall to standing"],"cues":["Also called ''wall squat''","Comfortable supported position for third trimester","Add a block under your heels if calves are tight"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Sta met je rug tegen een muur, voeten op heupbreedte en ongeveer 30 cm van de muur","Glijd langs de muur omlaag tot je zit (bovenbenen evenwijdig aan de vloer of hoger)","Houd deze houding vast en adem rustig door","Glijd langs de muur weer omhoog tot je staat"],"cues_nl":["Ook wel ''wall squat'' genoemd","Comfortabele, ondersteunde houding voor het derde trimester","Leg een blok onder je hielen als je kuiten stijf zijn"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["squat","seated-butterfly"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_tension_release_viz', 'tension-release-visualization', 'Tension Release', 'Spanning loslaten (visualisatie)', 'recovery', '["nervous_system","muscles"]', NULL, '["recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit or lie comfortably","Take a slow breath in and imagine collecting all your tension","As you exhale slowly, imagine the tension leaving your body as mist","Repeat 5–8 times with intention","Notice your body softening with each exhale"],"cues":["Simple and powerful","Works in any position — great for mid-night wakeups","Combine with progressive muscle relaxation"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga comfortabel zitten of liggen","Adem langzaam in en stel je voor dat je al je spanning verzamelt","Adem langzaam uit en stel je voor dat de spanning je lichaam verlaat als mist","Herhaal 5–8 keer met aandacht","Merk op dat je lichaam bij elke uitademing zachter wordt"],"cues_nl":["Eenvoudig en krachtig","Werkt in elke houding — fijn als je ''s nachts wakker wordt","Combineer met progressieve spierontspanning"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["progressive-relaxation-body","supported-side-lying-rest"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_thoracic_ext_chair', 'thoracic-extension-chair', 'Thoracic Extension on Chair', 'Thoracale extensie op stoel', 'mobility', '["thoracic_spine","chest","shoulders"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","sport_support:cycling","sport_support:rowing","sport_mobility:cycling","sport_mobility:rowing","loads_shoulder"]', '["chair"]', NULL, '{"steps":["Sit upright in a sturdy chair","Clasp your hands behind your head with your elbows wide","Gently arch your back over the top edge of the chair back","Hold for 3–5 seconds, then return upright","Repeat 5–8 times, moving slightly up and down your spine"],"cues":["Supported thoracic extension — very gentle","Great for desk workers and pregnancy posture","Don''t force — just let gravity help"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Ga rechtop op een stevige stoel zitten","Vouw je handen achter je hoofd met je ellebogen wijd","Buig je rug rustig achterover over de bovenrand van de rugleuning","Houd 3–5 seconden vast en kom weer rechtop","Herhaal 5–8 keer en schuif steeds iets omhoog of omlaag langs je rug"],"cues_nl":["Ondersteunde strekking van je bovenrug — heel zacht","Fijn voor wie veel achter een bureau zit en voor je houding tijdens de zwangerschap","Niet forceren — laat de zwaartekracht helpen"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["foam-roll-upper-back","thread-the-needle"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_tuck_jump', 'tuck-jump', 'Tuck Jump', 'Tuck jump', 'cardio', '["quadriceps","calves","core"]', NULL, '["bodyweight","no_floor","high_impact","loud","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with feet hip-width","Jump and drive both knees toward chest at the peak","Land softly with knees bent","Go straight into the next rep"],"cues":["Maximum effort jump","Very high impact — not for pregnancy or early postnatal","Great for athletic conditioning"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta met je voeten op heupbreedte","Spring en trek op het hoogste punt beide knieën naar je borst","Land zacht met gebogen knieën","Ga direct door naar de volgende herhaling"],"cues_nl":["Spring met maximale inzet","Zeer hoge impact — niet tijdens de zwangerschap of vlak na de bevalling","Ideaal voor atletische conditie"]}', '{"images":["/exercise-media/tuck-jump/0.jpg","/exercise-media/tuck-jump/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions": ["broad-jump", "counter-movement-jump"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_wall_chest_stretch', 'wall-chest-stretch', 'Wall Chest Stretch', 'Borststretch tegen de muur', 'mobility', '["chest","anterior_deltoids","biceps"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe","sport_support:swimming","sport_mobility:cycling","sport_mobility:swimming","loads_shoulder"]', '["none"]', NULL, '{"steps":["Stand sideways next to a wall","Place your right palm flat on the wall with your arm straight","Gently rotate your body to the left until you feel the stretch in your chest","Hold for 20–30 seconds","Release and switch sides"],"cues":["Keep arm at shoulder height","Very gentle rotation","Great for breastfeeding posture recovery"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Ga zijwaarts naast een muur staan","Zet je rechterhandpalm plat tegen de muur met je arm gestrekt","Draai je lichaam rustig naar links tot je de rek in je borst voelt","Houd 20–30 seconden vast","Laat los en wissel van kant"],"cues_nl":["Houd je arm op schouderhoogte","Draai heel rustig","Fijn om je houding te herstellen na het geven van borstvoeding"]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["cross-body-shoulder-stretch","chest-opener-arms"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_wide_step_touch', 'wide-step-touch', 'Wide Step Touch', 'Brede step touch', 'cardio', '["legs","glutes","core"]', NULL, '["bodyweight","no_floor","low_impact","quiet","pregnancy_safe","postnatal_safe","loads_knee"]', '["none"]', NULL, '{"steps":["Stand tall with your feet together","Step right foot wide to the right","Bring left foot to meet it, touching down briefly","Step left wide to the left","Bring your right foot in to meet it","Add arm raises for intensity"],"cues":["Wider steps = more glute engagement","Keep chest up","Great continuous warm-up movement"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta rechtop met je voeten bij elkaar","Stap met je rechtervoet breed naar rechts","Breng je linkervoet erbij en tik kort de vloer aan","Stap met links breed naar links","Breng je rechtervoet erbij","Breng je armen omhoog voor meer intensiteit"],"cues_nl":["Bredere passen = meer werk voor je bilspieren","Houd je borst omhoog","Ideale doorlopende warming-up"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["step-touch","lateral-knee-raise"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_worlds_greatest_stretch', 'world-greatest-stretch', 'World''s Greatest Stretch', 'World''s greatest stretch', 'mobility', '["hip_flexors","thoracic_spine","hamstrings","glutes"]', NULL, '["bodyweight","floor","low_impact","no_sweat","quiet","sport_mobility:running","sport_mobility:football","sport_mobility:skiing","sport_mobility:crossfit"]', '["none"]', NULL, '{"steps":["From push-up position, step right foot outside right hand","Drop left knee to floor","Rotate right arm toward ceiling, opening chest","Hold 2 seconds, return hand to floor","Repeat on other side — 5 per side"],"cues":["Slow and deliberate","Brilliant full-body mobility sequence","Modify: both knees on floor in lunge position"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Stap vanuit de push-uphouding met je rechtervoet naast de buitenkant van je rechterhand","Laat je linkerknie naar de vloer zakken","Draai je rechterarm naar het plafond en open je borst","Houd 2 seconden vast en zet je hand terug op de vloer","Herhaal aan de andere kant — 5 per kant"],"cues_nl":["Langzaam en bewust","Schitterende mobiliteitsreeks voor je hele lichaam","Aanpassing: beide knieën op de vloer in uitvalspashouding"]}', '{"images":["/exercise-media/world-greatest-stretch/0.jpg","/exercise-media/world-greatest-stretch/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","time"]}', '{"substitutions":["lunge-thoracic-rotation","seated-straddle-stretch"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_yawn_sigh', 'yawn-sigh-breath', 'Yawn & Sigh Breath', 'Geeuw- en zuchtademhaling', 'recovery', '["diaphragm","jaw","nervous_system"]', NULL, '["breathing","recovery","no_floor","low_impact","no_sweat","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Take a big exaggerated yawn — open mouth as wide as possible, inhale fully","At the top, hold for a moment","Release with a long audible sigh — ahhh or haaa","Let the face and shoulders completely drop on the sigh","Repeat 5 times"],"cues":["Yes, fake yawns often trigger real ones","One of the fastest ways to release jaw and neck tension","Excellent for anxiety and labour preparation"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Geeuw groot en overdreven — open je mond zo wijd mogelijk en adem volledig in","Houd bovenaan even vast","Laat los met een lange, hoorbare zucht — ahhh of haaa","Laat bij de zucht je gezicht en schouders helemaal zakken","Herhaal 5 keer"],"cues_nl":["Ja, van een nepgeeuw moet je vaak echt geeuwen","Een van de snelste manieren om spanning in je kaak en nek los te laten","Heel geschikt bij angst en als voorbereiding op de bevalling"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["478-breathing","alternate-nostril-breathing"]}', 1, 1742860800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_cycling_intervals_indoor', 'cycling-intervals-indoor', 'Cycling Intervals (Indoor)', 'Fietsen intervallen (binnen)', 'cardio', '["quads","hamstrings","glutes","cardiovascular_system"]', NULL, '["cardio","low_impact","quiet","indoor","high_intensity","hiit","loads_knee"]', '["indoor_bike","exercise_bike"]', NULL, '{"steps":["Warm up at 70–90W for 5 minutes at 80 RPM — HR should reach 110–120 bpm before the intervals begin.","Effort interval: increase resistance to your maximum sustainable output. Target 150–250W at 90–110 RPM. This should feel like 8–9 out of 10 effort — HR target 160–175 bpm.","Recovery interval: drop to 60–90W at 70–80 RPM. Let HR fall back to 120–130 bpm before the next effort begins. Full recovery makes HIIT effective.","Repeat the effort/recovery pattern. Final 5 minutes: cool down at 60–80W, 75 RPM."],"cues":["💡 Watt targets: beginners 120–160W effort / 60–80W recovery. Intermediate 160–220W / 70–90W. Advanced 200–280W+ / 80–100W.","💡 RPM during efforts: 90–110 revolutions per minute. High cadence maximises cardiovascular stimulus.","💡 HIIT on a bike is joint-friendly — you can push harder than running intervals with lower injury risk","💡 HR 165–175 bpm during effort is the target. If you cannot reach 160 bpm, increase resistance."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Doe een warming-up van 5 minuten op 70–90 W en 80 rpm — je hartslag hoort op 110–120 slagen per minuut te zitten voordat de intervallen beginnen","Inspanningsinterval: verhoog de weerstand tot het maximale vermogen dat je kunt volhouden. Mik op 150–250 W bij 90–110 rpm. Dit voelt als een 8–9 op 10 — streefhartslag 160–175 slagen per minuut","Herstelinterval: zak terug naar 60–90 W bij 70–80 rpm. Laat je hartslag dalen tot 120–130 slagen per minuut voordat de volgende inspanning begint. Volledig herstel maakt HIIT effectief","Herhaal het patroon van inspanning en herstel. Laatste 5 minuten: cooling-down op 60–80 W en 75 rpm"],"cues_nl":["💡 Wattages: beginners 120–160 W inspanning / 60–80 W herstel. Gemiddeld 160–220 W / 70–90 W. Gevorderd 200–280 W of meer / 80–100 W","💡 Trapfrequentie tijdens de inspanning: 90–110 omwentelingen per minuut. Een hoge trapfrequentie prikkelt hart en longen maximaal","💡 HIIT op de fiets is vriendelijk voor je gewrichten — je kunt harder gaan dan bij loopintervallen, met minder kans op blessures","💡 Een hartslag van 165–175 slagen per minuut tijdens de inspanning is het doel. Haal je de 160 niet, verhoog dan de weerstand"]}', NULL, '{"supports":["time"],"base_duration_sec":1080}', '{"substitutions": ["steady-indoor-cycle", "stationary-bike-steady", "cycling-tempo-effort", "cycling-sprint-intervals", "cycling-pyramid-effort"]}', 1, 1743897600000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_easy_run_outdoor', 'easy-run-outdoor', 'Easy Run (Outdoor)', 'Hardlopen rustig (buiten)', 'cardio', '["quads","hamstrings","calves","glutes","cardiovascular_system"]', NULL, '["cardio","high_impact","outdoor","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Start running outdoors at about 7.5 km/h, an easy pace","Adjust your pace until your heart rate settles at 125–135 bpm — this is Zone 2, your aerobic base pace","Stay within 7–9 km/h (6:40–8:30 min/km); your exact Zone 2 speed depends on fitness, so let heart rate be your guide","If your heart rate goes above 135 bpm, slow down by 0.3–0.5 km/h and hold that pace — this is precise Zone 2 training, not failure"],"cues":["💡 Talk test: say a full sentence without gasping. If you cannot, you have left Zone 2 — slow down","💡 Uphill or into the wind your heart rate climbs at the same speed — slow down and let heart rate decide, not pace","💡 Reference range for moderate-fitness runners in Zone 2: 7.5–8.5 km/h","💡 Zone 2 builds your aerobic engine. Slower than it feels right is usually correct on easy days."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Begin buiten te lopen op ongeveer 7,5 km/u, een rustig tempo","Pas je tempo aan tot je hartslag rond de 125–135 slagen per minuut blijft — dit is zone 2, je aerobe basistempo","Blijf tussen 7 en 9 km/u (6:40–8:30 min/km); je exacte zone 2-tempo hangt af van je conditie, dus laat je hartslag leidend zijn","Komt je hartslag boven de 135, ga dan 0,3–0,5 km/u langzamer en houd dat vast — dat is geen falen, maar precies trainen in zone 2"],"cues_nl":["💡 Praattest: zeg een hele zin zonder naar adem te happen. Lukt dat niet, dan zit je boven zone 2 — ga langzamer","💡 Heuvelop of met tegenwind stijgt je hartslag bij dezelfde snelheid — ga langzamer en laat je hartslag beslissen, niet je tempo","💡 Richtwaarde voor lopers met een gemiddelde conditie in zone 2: 7,5–8,5 km/u","💡 Zone 2 bouwt je aerobe motor op. Op rustige dagen is langzamer dan goed voelt meestal precies goed"]}', NULL, '{"supports":["time"],"base_duration_sec":1500}', '{"substitutions": ["tempo-run-outdoor", "run-intervals-outdoor", "treadmill-run-steady", "zone2-easy-run", "brisk-walk"]}', 1, 1743897600000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_rowing_intervals', 'rowing-intervals', 'Rowing Intervals', 'Roeien intervallen', 'cardio', '["legs","back","shoulders","arms","core","cardiovascular_system"]', NULL, '["cardio","strength","low_impact","indoor","full_body","high_intensity","hiit","loads_lower_back","loads_lower_back","loads_shoulder","loads_knee"]', '["rowing_machine"]', NULL, '{"steps":["Warm up with 3–5 minutes at easy pace: 24–26 SPM, split around 2:35–2:45 /500m, HR below 130.","Effort interval: drive hard for the prescribed duration. Target split: under 2:10 /500m at 24–28 SPM. This is near-maximum effort — HR target 165–175 bpm.","Recovery interval: drop to 18–20 SPM at 2:40–2:50 /500m. Let HR fall below 130 before the next effort. Active recovery — keep rowing, do not stop.","Repeat the effort/recovery pattern throughout the session."],"cues":["💡 HIIT rowing split targets: beginners under 2:20 /500m, intermediate under 2:10, advanced under 2:00","💡 SPM during efforts: 24–28 strokes per minute. Increase power, not SPM, to hit your split target","💡 The catch is where power begins: arms straight, shins vertical, weight forward — then legs drive","💡 Rowing HIIT is among the highest caloric-burn HIIT modalities — 800–1000 kcal/hr at max effort"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Roei je 3–5 minuten warm in een rustig tempo: 24–26 SPM, split rond 2:35–2:45 /500 m, hartslag onder 130","Inspanningsinterval: zet krachtig af voor de opgegeven duur. Richtsplit: onder 2:10 /500 m bij 24–28 SPM. Dit is bijna maximale inspanning — richthartslag 165–175 bpm","Herstelinterval: zak naar 18–20 SPM op 2:40–2:50 /500 m. Laat je hartslag onder 130 zakken voor de volgende inspanning. Actief herstel — blijf roeien, stop niet","Herhaal het patroon van inspanning en herstel de hele sessie"],"cues_nl":["💡 Richtsplits voor HIIT op de roeier: beginners onder 2:20 /500 m, gemiddeld onder 2:10, gevorderd onder 2:00","💡 SPM tijdens inspanningen: 24–28 halen per minuut. Verhoog je kracht, niet je SPM, om je richtsplit te halen","💡 De kracht begint bij de inpik: armen gestrekt, schenen verticaal, gewicht naar voren — daarna zetten je benen af","💡 HIIT op de roeier hoort bij de HIIT-vormen met het hoogste calorieverbruik — 800–1000 kcal/uur bij maximale inspanning"]}', '{"images":["/exercise-media/rowing-intervals/0.jpg","/exercise-media/rowing-intervals/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":1080}', '{"substitutions": ["rowing-steady-state", "rowing-2k-time-trial", "rowing-pyramid-intervals", "rowing-power-strokes"]}', 1, 1743897600000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_rowing_steady', 'rowing-steady-state', 'Rowing — Steady State', 'Roeien constant tempo', 'cardio', '["legs","back","shoulders","arms","core"]', NULL, '["cardio","strength","low_impact","indoor","full_body","zone2","loads_lower_back","loads_lower_back","loads_shoulder","loads_knee"]', '["rowing_machine"]', NULL, '{"steps":["Set resistance so you maintain 18–20 strokes per minute (SPM) at a comfortable, sustained effort.","Target split: 2:20–2:40 per 500m. This is Zone 2 rowing — HR should settle at 125–135 bpm within 5 minutes.","Hold this pace for the full session. If HR rises above 135, reduce stroke rate by 1–2 SPM or reduce drive power.","Focus on the catch-drive-finish-recovery sequence: legs first, then lean back, then arms draw to the lower chest."],"cues":["💡 Talk test applies on the rowing machine too — full sentences should be possible at Zone 2 effort","💡 Split target: 2:25–2:35 /500m is the standard Zone 2 reference for recreational rowers","💡 18–20 SPM: lower stroke rate forces longer, more powerful strokes — this builds aerobic efficiency","💡 Zone 2 rowing is full-body aerobic work: legs (60%), core (20%), arms (20%) at every stroke"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Stel de weerstand zo in dat je 18–20 halen per minuut (SPM) volhoudt op een comfortabele, constante inspanning","Richtsplit: 2:20–2:40 per 500 m. Dit is roeien in zone 2 — je hartslag hoort binnen 5 minuten uit te komen op 125–135 bpm","Houd dit tempo de hele sessie vast. Komt je hartslag boven 135, verlaag dan je haalfrequentie met 1–2 SPM of zet minder krachtig af","Let op de volgorde inpik, haal, uitpik, herstel: eerst je benen, dan achteroverleunen, dan trekken je armen naar je onderborst"],"cues_nl":["💡 De praattest werkt ook op de roeier — in zone 2 moet je hele zinnen kunnen zeggen","💡 Richtsplit: 2:25–2:35 /500 m is de gangbare zone 2-referentie voor recreatieve roeiers","💡 18–20 SPM: een lagere haalfrequentie dwingt je tot langere, krachtigere halen — zo bouw je aerobe efficiëntie op","💡 Roeien in zone 2 is aeroob werk voor je hele lichaam: benen (60%), core (20%), armen (20%) bij elke haal"]}', '{"images":["/exercise-media/rowing-steady-state/0.jpg","/exercise-media/rowing-steady-state/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":1200}', '{"substitutions": ["rowing-intervals", "steady-indoor-cycle", "rowing-2k-time-trial", "rowing-pyramid-intervals", "rowing-technique-drill"]}', 1, 1743897600000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_run_intervals_outdoor', 'run-intervals-outdoor', 'Running Intervals (Outdoor)', 'Hardlopen intervallen (buiten)', 'cardio', '["quads","hamstrings","calves","glutes","cardiovascular_system"]', NULL, '["cardio","high_impact","outdoor","high_intensity","hiit","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Warm up with a 5-minute easy jog","Run fast for 60 seconds — a hard effort, controlled but challenging","Recover for 90 seconds with a walk or a very easy jog","Repeat the hard effort and the recovery for the rounds of your session","Cool down with a 3-minute easy walk"],"cues":["Hard effort = you could not have a conversation","Recovery must be genuinely easy — it prepares the next rep","Focus on keeping form during hard effort: tall, relaxed, quick feet","💡 Beginner: 5 rounds · hard pace 5:30–6:30 min/km","💡 Intermediate: 8 rounds · hard pace 4:30–5:00 min/km","💡 Advanced: 10–12 rounds · hard pace 3:45–4:15 min/km"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Doe een warming-up van 5 minuten rustig joggen","Loop 60 seconden hard — een zware inspanning, beheerst maar uitdagend","Herstel 90 seconden met wandelen of heel rustig joggen","Herhaal de inspanning en het herstel voor de rondes van je sessie","Sluit af met een cooling-down van 3 minuten rustig wandelen"],"cues_nl":["Zware inspanning = je zou geen gesprek kunnen voeren","Het herstel moet echt rustig zijn — het bereidt je voor op de volgende herhaling","Let tijdens de zware inspanning op je techniek: lang, ontspannen, snelle voeten","💡 Beginner: 5 rondes · snel tempo 5:30–6:30 min/km","💡 Gemiddeld: 8 rondes · snel tempo 4:30–5:00 min/km","💡 Gevorderd: 10–12 rondes · snel tempo 3:45–4:15 min/km"]}', NULL, '{"supports":["time"],"base_duration_sec":1200}', '{"substitutions": ["easy-run-outdoor", "tempo-run-outdoor", "treadmill-run-steady", "fartlek-run", "hill-repeats-running"]}', 1, 1743897600000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_stationary_bike_steady', 'stationary-bike-steady', 'Stationary Bike — Steady Ride', 'Fietsen constant (hometrainer)', 'cardio', '["quads","hamstrings","glutes","calves"]', NULL, '["cardio","low_impact","quiet","indoor","loads_knee","loads_ankle"]', '["exercise_bike","indoor_bike"]', NULL, '{"steps":["Adjust seat height so your knee is almost straight at the bottom of the pedal stroke","Start at low resistance and spin for 3–4 minutes to warm up","Increase resistance to your target level and find a steady rhythm","Maintain a cadence of 70–90 rpm","Every 5 minutes, check your effort — increase resistance slightly if it feels too easy","Last 3 minutes: reduce resistance and cool down"],"cues":["Sit tall — don''t hunch over the handlebars","Engage your core lightly throughout","Focus on smooth, even pressure through both legs","💡 Beginner: light–moderate resistance · RPE 4–5 · ~30 min","💡 Intermediate: moderate resistance · RPE 6 · ~40 min","💡 Advanced: moderate–heavy resistance · RPE 7 · ~50 min"],"pregnancy_note":"Stay at conversational effort (RPE ≤ 5). Upright bikes are usually more comfortable than recumbent in late pregnancy.","why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Stel de zadelhoogte zo in dat je knie bijna gestrekt is onderaan de trapbeweging","Begin op lage weerstand en trap 3–4 minuten los als warming-up","Verhoog de weerstand tot je doelniveau en zoek een vast ritme","Houd een trapfrequentie van 70–90 rpm aan","Check elke 5 minuten je inspanning — zet de weerstand iets hoger als het te makkelijk voelt","Laatste 3 minuten: verlaag de weerstand en fiets uit"],"cues_nl":["Zit rechtop — hang niet over het stuur","Span je core de hele tijd licht aan","Let op een soepele, gelijkmatige druk met beide benen","💡 Beginner: lichte tot gemiddelde weerstand · RPE 4–5 · ~30 min","💡 Gemiddeld: gemiddelde weerstand · RPE 6 · ~40 min","💡 Gevorderd: gemiddelde tot zware weerstand · RPE 7 · ~50 min"],"pregnancy_note_nl":"Blijf op een inspanning waarbij je kunt praten (RPE ≤ 5). Een rechtop zittende fiets is laat in de zwangerschap meestal comfortabeler dan een ligfiets."}', '{"images":["/exercise-media/stationary-bike-steady/0.jpg","/exercise-media/stationary-bike-steady/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":1200}', '{"substitutions":["steady-indoor-cycle","cycling-intervals-indoor","cycling-zone2-ride","static-bike-zone2"]}', 1, 1743897600000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_steady_indoor_cycle', 'steady-indoor-cycle', 'Steady Indoor Cycling', 'Fietsen constant (indoorfiets)', 'cardio', '["quads","hamstrings","glutes","calves"]', NULL, '["cardio","low_impact","quiet","indoor","loads_knee","loads_ankle"]', '["indoor_bike"]', NULL, '{"steps":["Set your bike up — saddle height so your knee has a slight bend at the bottom of the pedal stroke","Start with 5 minutes easy spinning at 80–90 rpm to warm up","Settle into your target power or perceived effort and hold it steadily","Check in every 5 minutes — adjust resistance if drifting","Keep cadence above 80 rpm throughout","Final 3–5 minutes: drop resistance and spin easy to cool down"],"cues":["Smooth circles — push forward over the top, pull back at the bottom","Relax your grip and shoulders — your legs do the work","Breathe rhythmically — match breath to pedal stroke","💡 Beginner: 70–100 W · 80–90 rpm · RPE 4–5","💡 Intermediate: 120–155 W · 85–95 rpm · RPE 6","💡 Advanced: 170–230 W · 90–100 rpm · RPE 7"],"pregnancy_note":"Keep effort conversational (RPE ≤ 5). Stop if you feel dizzy, short of breath, or any pelvic pressure.","why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Stel je fiets af — zadelhoogte zo dat je knie licht gebogen is onderaan de trapbeweging","Begin met 5 minuten rustig trappen op 80–90 rpm als warming-up","Ga naar je doelvermogen of je doelinspanning en houd dat gelijkmatig vast","Check elke 5 minuten — pas de weerstand aan als je afwijkt","Houd je trapfrequentie de hele tijd boven 80 rpm","Laatste 3–5 minuten: verlaag de weerstand en trap rustig uit als cooling-down"],"cues_nl":["Trap soepele cirkels — duw bovenaan naar voren, trek onderaan naar achteren","Ontspan je handen en schouders — je benen doen het werk","Adem ritmisch — stem je ademhaling af op je trapbeweging","💡 Beginner: 70–100 W · 80–90 rpm · RPE 4–5","💡 Gemiddeld: 120–155 W · 85–95 rpm · RPE 6","💡 Gevorderd: 170–230 W · 90–100 rpm · RPE 7"],"pregnancy_note_nl":"Blijf op een inspanning waarbij je kunt praten (RPE ≤ 5). Stop als je duizelig of kortademig wordt of druk in je bekken voelt."}', NULL, '{"supports":["time"],"base_duration_sec":1200}', '{"substitutions": ["stationary-bike-steady", "cycling-intervals-indoor", "rowing-steady-state", "cycling-zone2-ride"]}', 1, 1743897600000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_tempo_run_outdoor', 'tempo-run-outdoor', 'Tempo Run (Outdoor)', 'Hardlopen tempoloop (buiten)', 'cardio', '["quads","hamstrings","calves","glutes","cardiovascular_system"]', NULL, '["cardio","high_impact","outdoor","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Walk or jog easily for 5 minutes to warm up","Build to tempo pace — comfortably hard, not all-out","Maintain this pace for the bulk of the run","Check with the two-word test: you can say two words but not a full sentence","Keep your form: tall posture, slight forward lean, quick light steps","Finish with a 5-minute easy jog or walk to cool down"],"cues":["Tempo = about 80% of max heart rate","If you can chat comfortably, go faster. If gasping, back off.","Think: controlled discomfort — not survival mode","💡 Beginner: 6:00–7:00 min/km · ~25 min (including warm-up/cool-down)","💡 Intermediate: 5:00–5:45 min/km · ~30 min total","💡 Advanced: 4:00–4:45 min/km · ~35 min total"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Wandel of jog 5 minuten rustig als warming-up","Versnel naar je tempolooptempo — comfortabel zwaar, niet voluit","Houd dit tempo het grootste deel van de loop vast","Check met de tweewoordentest: je kunt twee woorden zeggen, maar geen hele zin","Let op je techniek: rechte houding, licht naar voren geleund, snelle lichte passen","Sluit af met 5 minuten rustig joggen of wandelen als cooling-down"],"cues_nl":["Tempo = ongeveer 80% van je maximale hartslag","Kun je makkelijk kletsen, ga dan sneller. Hap je naar adem, doe dan een stap terug","Denk aan: beheerst ongemak — geen overlevingsstand","💡 Beginner: 6:00–7:00 min/km · ~25 min (inclusief warming-up en cooling-down)","💡 Gemiddeld: 5:00–5:45 min/km · ~30 min in totaal","💡 Gevorderd: 4:00–4:45 min/km · ~35 min in totaal"]}', NULL, '{"supports":["time"],"base_duration_sec":1800}', '{"substitutions": ["easy-run-outdoor", "run-intervals-outdoor", "treadmill-run-steady", "fartlek-run"]}', 1, 1743897600000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_treadmill_run_steady', 'treadmill-run-steady', 'Treadmill Run — Steady Pace', 'Hardlopen loopband constant tempo', 'cardio', '["quads","hamstrings","calves","glutes","cardiovascular_system"]', NULL, '["cardio","high_impact","indoor","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["treadmill"]', NULL, '{"steps":["Set incline to 1% — this better replicates outdoor running (compensates for no wind resistance)","Start at a slow walk for 2 minutes, then gradually increase speed","Find your target speed and lock it in","Keep your gaze forward and slightly down — not at your feet","Avoid holding the handrails unless needed for safety","Last 2–3 minutes: reduce speed to a walking cool-down"],"cues":["1% incline is the sweet spot for most runners","Don''t overstride — feet should land under your hips","Shorter, quicker steps are more efficient than long bounds","💡 Beginner: 7.5–8.5 km/h · 1% incline · ~20 min","💡 Intermediate: 9.5–11.0 km/h · 1% incline · ~25 min","💡 Advanced: 12.0–14.5 km/h · 1–2% incline · ~30 min"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Zet de helling op 1% — dat lijkt meer op buiten lopen (het compenseert het ontbreken van windweerstand)","Begin met 2 minuten rustig wandelen en verhoog daarna geleidelijk de snelheid","Zoek je doelsnelheid en houd die vast","Kijk naar voren en iets omlaag — niet naar je voeten","Houd de leuningen niet vast, tenzij het voor je veiligheid nodig is","Laatste 2–3 minuten: verlaag de snelheid en wandel uit als cooling-down"],"cues_nl":["1% helling is voor de meeste lopers precies goed","Maak je passen niet te groot — je voeten horen onder je heupen te landen","Korte, snelle passen zijn efficiënter dan grote sprongen","💡 Beginner: 7,5–8,5 km/u · 1% helling · ~20 min","💡 Gemiddeld: 9,5–11,0 km/u · 1% helling · ~25 min","💡 Gevorderd: 12,0–14,5 km/u · 1–2% helling · ~30 min"]}', '{"images":["/exercise-media/treadmill-run-steady/0.jpg","/exercise-media/treadmill-run-steady/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":1500}', '{"substitutions": ["easy-run-outdoor", "tempo-run-outdoor", "run-intervals-outdoor", "zone2-easy-run", "treadmill-intervals"]}', 1, 1743897600000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_068', '478-breathing', '4-7-8 Breathing', '4-7-8 ademhaling', 'recovery', '["diaphragm","nervous_system"]', NULL, '["recovery","breathing","quiet","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Sit or lie comfortably. Exhale completely through your mouth.","Inhale quietly through your nose for 4 counts.","Hold your breath for 7 counts. Then exhale completely through your mouth for 8 counts. That is one cycle. Repeat 4 times."],"cues":["💡 The extended exhale activates the parasympathetic nervous system — instant calm.","If 7 counts feels too long, scale the ratio: 2-3.5-4, keeping the 1:2 exhale ratio."],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga comfortabel zitten of liggen. Adem volledig uit door je mond","Adem rustig in door je neus in 4 tellen","Houd je adem 7 tellen vast. Adem daarna in 8 tellen volledig uit door je mond. Dat is één cyclus. Herhaal 4 keer"],"cues_nl":["💡 De lange uitademing activeert het parasympathische zenuwstelsel — direct rust","Voelen 7 tellen te lang? Schaal de verhouding: 2-3,5-4, en houd de 1:2-verhouding voor je uitademing aan"]}', NULL, '{"supports":["time"],"base_duration_sec":180}', '{"substitutions":["box-breathing","alternate-nostril-breathing","pursed-lip-breathing","breath-counting","cooling-breath"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_049', 'active-thoracic-rotation', 'Active Thoracic Rotation', 'Thoracale rotatie (actief)', 'mobility', '["thoracic_spine","obliques","rotator_cuff"]', NULL, '["mobility","low_impact","floor","pregnancy_safe","sport_support:cycling","sport_support:rowing","sport_support:climbing","sport_mobility:cycling","sport_mobility:swimming","sport_mobility:rowing","sport_mobility:crossfit","loads_shoulder"]', '["none"]', NULL, '{"steps":["Lie on your side in a foetal position, knees stacked and bent to 90°, arms extended in front.","Keeping your knees together and lower body still, rotate your top arm open toward the ceiling and behind you.","Follow your hand with your eyes. Return and repeat. Switch sides after reps."],"cues":["💡 Breathe out as you open — the exhale relaxes the chest and allows more rotation.","The lower body stays completely still — all movement comes from the thoracic spine."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Lig op je zij in foetushouding, knieën op elkaar en 90° gebogen, armen gestrekt voor je","Houd je knieën bij elkaar en je onderlichaam stil. Draai je bovenste arm open richting het plafond en verder naar achteren","Volg je hand met je ogen. Kom terug en herhaal. Wissel na je herhalingen van kant"],"cues_nl":["💡 Adem uit terwijl je opendraait — de uitademing ontspant je borst en geeft meer ruimte om te draaien","Je onderlichaam blijft helemaal stil — alle beweging komt uit je bovenrug"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions": ["seated-thoracic-rotation", "cat-cow-flow", "seated-spinal-twist", "lunge-thoracic-rotation", "foam-roll-upper-back"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_073', 'alternating-front-kick', 'Alternating Front Kick', 'Afwisselende voorwaartse trap', 'cardio', '["hip_flexors","quads","glutes","cardiovascular_system"]', NULL, '["cardio","low_impact","bodyweight","dynamic","no_floor","balance","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand tall, feet hip-width. Shift weight to your left leg.","Kick your right leg forward to hip height (or comfortable height), keeping it reasonably straight. Then lower and switch.","Increase tempo once you have the balance — swing your opposite arm with each kick."],"cues":["💡 Control the lowering phase — don''t let the leg drop back.","Look straight ahead, not down — balance improves immediately."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta rechtop, voeten op heupbreedte. Breng je gewicht naar je linkerbeen.","Trap je rechterbeen naar voren tot heuphoogte (of een comfortabele hoogte) en houd het redelijk gestrekt. Laat het zakken en wissel.","Verhoog het tempo zodra je balans goed is — zwaai bij elke trap je andere arm mee."],"cues_nl":["💡 Laat je been gecontroleerd zakken — laat het niet terugvallen.","Kijk recht vooruit, niet naar beneden — je balans wordt meteen beter."]}', NULL, '{"supports":["time"],"base_duration_sec":30}', '{"substitutions": ["high-knees", "lateral-knee-raise", "standing-bicycle", "reverse-lunge-kick"]}', 1, 1744700000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_019', 'band-bicep-curl', 'Resistance Band Bicep Curl', 'Biceps curl met weerstandsband', 'strength', '["biceps_brachii","brachialis"]', NULL, '["strength","pull","low_impact","no_floor","loads_shoulder"]', '["resistance_bands"]', NULL, '{"steps":["Stand on the center of the band with feet hip-width. Hold one end in each hand with an underhand grip, arms extended at your sides.","Curl both hands toward your shoulders, keeping your elbows pinned to your sides. Maintain steady tension throughout the movement.","Lower slowly — the resistance stays on all the way down, unlike with free weights."],"cues":["💡 Band resistance peaks at full extension and is minimal at the start — the opposite of a dumbbell. Great for end-range bicep strength.","Keep your elbows locked in place. If they drift forward, the work shifts away from the bicep."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga op het midden van de band staan, voeten op heupbreedte. Houd in elke hand een uiteinde vast met een onderhandse greep, armen gestrekt langs je lichaam","Curl beide handen naar je schouders en houd je ellebogen tegen je zij. Houd de hele beweging gelijkmatige spanning","Zak langzaam — de weerstand blijft tot helemaal onderaan, anders dan bij losse gewichten"],"cues_nl":["💡 De band geeft de meeste weerstand als hij maximaal is uitgerekt en bijna geen aan het begin — het omgekeerde van een dumbbell. Ideaal voor bicepskracht aan het einde van de beweging","Houd je ellebogen op hun plek. Schuiven ze naar voren, dan verschuift het werk weg van je biceps"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["dumbbell-bicep-curl","dumbbell-concentration-curl","dumbbell-hammer-curl"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_018', 'band-face-pull', 'Resistance Band Face Pull', 'Face pull met weerstandsband', 'strength', '["rear_deltoid","rotator_cuff","rhomboids","mid_traps"]', NULL, '["strength","pull","low_impact","no_floor","shoulder_health","loads_shoulder","loads_shoulder"]', '["resistance_bands"]', NULL, '{"steps":["Anchor the band at face height. Hold one end in each hand with an overhand grip, arms extended forward.","Pull the band toward your face, driving your elbows wide and high. Your hands should finish level with your ears, elbows above shoulder height.","Return to start with control. Resist the band pulling your hands back together."],"cues":["💡 Face pulls are the antidote to too much pressing — they balance the shoulder and develop the rear deltoid that most people neglect.","Elbows high and wide is the essential cue. If your elbows drop, you are doing a row, not a face pull."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Maak de band vast op gezichtshoogte. Houd in elke hand een uiteinde vast met een bovenhandse greep, armen naar voren gestrekt","Trek de band naar je gezicht en stuur je ellebogen wijd en hoog. Je handen eindigen ter hoogte van je oren, je ellebogen boven schouderhoogte","Ga gecontroleerd terug naar de start. Bied weerstand als de band je handen weer naar elkaar trekt"],"cues_nl":["💡 Face pulls zijn het tegengif voor te veel drukoefeningen — ze brengen je schouder in balans en trainen de achterste schouderspier die de meeste mensen verwaarlozen","Ellebogen hoog en wijd is de belangrijkste aanwijzing. Zakken je ellebogen, dan doe je een row en geen face pull"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions": ["band-pull-apart", "dumbbell-rear-delt-fly", "band-row-seated"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_023', 'band-hip-abduction-standing', 'Band Standing Hip Abduction', 'Heupabductie staand met weerstandsband', 'strength', '["glute_medius","hip_abductors","tensor_fasciae_latae"]', NULL, '["strength","low_impact","glutes","no_floor","sport_support:running","sport_support:football","sport_support:climbing"]', '["resistance_bands"]', NULL, '{"steps":["Anchor the band at ankle height. Loop the other end around one ankle. Stand with the anchor to your side or in front, holding a wall for balance if needed.","Lift your outside leg out to the side against the band, keeping it straight. Your hip drives the movement — not your lower back.","Lower slowly — resist the band pulling your leg in. Complete all reps, then switch sides."],"cues":["💡 This targets the gluteus medius — the hip stabiliser critical for knee alignment when running, landing, and squatting.","Do not tilt your torso as you lift. If you lean, the load has moved from your hip to your back."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Maak de band vast op enkelhoogte en leg het andere uiteinde om één enkel. Sta met het ankerpunt naast of voor je en houd je zo nodig vast aan een muur voor balans","Til je buitenste been gestrekt zijwaarts op tegen de band in. Je heup stuurt de beweging — niet je onderrug","Zak langzaam — bied weerstand als de band je been naar binnen trekt. Doe alle herhalingen en wissel dan van kant"],"cues_nl":["💡 Dit traint de gluteus medius — de heupstabilisator die bepalend is voor de stand van je knie bij hardlopen, landen en squatten","Kantel je romp niet als je je been optilt. Leun je, dan is de belasting van je heup naar je rug verschoven"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["side-lying-hip-abduction","standing-hip-abduction","band-lateral-walk"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_020', 'band-lateral-walk', 'Resistance Band Lateral Walk', 'Zijwaarts lopen met weerstandsband', 'strength', '["glute_medius","hip_abductors","quads"]', NULL, '["strength","low_impact","glutes","no_floor","loads_ankle","sport_support:running","sport_support:swimming","sport_support:football","loads_ankle","loads_knee"]', '["resistance_bands"]', NULL, '{"steps":["Place the band just above your knees. Stand in a half-squat position with feet hip-width — there should be constant tension in the band.","Step to the right with your right foot, then bring your left foot in to maintain the hip-width stance. Do not let feet come together.","Walk the prescribed steps in one direction, maintaining the squat depth throughout, then reverse."],"cues":["💡 Staying in the squat is the exercise — the moment you stand up, the glute work stops completely.","Feel the hip abductor activate as you step out. That is the gluteus medius — a muscle critical for knee and hip stability."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Doe de band net boven je knieën. Sta in een halve squat met je voeten op heupbreedte — er staat steeds spanning op de band","Stap met je rechtervoet naar rechts en haal je linkervoet bij tot je weer op heupbreedte staat. Laat je voeten elkaar niet raken","Loop het opgegeven aantal stappen één kant op en blijf even diep in je squat, ga dan terug"],"cues_nl":["💡 In de squat blijven ís de oefening — zodra je rechtop komt, stopt het werk voor je bilspieren helemaal","Voel de buitenkant van je heup aanspannen als je uitstapt. Dat is de gluteus medius — een spier die bepalend is voor de stabiliteit van je knie en heup"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions": ["standing-hip-abduction", "side-lying-hip-abduction", "band-hip-abduction-standing", "lateral-shuffle-drill", "leg-swings-lateral"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_021', 'band-overhead-press', 'Resistance Band Overhead Press', 'Overhead press met weerstandsband', 'strength', '["anterior_deltoid","medial_deltoid","triceps","upper_traps"]', NULL, '["strength","push","low_impact","no_floor","loads_shoulder","loads_shoulder"]', '["resistance_bands"]', NULL, '{"steps":["Stand on the center of the band with feet shoulder-width. Hold the ends at shoulder height, elbows forward. Create tension in the band before starting.","Press overhead until arms are fully extended. Core braced — do not let your lower back arch as the arms rise.","Lower slowly back to shoulder height, controlling the band the entire way down."],"cues":["💡 The band gets harder as it stretches — the top of the press is the most demanding portion, unlike free weights.","Keep your ribs down throughout. Overhead pressing quickly exposes any lower back weakness."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga op het midden van de band staan, voeten op schouderbreedte. Houd de uiteinden op schouderhoogte, ellebogen naar voren. Zet spanning op de band voordat je begint","Druk omhoog tot je armen helemaal gestrekt zijn. Core aangespannen — laat je onderrug niet hol trekken als je armen omhooggaan","Zak langzaam terug naar schouderhoogte en houd de band de hele weg onder controle"],"cues_nl":["💡 De band wordt zwaarder naarmate hij uitrekt — het bovenste deel van de press is het zwaarst, anders dan bij losse gewichten","Houd je ribben de hele tijd omlaag. Boven je hoofd drukken legt een zwakke onderrug snel bloot"]}', '{"images":["/exercise-media/band-overhead-press/0.jpg","/exercise-media/band-overhead-press/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions": ["dumbbell-shoulder-press", "dumbbell-seated-overhead-press", "dumbbell-arnold-press", "kettlebell-single-arm-press"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_017', 'band-pull-apart', 'Resistance Band Pull-Apart', 'Pull-apart met weerstandsband', 'strength', '["rear_deltoid","rhomboids","lower_traps"]', NULL, '["strength","pull","low_impact","no_floor","shoulder_health","loads_shoulder","loads_shoulder"]', '["resistance_bands"]', NULL, '{"steps":["Hold the band with both hands shoulder-width apart in front of you at shoulder height, arms straight.","Pull the band apart by moving your arms out to the sides until it touches your chest.","Return slowly — resist the band pulling your hands back together."],"cues":["💡 Ideal as a warm-up or between push sets to balance the shoulder.","Keep the movement controlled — a floppy band means no tension."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Houd de band met beide handen op schouderbreedte voor je vast, op schouderhoogte en met gestrekte armen","Trek de band uit elkaar door je armen zijwaarts te bewegen tot hij je borst raakt","Ga langzaam terug — bied weerstand als de band je handen weer naar elkaar trekt"],"cues_nl":["💡 Ideaal als warming-up of tussen sets drukoefeningen om je schouder in balans te houden","Houd de beweging gecontroleerd — een slappe band betekent geen spanning"]}', '{"images":["/exercise-media/band-pull-apart/0.jpg","/exercise-media/band-pull-apart/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions":["band-face-pull","dumbbell-rear-delt-fly"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_016', 'band-row-seated', 'Resistance Band Seated Row', 'Zittende row met band (voet of anker)', 'strength', '["lats","rhomboids","rear_deltoid","biceps"]', NULL, '["strength","pull","low_impact","no_floor","loads_shoulder"]', '["resistance_bands"]', NULL, '{"steps":["Sit on the floor with legs extended. Loop the band around your feet or a fixed anchor. Hold both ends with arms extended, back tall.","Row your elbows back behind you, squeezing your shoulder blades together. Bring your hands to your lower ribcage.","Return with control — resist the band pulling you forward. Do not round your back on the way out."],"cues":["💡 Sit tall the entire time — a rounded spine shifts the load to your lower back instead of your lats.","Pause for a full second at peak contraction before releasing. That pause is where the muscle gets built."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga op de vloer zitten met gestrekte benen. Leg de band om je voeten of om een vast ankerpunt. Houd beide uiteinden vast met gestrekte armen en een rechte rug","Trek je ellebogen naar achteren en knijp je schouderbladen naar elkaar. Breng je handen naar je onderste ribben","Ga gecontroleerd terug — bied weerstand als de band je naar voren trekt. Maak je rug niet bol op de terugweg"],"cues_nl":["💡 Blijf de hele tijd rechtop zitten — bij een bolle rug verschuift de belasting van je lats naar je onderrug","Houd een volle seconde vast op het punt van maximale aanspanning voordat je loslaat. In die pauze wordt de spier opgebouwd"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions": ["dumbbell-single-arm-row", "dumbbell-bent-over-row", "band-face-pull", "dumbbell-row", "pull-up"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_022', 'band-squat', 'Resistance Band Squat', 'Squat met weerstandsband', 'strength', '["quads","glutes","hamstrings"]', NULL, '["strength","low_impact","no_floor","loads_knee","loads_knee"]', '["resistance_bands"]', NULL, '{"steps":["Stand on the center of the band with feet shoulder-width. Hold the ends at shoulder height or crossed over your chest.","Squat down — hips back and down, chest tall, knees tracking over toes. Go to at least parallel depth.","Drive through your heels to stand, feeling the band resistance increase as you approach the top. Squeeze glutes at lockout."],"cues":["💡 Band squats load the top of the movement differently from free weights — this trains lockout strength and hip extension power.","Use the tension at the top as a cue to push your knees out. The band mimics the feedback of a barbell perfectly."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga op het midden van de band staan, voeten op schouderbreedte. Houd de uiteinden op schouderhoogte of gekruist voor je borst","Zak in een squat — heupen naar achteren en omlaag, borst omhoog, knieën in lijn met je tenen. Zak minstens tot je bovenbenen horizontaal zijn","Duw door je hielen om te gaan staan en voel de weerstand van de band toenemen naarmate je hoger komt. Span bovenin je bilspieren aan"],"cues_nl":["💡 Een squat met band belast de top van de beweging anders dan losse gewichten — zo train je kracht in het laatste stuk en explosieve heupstrekking","Gebruik de spanning bovenin als seintje om je knieën naar buiten te duwen. De band geeft precies de feedback die je van een barbell krijgt"]}', '{"images":["/exercise-media/band-squat/0.jpg","/exercise-media/band-squat/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions": ["sumo-squat", "dumbbell-goblet-squat", "wall-sit", "kettlebell-goblet-squat"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_037', 'bear-crawl', 'Bear Crawl', 'Berenkruip', 'strength', '["core","shoulders","quads","hip_flexors"]', NULL, '["strength","core","cardio","low_impact","floor","loads_shoulder","loads_shoulder","loads_knee"]', '["none"]', NULL, '{"steps":["Start on all fours — hands under shoulders, knees under hips. Hover knees 2–3 cm off the floor.","Move forward by stepping right hand + left knee simultaneously, then left hand + right knee.","Keep your back flat and hips level — the hover forces your core to stabilize."],"cues":["💡 Slow and controlled beats fast and sloppy — quality movement is the goal.","Reverse crawl (backward) is equally effective and challenges coordination."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Core & Stability","steps_nl":["Begin op handen en knieën — handen onder je schouders, knieën onder je heupen. Til je knieën 2–3 cm van de vloer.","Beweeg naar voren door tegelijk je rechterhand en linkerknie te verplaatsen, daarna je linkerhand en rechterknie.","Houd je rug vlak en je heupen recht — door het zweven moet je core stabiliseren."],"cues_nl":["💡 Langzaam en gecontroleerd wint van snel en slordig — het gaat om goede bewegingen.","Achteruit kruipen werkt net zo goed en vraagt meer coördinatie."]}', NULL, '{"supports":["time"],"base_duration_sec":40}', '{"substitutions":["plank-shoulder-tap","mountain-climber","hollow-body-hold"]}', 1, 1744700000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_080', 'boxing-combination', 'Boxing Combination', 'Bokscombinatie', 'cardio', '["shoulders","triceps","core","cardiovascular_system"]', NULL, '["cardio","low_impact","bodyweight","upper_body","dynamic","no_floor","loads_shoulder","loads_shoulder"]', '["none"]', NULL, '{"steps":["Stand in a fighting stance: left foot slightly forward, knees soft, hands up protecting your face.","Throw a jab-cross-hook-uppercut combination: jab (left straight), cross (right straight), hook (left), uppercut (right).","Reset and repeat. Rotate your hips and pivot your feet with each power punch."],"cues":["💡 Power comes from hip rotation, not arm strength — think of the punch starting at your feet.","Light on your feet between combinations — stay in your athletic stance."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta in vechthouding: linkervoet iets naar voren, knieën zacht, handen omhoog om je gezicht te beschermen.","Sla een combinatie van jab, cross, hoek en uppercut: jab (links recht), cross (rechts recht), hoek (links), uppercut (rechts).","Neem je houding weer aan en herhaal. Draai bij elke krachtstoot je heupen mee en pivoteer op je voeten."],"cues_nl":["💡 Kracht komt uit je heupdraai, niet uit je armen — de stoot begint bij je voeten.","Blijf licht op je voeten tussen de combinaties — blijf in je atletische houding."]}', NULL, '{"supports":["time"],"base_duration_sec":30}', '{"substitutions":["shadow-boxing","speed-bag-simulation","seated-cardio-punch"]}', 1, 1744700000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_087', 'brisk-walk', 'Brisk Walking', 'Stevig wandelen', 'cardio', '["cardiovascular_system","quads","hamstrings","calves","glutes"]', NULL, '["cardio","low_impact","zone2","conditioning","outdoor","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes","treadmill"]', NULL, '{"steps":["Walk at a pace that noticeably elevates your heart rate but still allows full conversation.","Swing your arms purposefully and stride forward — not a stroll, a deliberate power walk.","Maintain this effort for the full duration without stopping."],"cues":["💡 Brisk walking at Zone 2 intensity provides cardiovascular benefit with minimal joint impact.","Ideal starting point for beginners, or as active recovery for trained athletes."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Wandel in een tempo waarbij je hartslag merkbaar omhooggaat, maar je nog gewoon een gesprek kunt voeren","Zwaai je armen actief mee en zet stevige passen — geen slenteren, maar doelbewust doorstappen","Houd deze inspanning de hele duur vol zonder te stoppen"],"cues_nl":["💡 Stevig wandelen in zone 2 traint je hart en longen en belast je gewrichten nauwelijks","Ideaal om mee te beginnen, of als actief herstel voor getrainde sporters"]}', NULL, '{"supports":["time"],"base_duration_sec":1800}', '{"substitutions": ["zone2-easy-run", "easy-run-outdoor", "cycling-outdoor-easy"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_071', 'broad-jump', 'Broad Jump', 'Verspringen uit stand', 'cardio', '["quads","glutes","calves","hamstrings"]', NULL, '["cardio","high_impact","bodyweight","power","dynamic","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with feet shoulder-width, knees bent in an athletic stance.","Swing your arms back and explosively drive them forward as you jump as far as possible horizontally.","Land softly with bent knees, absorbing the impact through your legs."],"cues":["💡 The arm swing generates 20–30% of the jump distance — don''t skip it.","Stick your landing for a second to build deceleration strength."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta met je voeten op schouderbreedte, knieën gebogen in een atletische houding.","Zwaai je armen naar achteren en breng ze explosief naar voren terwijl je zo ver mogelijk vooruit springt.","Land zacht met gebogen knieën en vang de klap op met je benen."],"cues_nl":["💡 De armzwaai levert 20–30% van je sprongafstand — sla hem niet over.","Houd je landing een seconde vast om afremkracht op te bouwen."]}', '{"images":["/exercise-media/broad-jump/0.jpg","/exercise-media/broad-jump/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions": ["jump-squat", "tuck-jump", "power-step-up-jump", "counter-movement-jump"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_048', 'calf-stretch-wall', 'Calf Stretch (Wall)', 'Kuitstretch tegen de muur', 'mobility', '["gastrocnemius","soleus","achilles_tendon"]', NULL, '["mobility","low_impact","no_floor","pregnancy_safe","postnatal_safe","sport_mobility:running","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand facing a wall, arms extended, hands flat on the wall at chest height. Step one foot back about 60-90 cm, keeping it pointing straight forward and the heel flat on the floor.","Lean gently into the wall by bending your front knee, keeping the rear knee straight and the rear heel grounded. Feel the stretch in the calf of the rear leg (gastrocnemius stretch).","After 20-30 seconds, slightly bend the rear knee — keeping the heel down. This shifts the stretch deeper into the lower calf (soleus). Hold another 20 seconds.","Switch legs and repeat."],"cues":["Both versions matter: straight knee targets the gastrocnemius (upper calf), bent knee targets the soleus (lower calf). Neither replaces the other.","Heel stays down throughout — if it rises, step closer to the wall.","💡 Tight calves are a major contributor to plantar fasciitis, Achilles issues, and knee pain. This stretch is worth doing daily, especially for runners."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Ga met je gezicht naar een muur staan, armen gestrekt, handen plat tegen de muur op borsthoogte. Zet één voet ongeveer 60–90 cm naar achteren, met je tenen recht naar voren en je hiel plat op de vloer","Leun rustig naar de muur door je voorste knie te buigen. Houd je achterste knie gestrekt en je achterste hiel op de grond. Voel de rek in de kuit van je achterste been (rek van de gastrocnemius)","Buig na 20–30 seconden je achterste knie een beetje — je hiel blijft op de vloer. Zo verschuift de rek dieper naar je onderste kuit (soleus). Houd nog 20 seconden vast","Wissel van been en herhaal"],"cues_nl":["Beide versies tellen: met gestrekte knie rek je de gastrocnemius (bovenste kuit), met gebogen knie de soleus (onderste kuit). De een vervangt de ander niet","Je hiel blijft de hele tijd op de vloer — komt hij los, ga dan dichter bij de muur staan","💡 Stijve kuiten dragen sterk bij aan fasciitis plantaris, achillespeesklachten en kniepijn. Deze stretch is het waard om elke dag te doen, zeker als je hardloopt"]}', '{"images":["/exercise-media/calf-stretch-wall/0.jpg","/exercise-media/calf-stretch-wall/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":45}', '{"substitutions": ["ankle-mobility-circles", "single-leg-calf-raise", "ankle-pumps", "foam-roll-calves"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_044', 'cat-cow-flow', 'Cat-Cow Spinal Flow', 'Kat-koe met ademhaling', 'mobility', '["erector_spinae","core","spine"]', NULL, '["mobility","low_impact","floor","pregnancy_safe","postnatal_safe","breathing","loads_lower_back"]', '["none"]', NULL, '{"steps":["Start on all fours with your wrists under your shoulders and your knees under your hips, spine neutral","Inhale: let your belly drop toward the floor and gently lift your tailbone and chin (cow)","Exhale: round your spine toward the ceiling and tuck your chin and tailbone (cat)","Repeat slowly"],"cues":["💡 Move with your breath — inhale for cow, exhale for cat.","Move one vertebra at a time — wave through the spine rather than hinging at one spot."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Begin op handen en knieën met je polsen onder je schouders en je knieën onder je heupen, rug neutraal","Adem in: laat je buik naar de vloer zakken en til rustig je stuitje en kin op (koe)","Adem uit: maak je rug bol richting het plafond en trek je kin en stuitje in (kat)","Herhaal langzaam"],"cues_nl":["💡 Beweeg mee met je ademhaling — inademen voor koe, uitademen voor kat","Beweeg wervel voor wervel — laat een golf door je rug gaan in plaats van op één punt te knikken"]}', '{"images":["/exercise-media/cat-cow-flow/0.jpg","/exercise-media/cat-cow-flow/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions": ["seated-thoracic-rotation", "active-thoracic-rotation", "cat-cow-pregnancy", "lunge-thoracic-rotation", "foam-roll-upper-back"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_031', 'chin-up', 'Chin-Up', 'Optrekken onderhands (chin-up)', 'strength', '["biceps_brachii","lats","core"]', NULL, '["strength","pull","low_impact","no_floor","loads_shoulder","loads_shoulder"]', '["pull_up_bar"]', NULL, '{"steps":["Hang from the bar with a supinated grip (palms toward you), hands roughly shoulder-width.","Pull your body up until your chin clears the bar, elbows driving down toward your hips.","Lower with control to a full dead hang."],"cues":["💡 Supinated grip recruits the biceps more — generally easier than pull-ups for beginners.","Same rules as pull-ups: full extension at the bottom, every rep."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Hang aan de stang met een onderhandse greep (handpalmen naar je toe), handen ongeveer op schouderbreedte","Trek jezelf omhoog tot je kin boven de stang is en stuur je ellebogen omlaag richting je heupen","Zak gecontroleerd tot je weer volledig gestrekt hangt"],"cues_nl":["💡 Met een onderhandse greep doen je biceps meer mee — voor beginners meestal makkelijker dan pull-ups","Dezelfde regels als bij pull-ups: onderin helemaal strekken, elke herhaling"]}', '{"images":["/exercise-media/chin-up/0.jpg","/exercise-media/chin-up/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions":["pull-up","inverted-row-table","dumbbell-single-arm-row"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_043', 'couch-stretch', 'Couch Stretch', 'Couch stretch', 'mobility', '["hip_flexors","quads","psoas"]', NULL, '["mobility","low_impact","floor","sport_support:cycling","sport_mobility:running","sport_mobility:cycling","sport_mobility:rowing","sport_mobility:skiing","loads_knee"]', '["none"]', NULL, '{"steps":["Kneel with your back to a wall or sofa. Slide your rear foot up the wall so the top of your foot and shin are resting against it — this stretches the hip flexor of that rear leg.","Bring your front foot forward and plant it flat on the floor so your front knee is directly over your ankle, thigh roughly parallel to the floor.","Squeeze the glute of the rear leg firmly and tuck your pelvis slightly. This activates the stretch — without the glute squeeze you will just feel it in your knee, not your hip flexor.","Hold for 60-90 seconds, breathing steadily. Switch sides."],"cues":["Squeezing the glute of the rear leg is not optional — it is what moves the stretch from the knee to the hip flexor where it belongs.","Upright torso throughout — if you are leaning forward, bring your front foot further out.","💡 💡 One of the most effective hip flexor stretches available — essential for runners, cyclists, and anyone who sits. 60-90 seconds per side minimum to see results."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Kniel met je rug naar een muur of bank. Schuif je achterste voet omhoog langs de muur tot je wreef en scheen ertegenaan liggen — zo rek je de heupbuiger van dat achterste been","Zet je voorste voet naar voren, plat op de vloer, met je voorste knie recht boven je enkel en je bovenbeen ongeveer evenwijdig aan de vloer","Span de bilspier van je achterste been stevig aan en kantel je bekken iets. Dat zet de rek aan — zonder aangespannen bil voel je het alleen in je knie en niet in je heupbuiger","Houd 60-90 seconden vast en adem rustig door. Wissel van kant"],"cues_nl":["De bilspier van je achterste been aanspannen is geen extraatje: het verplaatst de rek van je knie naar je heupbuiger, waar hij hoort","Houd je bovenlichaam de hele tijd rechtop — leun je naar voren, zet dan je voorste voet verder naar voren","💡 💡 Een van de effectiefste stretches voor je heupbuigers — onmisbaar voor hardlopers, fietsers en iedereen die veel zit. Minimaal 60-90 seconden per kant om resultaat te zien"]}', NULL, '{"supports":["time"],"base_duration_sec":60}', '{"substitutions": ["hip-flexor-stretch", "half-kneeling-hip-opener", "ninety-ninety-hip-switch", "leg-swings-front-back", "foam-roll-hip-flexors"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_072', 'cross-country-ski-step', 'Cross-Country Ski Step', 'Langlaufpas', 'cardio', '["hip_flexors","glutes","shoulders","cardiovascular_system"]', NULL, '["cardio","low_impact","bodyweight","dynamic","no_floor","loads_shoulder"]', '["none"]', NULL, '{"steps":["Stand with feet staggered, one foot forward, one back. Arms opposite to feet (right arm forward if left foot is forward).","Simultaneously switch your feet and arms in a scissoring motion — like cross-country skiing.","Keep the movement smooth and rhythmic, driving your arms for momentum."],"cues":["💡 Low-impact version of a sprint in terms of cardiovascular demand.","Keep the step width small and quick — bigger steps are harder to sustain."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta met je voeten in spreidstand, één voet voor en één achter. Armen tegengesteld aan je voeten (rechterarm voor als je linkervoet voor staat).","Wissel tegelijk je voeten en armen in een schaarbeweging — zoals bij langlaufen.","Houd de beweging soepel en ritmisch en gebruik je armen voor vaart."],"cues_nl":["💡 Zonder impact, maar qua hartslag net zo zwaar als een sprint.","Houd je passen klein en snel — grote passen hou je minder lang vol."]}', NULL, '{"supports":["time"],"base_duration_sec":30}', '{"substitutions":["grapevine-step","shuffle-tap","lateral-shuffle-drill"]}', 1, 1744700000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_090', 'cycling-hill-climb', 'Cycling Hill Climb Effort', 'Fietsen heuvelklim', 'cardio', '["quads","glutes","hamstrings","calves","core","cardiovascular_system"]', NULL, '["cardio","strength","low_impact","conditioning","indoor","loads_knee","loads_ankle"]', '["road_bike","mountain_bike","indoor_bike","exercise_bike"]', NULL, '{"steps":["Increase resistance to simulate a 6–10% gradient. Reduce cadence to 60–75 rpm.","Push through the pedals with power — heavier resistance, seated. You can also alternate seated and standing.","Climb for 5–10 minutes, then reduce resistance to spin easy for 3 minutes. Repeat."],"cues":["💡 Climbing builds power and muscular endurance simultaneously.","On a road bike outdoors, pick a real hill and ride tempo effort to the top."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Verhoog de weerstand tot het voelt als een helling van 6–10%. Verlaag je trapfrequentie naar 60–75 rpm","Trap met kracht door — zwaardere weerstand, zittend. Je kunt ook afwisselen tussen zitten en staan","Klim 5–10 minuten en verlaag dan de weerstand om 3 minuten rustig te trappen. Herhaal"],"cues_nl":["💡 Klimmen bouwt kracht en spieruithoudingsvermogen tegelijk op","Buiten op de racefiets: kies een echte heuvel en rijd in tempo-inspanning naar de top"]}', NULL, '{"supports":["time"],"base_duration_sec":1800}', '{"substitutions":["cycling-tempo-effort","cycling-zone2-ride","cycling-sweet-spot"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_099', 'cycling-outdoor-easy', 'Easy Outdoor Ride', 'Fietsen rustig (buiten)', 'cardio', '["quads","hamstrings","glutes","calves","cardiovascular_system"]', NULL, '["cardio","low_impact","zone2","conditioning","outdoor","loads_knee","loads_ankle"]', '["road_bike","mountain_bike"]', NULL, '{"steps":["Set off at an easy, conversational effort — about Zone 2. Pick a flat or gently rolling route.","Maintain 80–90 rpm cadence in a gear that feels manageable but not too easy.","Cool down with a 5-minute very easy spin before stopping."],"cues":["💡 For outdoor cycling, traffic-safe awareness is a skill — plan a safe route in advance.","Shift gears to maintain cadence, not to increase resistance."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Vertrek in een rustig tempo waarbij je kunt praten — ongeveer zone 2. Kies een vlakke of licht glooiende route","Houd een trapfrequentie van 80–90 rpm aan in een versnelling die goed te doen is, maar niet te licht","Sluit af met 5 minuten heel rustig trappen voordat je stopt"],"cues_nl":["💡 Buiten fietsen vraagt om verkeersinzicht — plan vooraf een veilige route","Schakel om je trapfrequentie vast te houden, niet om de weerstand te verhogen"]}', NULL, '{"supports":["time"],"base_duration_sec":3600}', '{"substitutions":["cycling-zone2-ride","cycling-tempo-effort","brisk-walk"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_093', 'cycling-pyramid-effort', 'Cycling Pyramid Intervals', 'Fietsen piramide-intervallen', 'cardio', '["quads","glutes","cardiovascular_system"]', NULL, '["cardio","high_intensity","hiit","low_impact","conditioning","indoor","loads_knee"]', '["road_bike","mountain_bike","indoor_bike","exercise_bike"]', NULL, '{"steps":["After a 5-minute warm-up, build intervals in a pyramid: 1 min hard / 1 min easy, 2 min hard / 2 min easy, 3 min hard / 3 min easy, then back down: 2 min hard / 2 min easy, 1 min hard.","Hard intervals at 90–95% effort. Easy intervals genuinely easy.","Cool down 5 minutes easy."],"cues":["💡 The pyramid structure ensures variety in duration and intensity within a single session.","Mark your effort at each pyramid step and try to sustain the same perceived effort throughout."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Bouw na 5 minuten warming-up de intervallen op als een piramide: 1 min hard / 1 min rustig, 2 min hard / 2 min rustig, 3 min hard / 3 min rustig, en dan weer terug: 2 min hard / 2 min rustig, 1 min hard","Harde intervallen op 90–95% inspanning. Rustige intervallen echt rustig","Fiets 5 minuten rustig uit"],"cues_nl":["💡 De piramide-opbouw zorgt voor afwisseling in duur en intensiteit binnen één training","Let bij elke trede van de piramide op je inspanning en probeer steeds dezelfde gevoelsinspanning vast te houden"]}', NULL, '{"supports":["time"],"base_duration_sec":1980}', '{"substitutions":["cycling-sprint-intervals","cycling-sweet-spot","cycling-intervals-indoor"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_091', 'cycling-sprint-intervals', 'Cycling Sprint Intervals', 'Fietsen sprintintervallen', 'cardio', '["quads","glutes","hamstrings","cardiovascular_system"]', NULL, '["cardio","high_intensity","hiit","low_impact","conditioning","indoor","loads_knee","loads_ankle"]', '["road_bike","mountain_bike","indoor_bike","exercise_bike"]', NULL, '{"steps":["Warm up 5–8 minutes easy spinning. Reach 90+ rpm cadence.","Sprint all-out for 10–20 seconds — maximum effort, maximum cadence.","Recover easy spinning for 90–120 seconds. Repeat 6–10 times."],"cues":["💡 Short sprints train peak power output — the effort must be maximal or the adaptation is lost.","Stand on the pedals for the sprint if on a stationary setup; remain seated on a smart trainer."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Doe een warming-up van 5–8 minuten rustig trappen. Kom op een trapfrequentie van 90 rpm of hoger","Sprint 10–20 seconden voluit — maximale inspanning, maximale trapfrequentie","Herstel 90–120 seconden met rustig trappen. Herhaal 6–10 keer"],"cues_nl":["💡 Korte sprints trainen je piekvermogen — de inspanning moet maximaal zijn, anders mis je het trainingseffect","Ga op een hometrainer op de pedalen staan voor de sprint; blijf op een smart trainer zitten"]}', NULL, '{"supports":["time"],"base_duration_sec":1200}', '{"substitutions":["cycling-intervals-indoor","cycling-pyramid-effort","cycling-tempo-effort"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_092', 'cycling-sweet-spot', 'Cycling Sweet Spot Training', 'Fietsen sweet spot', 'cardio', '["quads","hamstrings","glutes","cardiovascular_system"]', NULL, '["cardio","low_impact","conditioning","indoor","loads_knee"]', '["road_bike","mountain_bike","indoor_bike","exercise_bike"]', NULL, '{"steps":["Target 88–93% of FTP (or perceived effort: 7–7.5 out of 10). Harder than tempo, easier than VO2 max.","Hold this ''sweet spot'' effort in blocks of 10–20 minutes with 5 minutes easy between blocks.","Cadence: 85–95 rpm. Finish with 5 minutes easy cool-down."],"cues":["💡 Sweet spot gives 80% of the adaptation of full threshold riding for 60% of the recovery cost.","Breathing is laboured but rhythmic — you can say a word or two, not sentences."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Mik op 88–93% van je FTP (of op gevoel: 7–7,5 op 10). Zwaarder dan tempo, lichter dan VO2 max","Houd deze ''sweet spot''-inspanning vast in blokken van 10–20 minuten, met 5 minuten rustig trappen tussen de blokken","Trapfrequentie: 85–95 rpm. Sluit af met 5 minuten rustig uitfietsen"],"cues_nl":["💡 Sweet spot levert 80% van het trainingseffect van volle drempeltraining op voor 60% van de herstelkosten","Je ademt zwaar maar ritmisch — een woord of twee lukt, hele zinnen niet"]}', NULL, '{"supports":["time"],"base_duration_sec":2400}', '{"substitutions": ["cycling-tempo-effort", "cycling-hill-climb", "cycling-zone2-ride", "cycling-pyramid-effort"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_089', 'cycling-tempo-effort', 'Cycling Tempo Effort', 'Fietsen tempo', 'cardio', '["quads","hamstrings","glutes","cardiovascular_system"]', NULL, '["cardio","low_impact","conditioning","indoor","loads_knee"]', '["road_bike","mountain_bike","indoor_bike","exercise_bike"]', NULL, '{"steps":["After a 5-minute easy spin warm-up, settle into a ''comfortably hard'' effort — about 75–85% FTP or 7 out of 10 perceived effort.","Maintain this tempo for 15–30 minutes, then cool down with 5 minutes easy spinning.","Breathe rhythmically and check in on your cadence (aim for 85–95 rpm)."],"cues":["💡 Tempo = you can speak 2–3 words, not full sentences.","Focus on a smooth, powerful pedal stroke — no dead spots at top or bottom."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Zoek na 5 minuten rustig infietsen een inspanning op die ''stevig maar vol te houden'' voelt — ongeveer 75–85% van je FTP of een 7 op 10","Houd dit tempo 15–30 minuten vast en fiets daarna 5 minuten rustig uit","Adem ritmisch en let op je trapfrequentie (mik op 85–95 rpm)"],"cues_nl":["💡 Tempo = je kunt 2–3 woorden zeggen, geen hele zinnen","Let op een soepele, krachtige pedaalslag — geen dode punten boven of onder"]}', NULL, '{"supports":["time"],"base_duration_sec":2100}', '{"substitutions": ["cycling-zone2-ride", "cycling-sweet-spot", "cycling-intervals-indoor", "cycling-hill-climb", "cycling-sprint-intervals"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_088', 'cycling-zone2-ride', 'Zone 2 Cycling Ride', 'Fietsen zone 2', 'cardio', '["quads","hamstrings","glutes","calves","cardiovascular_system"]', NULL, '["cardio","low_impact","zone2","conditioning","indoor","quiet","loads_knee","loads_ankle"]', '["road_bike","mountain_bike","indoor_bike","exercise_bike"]', NULL, '{"steps":["Set resistance so you are pedalling at 80–90 rpm at a cadence that feels like a 4–5 out of 10 effort.","Maintain this steady, conversational pace for the full duration.","If using a smart trainer: target 55–70% of FTP. On a road/exercise bike: you should be able to speak in full sentences."],"cues":["💡 Zone 2 builds your aerobic engine — more base = faster everything else later.","Nasal-only breathing is a useful real-time check that you''re in the zone."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Stel de weerstand zo in dat je 80–90 rpm trapt en het voelt als een 4–5 op 10","Houd dit gelijkmatige tempo, waarbij je kunt praten, de hele duur vol","Op een smart trainer: mik op 55–70% van je FTP. Op een racefiets of hometrainer: je moet in hele zinnen kunnen praten"],"cues_nl":["💡 Zone 2 bouwt je aerobe motor op — hoe breder je basis, hoe sneller al het andere later gaat","Alleen door je neus ademen is een handige controle of je nog in de zone zit"]}', NULL, '{"supports":["time"],"base_duration_sec":2400}', '{"substitutions": ["steady-indoor-cycle", "stationary-bike-steady", "cycling-tempo-effort", "cycling-hill-climb", "cycling-sweet-spot"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_033', 'dead-hang', 'Dead Hang', 'Dead hang', 'strength', '["shoulder_girdle","grip","forearms","spine"]', NULL, '["strength","mobility","low_impact","no_floor","shoulder_health","loads_shoulder","loads_shoulder","loads_lower_back"]', '["pull_up_bar"]', NULL, '{"steps":["Grab the bar with both hands just wider than shoulder-width, palms facing away.","Let your body hang fully — allow your shoulders to rise toward your ears (passive hang) or actively depress them (active hang).","Breathe steadily, hold for the prescribed duration, then step down."],"cues":["💡 Passive hang decompresses the spine. Active hang builds shoulder stability. Both are useful.","Build grip strength progressively — start with 20-second holds."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Pak de stang met beide handen iets breder dan schouderbreedte vast, handpalmen van je af","Laat je lichaam volledig hangen — laat je schouders naar je oren komen (passief hangen) of trek ze actief omlaag (actief hangen)","Adem rustig door, houd vast voor de opgegeven tijd en stap dan af"],"cues_nl":["💡 Passief hangen ontlast je wervelkolom. Actief hangen bouwt schouderstabiliteit op. Allebei nuttig","Bouw je knijpkracht stap voor stap op — begin met 20 seconden hangen"]}', NULL, '{"supports":["time"],"base_duration_sec":30}', '{"substitutions": ["scapular-retraction-hang", "pull-up", "foam-roll-lats"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_047', 'deep-squat-hold', 'Deep Squat Hold (Malasana)', 'Diepe squat houden (Malasana)', 'mobility', '["hip_flexors","adductors","ankles","glutes","spine"]', NULL, '["mobility","low_impact","floor","pregnancy_safe","loads_knee","loads_lower_back","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with feet slightly wider than shoulder-width, toes turned out 30-45 degrees. Lower into a full squat — hips below knees — and hold the bottom position.","Press your elbows against the inside of your knees to gently push them outward. Keep your chest up and spine long. Heels should stay flat on the floor.","Hold for the prescribed duration, breathing steadily. If your heels rise, place a folded towel or small weight plate under them while you work on ankle mobility."],"cues":["This position is a baseline of human mobility — if it is uncomfortable, it is a signal that hips, ankles, or thoracic spine need mobility work.","Elbows pressing knees open is both a coaching cue and a stretch — it actively opens the hips from the inside.","💡 💡 Practice daily for 60-second holds. Ankle dorsiflexion is the most common limiting factor — calf stretching and raised heels bridge the gap while you build it."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Sta met je voeten iets breder dan schouderbreedte, tenen 30-45 graden naar buiten. Zak in een volledige squat — heupen lager dan je knieën — en blijf onderin zitten","Duw je ellebogen tegen de binnenkant van je knieën om ze zachtjes naar buiten te drukken. Houd je borst omhoog en je rug lang. Je hielen blijven plat op de vloer","Houd vast voor de opgegeven tijd en adem rustig door. Komen je hielen omhoog, leg er dan een opgevouwen handdoek of kleine halterschijf onder terwijl je aan je enkelmobiliteit werkt"],"cues_nl":["Deze houding is een basis van menselijke mobiliteit — voelt hij oncomfortabel, dan is dat een signaal dat je heupen, enkels of bovenrug mobiliteitswerk nodig hebben","Je knieën openduwen met je ellebogen is een aanwijzing én een stretch — je opent je heupen actief van binnenuit","💡 💡 Oefen dagelijks en houd 60 seconden vast. De buiging van je enkel is meestal de beperkende factor — kuiten rekken en verhoogde hielen overbruggen het gat terwijl je eraan werkt"]}', NULL, '{"supports":["time"],"base_duration_sec":60}', '{"substitutions":["ninety-ninety-hip-switch","seated-butterfly","half-kneeling-hip-opener"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_003', 'dumbbell-arnold-press', 'Dumbbell Arnold Press', 'Dumbbell Arnold press', 'strength', '["anterior_deltoid","medial_deltoid","triceps","upper_traps"]', NULL, '["strength","dumbbell","push","no_floor","low_impact","loads_shoulder","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Sit or stand holding two dumbbells at shoulder height, palms facing your face — as if you just finished a bicep curl.","Press the weights overhead while rotating your palms to face forward. Finish with arms fully extended above your head.","Reverse: lower back to the start position, rotating palms back toward your face. That is one rep."],"cues":["💡 The rotation is the whole point — it recruits all three heads of the deltoid, not just the front like a standard press.","Brace your core at the top. Avoid arching your lower back as the dumbbells reach full extension."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Zit of sta met twee dumbbells op schouderhoogte, handpalmen naar je gezicht — alsof je net een biceps curl hebt afgemaakt","Druk de gewichten omhoog en draai je handpalmen daarbij naar voren. Eindig met je armen volledig gestrekt boven je hoofd","Andersom terug: laat zakken naar de beginpositie en draai je handpalmen weer naar je gezicht. Dat is één herhaling"],"cues_nl":["💡 Om de draai gaat het: die zet alle drie de koppen van je schouderspier aan het werk, niet alleen de voorste zoals bij een gewone press","Span bovenin je core aan. Maak je onderrug niet hol als de dumbbells helemaal boven zijn"]}', '{"images":["/exercise-media/dumbbell-arnold-press/0.jpg","/exercise-media/dumbbell-arnold-press/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions": ["dumbbell-shoulder-press", "dumbbell-seated-overhead-press", "band-overhead-press", "kettlebell-single-arm-press", "kettlebell-halo"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_002', 'dumbbell-bent-over-row', 'Dumbbell Bent-Over Row', 'Dumbbell bent-over row', 'strength', '["lats","rhomboids","rear_deltoid","biceps","erector_spinae"]', NULL, '["strength","dumbbell","pull","low_impact","loads_lower_back","sport_support:running","sport_support:cycling","sport_support:rowing","sport_support:climbing","loads_lower_back","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Stand with feet shoulder-width, hinge at the hips until your torso is near parallel to the floor, knees soft. Hold both dumbbells with a neutral grip.","Row both dumbbells to your lower ribcage simultaneously, driving elbows behind you. Squeeze your upper back hard at the top.","Lower with full control — do not let gravity win the eccentric portion."],"cues":["💡 Your lower back is bracing isometrically the whole time — engage your core before every rep.","If you are bouncing or jerking, the weight is too heavy. Controlled rows build more muscle."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta met je voeten op schouderbreedte en scharnier vanuit je heupen tot je romp bijna horizontaal is, knieën licht gebogen. Houd beide dumbbells vast met je handpalmen naar elkaar toe","Trek beide dumbbells tegelijk naar je onderste ribben en stuur je ellebogen naar achteren. Span bovenin je bovenrug hard aan","Laat volledig gecontroleerd zakken — laat de zwaartekracht het zakken niet overnemen"],"cues_nl":["💡 Je onderrug staat de hele tijd statisch onder spanning — span je core aan voor elke herhaling","Ga je veren of rukken, dan is het gewicht te zwaar. Met gecontroleerde rows bouw je meer spier op"]}', '{"images":["/exercise-media/dumbbell-bent-over-row/0.jpg","/exercise-media/dumbbell-bent-over-row/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions": ["dumbbell-single-arm-row", "band-row-seated", "inverted-row-table"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_005', 'dumbbell-bulgarian-split-squat', 'Dumbbell Bulgarian Split Squat', 'Dumbbell Bulgarian split squat', 'strength', '["quads","glutes","hamstrings","hip_flexors"]', NULL, '["strength","dumbbell","low_impact","unilateral","floor","loads_knee","loads_knee"]', '["dumbbell"]', NULL, '{"steps":["Stand in front of a bench or chair. Place your rear foot on it, laces down. Hold a dumbbell in each hand. Step your front foot forward far enough that your shin stays close to vertical when you descend.","Lower your rear knee toward the floor by bending your front knee. Keep your torso tall throughout — resist the urge to lean forward.","Drive up through your front heel to full hip extension. That is one rep. Complete all reps on one side before switching."],"cues":["💡 Most of the work should be felt in the front leg glute and quad. If you feel it mainly in your knee, step your front foot further forward.","This is a balance challenge as much as a strength exercise — go light until you own the position."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga voor een bank of stoel staan. Leg je achterste voet erop, wreef naar beneden. Houd in elke hand een dumbbell. Zet je voorste voet zo ver naar voren dat je scheen bijna verticaal blijft als je zakt","Laat je achterste knie richting de vloer zakken door je voorste knie te buigen. Houd je romp de hele tijd rechtop — leun niet naar voren","Duw door je voorste hiel omhoog tot je heup volledig gestrekt is. Dat is één herhaling. Doe alle herhalingen aan één kant voordat je wisselt"],"cues_nl":["💡 Je voelt het werk vooral in de bilspier en het bovenbeen van je voorste been. Voel je het vooral in je knie, zet je voorste voet dan verder naar voren","Dit is net zo goed een balansoefening als een krachtoefening — houd het licht tot je de houding beheerst"]}', '{"images":["/exercise-media/dumbbell-bulgarian-split-squat/0.jpg","/exercise-media/dumbbell-bulgarian-split-squat/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions": ["dumbbell-lunge", "reverse-lunge", "dumbbell-side-lunge", "walking-lunge", "pistol-squat-assist"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_011', 'dumbbell-chest-press-floor', 'Dumbbell Floor Chest Press', 'Dumbbell chest press op de vloer', 'strength', '["pectorals","triceps","anterior_deltoid"]', NULL, '["strength","dumbbell","push","floor","low_impact","loads_shoulder","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Lie flat on the floor holding dumbbells above your chest, palms facing forward, upper arms resting on the floor.","Lower the dumbbells until your upper arms touch the floor, pausing briefly. Keep your wrists stacked over your elbows throughout.","Press back up explosively, stopping just before full elbow lockout to keep tension in the chest."],"cues":["💡 The pause at the bottom removes stored elastic energy — every rep starts from nothing, making this harder and more effective than a bench press.","Keep your lower back flat on the floor throughout. No arching."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga plat op de vloer liggen met de dumbbells boven je borst, handpalmen naar voren, bovenarmen rustend op de vloer","Laat de dumbbells zakken tot je bovenarmen de vloer raken en houd even vast. Houd je polsen de hele tijd recht boven je ellebogen","Druk explosief terug omhoog en stop net voordat je ellebogen helemaal gestrekt zijn, zodat de spanning op je borst blijft"],"cues_nl":["💡 Door de pauze onderin verdwijnt de opgeslagen veerkracht — elke herhaling begint vanuit stilstand, wat dit zwaarder en effectiever maakt dan een bench press","Houd je onderrug de hele tijd plat op de vloer. Niet hol trekken"]}', '{"images":["/exercise-media/dumbbell-chest-press-floor/0.jpg","/exercise-media/dumbbell-chest-press-floor/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions":["dumbbell-incline-chest-press","dumbbell-floor-chest-fly"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_012', 'dumbbell-concentration-curl', 'Dumbbell Concentration Curl', 'Dumbbell concentratie curl', 'strength', '["biceps_brachii"]', NULL, '["strength","dumbbell","pull","no_floor","low_impact","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Brace your working arm elbow against the inside of your thigh. Hold the dumbbell hanging straight down, arm fully extended.","Curl the dumbbell toward your shoulder, keeping your upper arm completely still — only your forearm moves. Squeeze hard at the top.","Lower with full control until your arm is fully extended. Complete all reps, then switch sides."],"cues":["💡 Bracing your elbow on your thigh eliminates swinging — it is all bicep, all the time.","Slow down the lowering phase — the eccentric builds as much strength as the curl up."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Zet de elleboog van je werkende arm tegen de binnenkant van je bovenbeen. Laat de dumbbell recht omlaag hangen, arm volledig gestrekt","Curl de dumbbell naar je schouder en houd je bovenarm helemaal stil — alleen je onderarm beweegt. Span bovenin hard aan","Laat volledig gecontroleerd zakken tot je arm weer gestrekt is. Doe alle herhalingen en wissel dan van kant"],"cues_nl":["💡 Met je elleboog tegen je bovenbeen kun je niet zwaaien — je biceps doet al het werk","Zak langzamer — het zakken bouwt net zoveel kracht op als het omhoog curlen"]}', '{"images":["/exercise-media/dumbbell-concentration-curl/0.jpg","/exercise-media/dumbbell-concentration-curl/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions":["dumbbell-bicep-curl","dumbbell-hammer-curl","band-bicep-curl"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_010', 'dumbbell-floor-chest-fly', 'Dumbbell Floor Chest Fly', 'Dumbbell chest fly op de vloer', 'strength', '["pectorals","anterior_deltoid"]', NULL, '["strength","dumbbell","push","floor","low_impact","loads_shoulder","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Lie flat on the floor holding a dumbbell in each hand above your chest. Maintain a slight, permanent bend in your elbows — never fully straight.","Open your arms wide, lowering in an arc until your upper arms touch the floor. Feel the stretch across your chest.","Squeeze your chest to bring the dumbbells back together above your sternum, following the same arc."],"cues":["💡 The floor acts as a natural depth stop — your arms cannot drop past it, which protects your shoulder joint.","Think hugging a large barrel: the motion is an arc, not a press. Chest drives it, not arms."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga plat op de vloer liggen met in elke hand een dumbbell boven je borst. Houd je ellebogen steeds licht gebogen — nooit helemaal gestrekt","Open je armen wijd en laat ze in een boog zakken tot je bovenarmen de vloer raken. Voel de rek over je borst","Span je borst aan en breng de dumbbells via dezelfde boog weer samen boven je borstbeen"],"cues_nl":["💡 De vloer is een natuurlijke dieptestop — je armen kunnen er niet voorbij zakken, en dat beschermt je schoudergewricht","Denk aan het omhelzen van een grote ton: de beweging is een boog, geen drukbeweging. Je borst stuurt, niet je armen"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions":["dumbbell-incline-chest-press","dumbbell-chest-press-floor"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_004', 'dumbbell-goblet-squat', 'Dumbbell Goblet Squat', 'Dumbbell goblet squat', 'strength', '["quads","glutes","core","adductors"]', NULL, '["strength","dumbbell","low_impact","full_body","floor","loads_knee","loads_knee"]', '["dumbbell"]', NULL, '{"steps":["Hold one dumbbell vertically at your chest — both hands cupping the top end.","Stand feet shoulder-width, toes angled out 15–30°. Squat down keeping the dumbbell close to your chest.","Drive through your heels to stand, squeezing your glutes at the top."],"cues":["💡 Chest stays tall — the weight counterbalances you into a deep squat.","Knees track over toes throughout — push them out if they cave."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Houd één dumbbell verticaal voor je borst — beide handen om het bovenste uiteinde","Sta met je voeten op schouderbreedte, tenen 15–30° naar buiten. Zak in een squat en houd de dumbbell dicht bij je borst","Duw door je hielen om te gaan staan en span bovenin je bilspieren aan"],"cues_nl":["💡 Je borst blijft omhoog — het gewicht is een tegenwicht waarmee je diep kunt zakken","Je knieën blijven de hele tijd in lijn met je tenen — duw ze naar buiten als ze naar binnen vallen"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_single"}', '{"substitutions": ["dumbbell-sumo-deadlift", "sumo-squat", "kettlebell-goblet-squat", "band-squat", "back-squat"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_006', 'dumbbell-hip-thrust', 'Dumbbell Hip Thrust', 'Dumbbell hip thrust', 'strength', '["glutes","hamstrings","core"]', NULL, '["strength","dumbbell","low_impact","floor","glutes","sport_support:running","loads_lower_back"]', '["dumbbell"]', NULL, '{"steps":["Sit on the floor with your upper back against a bench, shoulder blades on the edge. Place a dumbbell horizontally across your hips. Feet flat, hip-width apart.","Drive through your heels to push your hips up until your body forms a straight line from knees to shoulders. Squeeze your glutes hard at the top.","Lower your hips back toward the floor with control. That is one rep."],"cues":["💡 The glute squeeze at the top is the whole exercise — a half-contracted glute produces half the benefit.","Tuck your chin slightly and brace your core to avoid over-extending your lower back."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga op de vloer zitten met je bovenrug tegen een bank, schouderbladen op de rand. Leg een dumbbell dwars over je heupen. Voeten plat, op heupbreedte","Duw door je hielen om je heupen omhoog te brengen tot je lichaam een rechte lijn vormt van knieën tot schouders. Span bovenin je bilspieren hard aan","Laat je heupen gecontroleerd terugzakken richting de vloer. Dat is één herhaling"],"cues_nl":["💡 Het aanspannen van je bilspieren bovenin ís de oefening — half aanspannen levert de helft op","Trek je kin iets in en span je core aan, zodat je je onderrug niet overstrekt"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions": ["supported-glute-bridge", "single-leg-glute-bridge", "kettlebell-swing", "reverse-plank"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_009', 'dumbbell-renegade-row', 'Dumbbell Renegade Row', 'Dumbbell renegade row', 'strength', '["lats","core","triceps","rear_deltoid"]', NULL, '["strength","dumbbell","pull","core","floor","loads_shoulder","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Get into a high plank with a dumbbell under each hand. Feet wider than hip-width for stability. Body forms a straight line from head to heels.","Row one dumbbell to your hip while pressing the other into the floor. Keep your hips completely level — resist any rotation or tilting.","Return the dumbbell to the floor, then row the other side. Both sides equal one rep."],"cues":["💡 The anti-rotation demand is the real exercise here. A wobbling hip means your core, not your back, is the limiting factor.","Go lighter than you expect. This is not a heavy rowing movement — it is a plank with a row attached."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Core & Stability","steps_nl":["Ga in een hoge plank staan met een dumbbell onder elke hand. Zet je voeten breder dan heupbreedte voor stabiliteit. Je lichaam vormt een rechte lijn van hoofd tot hielen","Trek één dumbbell naar je heup en druk de andere in de vloer. Houd je heupen helemaal recht — draai of kantel niet mee","Zet de dumbbell terug op de vloer en doe dan de row aan de andere kant. Beide kanten samen is één herhaling"],"cues_nl":["💡 Het tegengaan van de draaiing is hier de echte oefening. Wiebelt je heup, dan is je core de beperkende factor, niet je rug","Pak lichter dan je denkt. Dit is geen zware row — het is een plank met een row erbij"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions":["dumbbell-single-arm-row","plank-shoulder-tap"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_013', 'dumbbell-reverse-curl', 'Dumbbell Reverse Curl', 'Dumbbell reverse curl', 'strength', '["brachialis","brachioradialis","forearms"]', NULL, '["strength","dumbbell","pull","no_floor","low_impact","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Stand tall holding dumbbells with an overhand grip (palms facing down), arms fully extended at your sides.","Curl both dumbbells toward your shoulders, keeping elbows fixed at your sides. The palms-down grip targets the brachialis and forearms more than a standard curl.","Lower slowly — the eccentric with an overhand grip is demanding. Reach full extension between every rep."],"cues":["💡 Weaker here than in a standard curl? Good — you have found a real weak link. This builds forearm thickness most people neglect.","Keep your wrists neutral — do not let them roll under during the curl."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta rechtop met de dumbbells in een bovenhandse greep (handpalmen naar beneden), armen volledig gestrekt langs je lichaam","Curl beide dumbbells naar je schouders en houd je ellebogen vast tegen je zij. Met de handpalmen naar beneden werken je brachialis en onderarmen harder dan bij een gewone curl","Laat langzaam zakken — de weg terug is met een bovenhandse greep pittig. Strek je armen tussen elke herhaling volledig"],"cues_nl":["💡 Minder sterk dan bij een gewone curl? Mooi — dan heb je een echte zwakke schakel gevonden. Dit geeft je onderarmen de dikte die de meeste mensen verwaarlozen","Houd je polsen recht — laat ze tijdens de curl niet naar binnen krullen"]}', '{"images":["/exercise-media/dumbbell-reverse-curl/0.jpg","/exercise-media/dumbbell-reverse-curl/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions":["dumbbell-bicep-curl","dumbbell-hammer-curl"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_014', 'dumbbell-side-lunge', 'Dumbbell Lateral Lunge', 'Dumbbell zijwaartse uitvalspas', 'strength', '["adductors","glutes","quads"]', NULL, '["strength","dumbbell","low_impact","unilateral","no_floor","loads_knee","loads_knee","loads_ankle"]', '["dumbbell"]', NULL, '{"steps":["Stand tall holding a dumbbell at your side. Step wide out to one side, keeping toes pointing forward or slightly out on both feet.","Bend the stepping knee and sit into that hip. Keep the opposite leg straight. Let the dumbbell hang beside the bent knee.","Push off the bent foot to return to standing. Complete all reps on one side, then switch."],"cues":["💡 The lateral motion demands hip abductor strength and inner thigh flexibility — two things most training programs completely miss.","Keep your back flat and chest up as you sit into the lunge. If you round forward, the weight is too heavy."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta rechtop met een dumbbell langs je lichaam. Stap breed opzij en houd de tenen van beide voeten naar voren of iets naar buiten","Buig de knie van het been waarmee je stapt en zak in die heup. Houd je andere been gestrekt. Laat de dumbbell naast je gebogen knie hangen","Duw je af met je gebogen been om weer rechtop te komen. Doe alle herhalingen aan één kant en wissel dan"],"cues_nl":["💡 De zijwaartse beweging vraagt kracht in je heupabductoren en een soepele binnenkant van je bovenbenen — twee dingen die in de meeste trainingsschema''s ontbreken","Houd je rug vlak en je borst omhoog terwijl je in de uitvalspas zakt. Buig je voorover, dan is het gewicht te zwaar"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions": ["lateral-lunge", "dumbbell-lunge", "curtsy-lunge", "dumbbell-bulgarian-split-squat"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_001', 'dumbbell-single-arm-row', 'Dumbbell Single-Arm Row', 'Dumbbell row eenarmig', 'strength', '["lats","rhomboids","rear_deltoid","biceps"]', NULL, '["strength","dumbbell","pull","no_floor","low_impact","loads_lower_back","loads_lower_back","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Step your left foot forward, hinge forward with a flat back and rest your left hand on your left thigh","Hold the dumbbell in your right hand with your arm hanging straight below your shoulder","Row the dumbbell to your hip, keeping your elbow close to your torso","Stop when your upper arm is roughly parallel to the floor","Lower slowly until your arm is fully extended","Complete all reps, then switch sides"],"cues":["💡 Keep your working shoulder level — do not let it rotate up to help the lift.","Elbow to pocket, not elbow to ceiling. The lat does the pulling, not the shoulder."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Zet je linkervoet naar voren, scharnier met een vlakke rug naar voren en steun met je linkerhand op je linkerbovenbeen","Houd de dumbbell in je rechterhand en laat je arm recht onder je schouder hangen","Trek de dumbbell naar je heup en houd je elleboog dicht bij je romp","Stop als je bovenarm ongeveer horizontaal is","Laat langzaam zakken tot je arm volledig gestrekt is","Doe alle herhalingen en wissel dan van kant"],"cues_nl":["💡 Houd je werkende schouder recht — laat hem niet omhoog draaien om mee te helpen","Elleboog naar je broekzak, niet naar het plafond. Je brede rugspier trekt, niet je schouder"]}', '{"images":["/exercise-media/dumbbell-single-arm-row/0.jpg","/exercise-media/dumbbell-single-arm-row/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_single"}', '{"substitutions": ["dumbbell-bent-over-row", "band-row-seated", "dumbbell-renegade-row", "chin-up"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_007', 'dumbbell-single-leg-rdl', 'Dumbbell Single-Leg Romanian Deadlift', 'Dumbbell Romanian deadlift op één been', 'strength', '["hamstrings","glutes","erector_spinae"]', NULL, '["strength","dumbbell","low_impact","unilateral","posterior_chain","loads_lower_back","sport_support:running","sport_support:swimming","sport_support:football","loads_lower_back","loads_knee","loads_ankle"]', '["dumbbell"]', NULL, '{"steps":["Stand tall holding a dumbbell in one or both hands. Shift your weight onto one leg, keeping a soft bend in that knee.","Hinge forward at the hip, letting the dumbbell travel down your standing leg as your non-working leg extends behind you. Keep your hips square — resist rotating.","Return to standing by driving through your heel and squeezing your glute at the top. That is one rep."],"cues":["💡 Think of your back leg and torso as one rigid plank — they move together as a unit, not independently.","The range ends where your hip rotation starts. Do not chase extra depth at the cost of a square pelvis."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta rechtop met een dumbbell in één of beide handen. Breng je gewicht naar één been en houd die knie licht gebogen","Scharnier vanuit je heup naar voren en laat de dumbbell langs je standbeen zakken terwijl je andere been naar achteren strekt. Houd je heupen recht — draai niet mee","Kom terug omhoog door via je hiel te duwen en span bovenin je bilspier aan. Dat is één herhaling"],"cues_nl":["💡 Zie je achterste been en je romp als één stijve plank — ze bewegen samen, niet los van elkaar","De beweging eindigt waar je heup begint te draaien. Ga niet dieper ten koste van een recht bekken"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions": ["dumbbell-romanian-deadlift", "kettlebell-single-leg-rdl", "good-morning-bodyweight", "nordic-hamstring-curl"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_015', 'dumbbell-suitcase-carry', 'Dumbbell Suitcase Carry', 'Dumbbell suitcase carry', 'strength', '["obliques","core","hip_flexors","traps","forearms"]', NULL, '["strength","dumbbell","core","low_impact","no_floor","loads_shoulder","loads_lower_back"]', '["dumbbell"]', NULL, '{"steps":["Hold a single dumbbell in one hand at your side — suitcase style. Stand tall with shoulders level and equal.","Walk forward for the prescribed distance or time, resisting any side-bend toward the weight. Keep your core braced, eyes forward, breathing steady.","At the halfway point, switch hands and return."],"cues":["💡 The challenge is resisting the lean — the moment you tip toward the weight, your core has lost the battle.","Slower and heavier beats fast and light. A loaded carry is a posture and bracing exercise, not a conditioning sprint."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Core & Stability","steps_nl":["Houd één dumbbell in één hand langs je lichaam — zoals een koffer. Sta rechtop met je schouders op gelijke hoogte","Loop vooruit voor de opgegeven afstand of tijd en buig niet opzij naar het gewicht. Houd je core aangespannen, kijk vooruit en adem rustig door","Wissel halverwege van hand en loop terug"],"cues_nl":["💡 De uitdaging is niet opzij te hellen — zodra je naar het gewicht kantelt, heeft je core het verloren","Langzaam en zwaar wint van snel en licht. Dragen met gewicht is een oefening in houding en aanspannen, geen conditiesprint"]}', NULL, '{"supports":["time","weight"],"base_duration_sec":40,"load_type":"dumbbell_single"}', '{"substitutions":["dumbbell-farmers-walk","dumbbell-wood-chop","suitcase-carry"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_008', 'dumbbell-upright-row', 'Dumbbell Upright Row', 'Dumbbell upright row', 'strength', '["medial_deltoid","upper_traps","biceps"]', NULL, '["strength","dumbbell","pull","no_floor","low_impact","loads_shoulder","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Hold dumbbells in front of your thighs, palms facing you, hands close together.","Pull the dumbbells straight up along your body, elbows leading and flaring out to the sides.","Stop when elbows reach shoulder height, then lower slowly."],"cues":["💡 Elbows must stay higher than wrists throughout the movement.","Keep the range of motion comfortable — stop if you feel shoulder impingement."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Houd de dumbbells voor je bovenbenen, handpalmen naar je toe, handen dicht bij elkaar","Trek de dumbbells recht omhoog langs je lichaam; je ellebogen leiden en wijzen naar buiten","Stop als je ellebogen op schouderhoogte zijn en laat dan langzaam zakken"],"cues_nl":["💡 Je ellebogen blijven de hele beweging hoger dan je polsen","Houd de bewegingsuitslag comfortabel — stop als je iets voelt knellen in je schouder"]}', '{"images":["/exercise-media/dumbbell-upright-row/0.jpg","/exercise-media/dumbbell-upright-row/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions": ["dumbbell-lateral-raise", "dumbbell-shrug", "clean-pull", "high-pull"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_082', 'fartlek-run', 'Fartlek Run', 'Hardlopen fartlek', 'cardio', '["cardiovascular_system","quads","hamstrings","calves"]', NULL, '["cardio","high_impact","hiit","conditioning","outdoor","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Start with a 5-minute easy jog warm-up.","Pick a landmark ahead (lamp post, tree, corner) and run hard to it, then jog easy until fully recovered.","Repeat the hard/easy cycle for the session, varying effort and distance randomly."],"cues":["💡 Fartlek (Swedish for ''speed play'') — unstructured intervals that build both speed and endurance.","The recovery should be genuinely easy — not a moderate jog."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Begin met 5 minuten rustig inlopen","Kies een herkenningspunt verderop (lantaarnpaal, boom, hoek), loop er hard naartoe en jog daarna rustig tot je helemaal hersteld bent","Herhaal deze afwisseling van hard en rustig de hele training en varieer willekeurig in inspanning en afstand"],"cues_nl":["💡 Fartlek (Zweeds voor ''vaartspel'') — vrije intervallen die zowel je snelheid als je uithoudingsvermogen opbouwen","Het herstel moet echt rustig zijn — geen gematigd joggen"]}', NULL, '{"supports":["time"],"base_duration_sec":1800}', '{"substitutions": ["run-intervals-outdoor", "tempo-run-outdoor", "zone2-easy-run", "hill-repeats-running", "stride-outs"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_060', 'foam-roll-calves', 'Foam Roll: Calves', 'Foamrollen kuiten', 'recovery', '["gastrocnemius","soleus","achilles_tendon"]', NULL, '["recovery","low_impact","floor","loads_ankle"]', '["foam_roller"]', NULL, '{"steps":["Sit on the floor, roller under your calves. Hands behind you for support.","Lift your hips and roll from ankle to just below the knee, pausing on tight spots.","Cross one ankle over the other to increase pressure on one calf at a time."],"cues":["💡 Rotate your foot in and out to reach different angles of the calf muscle.","Essential after running or cycling — tight calves contribute to heel and knee pain."],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga op de vloer zitten met de roller onder je kuiten. Zet je handen achter je voor steun","Til je heupen op en rol van je enkel tot net onder je knie. Blijf even op strakke plekken","Leg één enkel over de andere om de druk op één kuit te vergroten"],"cues_nl":["💡 Draai je voet naar binnen en naar buiten om je kuitspier onder verschillende hoeken te raken","Onmisbaar na het hardlopen of fietsen — strakke kuiten dragen bij aan hiel- en kniepijn"]}', '{"images":["/exercise-media/foam-roll-calves/0.jpg","/exercise-media/foam-roll-calves/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":90}', '{"substitutions":["calf-stretch-wall","ankle-mobility-circles","foam-roll-quads","foam-roll-hamstrings","self-massage-feet"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_061', 'foam-roll-glutes', 'Foam Roll: Glutes', 'Foamrollen billen', 'recovery', '["gluteus_maximus","piriformis"]', NULL, '["recovery","low_impact","floor"]', '["foam_roller"]', NULL, '{"steps":["Sit on the foam roller, shifted to one side. Cross your right ankle over your left knee to target the right glute.","Lean into the right side and roll back and forth over the glute, pausing on tight spots.","Switch sides after 45 seconds."],"cues":["💡 The piriformis (deep glute) is often the real culprit in hip and back tightness.","More body weight = more pressure. Use your hands to lift slightly if too intense."],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga op de foamroller zitten, iets naar één kant. Leg je rechterenkel over je linkerknie om je rechterbil aan te pakken","Leun naar rechts en rol heen en weer over je bil. Blijf even op strakke plekken","Wissel na 45 seconden van kant"],"cues_nl":["💡 De piriformis (diepe bilspier) is vaak de echte boosdoener bij stijve heupen en een stijve rug","Meer lichaamsgewicht = meer druk. Til jezelf iets op met je handen als het te intens is"]}', '{"images":["/exercise-media/foam-roll-glutes/0.jpg","/exercise-media/foam-roll-glutes/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":90}', '{"substitutions":["supine-figure-four","glute-piriformis-stretch","foam-roll-it-band"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_064', 'foam-roll-hamstrings', 'Foam Roll: Hamstrings', 'Foamrollen hamstrings', 'recovery', '["hamstrings","biceps_femoris"]', NULL, '["recovery","low_impact","floor"]', '["foam_roller"]', NULL, '{"steps":["Sit on the floor, roller under the back of one thigh. Hands behind for support, other leg crossed over for extra pressure.","Roll from just above the knee to just below the glute, pausing on tight spots.","Rotate your leg in and out to hit different fibers."],"cues":["💡 The bulk of the hamstring is in the middle of the thigh — spend most time there.","Crossing one leg over the other doubles the pressure — use this when you need it."],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga op de vloer zitten met de roller onder de achterkant van één bovenbeen. Handen achter je voor steun, je andere been erover gekruist voor extra druk","Rol van net boven je knie tot net onder je bil en blijf even op strakke plekken","Draai je been naar binnen en naar buiten om verschillende vezels te raken"],"cues_nl":["💡 Het grootste deel van je hamstring zit in het midden van je bovenbeen — besteed daar de meeste tijd","Eén been over het andere kruisen verdubbelt de druk — gebruik dit als je het nodig hebt"]}', '{"images":["/exercise-media/foam-roll-hamstrings/0.jpg","/exercise-media/foam-roll-hamstrings/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":90}', '{"substitutions":["lying-hamstring-stretch","seated-hamstring-stretch","foam-roll-calves"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_062', 'foam-roll-hip-flexors', 'Foam Roll: Hip Flexors', 'Foamrollen heupbuigers', 'recovery', '["psoas","iliacus","rectus_femoris"]', NULL, '["recovery","low_impact","floor","loads_knee"]', '["foam_roller"]', NULL, '{"steps":["Lie face down. Position the foam roller under your right hip crease area (just below the pelvis, where the hip flexor meets the thigh).","Prop yourself on your forearms and slowly explore the area just inside and below the hip bone.","Pause on tight spots and breathe. Gently bend and extend your knee to add active pressure release."],"cues":["💡 This is a small, targeted area — move slowly, the tissue is deep.","High-value for runners, cyclists, and anyone who sits for long periods."],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga op je buik liggen. Leg de foamroller onder je rechterlies (net onder je bekken, waar je heupbuiger overgaat in je bovenbeen)","Steun op je onderarmen en verken langzaam het gebied net binnen en onder je heupbot","Blijf op strakke plekken en adem door. Buig en strek rustig je knie om de spanning actief los te maken"],"cues_nl":["💡 Dit is een klein, gericht gebied — beweeg langzaam, het weefsel ligt diep","Veel waard voor hardlopers, fietsers en iedereen die lang zit"]}', NULL, '{"supports":["time"],"base_duration_sec":60}', '{"substitutions":["couch-stretch","hip-flexor-stretch","foam-roll-quads"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_058', 'foam-roll-it-band', 'Foam Roll: IT Band', 'Foamrollen IT-band', 'recovery', '["iliotibial_band","tensor_fasciae_latae","vastus_lateralis"]', NULL, '["recovery","low_impact","floor","loads_knee"]', '["foam_roller"]', NULL, '{"steps":["Lie on your side, foam roller under your outer thigh. Support yourself on one forearm, top foot on the floor for stability.","Roll slowly from just above the knee to just below the hip — go slow; this area is often very sensitive.","Pause on tight spots, breathe, and allow the tissue to release before moving on."],"cues":["💡 The IT band itself doesn''t need direct pressure — you''re targeting the muscles that attach to it.","If too painful, stack both feet on the floor to reduce pressure."],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga op je zij liggen met de foamroller onder de buitenkant van je bovenbeen. Steun op één onderarm, je bovenste voet op de vloer voor stabiliteit","Rol langzaam van net boven je knie tot net onder je heup — rustig aan, dit gebied is vaak erg gevoelig","Blijf op strakke plekken, adem door en laat het weefsel ontspannen voordat je verdergaat"],"cues_nl":["💡 De IT-band zelf heeft geen directe druk nodig — je richt je op de spieren die eraan vastzitten","Te pijnlijk? Zet beide voeten op de vloer om de druk te verminderen"]}', '{"images":["/exercise-media/foam-roll-it-band/0.jpg","/exercise-media/foam-roll-it-band/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":90}', '{"substitutions": ["foam-roll-quads", "glute-piriformis-stretch", "band-lateral-walk", "foam-roll-glutes"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_063', 'foam-roll-lats', 'Foam Roll: Lats', 'Foamrollen lats', 'recovery', '["latissimus_dorsi","teres_major"]', NULL, '["recovery","low_impact","floor","loads_shoulder"]', '["foam_roller"]', NULL, '{"steps":["Lie on your side, roller under your armpit area. Extend the bottom arm overhead.","Roll slowly from just below the armpit to mid-rib cage, pausing on tight spots.","Rotate slightly forward to reach the serratus and rear shoulder area. Switch sides."],"cues":["💡 Tight lats pull the shoulder forward and limit overhead range — rolling here has big payoff.","Straighten and flex your elbow while on a tight spot for active release."],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga op je zij liggen met de roller onder je oksel. Strek je onderste arm boven je hoofd","Rol langzaam van net onder je oksel tot halverwege je ribbenkast en blijf even op strakke plekken","Draai iets naar voren om de serratus en de achterkant van je schouder te bereiken. Wissel van kant"],"cues_nl":["💡 Strakke lats trekken je schouder naar voren en beperken je bereik boven je hoofd — hier rollen levert veel op","Strek en buig je elleboog terwijl je op een strakke plek ligt om de spanning actief los te maken"]}', '{"images":["/exercise-media/foam-roll-lats/0.jpg","/exercise-media/foam-roll-lats/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":60}', '{"substitutions":["foam-roll-upper-back","chest-opener-arms","dead-hang"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_057', 'foam-roll-quads', 'Foam Roll: Quads', 'Foamrollen quadriceps', 'recovery', '["quadriceps","rectus_femoris"]', NULL, '["recovery","low_impact","floor","loads_knee"]', '["foam_roller"]', NULL, '{"steps":["Lie face down, foam roller under your thighs. Support yourself on your forearms.","Roll slowly from the top of your knee to just below your hip, pausing on any tight spots for 10–20 seconds.","Turn 30° to one side to target the outer quad (vastus lateralis), then the inner quad."],"cues":["💡 Breathe through tight spots instead of rolling off them.","Overlap each pass slightly — systematic coverage beats random rolling."],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga op je buik liggen met de foamroller onder je bovenbenen. Steun op je onderarmen","Rol langzaam van de bovenkant van je knie tot net onder je heup en blijf 10–20 seconden op strakke plekken","Draai 30° naar één kant voor de buitenkant van je quadriceps (vastus lateralis), daarna naar de binnenkant"],"cues_nl":["💡 Adem door op strakke plekken in plaats van eraf te rollen","Laat elke baan iets overlappen — systematisch werken is beter dan willekeurig rollen"]}', '{"images":["/exercise-media/foam-roll-quads/0.jpg","/exercise-media/foam-roll-quads/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":90}', '{"substitutions": ["foam-roll-it-band", "side-lying-quad-stretch", "foam-roll-hip-flexors", "foam-roll-calves"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_059', 'foam-roll-upper-back', 'Foam Roll: Upper Back', 'Foamrollen bovenrug', 'recovery', '["thoracic_spine","rhomboids","erector_spinae"]', NULL, '["recovery","low_impact","floor","loads_lower_back"]', '["foam_roller"]', NULL, '{"steps":["Sit in front of the foam roller and lean back onto it so it''s positioned across your mid-back.","Support your head with your hands. Gently extend over the roller, opening your chest.","Shift the roller one segment at a time from mid-back toward the top of your shoulder blades."],"cues":["💡 Do not roll the lower back or neck — mid and upper thoracic only.","This is one of the best antidotes to desk posture — spend extra time here."],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga voor de foamroller zitten en leun achterover tot hij dwars onder het midden van je rug ligt","Ondersteun je hoofd met je handen. Strek je rustig over de roller en open je borst","Verplaats de roller stukje voor stukje van het midden van je rug naar de bovenkant van je schouderbladen"],"cues_nl":["💡 Rol niet over je onderrug of nek — alleen het midden en bovenste deel van je rug","Een van de beste tegenhangers van een bureauhouding — neem hier extra tijd voor"]}', '{"images":["/exercise-media/foam-roll-upper-back/0.jpg","/exercise-media/foam-roll-upper-back/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":90}', '{"substitutions": ["thoracic-extension-chair", "active-thoracic-rotation", "cat-cow-flow", "foam-roll-lats"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_032', 'hanging-leg-raise', 'Hanging Leg Raise', 'Hangend beenheffen', 'strength', '["rectus_abdominis","hip_flexors","core"]', NULL, '["strength","core","low_impact","no_floor","loads_shoulder","loads_shoulder","loads_lower_back"]', '["pull_up_bar"]', NULL, '{"steps":["Hang from the bar with both hands, arms fully extended. Brace your core to prevent swinging.","Keeping your legs straight (or bent for easier variation), raise them until parallel to the floor or higher.","Lower slowly — don''t let momentum swing your legs back down."],"cues":["💡 Posterior pelvic tilt as you raise — curl your tailbone up to fully engage the abs.","Bent knees = easier, straight legs = harder. Master bent before going straight."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Core & Stability","steps_nl":["Hang met beide handen aan de stang, armen volledig gestrekt. Span je core aan om niet te zwaaien","Til je benen gestrekt (of gebogen als makkelijkere variant) op tot ze horizontaal zijn of hoger","Laat langzaam zakken — laat je benen niet met vaart terugzwaaien"],"cues_nl":["💡 Kantel je bekken achterover terwijl je optilt — krul je stuitje omhoog om je buikspieren volledig aan te spannen","Gebogen knieën = makkelijker, gestrekte benen = zwaarder. Beheers eerst gebogen voordat je strekt"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["v-up","dead-bug","hollow-body-hold"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_066', 'happy-baby-pose', 'Happy Baby Pose', 'Happy baby', 'recovery', '["hip_flexors","adductors","lower_back"]', NULL, '["recovery","mobility","low_impact","floor","pregnancy_safe","postnatal_safe","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie on your back. Draw both knees toward your chest, then open them wide toward the armpits.","Flex your feet and grab the outside edges of each foot (or your ankles or shins if needed).","Gently pull down, drawing the knees toward the floor beside your torso. Rock side to side if it feels good."],"cues":["💡 This is a restorative pose — let gravity do the work over a long hold.","One of the best post-run or post-leg-day hip openers."],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga op je rug liggen. Trek beide knieën naar je borst en open ze dan wijd richting je oksels","Buig je voeten en pak de buitenranden van je voeten vast (of je enkels of schenen als dat nodig is)","Trek rustig naar beneden en breng je knieën naar de vloer naast je romp. Wieg van links naar rechts als dat goed voelt"],"cues_nl":["💡 Dit is een herstellende houding — laat de zwaartekracht het werk doen en blijf er lang in","Een van de beste heupopeners na een hardloop- of beentraining"]}', NULL, '{"supports":["time"],"base_duration_sec":60}', '{"substitutions": ["supine-knee-to-chest", "seated-butterfly", "ninety-ninety-hip-switch", "childs-pose"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_083', 'hill-repeats-running', 'Hill Repeats', 'Hardlopen heuvelherhalingen', 'cardio', '["quads","glutes","calves","cardiovascular_system","hamstrings"]', NULL, '["cardio","high_impact","hiit","conditioning","outdoor","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Find a moderate hill (5–8% gradient, 50–150 m long). Jog 5 minutes easy to the base as your warm-up.","Run up the hill at 85–90% effort, focusing on driving your knees and pumping your arms.","Walk or jog back down as recovery. Repeat for the prescribed number of reps."],"cues":["💡 Uphill running builds leg strength and VO2 max faster than flat running.","Lean slightly forward from the ankle, not the waist — keeps form efficient."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Zoek een matige heuvel (5–8% stijging, 50–150 m lang). Jog 5 minuten rustig naar de voet van de heuvel als warming-up","Loop de heuvel op met 85–90% inspanning; til je knieën krachtig op en zwaai je armen actief mee","Wandel of jog terug naar beneden als herstel. Herhaal voor het opgegeven aantal herhalingen"],"cues_nl":["💡 Heuvelop lopen bouwt beenkracht en VO2max sneller op dan vlak lopen","Leun licht naar voren vanuit je enkels, niet vanuit je middel — zo blijft je techniek efficiënt"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions": ["run-intervals-outdoor", "fartlek-run", "power-step-up-jump", "treadmill-hill-run"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_035', 'hollow-body-hold', 'Hollow Body Hold', 'Hollow hold', 'strength', '["rectus_abdominis","hip_flexors","core"]', NULL, '["strength","core","low_impact","floor","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie on your back, arms extended overhead. Press your lower back flat into the floor.","Lift your arms, head, and legs simultaneously — legs straight, toes pointed, lower back stays flat.","Hold this banana-shaped position. Lower everything if your back lifts off the floor."],"cues":["💡 The test: you should not be able to slide a hand under your lower back — if you can, you''ve broken form.","Start with legs higher (easier) and progress toward parallel over time."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Core & Stability","steps_nl":["Ga op je rug liggen met je armen gestrekt boven je hoofd. Druk je onderrug plat in de vloer","Til tegelijk je armen, hoofd en benen op — benen gestrekt, tenen gestrekt, onderrug blijft plat","Houd deze banaanvorm vast. Laat alles zakken als je rug van de vloer komt"],"cues_nl":["💡 De test: je moet geen hand onder je onderrug kunnen schuiven — lukt dat wel, dan klopt je houding niet meer","Begin met je benen hoger (makkelijker) en werk geleidelijk toe naar horizontaal"]}', NULL, '{"supports":["time"],"base_duration_sec":30}', '{"substitutions": ["v-up", "dead-bug", "modified-plank", "hanging-leg-raise", "bear-crawl"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_039', 'inverted-row-table', 'Inverted Row (Under Table)', 'Inverted row onder tafel', 'strength', '["lats","rhomboids","rear_deltoid","biceps"]', NULL, '["strength","pull","low_impact","floor","loads_shoulder"]', '["none"]', NULL, '{"steps":["Lie under a sturdy table, grip the edge with both hands roughly shoulder-width apart.","Keeping your body in a straight line from head to heels, pull your chest up to the table edge.","Lower slowly until your arms are straight."],"cues":["💡 The more horizontal your body, the harder it is — start with knees bent for more upright angle.","The table version is a genuine pull-up alternative for those without a bar."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga onder een stevige tafel liggen en pak de rand met beide handen vast, ongeveer op schouderbreedte","Houd je lichaam in een rechte lijn van hoofd tot hielen en trek je borst naar de tafelrand","Laat langzaam zakken tot je armen gestrekt zijn"],"cues_nl":["💡 Hoe horizontaler je lichaam, hoe zwaarder — begin met gebogen knieën voor een steilere hoek","De tafelversie is een volwaardig alternatief voor de pull-up als je geen stang hebt"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions": ["pull-up", "band-row-seated", "dumbbell-bent-over-row", "chin-up"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_070', 'jumping-jack', 'Jumping Jack', 'Jumping jack', 'cardio', '["cardiovascular_system","calves","shoulders","hip_abductors"]', NULL, '["cardio","high_impact","bodyweight","dynamic","no_floor","loads_knee","loads_ankle","loads_knee","loads_ankle","loads_shoulder"]', '["none"]', NULL, '{"steps":["Stand with feet together, arms at your sides.","Jump your feet out to shoulder width while simultaneously raising your arms overhead.","Jump your feet back together and lower your arms. That is one rep."],"cues":["💡 Land softly with slightly bent knees — protect your joints.","For low-impact: step side to side instead of jumping."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta met je voeten tegen elkaar, armen langs je lichaam.","Spring je voeten uit tot schouderbreedte en breng tegelijk je armen boven je hoofd.","Spring je voeten weer bij elkaar en laat je armen zakken. Dat is één herhaling."],"cues_nl":["💡 Land zacht met licht gebogen knieën — zo spaar je je gewrichten.","Zonder springen: stap van links naar rechts in plaats van te springen."]}', NULL, '{"supports":["time"],"base_duration_sec":30}', '{"substitutions":["low-impact-jumping-jacks","high-knees","march-in-place","jump-rope-simulation"]}', 1, 1744700000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_029', 'kettlebell-deadlift', 'Kettlebell Deadlift', 'Kettlebell deadlift', 'strength', '["hamstrings","glutes","erector_spinae","traps","forearms"]', NULL, '["strength","low_impact","posterior_chain","full_body","loads_lower_back","loads_lower_back","loads_shoulder","loads_knee"]', '["kettlebell"]', NULL, '{"steps":["Stand with the kettlebell between your feet, feet just wider than shoulder-width. Hinge at the hips to grip it with both hands — flat back, hips above knees, chest up.","Push the floor away with your legs while driving your hips forward. Keep the bell close to your body as it rises — it should travel up your shins.","Stand tall at the top: hips and knees locked, core tight. Lower by hinging first, then bending the knees. Set the bell down under control."],"cues":["💡 This is a hinge, not a squat. Your hips descend back and behind you, not straight down.","Keep the bell directly over the mid-foot throughout. A bell that drifts forward puts unnecessary strain on your lower back."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta met de kettlebell tussen je voeten, voeten net iets breder dan schouderbreedte. Scharnier vanuit je heupen en pak hem met beide handen vast — vlakke rug, heupen boven je knieën, borst omhoog","Duw de vloer met je benen weg en breng je heupen naar voren. Houd de kettlebell dicht bij je lichaam terwijl hij omhoogkomt — hij gaat langs je schenen omhoog","Sta bovenin rechtop: heupen en knieën gestrekt, core aangespannen. Zak door eerst te scharnieren en dan je knieën te buigen. Zet de kettlebell gecontroleerd neer"],"cues_nl":["💡 Dit is een heupscharnier, geen squat. Je heupen gaan naar achteren, niet recht omlaag","Houd de kettlebell de hele tijd recht boven het midden van je voet. Een kettlebell die naar voren zweeft belast je onderrug onnodig"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_single"}', '{"substitutions":["dumbbell-deadlift","dumbbell-romanian-deadlift","kettlebell-swing"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_025', 'kettlebell-goblet-squat', 'Kettlebell Goblet Squat', 'Kettlebell goblet squat', 'strength', '["quads","glutes","core","adductors"]', NULL, '["strength","low_impact","full_body","loads_knee","loads_knee"]', '["kettlebell"]', NULL, '{"steps":["Hold the kettlebell vertically with both hands cupping the top of the bell at your chest. Stand with feet shoulder-width, toes angled out 15 to 30 degrees.","Squat down with the kettlebell close to your chest — its weight counterbalances you and pulls you into a deep, upright position.","Drive through your heels to stand, squeezing your glutes at the top. That is one rep."],"cues":["💡 The goblet position forces an upright torso and deep hip flexion — this is one of the best teaching tools for a perfect squat pattern.","Knees track over toes throughout. If they cave in, use your elbows to push them out on the way down."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Houd de kettlebell verticaal tegen je borst met beide handen om de bovenkant van de bol. Sta met je voeten op schouderbreedte, tenen 15 tot 30 graden naar buiten","Zak in de squat met de kettlebell dicht bij je borst — het gewicht werkt als tegenwicht en trekt je in een diepe, rechte houding","Duw via je hielen omhoog en span bovenin je bilspieren aan. Dat is één herhaling"],"cues_nl":["💡 De gobletpositie dwingt een rechte romp en diepe heupbuiging af — een van de beste manieren om een goede squat aan te leren","Je knieën blijven de hele tijd boven je tenen. Vallen ze naar binnen, duw ze dan op de weg omlaag met je ellebogen naar buiten"]}', '{"images":["/exercise-media/kettlebell-goblet-squat/0.jpg","/exercise-media/kettlebell-goblet-squat/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_single"}', '{"substitutions":["dumbbell-goblet-squat","sumo-squat","band-squat","kettlebell-front-rack-squat"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_027', 'kettlebell-halo', 'Kettlebell Halo', 'Kettlebell halo', 'strength', '["anterior_deltoid","medial_deltoid","triceps","rotator_cuff","core"]', NULL, '["strength","mobility","low_impact","no_floor","shoulder_health","loads_shoulder"]', '["kettlebell"]', NULL, '{"steps":["Hold the kettlebell with both hands at chest height, arms slightly bent. Stand with feet shoulder-width.","Move the bell in a circular path around your head: left side, over the top, right side, and back to start. Keep the circle controlled and close to your head.","Complete the prescribed reps, then reverse direction for the same number."],"cues":["💡 The halo challenges shoulder mobility and stability simultaneously — go slow enough to feel the control demand.","Keep your core braced and avoid leaning. If you are tilting to follow the bell, slow down."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Houd de kettlebell met beide handen op borsthoogte, armen licht gebogen. Sta met je voeten op schouderbreedte","Beweeg de kettlebell in een cirkel om je hoofd: linkerkant, over de bovenkant, rechterkant en terug naar de start. Houd de cirkel gecontroleerd en dicht bij je hoofd","Doe de opgegeven herhalingen en draai dan even vaak de andere kant op"],"cues_nl":["💡 De halo vraagt mobiliteit én stabiliteit van je schouders tegelijk — ga langzaam genoeg om die controle te voelen","Houd je core aangespannen en leun niet mee. Kantel je om de kettlebell te volgen, ga dan langzamer"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_single"}', '{"substitutions": ["dumbbell-arnold-press", "shoulder-circles-active"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_026', 'kettlebell-single-arm-press', 'Kettlebell Single-Arm Press', 'Kettlebell press eenarmig', 'strength', '["anterior_deltoid","triceps","core"]', NULL, '["strength","push","low_impact","no_floor","core","loads_shoulder","loads_shoulder"]', '["kettlebell"]', NULL, '{"steps":["Clean the kettlebell to the rack position: bell resting on your forearm, elbow close to your body, wrist neutral, fist at shoulder height.","Press straight up until your arm is fully locked out overhead. Keep your core braced and avoid side-bending.","Lower the bell back to the rack position with control. Complete all reps, then switch sides."],"cues":["💡 The rack position is a skill in itself — the bell should rest on your forearm, not dangle from your wrist.","A single-arm press reveals any imbalance between sides immediately. Start with your weaker arm."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Core & Stability","steps_nl":["Breng de kettlebell met een clean naar de rackpositie: de bol rust op je onderarm, elleboog dicht bij je lichaam, pols recht, vuist op schouderhoogte","Druk recht omhoog tot je arm volledig gestrekt boven je hoofd is. Houd je core aangespannen en buig niet opzij","Laat de kettlebell gecontroleerd terugzakken naar de rackpositie. Doe alle herhalingen en wissel dan van kant"],"cues_nl":["💡 De rackpositie is een vaardigheid op zich — de kettlebell rust op je onderarm en hangt niet aan je pols","Een press met één arm laat elk verschil tussen links en rechts meteen zien. Begin met je zwakste arm"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_single"}', '{"substitutions":["dumbbell-shoulder-press","dumbbell-arnold-press","band-overhead-press"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_028', 'kettlebell-single-leg-rdl', 'Kettlebell Single-Leg RDL', 'Kettlebell RDL op één been', 'strength', '["hamstrings","glutes","erector_spinae"]', NULL, '["strength","low_impact","unilateral","posterior_chain","loads_lower_back","sport_support:running","loads_lower_back","loads_knee","loads_ankle"]', '["kettlebell"]', NULL, '{"steps":["Stand tall holding the kettlebell in one hand at your side. Shift your weight to the opposite leg, soft bend in the knee.","Hinge at the hip, letting the kettlebell travel down your standing leg as your non-working leg extends behind you. Hips stay square.","Return to standing by driving through your heel and squeezing your glute. That is one rep. Complete all reps, then switch sides."],"cues":["💡 Think of your back leg and torso as a single rigid plank — they rotate as one unit around your hip joint.","The range ends where your pelvis rotates. Quality over depth: a square hip at 45 degrees beats a rotated hip at 90."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta rechtop met de kettlebell in één hand langs je lichaam. Breng je gewicht naar het andere been, knie licht gebogen","Scharnier vanuit je heup en laat de kettlebell langs je standbeen zakken terwijl je andere been naar achteren strekt. Je heupen blijven recht","Kom terug omhoog door via je hiel te duwen en je bilspier aan te spannen. Dat is één herhaling. Doe alle herhalingen en wissel dan van kant"],"cues_nl":["💡 Zie je achterste been en je romp als één stijve plank — ze draaien als één geheel om je heupgewricht","De beweging eindigt waar je bekken gaat draaien. Kwaliteit boven diepte: een rechte heup op 45 graden is beter dan een gedraaide heup op 90"]}', '{"images":["/exercise-media/kettlebell-single-leg-rdl/0.jpg","/exercise-media/kettlebell-single-leg-rdl/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_single"}', '{"substitutions":["dumbbell-single-leg-rdl","dumbbell-romanian-deadlift"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_024', 'kettlebell-swing', 'Kettlebell Swing', 'Kettlebell swing', 'strength', '["glutes","hamstrings","erector_spinae","core","shoulders"]', NULL, '["strength","cardio","low_impact","full_body","posterior_chain","loads_lower_back","sport_support:running","sport_support:football","loads_lower_back","loads_shoulder"]', '["kettlebell"]', NULL, '{"steps":["Stand with feet slightly wider than shoulder-width, kettlebell on the floor between your feet.","Hinge at the hips, grab the bell and hike it back between your legs. Then explosively drive your hips forward to send the bell swinging to shoulder height.","Let the bell fall back, hinging your hips to receive it — don''t squat, hinge."],"cues":["💡 The power is a hip snap, not a shoulder lift — your arms are just the cable.","Squeeze your glutes hard at the top like you''re trying to crack a walnut."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta met je voeten iets breder dan schouderbreedte, de kettlebell op de vloer tussen je voeten","Scharnier vanuit je heupen, pak de kettlebell en zwaai hem naar achteren tussen je benen. Duw dan je heupen explosief naar voren zodat hij tot schouderhoogte zwaait","Laat de kettlebell terugvallen en vang hem op door vanuit je heupen te scharnieren — niet squatten, scharnieren"],"cues_nl":["💡 De kracht komt uit een heupstoot, niet uit je schouders — je armen zijn alleen de kabel","Span bovenin je bilspieren hard aan, alsof je een walnoot wilt kraken"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_single"}', '{"substitutions": ["dumbbell-romanian-deadlift", "good-morning-bodyweight", "dumbbell-hip-thrust", "kettlebell-deadlift", "clean-pull"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_076', 'lateral-shuffle-drill', 'Lateral Shuffle Drill', 'Zijwaartse shuffle', 'cardio', '["glute_medius","quads","calves","cardiovascular_system"]', NULL, '["cardio","low_impact","bodyweight","agility","dynamic","no_floor","loads_ankle","loads_ankle","loads_knee"]', '["none"]', NULL, '{"steps":["Stand in an athletic stance, knees slightly bent, weight on the balls of your feet.","Shuffle quickly to the right for 4–5 steps by pushing off your left foot.","Immediately shuffle back to the left. Keep your hips low and your feet never crossing."],"cues":["💡 The lower you stay, the more glute and quad activation you get.","Hips face forward the whole time — this is a lateral movement, not a rotation."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta in een atletische houding, knieën licht gebogen, gewicht op je voorvoeten","Shuffle snel 4–5 passen naar rechts door af te zetten met je linkervoet","Shuffle direct terug naar links. Houd je heupen laag en kruis je voeten nooit"],"cues_nl":["💡 Hoe lager je blijft, hoe meer je je bilspieren en bovenbenen aanspreekt","Je heupen blijven de hele tijd naar voren wijzen — dit is een zijwaartse beweging, geen draaiing"]}', NULL, '{"supports":["time"],"base_duration_sec":40}', '{"substitutions": ["shuffle-tap", "grapevine-step", "band-lateral-walk", "speed-skater", "cross-country-ski-step"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_045', 'leg-swings-front-back', 'Active Leg Swings (Front/Back)', 'Beenzwaaien voor-achter (actief)', 'mobility', '["hip_flexors","hamstrings","glutes"]', NULL, '["mobility","low_impact","no_floor","dynamic"]', '["none"]', NULL, '{"steps":["Stand sideways to a wall, one hand touching for balance. Shift weight to the inner leg.","Swing the outer leg forward and back in a relaxed pendulum motion — gradually increasing the range.","After reps, turn and repeat on the other side."],"cues":["💡 Relaxed, not forced — let momentum build the range over successive swings.","Active warm-up for running, cycling, or any lower-body session."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Sta zijwaarts naast een muur en raak die met één hand aan voor balans. Breng je gewicht naar je binnenste been","Zwaai je buitenste been ontspannen als een slinger naar voren en naar achteren en maak de zwaai geleidelijk groter","Draai je na je herhalingen om en herhaal aan de andere kant"],"cues_nl":["💡 Ontspannen, niet geforceerd: laat de vaart de zwaai bij elke herhaling iets groter maken","Actieve warming-up voor hardlopen, fietsen of elke training voor je onderlichaam"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["leg-swings-lateral","hip-flexor-stretch","couch-stretch"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_046', 'leg-swings-lateral', 'Active Leg Swings (Side to Side)', 'Beenzwaaien zijwaarts (actief)', 'mobility', '["hip_abductors","adductors","glute_medius"]', NULL, '["mobility","low_impact","no_floor","dynamic"]', '["none"]', NULL, '{"steps":["Face a wall, both hands lightly touching for balance. Weight on one foot.","Swing the free leg across your body and then out to the side in a wide arc.","Keep the movement controlled at the extremes — let momentum build gradually."],"cues":["💡 Swing from the hip, not the knee — think wide arc from the pelvis.","Particularly useful before lateral sports and hip-heavy strength training."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Sta met je gezicht naar een muur en raak die licht aan met beide handen voor balans. Gewicht op één voet.","Zwaai je vrije been voor je lichaam langs en dan in een wijde boog opzij.","Blijf aan de uitersten gecontroleerd bewegen en bouw de zwaai geleidelijk op."],"cues_nl":["💡 Zwaai vanuit je heup, niet vanuit je knie: denk aan een wijde boog vanuit je bekken.","Vooral handig voor sporten met zijwaartse bewegingen en krachttraining met veel heupwerk."]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["leg-swings-front-back","ninety-ninety-hip-switch","band-lateral-walk"]}', 1, 1744700000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_054', 'lunge-thoracic-rotation', 'Lunge with Thoracic Rotation', 'Uitvalspas met thoracale rotatie', 'mobility', '["hip_flexors","thoracic_spine","obliques","glutes"]', NULL, '["mobility","low_impact","floor","dynamic","sport_support:cycling","sport_support:rowing","sport_mobility:running","sport_mobility:cycling","sport_mobility:rowing","sport_mobility:football","sport_mobility:skiing","sport_mobility:crossfit","loads_knee"]', '["none"]', NULL, '{"steps":["Step into a lunge, front foot flat, rear knee on or near the floor.","Place both hands on your front thigh. Rotate your torso toward the front leg, reaching the top arm toward the ceiling.","Return to centre and alternate sides each rep."],"cues":["💡 This is one of the best single mobility exercises — hits hip flexors AND thoracic at once.","Move with your breath: inhale to stand tall, exhale to rotate further."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Stap in een uitvalspas met je voorste voet plat en je achterste knie op of vlak boven de vloer","Leg beide handen op je voorste bovenbeen. Draai je romp naar je voorste been en reik met je bovenste arm naar het plafond","Kom terug naar het midden en wissel elke herhaling van kant"],"cues_nl":["💡 Een van de beste losse mobiliteitsoefeningen: je pakt je heupbuigers én je bovenrug in één keer","Beweeg op je adem: adem in om lang te worden, adem uit om verder te draaien"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["world-greatest-stretch","active-thoracic-rotation","cat-cow-flow"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_051', 'lying-hamstring-stretch', 'Lying Hamstring Stretch', 'Hamstring stretch liggend', 'mobility', '["hamstrings","calves"]', NULL, '["mobility","low_impact","floor","pregnancy_safe","postnatal_safe","sport_mobility:running","sport_mobility:football","loads_ankle"]', '["none"]', NULL, '{"steps":["Lie on your back. Bend one knee with foot flat. Extend the other leg and lift it, clasping behind the thigh.","Gently pull the leg toward you until you feel a comfortable stretch along the back of the thigh.","Flex your foot (toes toward your shin) to add calf and sciatic nerve stretch. Hold and switch sides."],"cues":["💡 Keep your lower back flat — don''t let it arch off the floor.","Breathing into the stretch and relaxing on the exhale helps the muscle release further."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Lig op je rug. Buig één knie met je voet plat. Strek je andere been, til het op en pak het achter je dij vast.","Trek je been rustig naar je toe tot je een prettige rek achter in je dij voelt.","Trek je tenen naar je scheenbeen om ook je kuit en heupzenuw te rekken. Houd vast en wissel van kant."],"cues_nl":["💡 Houd je onderrug plat: laat hem niet van de vloer komen.","Adem naar de rek toe en ontspan bij het uitademen, dan geeft de spier verder mee."]}', '{"images":["/exercise-media/lying-hamstring-stretch/0.jpg","/exercise-media/lying-hamstring-stretch/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":60}', '{"substitutions": ["seated-hamstring-stretch", "standing-hamstring-stretch", "standing-forward-fold", "foam-roll-hamstrings"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_056', 'neck-half-circles', 'Neck Half-Circles', 'Nek halve cirkels', 'mobility', '["cervical_spine","upper_trapezius","sternocleidomastoid"]', NULL, '["mobility","low_impact","no_floor","pregnancy_safe","postnatal_safe","quiet"]', '["none"]', NULL, '{"steps":["Sit or stand tall. Drop your right ear toward your right shoulder, feeling the stretch on the left side.","Slowly roll your chin forward toward your chest, continuing to the left ear down to the left shoulder.","Reverse the arc back to neutral. Never complete a full circle by taking the head back — that compresses the cervical spine."],"cues":["💡 Front semicircle only — half-circles are safe, full circles backward are not.","Breathe into each stretch position and let the weight of your head do the work."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Zit of sta rechtop. Laat je rechteroor naar je rechterschouder zakken en voel de rek aan de linkerkant.","Rol je kin langzaam naar voren richting je borst en ga door tot je linkeroor naar je linkerschouder zakt.","Maak de boog terug naar het midden. Maak nooit een volledige cirkel door je hoofd naar achteren te brengen: dat drukt je halswervels samen."],"cues_nl":["💡 Alleen de voorste halve cirkel: halve cirkels zijn veilig, volledige cirkels naar achteren niet.","Adem in elke rekpositie en laat het gewicht van je hoofd het werk doen."]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["neck-stretch","shoulder-roll-stretch"]}', 1, 1744700000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_042', 'ninety-ninety-hip-switch', '90/90 Hip Switch', 'Heup 90/90 wissel', 'mobility', '["hip_external_rotators","hip_internal_rotators","glutes","adductors"]', NULL, '["mobility","low_impact","floor","pregnancy_safe","postnatal_safe","sport_mobility:running","sport_mobility:football"]', '["none"]', NULL, '{"steps":["Sit on the floor with both knees bent at 90 degrees — one leg in front of you (shin perpendicular to your torso), one leg to the side (shin parallel to your torso). Sit tall with a neutral spine.","Rotate both knees to the opposite side simultaneously — the front leg becomes the back leg and vice versa. Your hips pivot as you switch.","Pause briefly in the new position, sitting as tall as possible before switching back. That is one rep."],"cues":["Keep the rotation driven from your hips, not from leaning your torso — the goal is hip mobility, not body sway.","If you cannot get both shins to the floor without pain, sit on a folded blanket to reduce the hip angle demand.","💡 💡 This exercise builds the internal and external hip rotation range that protects the hips and lower back long-term. Slow and intentional is far more effective than fast reps."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Zit op de vloer met beide knieën in 90 graden: één been voor je (scheen dwars op je romp), één been opzij (scheen evenwijdig aan je romp). Zit rechtop met een neutrale rug.","Draai beide knieën tegelijk naar de andere kant: je voorste been wordt je achterste en andersom. Je heupen draaien mee.","Pauzeer kort in de nieuwe positie, zo rechtop mogelijk, voor je terugdraait. Dat is één herhaling."],"cues_nl":["Laat de draai uit je heupen komen, niet door met je romp te leunen: het doel is heupmobiliteit, niet zwaaien.","Krijg je niet beide schenen pijnvrij op de vloer? Ga dan op een opgevouwen deken zitten om de heuphoek te verkleinen.","💡 💡 Deze oefening vergroot de binnen- en buitenrotatie van je heupen, wat je heupen en onderrug op lange termijn beschermt. Langzaam en bewust werkt veel beter dan snelle herhalingen."]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions": ["half-kneeling-hip-opener", "pigeon-pose", "couch-stretch", "leg-swings-lateral", "deep-squat-hold"]}', 1, 1744700000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_038', 'nordic-hamstring-curl', 'Nordic Hamstring Curl', 'Nordic hamstring curl', 'strength', '["hamstrings","glutes"]', NULL, '["strength","posterior_chain","floor","low_impact","sport_support:running","sport_support:football","loads_knee"]', '["chair"]', NULL, '{"steps":["Kneel on a mat with a partner holding your ankles — or hook your heels under a heavy sofa or secured bar.","With your body upright, lower your torso toward the floor as slowly as you can.","Catch yourself with your hands, then push back up to the kneeling position."],"cues":["💡 The eccentric (lowering) phase is where the hamstring strength is built — make it slow.","This is hard. Even 3–5 slow reps builds significant hamstring resilience."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Kniel op een mat terwijl een partner je enkels vasthoudt — of haak je hielen onder een zware bank of een vastgezette stang","Houd je lichaam rechtop en laat je bovenlichaam zo langzaam mogelijk naar de vloer zakken","Vang jezelf op met je handen en duw je daarna terug naar de knielende positie"],"cues_nl":["💡 In de excentrische fase (het zakken) bouw je de kracht in je hamstrings op — doe het langzaam","Dit is zwaar. Zelfs 3–5 langzame herhalingen maken je hamstrings al een stuk weerbaarder"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["dumbbell-single-leg-rdl","good-morning-bodyweight","dumbbell-romanian-deadlift"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_041', 'pistol-squat-assist', 'Assisted Pistol Squat', 'Pistol squat ondersteund', 'strength', '["quads","glutes","hip_flexors","core"]', NULL, '["strength","low_impact","unilateral","floor","loads_knee","loads_knee"]', '["chair"]', NULL, '{"steps":["Stand in front of a chair or wall for balance. Extend one leg in front of you, slightly bent.","Lower yourself slowly on the standing leg until you tap the chair or reach your comfortable depth — keep the elevated leg straight.","Drive through the standing heel to rise back to standing."],"cues":["💡 Holding a counterweight (light dumbbell) actually makes balancing easier.","This is a skill as much as a strength exercise — patience with the progression."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga voor een stoel of muur staan voor je balans. Strek één been licht gebogen voor je uit","Zak langzaam op je standbeen tot je de stoel aantikt of je comfortabele diepte bereikt — houd je opgetilde been gestrekt","Duw door de hiel van je standbeen om weer rechtop te komen"],"cues_nl":["💡 Met een tegengewicht (een lichte dumbbell) in je handen houd je juist makkelijker je balans","Dit is net zo goed een vaardigheid als een krachtoefening — heb geduld met de opbouw"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["dumbbell-bulgarian-split-squat","reverse-lunge","lateral-lunge"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_078', 'power-step-up-jump', 'Power Step-Up (Explosive)', 'Explosieve opstap met sprong', 'cardio', '["quads","glutes","calves","cardiovascular_system"]', NULL, '["cardio","high_impact","bodyweight","power","dynamic","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["chair"]', NULL, '{"steps":["Stand in front of a sturdy step or box. Place your right foot on the step.","Drive through the right heel to step up explosively, driving your left knee high at the top.","Land softly back on the floor and immediately repeat. Alternate lead legs."],"cues":["💡 The drive comes from the heel of the working leg — not a toe push.","Land with bent knees to absorb impact — quiet landings protect joints."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Ga voor een stevige step of box staan. Zet je rechtervoet op de step.","Duw explosief door je rechterhiel om op te stappen en breng bovenaan je linkerknie hoog op.","Land zacht terug op de vloer en herhaal direct. Wissel je voorste been af."],"cues_nl":["💡 De kracht komt uit de hiel van je werkende been — niet afzetten met je tenen.","Land met gebogen knieën om de klap op te vangen — stille landingen sparen je gewrichten."]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions": ["box-step-up", "jump-squat", "broad-jump", "stair-climb-simulation", "hill-repeats-running"]}', 1, 1744700000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_067', 'progressive-relaxation-body', 'Progressive Muscle Relaxation', 'Progressieve spierontspanning', 'recovery', '["whole_body"]', NULL, '["recovery","breathing","quiet","floor","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Lie down comfortably. Starting at your feet, tense each muscle group for 5 seconds, then release completely for 10 seconds.","Work up the body in sequence: feet → calves → thighs → glutes → abdomen → hands → forearms → shoulders → face.","Finish with 2 minutes of complete stillness."],"cues":["💡 The contrast between tension and release teaches your nervous system what ''fully relaxed'' actually feels like.","If you fall asleep, that''s fine — your body needed it."],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga comfortabel liggen. Begin bij je voeten: span elke spiergroep 5 seconden aan en laat dan 10 seconden helemaal los","Werk in volgorde omhoog door je lichaam: voeten → kuiten → bovenbenen → bilspieren → buik → handen → onderarmen → schouders → gezicht","Sluit af met 2 minuten volledig stilliggen"],"cues_nl":["💡 Het contrast tussen aanspannen en loslaten leert je zenuwstelsel hoe ''helemaal ontspannen'' echt voelt","Val je in slaap, dan is dat prima — je lichaam had het nodig"]}', NULL, '{"supports":["time"],"base_duration_sec":600}', '{"substitutions":["body-scan-meditation","tension-release-visualization","mindful-body-check"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_030', 'pull-up', 'Pull-Up', 'Optrekken', 'strength', '["lats","rhomboids","rear_deltoid","biceps","core"]', NULL, '["strength","pull","low_impact","no_floor","loads_shoulder","loads_shoulder"]', '["pull_up_bar"]', NULL, '{"steps":["Hang from the bar with a pronated grip (palms away) just wider than shoulder-width.","Pull your body up until your chin clears the bar — lead with your chest, not your chin.","Lower slowly over 2–3 seconds until your arms are fully extended."],"cues":["💡 Initiate by depressing your shoulder blades before you bend your elbows.","Full extension at the bottom — no partial reps, every rep from a dead hang."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Hang aan de stang met een bovenhandse greep (handpalmen van je af), net iets breder dan schouderbreedte","Trek je lichaam omhoog tot je kin boven de stang komt — leid met je borst, niet met je kin","Zak langzaam in 2–3 seconden tot je armen volledig gestrekt zijn"],"cues_nl":["💡 Begin door je schouderbladen omlaag te trekken voordat je je ellebogen buigt","Onderin volledig strekken — geen halve herhalingen, elke herhaling vanuit een volledige hang"]}', '{"images":["/exercise-media/pull-up/0.jpg","/exercise-media/pull-up/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions": ["chin-up", "inverted-row-table", "band-row-seated", "dead-hang", "scapular-retraction-hang"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_077', 'reverse-lunge-kick', 'Reverse Lunge to Front Kick', 'Achterwaartse uitvalspas met trap', 'cardio', '["quads","glutes","hamstrings","hip_flexors","cardiovascular_system"]', NULL, '["cardio","low_impact","bodyweight","balance","dynamic","no_floor","loads_knee","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand tall. Step your right foot back into a reverse lunge, lowering your rear knee toward the floor.","Drive through your left foot to stand, immediately bringing your right knee up and extending it into a front kick.","Lower your right foot back down and repeat. Switch legs after reps."],"cues":["💡 The kick is controlled, not a wild flick — squeeze the quad at the top.","Your balance leg works hard — this is a coordination and strength challenge as much as cardio."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta rechtop. Stap met je rechtervoet naar achteren in een achterwaartse uitvalspas en laat je achterste knie richting de vloer zakken","Duw door je linkervoet om op te staan, breng direct je rechterknie omhoog en strek je been uit in een voorwaartse trap","Zet je rechtervoet weer neer en herhaal. Wissel van been na je herhalingen"],"cues_nl":["💡 De trap is gecontroleerd, geen wilde zwiep — span bovenaan je bovenbeenspier aan","Je standbeen werkt hard — dit is net zo goed een oefening voor coördinatie en kracht als voor cardio"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["reverse-lunge","alternating-front-kick","lateral-knee-raise"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_040', 'reverse-plank', 'Reverse Plank', 'Omgekeerde plank', 'strength', '["glutes","hamstrings","erector_spinae","triceps","rear_deltoid"]', NULL, '["strength","posterior_chain","low_impact","floor","loads_shoulder","loads_lower_back"]', '["none"]', NULL, '{"steps":["Sit on the floor, hands behind you, fingers pointing forward or outward. Feet flat on the floor.","Push through your hands and heels to lift your hips until your body forms a straight line from head to heels.","Hold the position, squeezing your glutes and keeping your chin slightly tucked."],"cues":["💡 A neglected posterior chain exercise — great complement to planks and push-ups.","If wrists hurt, make fists or use push-up handles to stay neutral."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga op de vloer zitten, handen achter je, vingers naar voren of naar buiten. Voeten plat op de vloer.","Duw door je handen en hielen en til je heupen op tot je lichaam een rechte lijn vormt van hoofd tot hielen.","Houd deze positie vast, span je bilspieren aan en houd je kin licht ingetrokken."],"cues_nl":["💡 Een vaak vergeten oefening voor je achterketen — mooie aanvulling op Plank en push-ups.","Doen je polsen pijn? Maak vuisten of gebruik push-up grips om ze neutraal te houden."]}', NULL, '{"supports":["time"],"base_duration_sec":30}', '{"substitutions":["hollow-body-hold","dumbbell-hip-thrust","supported-glute-bridge"]}', 1, 1744700000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_094', 'rowing-2k-time-trial', 'Rowing 2K Time Trial', 'Roeien 2 km tijdrit', 'cardio', '["legs","back","shoulders","arms","core","cardiovascular_system"]', NULL, '["cardio","strength","full_body","high_intensity","hiit","indoor","low_impact","loads_lower_back","loads_lower_back","loads_shoulder","loads_knee"]', '["rowing_machine"]', NULL, '{"steps":["Set the monitor to row 2000 metres. Warm up 5 minutes easy, building to a moderate pace.","Row the full 2K at maximal sustained effort. Go out at target pace, hold it through the middle, lift in the last 500 m.","After finishing, easy paddle 5 minutes to recover — your heart rate will be high."],"cues":["💡 Negative split strategy: rows 1000–1500 m feeling controlled, then build from 1500 m onward.","Record your split time and use it as your benchmark for future sessions."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Stel de monitor in op 2000 meter roeien. Roei je 5 minuten rustig warm en bouw op naar een gemiddeld tempo","Roei de volledige 2 km op de maximale inspanning die je kunt volhouden. Start op je doeltempo, houd dat vast in het middenstuk en versnel in de laatste 500 m","Roei na de finish 5 minuten rustig uit om te herstellen — je hartslag is dan hoog"],"cues_nl":["💡 Negative split: roei van 1000 tot 1500 m beheerst en bouw vanaf 1500 m op","Noteer je splittijd en gebruik die als ijkpunt voor volgende sessies"]}', '{"images":["/exercise-media/rowing-2k-time-trial/0.jpg","/exercise-media/rowing-2k-time-trial/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":600}', '{"substitutions": ["rowing-intervals", "rowing-pyramid-intervals", "rowing-steady-state", "rowing-power-strokes"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_097', 'rowing-power-strokes', 'Rowing Power Strokes', 'Roeien krachthalen', 'cardio', '["legs","back","arms","glutes","core","cardiovascular_system"]', NULL, '["cardio","strength","full_body","high_intensity","hiit","low_impact","indoor","loads_lower_back","loads_lower_back","loads_shoulder","loads_knee"]', '["rowing_machine"]', NULL, '{"steps":["Row easy for 3 minutes as a warm-up. Then, within each minute, perform 10 strokes at maximum power followed by the rest of the minute easy.","The 10 power strokes should be explosive — push your split significantly lower than normal.","Repeat this 1-minute cycle for 10 minutes. Cool down 2 minutes easy."],"cues":["💡 Count the 10 strokes carefully — after 10, immediately drop back to easy.","This develops raw power without accumulating excessive fatigue."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Roei 3 minuten rustig als warming-up. Doe daarna binnen elke minuut 10 halen op maximale kracht en roei de rest van de minuut rustig","De 10 krachthalen moeten explosief zijn — duw je split duidelijk lager dan normaal","Herhaal deze cyclus van 1 minuut 10 minuten lang. Roei 2 minuten rustig uit als cooling-down"],"cues_nl":["💡 Tel de 10 halen zorgvuldig — ga na 10 direct terug naar rustig roeien","Hiermee ontwikkel je pure kracht zonder dat de vermoeidheid te veel oploopt"]}', '{"images":["/exercise-media/rowing-power-strokes/0.jpg","/exercise-media/rowing-power-strokes/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":780}', '{"substitutions":["rowing-intervals","rowing-pyramid-intervals","rowing-2k-time-trial"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_095', 'rowing-pyramid-intervals', 'Rowing Pyramid Intervals', 'Roeien piramide-intervallen', 'cardio', '["legs","back","arms","core","cardiovascular_system"]', NULL, '["cardio","strength","full_body","high_intensity","hiit","indoor","low_impact","loads_lower_back","loads_lower_back","loads_shoulder","loads_knee"]', '["rowing_machine"]', NULL, '{"steps":["Warm up 3 minutes easy. Row hard intervals in a pyramid: 30s / 60s / 90s / 2 min / 90s / 60s / 30s.","Rest equals the work interval between each. Hard intervals at near-maximum effort.","Cool down 3 minutes easy."],"cues":["💡 The 2-minute peak is the hardest — pace yourself on the way up so you can sustain it.","Keep the drive sequence correct even at high intensity: legs → back → arms."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Roei 3 minuten rustig warm. Roei zware intervallen in een piramide: 30 s / 60 s / 90 s / 2 min / 90 s / 60 s / 30 s","De rust tussen de intervallen is even lang als het interval zelf. Roei de zware intervallen op bijna maximale inspanning","Roei 3 minuten rustig uit als cooling-down"],"cues_nl":["💡 De piek van 2 minuten is het zwaarst — doseer op weg omhoog, zodat je die kunt volhouden","Houd de volgorde van de haal ook op hoge intensiteit correct: benen → rug → armen"]}', '{"images":["/exercise-media/rowing-pyramid-intervals/0.jpg","/exercise-media/rowing-pyramid-intervals/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":1500}', '{"substitutions": ["rowing-intervals", "rowing-2k-time-trial", "rowing-steady-state", "rowing-technique-drill", "rowing-power-strokes"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_096', 'rowing-technique-drill', 'Rowing Technique Drill', 'Roeien techniekoefening', 'cardio', '["legs","back","core"]', NULL, '["cardio","skill","full_body","low_impact","indoor","quiet","loads_lower_back","loads_lower_back","loads_shoulder","loads_knee"]', '["rowing_machine"]', NULL, '{"steps":["Row at a very slow rate (16–18 spm) and low pressure, focusing entirely on sequence: LEGS → BACK → ARMS (drive), then ARMS → BACK → LEGS (recovery).","Pause at three positions: arms only at the finish, halfway up the slide, and at the catch (shins vertical).","After each pause, check your posture before moving to the next segment."],"cues":["💡 Correct sequencing at slow speed becomes automatic at race pace.","This is NOT about getting a cardiovascular workout — quality of movement is everything."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Roei heel langzaam (16–18 SPM) en met weinig druk, en let volledig op de volgorde: BENEN → RUG → ARMEN (haal), daarna ARMEN → RUG → BENEN (herstel)","Pauzeer op drie punten: alleen armen bij de uitpik, halverwege de slide en bij de inpik (schenen verticaal)","Controleer na elke pauze je houding voordat je naar het volgende deel gaat"],"cues_nl":["💡 Een goede volgorde op lage snelheid wordt op wedstrijdtempo een automatisme","Dit gaat NIET om een cardiotraining — de kwaliteit van je beweging is het enige dat telt"]}', '{"images":["/exercise-media/rowing-technique-drill/0.jpg","/exercise-media/rowing-technique-drill/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":900}', '{"substitutions": ["rowing-steady-state", "rowing-pyramid-intervals", "rowing-zone2"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_098', 'rowing-zone2', 'Rowing Zone 2 Steady', 'Roeien zone 2', 'cardio', '["cardiovascular_system","legs","back","core"]', NULL, '["cardio","zone2","full_body","low_impact","indoor","quiet","loads_lower_back","loads_lower_back","loads_shoulder","loads_knee"]', '["rowing_machine"]', NULL, '{"steps":["Set your target split at a pace you can maintain conversationally — about 2:20–2:40 /500 m for beginners, 2:00–2:20 for intermediate.","Row at rate 18–20 strokes per minute. Focus on maintaining consistent split without drift.","Hold this for the full duration. End with 2 minutes of easy paddling."],"cues":["💡 Zone 2 rowing is particularly effective as a full-body aerobic base builder.","Check every 5 minutes that your split hasn''t crept up — if it has, that''s fatigue: adjust."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Stel je richtsplit in op een tempo waarbij je kunt blijven praten — ongeveer 2:20–2:40 /500 m voor beginners, 2:00–2:20 voor gemiddelde roeiers","Roei met 18–20 halen per minuut. Let erop dat je split constant blijft en niet verloopt","Houd dit de hele duur vol. Sluit af met 2 minuten rustig uitroeien"],"cues_nl":["💡 Roeien in zone 2 is bijzonder effectief om met je hele lichaam een aerobe basis op te bouwen","Controleer elke 5 minuten of je split niet is opgelopen — is dat zo, dan is het vermoeidheid: pas aan"]}', '{"images":["/exercise-media/rowing-zone2/0.jpg","/exercise-media/rowing-zone2/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":1800}', '{"substitutions":["rowing-steady-state","rowing-technique-drill","cycling-zone2-ride"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_034', 'scapular-retraction-hang', 'Scapular Pull (Bar Hang)', 'Scapula-activatie in hang', 'strength', '["lower_traps","serratus_anterior","shoulder_girdle"]', NULL, '["strength","mobility","low_impact","no_floor","shoulder_health","loads_shoulder","loads_shoulder"]', '["pull_up_bar"]', NULL, '{"steps":["Hang from the bar in a dead hang with arms fully extended.","Without bending your elbows, depress your shoulder blades — your body will rise slightly.","Hold for a second, then let the shoulder blades rise back to the passive hang position."],"cues":["💡 This is a small movement — 2–3 cm rise, not a full pull-up.","Builds the shoulder stability required for safe, strong pull-ups."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Hang ontspannen aan de stang met je armen volledig gestrekt","Trek zonder je ellebogen te buigen je schouderbladen omlaag — je lichaam komt iets omhoog","Houd een seconde vast en laat je schouderbladen dan weer omhoogkomen naar de passieve hang"],"cues_nl":["💡 Dit is een kleine beweging — 2–3 cm omhoog, geen volledige pull-up","Bouwt de schouderstabiliteit op die je nodig hebt voor veilige, sterke pull-ups"]}', '{"images":["/exercise-media/scapular-retraction-hang/0.jpg","/exercise-media/scapular-retraction-hang/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions":["dead-hang","pull-up"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_053', 'seated-straddle-stretch', 'Seated Straddle Stretch', 'Spreidzit stretch', 'mobility', '["adductors","hamstrings","hip_flexors"]', NULL, '["mobility","low_impact","floor","pregnancy_safe"]', '["none"]', NULL, '{"steps":["Sit on the floor with legs spread wide in a V shape. Sit tall with a neutral spine.","Hinge forward from the hips (not the waist), keeping your back long as you lower your chest toward the floor.","Hold at your comfortable depth. Walk your hands forward to increase the stretch."],"cues":["💡 Sit on a folded blanket if your hips tip back — this immediately improves your fold.","The goal is hip crease going forward, not spine rounding forward."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Ga op de vloer zitten met je benen wijd in een V. Zit rechtop met een neutrale rug","Buig naar voren vanuit je heupen (niet vanuit je taille) en houd je rug lang terwijl je je borst richting de vloer brengt","Blijf op een diepte die prettig voelt. Loop met je handen naar voren om de rek te vergroten"],"cues_nl":["💡 Ga op een opgevouwen deken zitten als je heupen naar achteren kantelen — je komt dan meteen beter naar voren","Het doel is dat je vanuit je heupen naar voren gaat, niet dat je je rug bol maakt"]}', '{"images":["/exercise-media/seated-straddle-stretch/0.jpg","/exercise-media/seated-straddle-stretch/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":60}', '{"substitutions":["seated-butterfly","seated-hamstring-stretch","seated-spinal-twist"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_055', 'shoulder-circles-active', 'Active Shoulder Circles', 'Schoudercirkels (actief)', 'mobility', '["rotator_cuff","deltoids","trapezius"]', NULL, '["mobility","low_impact","no_floor","dynamic","pregnancy_safe","postnatal_safe","shoulder_health","sport_support:swimming","sport_support:climbing","sport_mobility:swimming","sport_mobility:crossfit","loads_shoulder"]', '["none"]', NULL, '{"steps":["Stand with arms at your sides. Begin making small circles forward, gradually increasing the size over 30 seconds.","Reverse the direction — large circles backward for 30 seconds.","Bring arms to a T position and make small backward circles focusing on the rear deltoids."],"cues":["💡 Slow, deliberate circles warm the shoulder capsule better than fast flailing.","Ideal before any upper body session or after a long period of sitting."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Sta met je armen langs je lichaam. Maak kleine cirkels naar voren en maak ze in 30 seconden steeds groter.","Draai de richting om: 30 seconden grote cirkels naar achteren.","Breng je armen in een T en maak kleine cirkels naar achteren, met de focus op je achterste schouderspieren."],"cues_nl":["💡 Langzame, gecontroleerde cirkels warmen je schoudergewricht beter op dan snel zwaaien.","Ideaal voor elke bovenlichaamtraining of na lang zitten."]}', NULL, '{"supports":["time"],"base_duration_sec":60}', '{"substitutions":["chest-opener-arms","kettlebell-halo","shoulder-roll-stretch"]}', 1, 1744700000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_074', 'speed-bag-simulation', 'Speed Bag Simulation', 'Speedbag-beweging (zonder zak)', 'cardio', '["forearms","deltoids","cardiovascular_system"]', NULL, '["cardio","low_impact","bodyweight","upper_body","dynamic","no_floor","loads_shoulder","loads_shoulder"]', '["none"]', NULL, '{"steps":["Raise your hands to face level, elbows bent, hands in loose fists in front of you.","Circle your forearms rhythmically in a forward rolling motion — one in front of the other.","Maintain a steady pace for the duration, keeping elbows at chest height."],"cues":["💡 Excellent active recovery that keeps your heart rate up without impact.","Add small lateral footwork to increase intensity and coordination demand."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Breng je handen op gezichtshoogte, ellebogen gebogen, losse vuisten voor je.","Draai je onderarmen ritmisch in een voorwaartse rolbeweging om elkaar heen.","Houd een constant tempo aan en houd je ellebogen op borsthoogte."],"cues_nl":["💡 Uitstekend actief herstel: je hartslag blijft hoog zonder impact.","Voeg klein zijwaarts voetenwerk toe voor meer intensiteit en coördinatie."]}', NULL, '{"supports":["time"],"base_duration_sec":30}', '{"substitutions": ["shadow-boxing", "standing-bicycle", "seated-cardio-punch", "boxing-combination"]}', 1, 1744700000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_069', 'speed-skater', 'Speed Skater', 'Schaatssprong (snel)', 'cardio', '["glutes","quads","hip_abductors","calves","cardiovascular_system"]', NULL, '["cardio","high_impact","bodyweight","dynamic","no_floor","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand on one leg with a slight bend. Push off laterally, leaping sideways to land on the opposite foot — swing the free leg behind like a speed skater.","Swing your arms across your body as you leap — same-side arm crosses toward the landing leg.","Land softly with a bent knee and immediately push back in the opposite direction."],"cues":["💡 Land as quietly as possible — soft landings protect the knee and build deceleration strength.","The further the leap, the more lateral power you develop."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta op één licht gebogen been. Zet zijwaarts af en spring opzij naar je andere voet — zwaai je vrije been achter je, zoals een schaatser.","Zwaai je armen voor je lichaam langs tijdens de sprong — de arm aan dezelfde kant kruist richting je landingsbeen.","Land zacht met een gebogen knie en zet direct af naar de andere kant."],"cues_nl":["💡 Land zo stil mogelijk — zachte landingen sparen je knie en bouwen afremkracht op.","Hoe verder je springt, hoe meer zijwaartse kracht je opbouwt."]}', NULL, '{"supports":["time"],"base_duration_sec":30}', '{"substitutions":["skater-hop","lateral-shuffle-drill","grapevine-step"]}', 1, 1744700000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_075', 'stair-climb-simulation', 'Stair Climb Simulation', 'Traplopen (simulatie)', 'cardio', '["quads","glutes","calves","cardiovascular_system"]', NULL, '["cardio","low_impact","bodyweight","dynamic","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["chair"]', NULL, '{"steps":["Stand in front of a step, low box, or bottom stair.","Step up with your right foot, then your left, so you''re standing on the step. Step down right, then left.","Increase pace progressively. Lead with the opposite foot each round."],"cues":["💡 Drive through the heel of the stepping foot — not the toe.","Adding a knee drive as you step up turns this into a full lower-body challenge."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Ga voor een step, een lage box of de onderste traptree staan.","Stap op met rechts, dan met links, zodat je op de tree staat. Stap af met rechts, dan met links.","Voer het tempo geleidelijk op. Begin elke ronde met de andere voet."],"cues_nl":["💡 Duw af via de hiel van je opstappende voet, niet via je tenen.","Breng bij het opstappen je knie omhoog en het wordt een volledige uitdaging voor je onderlichaam."]}', NULL, '{"supports":["time"],"base_duration_sec":40}', '{"substitutions":["box-step-up","power-step-up-jump","high-knees"]}', 1, 1744700000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_084', 'stride-outs', 'Stride Outs', 'Hardlopen versnellingen', 'cardio', '["quads","hamstrings","calves","neuromuscular_system"]', NULL, '["cardio","high_impact","skill","conditioning","outdoor","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["After a 10-minute easy jog, begin striding: gradually accelerate over 80–100 m to about 90% of your top speed.","Hold 90% for the middle third, then gradually decelerate over the final 30 m.","Walk or jog easily back to the start. Recover fully between strides."],"cues":["💡 Strides teach your neuromuscular system what fast feels like — they improve running economy.","Focus on relaxation at speed: loose hands, soft shoulders, tall posture."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Begin na 10 minuten rustig joggen met de versnellingen: versnel geleidelijk over 80–100 m tot ongeveer 90% van je topsnelheid","Houd die 90% vast in het middelste derde deel en rem dan geleidelijk af over de laatste 30 m","Wandel of jog rustig terug naar de start. Herstel volledig tussen de versnellingen"],"cues_nl":["💡 Versnellingen leren je zenuwen en spieren hoe snel lopen voelt — ze verbeteren je loopefficiëntie","Let op ontspanning op snelheid: losse handen, zachte schouders, lange houding"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["fartlek-run","run-intervals-outdoor","zone2-easy-run"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_050', 'supine-figure-four', 'Supine Figure-Four Stretch', 'Figuur-4 stretch liggend', 'mobility', '["piriformis","glutes","hip_external_rotators"]', NULL, '["mobility","low_impact","floor","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Lie on your back, knees bent, feet flat. Cross your right ankle over your left knee (figure-four shape).","Option A: stay here for a passive stretch. Option B: reach through and pull your left thigh toward you.","Hold, breathing into the stretch. Switch sides."],"cues":["💡 The closer you pull the thigh, the deeper the stretch — move only as far as comfortable.","Effective for piriformis and posterior hip tightness — often the culprit in lower back pain."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Lig op je rug met je knieën gebogen en je voeten plat. Leg je rechterenkel over je linkerknie (de vorm van een 4)","Optie A: blijf zo liggen voor een passieve rek. Optie B: reik tussen je benen door en trek je linkerdij naar je toe","Houd vast en adem naar de rek toe. Wissel van kant"],"cues_nl":["💡 Hoe dichter je je dij naar je toe trekt, hoe dieper de rek — ga alleen zo ver als prettig voelt","Werkt goed bij een stijve piriformis en achterkant van de heup — vaak de boosdoener bij lage rugpijn"]}', NULL, '{"supports":["time"],"base_duration_sec":60}', '{"substitutions": ["pigeon-pose", "glute-piriformis-stretch", "standing-figure-four", "foam-roll-glutes", "supine-knee-to-chest"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_065', 'supine-knee-to-chest', 'Supine Knee-to-Chest', 'Knie naar borst liggend', 'recovery', '["lower_back","hip_flexors","glutes"]', NULL, '["recovery","mobility","low_impact","floor","pregnancy_safe","postnatal_safe","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie on your back, knees bent, feet flat. Draw one knee toward your chest with both hands.","Hold the stretch in your lower back and hip. Option: gently rock side to side for a massage effect.","Switch legs after 30–45 seconds. For both legs: draw both knees to chest simultaneously."],"cues":["💡 A simple reset for a tight lower back — effective before getting up in the morning.","Keep the opposite leg relaxed and flat — or bend it if your lower back has trouble."],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga op je rug liggen met gebogen knieën en je voeten plat. Trek met beide handen één knie naar je borst","Houd de stretch vast in je onderrug en heup. Optie: wieg rustig van links naar rechts voor een masserend effect","Wissel na 30–45 seconden van been. Voor beide benen: trek beide knieën tegelijk naar je borst"],"cues_nl":["💡 Een eenvoudige reset voor een stijve onderrug — werkt goed voordat je ''s ochtends opstaat","Houd je andere been ontspannen en plat — of buig het als je onderrug moeite heeft"]}', '{"images":["/exercise-media/supine-knee-to-chest/0.jpg","/exercise-media/supine-knee-to-chest/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":60}', '{"substitutions": ["pigeon-pose", "supine-figure-four", "legs-up-wall", "childs-pose", "happy-baby-pose"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_100', 'trail-run-easy', 'Easy Trail Run', 'Hardlopen trail rustig', 'cardio', '["quads","hamstrings","calves","glutes","cardiovascular_system","proprioception"]', NULL, '["cardio","high_impact","outdoor","conditioning","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Choose a trail suitable for your fitness level — wide, well-maintained paths for beginners.","Run at an easy, conversational effort. Reduce to a walk on uphills; pick it back up on the flat.","Focus on where your feet land — uneven terrain demands present-moment attention."],"cues":["💡 Trail running strengthens the stabilisers around your ankles, knees, and hips faster than road running.","Effort over pace — hills will slow your pace; let them. The effort counts."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Kies een trail die past bij je conditie — brede, goed onderhouden paden voor beginners","Loop op een rustige inspanning waarbij je kunt praten. Ga heuvelop over op wandelen en pak het lopen weer op zodra het vlak is","Let op waar je voeten landen — oneffen terrein vraagt je volle aandacht"],"cues_nl":["💡 Trailrunning versterkt de stabiliserende spieren rond je enkels, knieën en heupen sneller dan lopen op de weg","Inspanning gaat boven tempo — heuvels maken je langzamer en dat mag. De inspanning telt"]}', '{"images":["/exercise-media/trail-run-easy/0.jpg","/exercise-media/trail-run-easy/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":2400}', '{"substitutions":["easy-run-outdoor","zone2-easy-run","fartlek-run"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_086', 'treadmill-hill-run', 'Treadmill Hill Run', 'Hardlopen loopband heuvel', 'cardio', '["quads","glutes","calves","cardiovascular_system"]', NULL, '["cardio","high_impact","conditioning","indoor","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["treadmill"]', NULL, '{"steps":["Set the treadmill to 6–10% incline at a moderate speed. Warm up 2 minutes at flat and easy.","Run at this elevation for the duration, focusing on uphill mechanics: driving the knees and pumping the arms.","Every 5 minutes, return to flat for 1 minute to recover."],"cues":["💡 Don''t hold the handrails — it removes most of the cardiovascular benefit.","Incline running builds glutes and calves rapidly; reduce speed compared to flat runs."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Zet de loopband op 6–10% helling en een gemiddelde snelheid. Doe een warming-up van 2 minuten, vlak en rustig","Loop de hele duur op deze helling en let op je klimtechniek: knieën krachtig omhoog en je armen actief meezwaaien","Ga elke 5 minuten 1 minuut terug naar vlak om te herstellen"],"cues_nl":["💡 Houd de leuningen niet vast — daarmee verdwijnt het grootste deel van het effect op je hart en longen","Lopen op een helling bouwt snel je bilspieren en kuiten op; loop langzamer dan op vlak terrein"]}', NULL, '{"supports":["time"],"base_duration_sec":1200}', '{"substitutions":["treadmill-run-steady","treadmill-intervals","hill-repeats-running"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_085', 'treadmill-intervals', 'Treadmill Speed Intervals', 'Hardlopen loopband snelheidsintervallen', 'cardio', '["cardiovascular_system","quads","hamstrings","calves"]', NULL, '["cardio","high_impact","hiit","conditioning","indoor","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["treadmill"]', NULL, '{"steps":["Warm up 3–4 minutes at an easy walk/jog. Set the speed to a challenging but sustainable pace.","Run at this elevated speed for 30–60 seconds, then reduce to a recovery pace for 90–120 seconds.","Repeat the work/rest cycle for the session duration. Cool down with 2 minutes of walking."],"cues":["💡 Set the pace before you step on — fumbling the controls during an interval is a distraction.","Use 1% incline throughout to better replicate outdoor running effort."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Doe een warming-up van 3–4 minuten rustig wandelen of joggen. Zet de snelheid op een uitdagend tempo dat je kunt volhouden","Loop 30–60 seconden op deze hogere snelheid en ga dan 90–120 seconden terug naar een hersteltempo","Herhaal deze afwisseling van inspanning en rust de hele sessie. Sluit af met een cooling-down van 2 minuten wandelen"],"cues_nl":["💡 Stel het tempo in voordat je opstapt — gepruts met de knoppen tijdens een interval leidt af","Gebruik de hele tijd 1% helling; dat lijkt meer op de inspanning van buiten lopen"]}', '{"images":["/exercise-media/treadmill-intervals/0.jpg","/exercise-media/treadmill-intervals/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":1200}', '{"substitutions":["run-intervals-outdoor","treadmill-run-steady","treadmill-hill-run"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_036', 'v-up', 'V-Up', 'V-up', 'strength', '["rectus_abdominis","hip_flexors","core"]', NULL, '["strength","core","low_impact","floor","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie on your back, arms extended overhead, legs straight.","Simultaneously lift your legs and torso toward each other — arms reach toward your toes, forming a ''V'' shape.","Lower back to the floor with control."],"cues":["💡 If you can''t keep legs straight, bend your knees — maintain quality over range.","Exhale sharply as you rise; inhale as you lower."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Core & Stability","steps_nl":["Ga op je rug liggen met je armen gestrekt boven je hoofd en je benen recht","Til tegelijk je benen en bovenlichaam naar elkaar toe — je armen reiken naar je tenen, zodat je een ''V'' vormt","Zak gecontroleerd terug naar de vloer"],"cues_nl":["💡 Lukt het niet om je benen gestrekt te houden, buig dan je knieën — kwaliteit gaat voor bereik","Adem krachtig uit terwijl je omhoogkomt; adem in terwijl je zakt"]}', '{"images":["/exercise-media/v-up/0.jpg","/exercise-media/v-up/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions": ["hollow-body-hold", "hanging-leg-raise", "dead-bug", "bicycle-crunch"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_079', 'walking-lunge', 'Walking Lunge', 'Wandelende uitvalspas', 'cardio', '["quads","glutes","hamstrings","hip_flexors"]', NULL, '["cardio","low_impact","bodyweight","dynamic","loads_knee","loads_knee"]', '["none"]', NULL, '{"steps":["Stand tall with feet together. Step forward with your right foot into a lunge — front knee above ankle, rear knee toward the floor.","Without returning to start, step the rear foot forward to meet the front, then immediately lunge forward with the left foot.","Continue walking forward in this alternating pattern for the prescribed distance or reps."],"cues":["💡 Upright torso — resist leaning forward, even as you get tired.","Long steps challenge glutes and flexibility; shorter steps challenge quads more."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta rechtop met je voeten tegen elkaar. Stap met je rechtervoet naar voren in een uitvalspas — voorste knie boven je enkel, achterste knie richting de vloer.","Stap zonder terug te gaan met je achterste voet naar voren, naast je voorste voet. Maak direct een uitvalspas met je linkervoet.","Loop zo afwisselend door voor de opgegeven afstand of het aantal herhalingen."],"cues_nl":["💡 Houd je bovenlichaam rechtop — leun niet naar voren, ook niet als je moe wordt.","Lange passen vragen meer van je bilspieren en flexibiliteit. Korte passen belasten je bovenbenen meer."]}', '{"images":["/exercise-media/walking-lunge/0.jpg","/exercise-media/walking-lunge/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions": ["reverse-lunge", "dumbbell-lunge", "dumbbell-bulgarian-split-squat", "lunge"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_052', 'wrist-flexor-stretch', 'Wrist Flexor Stretch', 'Polsbuigerstretch', 'mobility', '["forearm_flexors","wrist"]', NULL, '["mobility","low_impact","no_floor","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Extend one arm in front, palm facing up. With the other hand, gently bend the fingers toward the floor.","Hold the stretch until you feel it along the inside of your forearm.","Switch to palm facing down (wrist extension stretch) for the opposing muscles. Repeat on both sides."],"cues":["💡 Essential for anyone who types, grips weights, or cycles — often skipped and later regretted.","Gentle pressure only — the wrist is a complex joint."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Strek één arm voor je uit met je handpalm omhoog. Buig met je andere hand je vingers rustig richting de vloer","Houd de stretch vast tot je hem voelt langs de binnenkant van je onderarm","Draai je handpalm naar beneden (stretch voor de polsstrekkers) voor de tegenoverliggende spieren. Herhaal aan beide kanten"],"cues_nl":["💡 Onmisbaar als je veel typt, gewichten vastpakt of fietst — vaak overgeslagen, en daar krijg je later spijt van","Alleen lichte druk — de pols is een complex gewricht"]}', NULL, '{"supports":["time"],"base_duration_sec":30}', '{"substitutions":["forearm-wrist-stretch","wrist-ankle-circles"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex20_081', 'zone2-easy-run', 'Zone 2 Easy Run', 'Hardlopen zone 2 rustig', 'cardio', '["cardiovascular_system","quads","hamstrings","calves","glutes"]', NULL, '["cardio","low_impact","zone2","conditioning","outdoor","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes","treadmill"]', NULL, '{"steps":["Set off at a fully conversational pace — you must be able to speak in full sentences throughout.","Maintain steady effort, not pace; if you feel out of breath, slow down.","Finish with a 2-minute walk to cool down."],"cues":["💡 Nasal breathing is a useful guide — if you need to open your mouth, you may be above Zone 2.","Zone 2 builds aerobic base and fat-burning capacity. Boring is the point."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Vertrek in een tempo waarbij je volledig kunt praten — je moet de hele loop in hele zinnen kunnen spreken","Houd je inspanning gelijk, niet je tempo; raak je buiten adem, loop dan langzamer","Sluit af met 2 minuten wandelen als cooling-down"],"cues_nl":["💡 Ademen door je neus is een handige graadmeter — moet je je mond opendoen, dan zit je mogelijk boven zone 2","Zone 2 bouwt je aerobe basis en je vetverbranding op. Saai is precies de bedoeling"]}', NULL, '{"supports":["time"],"base_duration_sec":1800}', '{"substitutions": ["easy-run-outdoor", "treadmill-run-steady", "brisk-walk", "fartlek-run", "stride-outs"]}', 1, 1744700000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('31e428cb-06fe-58f7-b602-79a8e66ab1ff', '12-minuten-loop', '12 minuten loop (Cooper test)', '12 minuten loop (Cooper test)', 'cardio', '["quads","hamstrings","calves","glutes","cardiovascular_system"]', '[]', '["running","fitness-test","baseline","endurance","military","protocol","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Run as many meters as possible in 12 minutes at a sustainable pace"],"cues":["Baseline fitness test (nul-meting)","Track total distance covered","Pace yourself — do not sprint early"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop in 12 minuten zo veel mogelijk meters in een tempo dat je kunt volhouden"],"cues_nl":["Nulmeting van je conditie","Houd de totale afstand bij","Verdeel je krachten — sprint niet in het begin"]}', NULL, '{"supports": ["time", "distance"], "base_duration_sec": 720, "fixed_duration": true}', '{"substitutions":["hardlopen-zone-1-5-minuten-warmup","hardlopen-zone-1-10-minuten"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('645254e8-4dcb-52a3-b16c-9504340b1484', 'cooling-down', 'Cooling-down', 'Cooling-down', 'recovery', '[]', '[]', '["cool-down", "stretching", "mobility"]', '["none"]', NULL, '{"steps":["Easy jog or walk for 5 minutes (zone 1 pace)","Perform static stretches for major muscle groups (quads, hamstrings, calves, hip flexors)"],"cues":["Low intensity","Hold each stretch 20–30 s","Breathe deeply throughout"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Jog of wandel 5 minuten rustig uit (tempo zone 1)","Doe statische stretches voor de grote spiergroepen (quadriceps, hamstrings, kuiten, heupbuigers)"],"cues_nl":["Lage intensiteit","Houd elke stretch 20–30 s vast","Blijf diep doorademen"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["body-scan-meditation","box-breathing"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('651944bc-7774-5ad5-84dd-51aa1d1d4bae', 'deadlift', 'Deadlift', 'Deadlift', 'strength', '["glutes", "hamstrings"]', '["lats", "abs", "traps"]', '["lower-body","compound","military","loads_shoulder","loads_knee","loads_lower_back"]', '["barbell"]', NULL, '{"steps":["Stand with barbell (or weighted rucksack/box) over mid-foot, feet hip-width","Hinge at hips and grip object firmly","Brace core, keep back straight, press floor away to lift","Lock hips and knees fully at top","Lower with control"],"cues":["Do 3 sets of sustained effort with 30 s rest between sets","You can swap the barbell for a filled rucksack or a sturdy box","Keep a flat back throughout — do not round it"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga staan met de barbell (of een verzwaarde rugzak of doos) boven het midden van je voeten, voeten op heupbreedte","Scharnier vanuit je heupen en pak het voorwerp stevig vast","Span je core aan, houd je rug recht en duw de vloer weg om te tillen","Strek bovenin je heupen en knieën volledig","Laat gecontroleerd zakken"],"cues_nl":["Doe 3 sets met aanhoudende inspanning, met 30 s rust tussen de sets","Je kunt de barbell vervangen door een gevulde rugzak of een stevige doos","Houd je rug de hele tijd vlak — maak hem niet bol"]}', '{"images":["/exercise-media/deadlift/0.jpg","/exercise-media/deadlift/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"barbell"}', '{"substitutions":["glute-bridge","good-morning-bodyweight"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a347874a-e92f-500c-ab38-fc3660355a31', 'graaftest', 'Graaftest', 'Graaftest', 'skill', '["obliques","shoulders"]', '["glutes","quads"]', '["rotation","core","military","functional","protocol","loads_shoulder","loads_knee","loads_lower_back"]', '["dumbbell"]', NULL, '{"steps":["Stand with feet shoulder-width apart, weight held in both hands","Lower the weight diagonally to hip height on one side — start position","In one explosive movement, rotate and lift the weight diagonally to shoulder height on the opposite side","Reverse under control back to start position — this is one repetition","Alternate sides each set or complete all reps on one side first"],"cues":["Use a medicine ball, dumbbell, or kettlebell — any weighted implement is valid","Drive the movement from your hips and core, not your arms","Keep a neutral spine throughout","Test is scored on power and control of the rotation"],"why":"Skill training builds neuromuscular coordination — the connection between brain and muscle that makes movement efficient and automatic.","muscle_target":"Core & Stability","steps_nl":["Sta met je voeten op schouderbreedte en houd het gewicht met beide handen vast","Laat het gewicht aan één kant diagonaal zakken tot heuphoogte — dit is de startpositie","Draai in één explosieve beweging en til het gewicht diagonaal naar schouderhoogte aan de andere kant","Ga gecontroleerd terug naar de startpositie — dit is één herhaling","Wissel elke set van kant of doe eerst alle herhalingen aan één kant"],"cues_nl":["Gebruik een medicijnbal, dumbbell of kettlebell — elk gewicht is goed","Zet de beweging in vanuit je heupen en core, niet vanuit je armen","Houd je rug de hele tijd neutraal","De test wordt beoordeeld op kracht en controle van de draai"]}', NULL, '{"supports":["reps","sets","time","weight"],"load_type":"dumbbell_pair"}', '{"substitutions":["til-draagtest-full-exercise","optillen-vanaf-de-grond"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('886c63db-e3af-5a6e-8d90-77b0a2d9af59', 'hardlopen-zone-1-10-minuten', 'Hardlopen zone 1 - 10 minuten', 'Hardlopen zone 1 - 10 minuten', 'cardio', '["quads","hamstrings","calves","glutes","cardiovascular_system"]', '[]', '["running","zone-1","endurance","military","protocol","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Run at zone 1 intensity for 10 minutes"],"cues":["Zone 1 = easy/recovery pace, low heart rate"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop 10 minuten in zone 1"],"cues_nl":["Zone 1 = rustig hersteltempo, lage hartslag"]}', NULL, '{"supports": ["time"], "base_duration_sec": 600, "fixed_duration": true}', '{"substitutions":["hardlopen-zone-1-1x5-minuten","hardlopen-zone-1-2200-meter","12-minuten-loop","hardlopen-zone-1-2700-meter","hardlopen-zone-1-7-minuten"]}', 1, 1746230400000, 1795305600000);
