  ('0add4e6a-f1a5-57b2-b601-ff1c14cdd4f2', 'hardlopen-zone-1-5-minuten-warmup', 'Hardlopen zone 1 - 5 minuten (inlopen)', 'Hardlopen zone 1 - 5 minuten (inlopen)', 'cardio', '["quads","hamstrings","calves","glutes","cardiovascular_system"]', '[]', '["running","zone-1","warm-up","military","protocol","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Run at a very easy conversational pace for 5 minutes as warm-up"],"cues":["Zone 1 = very light effort, able to hold a full conversation","Used specifically as pre-workout warm-up (inlopen)"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop 5 minuten in als warming-up, in een heel rustig tempo waarbij je kunt praten"],"cues_nl":["Zone 1 = heel lichte inspanning, je kunt een heel gesprek voeren","Speciaal bedoeld als inlopen vóór je training"]}', NULL, '{"supports": ["time"], "base_duration_sec": 300, "fixed_duration": true}', '{"substitutions":["hardlopen-zone-1-7-minuten","hardlopen-zone-1-1x5-minuten"]}', 1, 1746230400000, 1795305600000);
