  ('674ecd27-0ceb-582e-b98e-8c28a6ce3426', 'hardlopen-zone-2-2700-meter', 'Hardlopen zone 2 - 2700 meter', 'Hardlopen zone 2 - 2700 meter', 'cardio', '["quads","hamstrings","calves","glutes","cardiovascular_system"]', '[]', '["running","zone-2","intervals","distance-target","military","protocol","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Run 8 minutes at zone 2 intensity","Rest 2 minutes between sets","Repeat for 2 sets total — aim to cover 2700 meters in all"],"cues":["Moderate effort","Pace to cover distance within interval window"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop 8 minuten in zone 2","Neem 2 minuten rust tussen de sets","Herhaal tot je in totaal 2 sets hebt gedaan — probeer samen 2700 meter af te leggen"],"cues_nl":["Matige inspanning","Kies je tempo zo dat je de afstand binnen de intervallen haalt"]}', NULL, '{"supports": ["distance", "time", "sets"], "base_duration_sec": 932, "fixed_duration": true}', '{"substitutions":["hardlopen-zone-1-10-minuten","hardlopen-zone-1-1x5-minuten"]}', 1, 1746230400000, 1795305600000);
