  ('5c5275e3-c4f7-576e-bc5c-249b1a617cb1', 'hardlopen-zone-2-2x10-minuten', 'Hardlopen zone 2 - 2x10 minuten', 'Hardlopen zone 2 - 2x10 minuten', 'cardio', '["quads","hamstrings","calves","glutes","cardiovascular_system"]', '[]', '["running","zone-2","intervals","military","protocol","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Run 10 minutes at zone 2 intensity","Recover 2 minutes at zone 1","Repeat for 2 sets total"],"cues":["Zone 2 = moderate effort"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop 10 minuten in zone 2","Herstel 2 minuten in zone 1","Herhaal tot je in totaal 2 sets hebt gedaan"],"cues_nl":["Zone 2 = matige inspanning"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 600, "fixed_duration": true, "fixed_sets": 2}', '{"substitutions":["hardlopen-zone-1-10-minuten","hardlopen-zone-1-1x5-minuten"]}', 1, 1746230400000, 1795305600000);
