  ('c5950b20-8666-5837-9756-bf2c2125fa89', 'hardlopen-zone-5-6x30-seconden', 'Hardlopen zone 5 - 6x30 seconden', 'Hardlopen zone 5 - 6x30 seconden', 'cardio', '["quads","hamstrings","glutes","calves","cardiovascular_system"]', '[]', '["running","zone-5","max-effort","repeats","high_impact","military","protocol","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Sprint at maximum effort for 30 seconds","Rest (zone 1 or full rest) for 30 seconds or 2 minutes as prescribed","Repeat for 6 sets total"],"cues":["Zone 5 = maximal sprint","Source prescribes either 30 s or 2 min rest — confirm per session plan"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sprint 30 seconden op maximale inspanning","Rust 30 seconden of 2 minuten (zone 1 of volledige rust), zoals in je schema staat","Herhaal tot je in totaal 6 sets hebt gedaan"],"cues_nl":["Zone 5 = maximale sprint","De bron schrijft 30 s of 2 min rust voor — kijk in je schema welke geldt"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 30, "fixed_duration": true}', '{"substitutions":["hardlopen-zone-1-10-minuten","hardlopen-zone-1-1x5-minuten"]}', 1, 1746230400000, 1795305600000);
