  ('61e60c7f-887c-5a74-8de1-7aefbaac6aea', 'heup-brug', 'Heup brug', 'Heupbrug (militair)', 'strength', '["glutes"]', '["hamstrings", "lower_back"]', '["lower-body","glutes","bodyweight","supine","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie on back with knees bent and feet flat on floor hip-width apart","Press through heels and drive hips upward until body forms a straight line from shoulders to knees","Squeeze glutes at top, hold briefly","Lower with control"],"cues":["Do 4 sets of 10 s with 30 s rest between sets","Do not hyperextend the lower back at top","Keep core braced throughout"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Ga op je rug liggen met je knieën gebogen en je voeten plat op de vloer op heupbreedte","Duw via je hielen je heupen omhoog tot je lichaam een rechte lijn vormt van schouders tot knieën","Span bovenin je bilspieren aan en houd kort vast","Laat gecontroleerd zakken"],"cues_nl":["Doe 4 sets van 10 s met 30 s rust tussen de sets","Overstrek je onderrug bovenin niet","Houd je core de hele tijd aangespannen"]}', '{"images":["/exercise-media/heup-brug/0.jpg","/exercise-media/heup-brug/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["standing-hip-abduction","glute-bridge"]}', 1, 1746230400000, 1795305600000);
