  ('165b4008-cbf8-59bc-9e1d-a736ad7c235c', 'marsen-6-km-u-8-minuten-rugzak-45kg', 'Marsen (6 km/u) - 8 minuten (rugzak 45 kg)', 'Rugzakmars 6 km/u · 8 min (45 kg)', 'cardio', '["quads","hamstrings","glutes","calves","core","upper_back"]', '[]', '["walking","march","weighted","military","protocol","loads_shoulder","loads_knee","loads_lower_back","loads_ankle"]', '["rucksack"]', NULL, '{"steps":["March at 6 km/h for 8 minutes with 45 kg rucksack"],"cues":["Very heavy loaded march — caution with posture and lower back","45 kg pack"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Marcheer 8 minuten op 6 km/u met een rugzak van 45 kg"],"cues_nl":["Zeer zware mars met rugzak — let op je houding en je onderrug","Rugzak van 45 kg"]}', NULL, '{"supports": ["time"], "base_duration_sec": 480, "fixed_duration": true}', '{"substitutions":["marsen-5-5-km-u-25-minuten","marsen-6-km-u-30-minuten"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('2ea4afcf-e936-57b3-8e69-0eba3365195a', 'optillen-vanaf-de-grond', 'Optillen vanaf de grond', 'Optillen vanaf de grond', 'strength', '["glutes","quads"]', '["lats","abs"]', '["power","lower-body","military","protocol","loads_shoulder","loads_knee","loads_lower_back"]', '["none"]', NULL, '{"steps":["Stand with feet shoulder-width apart over the object (rucksack, crate, or box)","Hinge at hips and knees with flat back and grip the object firmly","Lift the object explosively from floor to hip height","Lower with control back to the floor"],"cues":["Do 3 sets of 30 s with 30 s rest between sets","Keep back straight throughout","Object: filled rucksack, crate, or box — test standard uses a munitiekist (20 kg Basis/K1, 30 kg K2-K6, 40 kg K3/K5/K6)"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta met je voeten op schouderbreedte boven het voorwerp (rugzak, krat of doos)","Buig vanuit je heupen en knieën met een rechte rug en pak het voorwerp stevig vast","Til het voorwerp explosief van de vloer tot heuphoogte","Laat het gecontroleerd terugzakken naar de vloer"],"cues_nl":["Doe 3 sets van 30 s met 30 s rust tussen de sets","Houd je rug de hele tijd recht","Voorwerp: gevulde rugzak, krat of doos — bij de test wordt een munitiekist gebruikt (20 kg Basis/K1, 30 kg K2-K6, 40 kg K3/K5/K6)"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["til-draagtest-gewicht-plaatsen-naar-heupen","graaftest"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a883e6b1-9f59-5c2a-93c7-d3c4af7b5ff9', 'optillen-vanaf-de-grond-rugzak', 'Optillen vanaf de grond (rugzak)', 'Optillen vanaf de grond (rugzak)', 'strength', '["glutes", "quads"]', '["lats", "abs"]', '["power","lower-body","weighted","military","protocol","loads_shoulder","loads_knee","loads_lower_back","loads_ankle"]', '["rucksack"]', NULL, '{"steps":["Stand over a loaded rucksack on the floor","Hinge at hips and knees with flat back, grip rucksack handles","Lift rucksack from ground to hip height explosively","Lower with control"],"cues":["Do 3 sets of 30 s with 30 s rest between sets","Keep back straight — do not round"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga boven een gevulde rugzak op de vloer staan","Buig vanuit je heupen en knieën met een rechte rug en pak de handvatten van de rugzak vast","Til de rugzak explosief van de grond tot heuphoogte","Laat hem gecontroleerd zakken"],"cues_nl":["Doe 3 sets van 30 s met 30 s rust tussen de sets","Houd je rug recht — maak hem niet bol"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["optillen-vanaf-de-grond","til-draagtest-full-exercise"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('fabb91a7-1fc4-58db-8913-58b7d1270023', 'plyo-push-up', 'Plyo Push Up', 'Opdrukken explosief (plyo)', 'strength', '["chest"]', '["delts_front", "triceps"]', '["upper-body","push","bodyweight","plyometric","high_impact","prone","military","loads_shoulder"]', '["none"]', NULL, '{"steps":["Start in push-up position","Lower chest to floor under control","Explode upward pushing hard enough for hands to leave the floor","Land softly with bent elbows and immediately descend for next rep"],"cues":["Do 5 sets of 3–10 reps with 2 min rest between sets","Explosive push = maximum force","Land with control each time"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Start in de opdrukpositie","Laat je borst gecontroleerd naar de vloer zakken","Duw explosief omhoog, hard genoeg om je handen van de vloer te laten komen","Land zacht met gebogen ellebogen en zak direct in voor de volgende herhaling"],"cues_nl":["Doe 5 sets van 3–10 herhalingen met 2 min rust tussen de sets","Explosief duwen = maximale kracht","Land elke keer gecontroleerd"]}', NULL, '{"supports": ["reps", "sets"]}', '{"substitutions":["push-up","knee-push-up"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('2d8a7f87-6da3-5a85-a582-ea4433b1be8f', 'shoulder-tap', 'Shoulder tap', 'Shoulder tap', 'strength', '["abs", "obliques"]', '["delts_front"]', '["core","stability","bodyweight","loads_shoulder"]', '["none"]', NULL, '{"steps":["Start in high plank position with hands under shoulders and feet hip-width apart","While maintaining stable hips, lift right hand and tap left shoulder","Return and repeat with left hand to right shoulder"],"cues":["Do 4 sets of 10 s with 30 s rest between sets","Resist rotation — hips stay square","Wider foot stance makes it easier"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Core & Stability","steps_nl":["Start in een hoge plank met je handen onder je schouders en je voeten op heupbreedte","Houd je heupen stabiel, til je rechterhand op en tik je linkerschouder aan","Zet je hand terug en herhaal met je linkerhand naar je rechterschouder"],"cues_nl":["Doe 4 sets van 10 s met 30 s rust tussen de sets","Weersta de draaiing — je heupen blijven recht","Met je voeten breder is het makkelijker"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["voorwaartse-plank","modified-plank","zijwaartse-plank"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('701fef69-7cfc-5b6a-916b-0c5f2887eeaa', 'split-squat', 'Split Squat', 'Split squat', 'strength', '["quads", "glutes"]', '["hamstrings"]', '["lower-body","unilateral","bodyweight","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Step one foot forward into a lunge stance and stay stationary","Lower the rear knee toward the floor keeping front shin vertical","Drive through front foot to return to start"],"cues":["Do 4 sets of 10 reps per leg with 2 min rest between sets","Keep torso upright","Front knee tracks over second toe"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Stap met één voet naar voren in een uitvalspasstand en blijf op die plek staan","Laat je achterste knie richting de vloer zakken en houd je voorste scheenbeen verticaal","Duw door je voorste voet om terug te komen naar de start"],"cues_nl":["Doe 4 sets van 10 herhalingen per been met 2 min rust tussen de sets","Houd je bovenlichaam rechtop","Je voorste knie blijft in lijn met je tweede teen"]}', '{"images":["/exercise-media/split-squat/0.jpg","/exercise-media/split-squat/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["reps", "sets"]}', '{"substitutions":["forward-lunge","walking-lunges"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('3c95a4f9-ffc5-5c2b-ba80-b457fc282c06', 'squat-calf-raise', 'Squat Calf Raise', 'Squat met kuitheffen', 'strength', '["quads", "calves"]', '["glutes"]', '["lower-body","compound","bodyweight","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with feet shoulder-width apart","Perform a squat","As you rise back up, continue onto your toes for a calf raise","Lower heels and immediately begin next squat"],"cues":["Work for 30 s, then rest for 30 s","Control the calf raise — do not bounce"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Sta met je voeten op schouderbreedte","Maak een squat","Kom omhoog en ga in één beweging door tot op je tenen voor een kuitheffing","Laat je hielen zakken en begin direct aan de volgende squat"],"cues_nl":["Werk 30 s en rust daarna 30 s","Doe de kuitheffing gecontroleerd — niet veren"]}', NULL, '{"supports": ["reps", "time"]}', '{"substitutions":["soleus-wall-sit","bent-knee-calf-raise"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('3447ec47-f3da-582d-8207-22733d6f872b', 'squat-jump', 'Squat Jump', 'Squat jump', 'strength', '["quads", "glutes"]', '["calves", "abs"]', '["plyometric","power","lower-body","bodyweight","high_impact","military","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with feet shoulder-width apart","Squat down to parallel","Explode upward jumping off both feet","Land softly with bent knees and immediately descend into next squat"],"cues":["Work for 30 s, rest for 1 min and repeat the circuit 3× in total","Land quietly — absorb impact through legs not back"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Sta met je voeten op schouderbreedte","Zak in een squat tot je dijen horizontaal zijn","Spring explosief omhoog en zet af met beide voeten","Land zacht met gebogen knieën en zak direct in de volgende squat"],"cues_nl":["Werk 30 s, rust 1 min en herhaal het circuit in totaal 3×","Land stil — vang de klap op met je benen, niet met je rug"]}', '{"images":["/exercise-media/squat-jump/0.jpg","/exercise-media/squat-jump/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["time", "reps"]}', '{"substitutions":["wall-sit","split-squat"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('02924279-73f8-5057-9be7-eddb4e3a8dda', 'step-up', 'Step up', 'Opstap', 'strength', '["quads", "glutes"]', '["hamstrings"]', '["lower-body","unilateral","bodyweight","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand in front of a step, box or bench (knee height approximately)","Step up with one foot, drive through that heel to stand fully on the surface","Bring the trailing foot up to join, then step back down","Alternate lead leg"],"cues":["Keep going for 30 s","Controlled descent","Keep chest up throughout"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Ga voor een opstapje, box of bank staan (ongeveer kniehoogte)","Stap op met één voet en duw door die hiel tot je helemaal rechtop op het vlak staat","Zet je andere voet erbij en stap dan weer af","Wissel het been waarmee je opstapt af"],"cues_nl":["Ga 30 s door","Zak gecontroleerd","Houd je borst de hele tijd omhoog"]}', NULL, '{"supports": ["time", "reps"]}', '{"substitutions":["forward-lunge","walking-lunges"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('485f47ea-5303-5bfa-bd2a-66f043d49add', 'til-draagtest-full-exercise', 'Til/draagtest: Full exercise', 'Til/draagtest: volledige oefening', 'skill', '["glutes","lats"]', '["abs","quads"]', '["full-body","military","protocol","loads_shoulder","loads_knee","loads_lower_back"]', '["none"]', NULL, '{"steps":["Stand in front of the munitiekist (ammunition crate) on the floor and grip the handles","Lift the crate from the floor and carry it 25 metres to the lift table","Place the crate on the table at shoulder height (115-135 cm, adjusted to body height)","Lift the crate from the table and carry it 25 metres back","Lower the crate to the floor — this completes one repetition","Start a new repetition every 25 seconds; do 2 sets of 10 reps with 30 s rest between sets"],"cues":["Test weights: 20 kg (Basis/K1), 20+30 kg (K2/K4), 20+30+40 kg (K3/K5/K6)","Arms horizontal at shoulder height when gripping handles","Train with the weight appropriate for your cluster target"],"why":"Skill training builds neuromuscular coordination — the connection between brain and muscle that makes movement efficient and automatic.","muscle_target":"Coordination & Control","steps_nl":["Ga voor de munitiekist op de vloer staan en pak de handgrepen vast","Til de kist van de vloer en draag hem 25 meter naar de tiltafel","Zet de kist op de tafel op schouderhoogte (115-135 cm, afgestemd op je lichaamslengte)","Til de kist van de tafel en draag hem 25 meter terug","Zet de kist op de vloer — dat is één herhaling","Start elke 25 seconden een nieuwe herhaling; doe 2 sets van 10 herhalingen met 30 s rust tussen de sets"],"cues_nl":["Testgewichten: 20 kg (Basis/K1), 20+30 kg (K2/K4), 20+30+40 kg (K3/K5/K6)","Armen horizontaal op schouderhoogte als je de handgrepen vastpakt","Train met het gewicht dat past bij je clusterdoel"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["til-draagtest-gewicht-plaatsen-naar-heupen","optillen-vanaf-de-grond"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('f29f1e9c-c415-508e-adc3-375999c3b844', 'til-draagtest-gewicht-plaatsen-naar-heupen', 'Til/draagtest: Gewicht plaatsen naar heupen', 'Til/draagtest: gewicht naar heupen', 'skill', '["glutes","quads"]', '["lats","abs"]', '["power","military","protocol","loads_shoulder","loads_knee","loads_lower_back"]', '["none"]', NULL, '{"steps":["Stand in front of the munitiekist (ammunition crate) on the floor","Grip the handles firmly — arms horizontal at shoulder height when extended","Explosively lift the crate from the floor to shoulder height in one fast movement","Place the crate on the lift table at shoulder height (115-135 cm, adjusted to body height)","Lower the crate with control","Do 5 sets of 10 s with 2 min rest"],"cues":["Fast explosive execution","Test weights: 20 kg (Basis/K1), 30 kg (K2/K4), 40 kg (K3/K5/K6)","New repetition every 25 seconds in the actual test"],"why":"Skill training builds neuromuscular coordination — the connection between brain and muscle that makes movement efficient and automatic.","muscle_target":"Coordination & Control","steps_nl":["Ga voor de munitiekist op de vloer staan","Pak de handgrepen stevig vast — armen horizontaal op schouderhoogte als ze gestrekt zijn","Til de kist explosief van de vloer naar schouderhoogte in één snelle beweging","Zet de kist op de tiltafel op schouderhoogte (115-135 cm, afgestemd op je lichaamslengte)","Laat de kist gecontroleerd zakken","Doe 5 sets van 10 s met 2 min rust"],"cues_nl":["Snel en explosief uitvoeren","Testgewichten: 20 kg (Basis/K1), 30 kg (K2/K4), 40 kg (K3/K5/K6)","In de echte test start elke 25 seconden een nieuwe herhaling"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 45}', '{"substitutions":["til-draagtest-full-exercise","optillen-vanaf-de-grond"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('0176a457-5a1e-5c63-9499-a9d071099431', 'voorwaartse-plank', 'Voorwaartse plank', 'Voorwaartse plank', 'strength', '["abs", "obliques"]', '["delts_front", "glutes"]', '["core","stability","bodyweight","loads_shoulder"]', '["none"]', NULL, '{"steps":["Place your forearms flat on the floor with your elbows directly under your shoulders","Support your body on your forearms and toes in a straight line from head to heels","Hold the position for the set, then lower your knees to the floor"],"cues":["Do 4 sets of 10 s with 30 s rest between sets","Squeeze glutes and abs","Do not let hips drop or rise"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Core & Stability","steps_nl":["Leg je onderarmen plat op de vloer met je ellebogen recht onder je schouders","Steun op je onderarmen en tenen, met je lichaam in een rechte lijn van hoofd tot hielen","Houd deze positie de hele set vast en zet daarna je knieën op de vloer"],"cues_nl":["Doe 4 sets van 10 s met 30 s rust tussen de sets","Span je bilspieren en buikspieren aan","Laat je heupen niet zakken of omhoogkomen"]}', '{"images":["/exercise-media/voorwaartse-plank/0.jpg","/exercise-media/voorwaartse-plank/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["shoulder-tap","modified-plank"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('068e51c0-7c11-5c1a-bf61-97f4467659f8', 'walking-lunges', 'Walking Lunges', 'Wandelende uitvalspassen', 'strength', '["quads", "glutes"]', '["hamstrings"]', '["lower-body","unilateral","bodyweight","military","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Step forward with right leg into a lunge, lowering back knee toward floor","Push through front heel to rise and immediately step forward with left leg into next lunge","Continue walking forward"],"cues":["Keep going for 30 s","Keep torso upright","Controlled descent each rep"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Stap met je rechterbeen naar voren in een uitvalspas en laat je achterste knie richting de vloer zakken","Duw door je voorste hiel omhoog en stap direct met je linkerbeen door in de volgende uitvalspas","Blijf zo vooruit lopen"],"cues_nl":["Ga 30 s door","Houd je bovenlichaam rechtop","Zak elke herhaling gecontroleerd"]}', '{"images":["/exercise-media/walking-lunges/0.jpg","/exercise-media/walking-lunges/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["reps", "time"]}', '{"substitutions":["reverse-lunge","split-squat"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a46be110-e86b-5abb-9000-a6aa84c51184', 'warming-up', 'Warming-up', 'Warming-up', 'recovery', '[]', '[]', '["warm-up", "mobility"]', '["none"]', NULL, '{"steps":["Perform dynamic stretching and movement preparation for 5–10 minutes"],"cues":["Include: leg swings, arm circles, hip rotations, high knees, butt kicks","Progressive intensity — start gentle, build to workout pace"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Doe 5–10 minuten dynamische stretches en bewegingen om je lichaam voor te bereiden"],"cues_nl":["Denk aan: beenzwaaien, armcirkels, heuprotaties, knieheffen, hakken-billen","Bouw de intensiteit op — begin rustig en werk toe naar je trainingstempo"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["leg-swings-front-back","leg-swings-lateral"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('86766191-db95-54af-be15-3046fee4bfec', 'wissel-sprongen', 'Wissel sprongen', 'Wisselsprongen', 'strength', '["glutes", "quads"]', '["calves", "abs"]', '["plyometric","power","bodyweight","high_impact","military","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand in a split stance with one foot forward, one back","Jump explosively and switch foot positions in mid-air","Land softly with opposite foot forward and immediately repeat"],"cues":["Do 4 sets of 10 s with 30 s rest between sets","Land softly each rep","Stay on balls of feet throughout"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Sta in een spreidstand met één voet voor en één voet achter","Spring explosief omhoog en wissel in de lucht van voetpositie","Land zacht met je andere voet voor en herhaal direct"],"cues_nl":["Doe 4 sets van 10 s met 30 s rust tussen de sets","Land elke herhaling zacht","Blijf de hele tijd op je voorvoeten"]}', NULL, '{"supports": ["time", "reps"]}', '{"substitutions":["walking-lunges","wall-sit"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('afad7a10-01bb-5d56-ada6-743c01b0500a', 'zijwaartse-plank', 'Zijwaartse plank', 'Zijwaartse plank', 'strength', '["obliques"]', '["abs", "glutes"]', '["core","stability","bodyweight","loads_shoulder"]', '["none"]', NULL, '{"steps":["Lie on your side and prop up on one forearm with elbow directly below shoulder","Stack feet or stagger them for stability","Lift hips so body forms a straight diagonal line from head to feet","Hold, then repeat on other side"],"cues":["Do 4 sets of 10 s per side with 30 s rest between sets","Do not let hips sag or rotate forward","Squeeze obliques throughout"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Core & Stability","steps_nl":["Ga op je zij liggen en steun op één onderarm, met je elleboog recht onder je schouder","Leg je voeten op elkaar of zet ze achter elkaar voor meer stabiliteit","Til je heupen op tot je lichaam een rechte schuine lijn vormt van hoofd tot voeten","Houd vast en herhaal daarna aan de andere kant"],"cues_nl":["Doe 4 sets van 10 s per kant met 30 s rust tussen de sets","Laat je heupen niet doorzakken of naar voren draaien","Span je schuine buikspieren de hele tijd aan"]}', '{"images":["/exercise-media/zijwaartse-plank/0.jpg","/exercise-media/zijwaartse-plank/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["modified-plank","shoulder-tap"]}', 1, 1746230400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_mil_cooper_test', '12-minute-cooper-test', '12-Minute Cooper Test', 'Cooper test (12 min)', 'cardio', '["cardiovascular","quads","hamstrings","calves"]', NULL, '["cardio","outdoor","assessment","military","running","protocol","measurable","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Start a 12-minute timer on a measured track or GPS route","Run as far as possible in 12 minutes — pace yourself so you do not blow up in the first 3 minutes","Record the total distance covered when the timer ends"],"cues":["Even pacing beats going out fast and dying — aim for a pace you can hold for 10 minutes, then push the final 2","Your distance maps to your fitness level: < 2000 m = below baseline, 2400–2800 m = Cluster 1–3, > 2800 m = Cluster 4–6","💡 Use this as a benchmark every 4–6 weeks — not as a training session in itself"],"pregnancy_note":"Not appropriate during pregnancy. Consult your healthcare provider for a modified cardiovascular assessment.","why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Start een timer van 12 minuten op een gemeten baan of een gps-route","Loop in 12 minuten zo ver als je kunt — verdeel je krachten, zodat je niet in de eerste 3 minuten stukgaat","Noteer de totale afstand zodra de timer afloopt"],"cues_nl":["Een gelijkmatig tempo wint het van hard starten en instorten — kies een tempo dat je 10 minuten volhoudt en zet de laatste 2 minuten aan","Je afstand zegt iets over je conditieniveau: < 2000 m = onder het basisniveau, 2400–2800 m = cluster 1–3, > 2800 m = cluster 4–6","💡 Gebruik dit elke 4–6 weken als meetmoment — niet als training op zich"],"pregnancy_note_nl":"Niet geschikt tijdens de zwangerschap. Overleg met je verloskundige of arts over een aangepaste conditietest."}', NULL, '{"supports":["time"],"base_duration_sec":720}', NULL, 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('1bb090ff-532b-5a98-b849-d170214b0f46', '90-90-stretch', '90-90 Stretch', 'Heup 90/90 stretch', 'mobility', '["hips","glutes"]', '["adductors"]', '["mobility","stretch","low_impact","quiet","floor","sport_mobility:running","sport_mobility:football","sport_mobility:skiing","sport_mobility:crossfit"]', '["none"]', '["exercise_mat"]', '{"steps":["Sit with one leg in front bent about 90 degrees and the other leg out to the side bent about 90 degrees","Sit tall and lean gently over your front shin to open the hip (external rotation)","Come back up and rotate your chest toward your back leg (internal rotation)","Move slowly, keep breathing, then switch legs"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","cues":["Keep your back long — fold from the hips, do not round","Go to a firm stretch, never to pain in your knee or hip"],"steps_nl":["Ga zitten met één been voor je, ongeveer 90 graden gebogen, en het andere been opzij, ook ongeveer 90 graden gebogen","Zit rechtop en leun rustig over je voorste scheenbeen om je heup te openen (exorotatie)","Kom terug omhoog en draai je borst naar je achterste been (endorotatie)","Beweeg langzaam, adem door en wissel daarna van been"],"cues_nl":["Houd je rug lang — buig vanuit je heupen, maak je rug niet bol","Ga tot een stevige rek, nooit tot pijn in je knie of heup"]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions": ["pigeon-pose", "hip-flexor-stretch"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('8d10d81c-af7c-5e5b-a855-5eb00134952d', 'air-squat', 'Air Squat', 'Squat zonder gewicht', 'strength', '["quadriceps","glutes","hamstrings"]', '["core","calves"]', '["strength","bodyweight","lower_body","squat","no_floor","quiet","low_impact","loads_knee","loads_knee","loads_ankle"]', '["none"]', '["none"]', '{"steps":["Stand with feet shoulder-width apart.","Sit hips back and down, keeping heels grounded.","Reach comfortable depth with neutral spine.","Stand up fully, squeezing glutes at the top."],"cues":["Knees track over toes.","Chest tall, brace core."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Sta met je voeten op schouderbreedte","Zak met je heupen naar achteren en omlaag en houd je hielen op de vloer","Zak tot een diepte die prettig voelt, met een neutrale rug","Kom helemaal omhoog en span bovenaan je bilspieren aan"],"cues_nl":["Knieën bewegen in de lijn van je tenen","Borst hoog, span je core aan"]}', '{"images":["/exercise-media/air-squat/0.jpg","/exercise-media/air-squat/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","tempo"]}', '{"substitutions":["goblet-squat","wall-sit"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_back_squat', 'back-squat', 'Back Squat', 'Back squat', 'strength', '["quads","hamstrings","glutes","erector_spinae"]', NULL, '["bodyweight","no_floor","high_impact","loads_knee","loads_lower_back","military","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with feet shoulder-width apart; for a loaded version rest the bar across your upper traps","Push your hips back and descend, keeping your chest upright and core braced","Lower until your thighs are at least parallel to the floor","Drive through your full foot — heels and mid-foot — to stand"],"cues":["Knees track outward over your second toe throughout","Brace your core before every rep like you''re about to be punched in the stomach","💡 Bodyweight first: master the pattern before adding load. Heels rising = tight ankles — elevate slightly"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Sta met je voeten op schouderbreedte; leg bij een variant met gewicht de stang op je bovenste trapezius","Duw je heupen naar achteren en zak, met je borst rechtop en je core aangespannen","Zak tot je bovenbenen minstens evenwijdig aan de vloer zijn","Duw door je hele voet — hiel en middenvoet — om omhoog te komen"],"cues_nl":["Je knieën wijzen de hele beweging naar buiten, boven je tweede teen","Span voor elke herhaling je core aan alsof je een stomp in je maag krijgt","💡 Eerst met lichaamsgewicht: beheers de beweging voordat je gewicht toevoegt. Komen je hielen los = stijve enkels — leg er iets onder"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["squat","dumbbell-goblet-squat","front-squat"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_bicycle_crunch', 'bicycle-crunch', 'Bicycle Crunch', 'Bicycle crunch', 'strength', '["obliques","rectus_abdominis","hip_flexors"]', NULL, '["bodyweight","floor","low_impact","core","military","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie on your back, hands loosely behind your head, elbows wide","Lift your shoulders off the floor and bring both knees to a 90° tabletop","Extend your right leg while rotating your right shoulder toward your left knee","Switch sides in a controlled cycling motion"],"cues":["Rotate from the ribs — don''t pull your neck with your hands","Keep both shoulders lifted throughout the movement","💡 Quality over speed — slow reps build more rotational strength"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Core & Stability","steps_nl":["Ga op je rug liggen met je handen losjes achter je hoofd en je ellebogen wijd","Til je schouders van de vloer en breng beide knieën in een hoek van 90° boven je heupen","Strek je rechterbeen terwijl je je rechterschouder naar je linkerknie draait","Wissel gecontroleerd van kant, alsof je fietst"],"cues_nl":["Draai vanuit je ribbenkast — trek niet met je handen aan je nek","Houd beide schouders de hele beweging van de vloer","💡 Kwaliteit boven snelheid — met langzame herhalingen bouw je meer rotatiekracht op"]}', '{"images":["/exercise-media/bicycle-crunch/0.jpg","/exercise-media/bicycle-crunch/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions":["dead-bug","standing-bicycle","v-up","sit-up","reverse-crunch"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_bird_dog', 'bird-dog', 'Bird Dog', 'Bird dog', 'strength', '["core","lower_back","glutes"]', NULL, '["bodyweight","floor","low_impact","quiet","sport_support:running","sport_support:cycling","sport_support:swimming","sport_support:rowing","sport_support:football","sport_support:climbing","loads_shoulder","loads_lower_back"]', '["none"]', NULL, '{"steps":["Start on all fours with your wrists under your shoulders","Extend your right arm and left leg at the same time","Hold for 2 seconds","Lower back to all fours and switch sides"],"cues":["Keep hips square","Move slowly and deliberately"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Begin op handen en knieën met je polsen onder je schouders","Strek tegelijk je rechterarm en je linkerbeen","Houd 2 seconden vast","Kom terug op handen en knieën en wissel van kant"],"cues_nl":["Houd je heupen recht","Beweeg langzaam en bewust"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions": ["mountain-climber", "plank", "single-leg-deadlift"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_body_scan', 'body-scan-meditation', 'Body Scan', 'Bodyscan', 'recovery', '["full_body"]', NULL, '["bodyweight","floor","low_impact","no_sweat","quiet","supine","recovery","pregnancy_safe","postnatal_safe"]', '["none"]', NULL, '{"steps":["Lie down comfortably","Close eyes","Slowly bring attention from feet up through body","Notice sensations without judgment"],"cues":["5-10 minutes ideal","Can be done in bed"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga comfortabel liggen","Sluit je ogen","Breng je aandacht langzaam van je voeten omhoog door je lichaam","Merk op wat je voelt, zonder oordeel"],"cues_nl":["5-10 minuten is ideaal","Kan ook in bed"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["progressive-relaxation-body","supported-side-lying-rest"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_box_breathing', 'box-breathing', 'Box Breathing', 'Box-ademhaling', 'recovery', '["diaphragm"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet"]', '["none"]', NULL, '{"steps":["Sit or lie comfortably","Inhale for 4 counts","Hold for 4 counts","Exhale for 4 counts","Hold empty for 4 counts","Repeat 4-6 cycles"],"cues":["Used by elite athletes for stress control","Eyes closed if comfortable"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Ga comfortabel zitten of liggen","Adem in 4 tellen in","Houd 4 tellen vast","Adem in 4 tellen uit","Houd 4 tellen vast met lege longen","Herhaal 4-6 cycli"],"cues_nl":["Topsporters gebruiken dit om stress te beheersen","Ogen dicht als dat prettig voelt"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["478-breathing","alternate-nostril-breathing"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_box_step', 'box-step-up', 'Step Up', 'Opstap op stoel', 'cardio', '["quadriceps","glutes","calves"]', NULL, '["bodyweight","no_floor","low_impact","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["chair"]', NULL, '{"steps":["Stand in front of a stable chair, step, or bench that places your thigh at or near 90 degrees when your foot is on it. Place your entire right foot flat on the surface — heel included.","Drive through the right heel to step up, bringing your left knee up to hip height as you stand tall on the step. Avoid pushing off with the trail foot.","Stand tall at the top — fully extend the standing hip before lowering. Then lower your left foot slowly and with control back to the floor, followed by the right foot.","Complete all reps on the right side, then switch to the left, or alternate legs each rep."],"cues":["Push through the heel of the elevated foot — the glute of that leg should do the work, not a push-off from the floor foot.","Slow the descent — lowering with control builds more strength than a sloppy step-down.","💡 💡 Add dumbbells at your sides to progress once bodyweight feels easy. Increase the step height to increase the range of motion challenge."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Ga voor een stevige stoel, step of bank staan waarbij je bovenbeen ongeveer 90 graden maakt als je voet erop staat. Zet je hele rechtervoet plat op het oppervlak, ook je hiel.","Duw door je rechterhiel om op te stappen en breng je linkerknie tot heuphoogte terwijl je rechtop op de step komt. Zet niet af met je achterste voet.","Sta bovenaan helemaal rechtop — strek je heup volledig voordat je zakt. Breng dan je linkervoet langzaam en gecontroleerd terug naar de vloer, daarna je rechtervoet.","Doe alle herhalingen rechts en wissel dan naar links, of wissel elke herhaling van been."],"cues_nl":["Duw door de hiel van je voet op de verhoging — de bilspier van dat been doet het werk, niet een afzet van je voet op de vloer.","Zak langzaam — gecontroleerd zakken bouwt meer kracht op dan slordig afstappen.","💡 💡 Pak dumbbells langs je zij zodra het met lichaamsgewicht makkelijk voelt. Maak de step hoger voor een grotere bewegingsuitslag."]}', NULL, '{"supports":["reps","time","sets"]}', '{"substitutions": ["stair-climb-simulation", "power-step-up-jump"]}', 1, 1767830400000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('36f46085-ae5b-5887-bb9a-201a8993a5cd', 'burpee', 'Burpee', 'Burpee', 'cardio', '["full_body","legs","chest","core"]', '["shoulders"]', '["cardio","conditioning","full_body","high_impact","floor","loud","loads_knee","loads_ankle","loads_knee","loads_ankle","loads_shoulder","loads_lower_back"]', '["none"]', '["none"]', '{"steps":["From standing, squat down and place hands on floor.","Jump (or step) feet back to a plank.","Optionally perform a push-up.","Jump (or step) feet forward and stand tall."],"cues":["Land softly.","Keep core braced in plank."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Zak vanuit stand door je knieën en zet je handen op de vloer.","Spring (of stap) met je voeten naar achteren in een plank.","Doe eventueel een push-up.","Spring (of stap) met je voeten naar voren en kom rechtop staan."],"cues_nl":["Land zacht.","Houd je core aangespannen in de plank."]}', NULL, '{"supports":["reps","time","intervals"]}', '{"substitutions":["mountain-climbers","modified-burpee"]}', 1, 1767830400000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_calf_raise', 'calf-raise', 'Calf Raise', 'Kuitheffen', 'strength', '["calves"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","loads_ankle","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with feet hip-width","Rise onto toes","Hold 1 second","Lower slowly"],"cues":["Hold wall for balance if needed","Slow descent for more effect"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Sta met je voeten op heupbreedte","Kom omhoog op je tenen","Houd 1 seconde vast","Zak langzaam"],"cues_nl":["Houd zo nodig een muur vast voor balans","Zak langzaam voor meer effect"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["bent-knee-calf-raise","toe-walk"]}', 1, 1767830400000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('95f1da8d-c126-5be3-8b1f-bb13139b44e9', 'cat-cow', 'Cat-Cow', 'Kat-koe', 'mobility', '["spine"]', '["core"]', '["mobility","recovery","low_impact","quiet","floor","sport_support:cycling","sport_support:rowing","sport_support:climbing","sport_mobility:cycling","sport_mobility:swimming","sport_mobility:rowing","sport_mobility:skiing","sport_mobility:crossfit","loads_lower_back"]', '["none"]', '["exercise_mat"]', '{"steps":["Start on all fours — hands under shoulders, knees under hips. Spine is neutral, no sag or arch.","Inhale: let your belly drop, lift your chest and tailbone gently toward the ceiling (cow position). Eyes look slightly forward.","Exhale: round your entire spine upward, tuck your chin to your chest and your tailbone under (cat position). Feel the stretch across your upper back."],"cues":["💡 Let your breath drive the movement — cow on the inhale, cat on the exhale. This links movement to your nervous system, not just your joints.","Move slowly and intentionally. This is mobility work, not a warm-up speed drill."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Begin op handen en knieën — handen onder je schouders, knieën onder je heupen. Je rug is neutraal, niet hol en niet bol","Adem in: laat je buik zakken en til je borst en stuitje rustig richting het plafond (koe). Kijk iets naar voren","Adem uit: maak je hele rug bol, breng je kin naar je borst en kantel je stuitje naar binnen (kat). Voel de rek over je bovenrug"],"cues_nl":["💡 Laat je ademhaling de beweging sturen — koe op de inademing, kat op de uitademing. Zo koppel je de beweging aan je zenuwstelsel, niet alleen aan je gewrichten","Beweeg langzaam en bewust. Dit is mobiliteitswerk, geen snelle warming-upoefening"]}', '{"images":["/exercise-media/cat-cow/0.jpg","/exercise-media/cat-cow/1.jpg"],"source":"free-exercise-db","audio":{"nl":"/exercise-audio/cat-cow/nl.mp3","en":"/exercise-audio/cat-cow/en.mp3"}}', '{"supports":["time","reps"]}', '{"substitutions": ["thread-the-needle", "childs-pose"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('dadf0850-192a-52e2-8053-4b17da1584be', 'childs-pose', 'Child''s Pose', 'Kindhouding', 'recovery', '["hips","back"]', '["shoulders"]', '["mobility","stretch","recovery","low_impact","quiet","floor","loads_shoulder","loads_lower_back"]', '["none"]', '["exercise_mat"]', '{"steps":["Kneel on a mat and sit your hips back toward your heels. Separate your knees as wide as comfortable or keep them together — both variations work.","Reach your arms forward along the floor and lower your forehead to the mat. Let your chest sink toward the ground.","Breathe slowly and deeply. With each exhale, allow your hips to settle a little further back and your spine to lengthen."],"cues":["Wider knees gives a deeper hip stretch and more space for your torso. Knees together emphasises the lower back stretch.","Breathe into your lower back — you should feel it expand laterally with each inhale. This is passive decompression.","💡 Use this as a reset between hard sets or as the final pose of any session. There is no wrong way to rest here."],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Kniel op een mat en breng je heupen naar achteren richting je hielen. Zet je knieën zo wijd als prettig voelt of houd ze tegen elkaar — beide varianten werken","Strek je armen naar voren over de vloer en leg je voorhoofd op de mat. Laat je borst naar de grond zakken","Adem langzaam en diep. Laat bij elke uitademing je heupen iets verder naar achteren zakken en je rug langer worden"],"cues_nl":["Knieën wijder geeft een diepere heupstretch en meer ruimte voor je romp. Knieën tegen elkaar legt de nadruk op de stretch van je onderrug","Adem naar je onderrug — je voelt hem bij elke inademing zijwaarts uitzetten. Dit is passieve decompressie","💡 Gebruik dit als reset tussen zware sets of als laatste houding van je sessie. Je kunt hier niet verkeerd rusten"]}', '{"images":["/exercise-media/childs-pose/0.jpg","/exercise-media/childs-pose/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions": ["cat-cow", "supine-knee-to-chest", "happy-baby-pose"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_clean_pull', 'clean-pull', 'Clean Pull', 'Clean pull', 'strength', '["hamstrings","glutes","traps","upper_back","lats"]', NULL, '["strength","no_floor","high_impact","olympic","military","loads_shoulder","loads_knee","loads_lower_back","loads_ankle"]', '["none"]', NULL, '{"steps":["Start standing, feet hip-width; hinge at the hips with a flat back to reach your hands to mid-shin height","Drive through your legs and extend your hips explosively — think of jumping straight up","As your hips fully extend, shrug your shoulders aggressively and pull your elbows high and wide","The bar (or your hands) rises to upper-chest height; lower under control and reset"],"cues":["Power comes from the legs and hips — the arms guide, not pull","Keep the bar (or hands) close to your body throughout","💡 This is the first pull of a clean — it builds the explosive hip extension needed for military physical tests"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Begin staand, voeten op heupbreedte. Scharnier vanuit je heupen met een vlakke rug tot je handen op scheenhoogte zijn","Duw door je benen en strek je heupen explosief — alsof je recht omhoog springt","Trek zodra je heupen gestrekt zijn krachtig je schouders op en trek je ellebogen hoog en breed","De stang (of je handen) komt tot hoog op je borst. Laat gecontroleerd zakken en begin opnieuw"],"cues_nl":["De kracht komt uit je benen en heupen — je armen begeleiden, ze trekken niet","Houd de stang (of je handen) de hele tijd dicht bij je lichaam","💡 Dit is de eerste trek van een clean — het bouwt de explosieve heupstrekking op die je nodig hebt voor militaire fysieke testen"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["high-pull","dumbbell-upright-row","kettlebell-swing"]}', 1, 1767830400000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_counter_movement_jump', 'counter-movement-jump', 'Counter Movement Jump', 'Countermovement jump', 'strength', '["quads","hamstrings","glutes","calves"]', NULL, '["bodyweight","no_floor","high_impact","plyometric","assessment","loads_knee","loads_ankle","military"]', '["none"]', NULL, '{"steps":["Stand upright, feet shoulder-width, arms at your sides","Quickly dip into a quarter-squat while swinging your arms back","Immediately reverse — drive your arms up and extend your hips, knees, and ankles fully to jump as high as possible","Land softly, absorbing through ankles, knees, and hips","Reset fully before the next rep"],"cues":["The dip-and-drive is what makes this a counter-movement — use that elastic energy","Reach for the ceiling with your arms — it helps you jump higher","💡 Used in military and elite sports fitness testing. Focus on maximal height per jump, not speed"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Sta rechtop, voeten op schouderbreedte, armen langs je lichaam.","Zak snel in een kwart squat en zwaai je armen naar achteren.","Keer direct om: zwaai je armen omhoog en strek je heupen, knieën en enkels volledig om zo hoog mogelijk te springen.","Land zacht en vang op met je enkels, knieën en heupen.","Kom helemaal tot rust voor de volgende herhaling."],"cues_nl":["Het snelle zakken en afzetten maakt dit een countermovement: gebruik die veerkracht.","Reik met je armen naar het plafond: zo spring je hoger.","💡 Wordt gebruikt bij fitheidstests in het leger en de topsport. Focus op maximale hoogte per sprong, niet op snelheid."]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["jump-squat","tuck-jump","broad-jump"]}', 1, 1767830400000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_dead_bug', 'dead-bug', 'Dead Bug', 'Dead bug', 'strength', '["core","transverse_abdominis"]', NULL, '["bodyweight","floor","low_impact","quiet","supine"]', '["none"]', NULL, '{"steps":["Lie on your back with your arms straight up and your knees bent at 90°","Lower your right arm and left leg towards the floor","Return to the start position","Switch sides"],"cues":["Keep lower back pressed to floor","Move slowly"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Ga op je rug liggen met je armen recht omhoog en je knieën 90° gebogen","Laat je rechterarm en linkerbeen richting de vloer zakken","Kom terug naar de beginpositie","Wissel van kant"],"cues_nl":["Houd je onderrug tegen de vloer gedrukt","Beweeg langzaam"]}', '{"images":["/exercise-media/dead-bug/0.jpg","/exercise-media/dead-bug/1.jpg"],"source":"free-exercise-db","audio":{"nl":"/exercise-audio/dead-bug/nl.mp3","en":"/exercise-audio/dead-bug/en.mp3"}}', '{"supports":["reps","sets"]}', '{"substitutions": ["mountain-climber", "plank", "hanging-leg-raise", "hollow-body-hold", "v-up"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_diamond_pushup', 'diamond-push-up', 'Diamond Push-up', 'Opdrukken diamant', 'strength', '["triceps","chest","shoulders"]', NULL, '["bodyweight","floor","high_impact","loads_shoulder","loads_shoulder"]', '["none"]', NULL, '{"steps":["Start in a push-up position with your hands close together directly beneath your chest — thumbs and index fingers touching to form a diamond or triangle shape.","Brace your core and lower your chest toward your hands, keeping your elbows tucked close to your sides. They should brush your ribs on the way down, not flare out.","Press back up to full arm extension, squeezing your triceps hard at the top.","Maintain a rigid plank throughout — hips level, no sagging at the waist or piking at the hips."],"cues":["Triceps do most of the work here — think of this as a tricep exercise that also loads the chest.","Elbows stay close to your ribs throughout — if they flare wide, you lose the tricep emphasis entirely.","💡 💡 Beginner: elevate hands on a chair to reduce load. Advanced: use a 3-second controlled descent for maximum time under tension."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Begin in push-uphouding met je handen dicht bij elkaar recht onder je borst — duimen en wijsvingers tegen elkaar, zodat ze een diamant of driehoek vormen","Span je core aan en laat je borst naar je handen zakken, met je ellebogen dicht langs je zij. Ze strijken onderweg langs je ribben en wijzen niet naar buiten","Druk jezelf terug omhoog tot je armen gestrekt zijn en span bovenin je triceps hard aan","Blijf de hele tijd een strakke plank — heupen recht, niet doorzakken in je middel en je billen niet omhoog steken"],"cues_nl":["Je triceps doen hier het meeste werk — zie dit als een tricepsoefening die ook je borst belast","Je ellebogen blijven de hele tijd dicht bij je ribben — wijzen ze naar buiten, dan verlies je de nadruk op je triceps","💡 💡 Beginner: zet je handen op een stoel om het lichter te maken. Gevorderd: zak in 3 seconden gecontroleerd voor maximale tijd onder spanning"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["incline-push-up","knee-push-up"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_downward_dog', 'downward-dog', 'Downward Dog', 'Neerwaartse hond', 'mobility', '["hamstrings","calves","shoulders","spine"]', NULL, '["bodyweight","floor","low_impact","no_sweat","quiet","loads_shoulder","loads_lower_back","loads_ankle"]', '["none"]', NULL, '{"steps":["Start on all fours, tuck your toes and push your hips up and back","Form an inverted V shape with your body","Press your heels toward the floor","Alternate bending each knee (pedalling)","Lower your knees back to the floor to finish"],"cues":["Spread fingers wide","Relax head between arms"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Begin op handen en knieën, zet je tenen neer en duw je heupen omhoog en naar achteren","Vorm met je lichaam een omgekeerde V","Duw je hielen richting de vloer","Buig om en om je knieën (fietsen).","Zet je knieën terug op de vloer om af te sluiten"],"cues_nl":["Spreid je vingers wijd.","Laat je hoofd ontspannen tussen je armen hangen."]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["seated-hamstring-stretch","lying-hamstring-stretch"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_db_curl', 'dumbbell-bicep-curl', 'Dumbbell Bicep Curl', 'Dumbbell biceps curl', 'strength', '["biceps","forearms"]', NULL, '["dumbbell","no_floor","low_impact","no_sweat","quiet","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Stand or sit with a dumbbell in each hand at your sides, palms facing forward","Curl the weights to your shoulders","Squeeze your biceps at the top","Lower slowly"],"cues":["Keep elbows fixed at sides","Full range of motion"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta of zit met in elke hand een dumbbell langs je zij, handpalmen naar voren","Curl de gewichten naar je schouders","Span bovenin je biceps aan","Laat langzaam zakken"],"cues_nl":["Houd je ellebogen vast tegen je zij","Maak de volledige beweging"]}', '{"images":["/exercise-media/dumbbell-bicep-curl/0.jpg","/exercise-media/dumbbell-bicep-curl/1.jpg"],"source":"free-exercise-db","audio":{"nl":"/exercise-audio/dumbbell-bicep-curl/nl.mp3","en":"/exercise-audio/dumbbell-bicep-curl/en.mp3"}}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions": ["dumbbell-concentration-curl", "dumbbell-reverse-curl", "band-bicep-curl"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_db_deadlift', 'dumbbell-deadlift', 'Dumbbell Deadlift', 'Dumbbell deadlift', 'strength', '["hamstrings","glutes","lower_back"]', NULL, '["dumbbell","no_floor","loads_lower_back","loads_lower_back","loads_knee"]', '["dumbbell"]', NULL, '{"steps":["Stand holding the dumbbells in front of your thighs","Hinge at your hips, sending them back","Lower the weights along your legs to mid-shin","Drive your hips forward to return to standing"],"cues":["Flat back throughout","Squeeze glutes at top"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta rechtop met de dumbbells voor je bovenbenen","Scharnier vanuit je heupen en duw ze naar achteren","Laat de gewichten langs je benen zakken tot halverwege je schenen","Duw je heupen naar voren om weer rechtop te komen"],"cues_nl":["Houd je rug de hele tijd vlak","Span bovenin je bilspieren aan"]}', '{"images":["/exercise-media/dumbbell-deadlift/0.jpg","/exercise-media/dumbbell-deadlift/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions":["kettlebell-deadlift","good-morning-bodyweight"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('0ba3d7b5-17a9-562c-a74c-e31b90692dbc', 'dumbbell-floor-press', 'Dumbbell Floor Press', 'Dumbbell floor press', 'strength', '["chest","triceps","shoulders"]', '["core"]', '["strength","dumbbell","upper_body","push","floor","quiet","low_impact","supine","loads_shoulder","loads_shoulder"]', '["dumbbell"]', '["exercise_mat","bench"]', '{"steps":["Lie on your back with knees bent, feet flat on the floor. Hold a dumbbell in each hand directly over your chest, arms extended, palms facing your feet.","Bend your elbows and lower the dumbbells in a controlled arc until your upper arms lightly contact the floor. Keep elbows at roughly 45 degrees from your torso — not straight out to your sides.","Without bouncing, press back up from the floor contact point. Exhale on the press. Squeeze your chest at the top.","The floor acts as a built-in range-of-motion limit — it protects your shoulder by preventing overstretching at the bottom."],"cues":["Wrists stay stacked over elbows throughout — wrists bending backward is a form break and injury risk.","Never bounce off the floor — the pause and press from a dead stop is what makes this version effective.","💡 💡 The shorter range of motion compared to bench press means you can often handle more volume safely. Excellent for building the upper chest."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Lig op je rug met je knieën gebogen en voeten plat op de vloer. Houd in elke hand een dumbbell recht boven je borst, armen gestrekt, handpalmen richting je voeten.","Buig je ellebogen en laat de dumbbells gecontroleerd in een boog zakken tot je bovenarmen licht de vloer raken. Houd je ellebogen op zo''n 45 graden van je romp, niet recht opzij.","Druk zonder te veren terug omhoog vanaf de vloer. Adem uit tijdens het drukken. Span bovenin je borst aan.","De vloer begrenst je bewegingsuitslag: dat beschermt je schouder tegen overrekken onderin."],"cues_nl":["Houd je polsen de hele tijd boven je ellebogen: polsen die naar achteren knikken zijn een vormfout en een blessurerisico.","Veer nooit af van de vloer: de pauze en het drukken vanuit stilstand maken deze variant effectief.","💡 💡 Door de kortere bewegingsuitslag dan bij bench press kun je vaak veilig meer volume aan. Uitstekend voor het opbouwen van je bovenste borstspieren."]}', '{"images":["/exercise-media/dumbbell-floor-press/0.jpg","/exercise-media/dumbbell-floor-press/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"dumbbell_pair"}', '{"substitutions": ["push-up", "incline-push-up"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_db_lateral_raise', 'dumbbell-lateral-raise', 'Dumbbell Lateral Raise', 'Dumbbell zijwaarts heffen', 'strength', '["shoulders","traps"]', NULL, '["dumbbell","no_floor","low_impact","no_sweat","quiet","loads_shoulder","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Stand with feet hip-width holding a dumbbell in each hand at your sides. Raise both dumbbells out to the sides until your arms are parallel to the floor, leading with your elbows slightly.","Hold briefly at the top — do not let momentum carry the weight. Your palms should face down at the top.","Lower slowly — 3 seconds down. The eccentric builds the rear and lateral deltoid far more than the lift up."],"cues":["💡 Lighter than you think — lateral raises with heavy weight turn into a trap shrug. Use a weight you can control fully.","Slight forward lean (10–15 degrees) shifts more load onto the lateral deltoid and less onto the trap."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta met je voeten op heupbreedte en houd in elke hand een dumbbell langs je zij. Til beide dumbbells zijwaarts op tot je armen horizontaal zijn, met je ellebogen iets voorop","Houd bovenin even vast — laat het gewicht niet op vaart omhoogkomen. Je handpalmen wijzen bovenin naar beneden","Laat langzaam zakken — 3 seconden omlaag. Het zakken traint de achterste en zijkant van je schouderspier veel meer dan het optillen"],"cues_nl":["💡 Lichter dan je denkt — met zwaar gewicht wordt zijwaarts heffen een schouderophaalbeweging. Kies een gewicht dat je volledig onder controle hebt","Licht voorover leunen (10–15 graden) legt meer belasting op de zijkant van je schouder en minder op je monnikskapspier"]}', '{"images":["/exercise-media/dumbbell-lateral-raise/0.jpg","/exercise-media/dumbbell-lateral-raise/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions":["dumbbell-upright-row","knee-push-up"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('3b258049-88d8-5596-8aa3-41d49a3cbef4', 'dumbbell-row', 'Dumbbell Row', 'Dumbbell row (twee armen)', 'strength', '["lats","upper_back","biceps"]', '["rear_delts","core"]', '["strength","dumbbell","upper_body","pull","no_floor","quiet","low_impact","loads_lower_back","loads_lower_back","loads_shoulder"]', '["dumbbell"]', '["bench"]', '{"steps":["Stand with feet hip-width, hinge forward 45° keeping your back flat. Hold a dumbbell in each hand, arms hanging straight down.","Drive your elbows back toward your hips, pulling the dumbbells to your lower ribcage. Squeeze your shoulder blades together at the top.","Lower with control — resist the weight pulling your shoulders forward."],"cues":["💡 Hinge first, row second — set the flat back before you pull anything.","Think elbows to back pockets, not hands to chest. The elbow leads the movement."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta met je voeten op heupbreedte en scharnier 45° naar voren met een vlakke rug. Houd in elke hand een dumbbell, armen recht naar beneden","Trek je ellebogen naar achteren richting je heupen en breng de dumbbells naar je onderste ribben. Knijp bovenin je schouderbladen samen","Laat gecontroleerd zakken — laat het gewicht je schouders niet naar voren trekken"],"cues_nl":["💡 Eerst scharnieren, dan trekken — zet je rug vlak voordat je iets optrekt","Denk: ellebogen naar je achterzakken, niet handen naar je borst. Je elleboog leidt de beweging"]}', '{"images":["/exercise-media/dumbbell-row/0.jpg","/exercise-media/dumbbell-row/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"dumbbell_pair"}', '{"substitutions": ["band-row-seated", "band-bent-over-row", "doorway-isometric-row"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_db_shoulder_press', 'dumbbell-shoulder-press', 'Dumbbell Shoulder Press', 'Dumbbell schouderpress', 'strength', '["shoulders","triceps"]', NULL, '["dumbbell","no_floor","low_impact","loads_shoulder","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Sit or stand with dumbbells at shoulder height, palms facing forward. Elbows should be at roughly 90 degrees and just below the level of your ears — not dropped too low or flared too high.","Press both dumbbells straight overhead until your arms are fully extended. Exhale on the way up. Do not lock out your elbows hard at the top.","Lower slowly and with control back to the starting position, elbows returning to 90 degrees. Inhale on the way down.","Keep your core firmly braced throughout — avoid arching your lower back as the weight goes overhead."],"cues":["Wrists stay stacked over elbows throughout — wrists bending backward increases injury risk and reduces power transfer.","If you feel pinching at the front of the shoulder, try a neutral grip (palms facing each other) — this externally rotates the shoulder into a safer position.","💡 💡 Seated removes the option to use leg drive, making it a purer shoulder challenge. Standing adds full-body stability demand."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Ga zitten of staan met de dumbbells op schouderhoogte, handpalmen naar voren. Je ellebogen staan in ongeveer 90 graden en net onder oorhoogte — niet te laag en niet te ver omhoog","Druk beide dumbbells recht boven je hoofd tot je armen volledig gestrekt zijn. Adem uit op de weg omhoog. Zet je ellebogen bovenin niet hard op slot","Laat langzaam en gecontroleerd zakken naar de startpositie, ellebogen terug naar 90 graden. Adem in op de weg omlaag","Houd je core de hele tijd stevig aangespannen — maak geen holle onderrug als het gewicht boven je hoofd komt"],"cues_nl":["Houd je polsen de hele tijd recht boven je ellebogen — polsen die naar achteren knikken vergroten de kans op blessures en kosten kracht","Voel je iets knellen aan de voorkant van je schouder, probeer dan een neutrale greep (handpalmen naar elkaar) — je schouder draait dan naar buiten in een veiligere positie","💡 💡 Zittend kun je je benen niet gebruiken, dus je schouders doen al het werk. Staand vraagt het stabiliteit van je hele lichaam"]}', '{"images":["/exercise-media/dumbbell-shoulder-press/0.jpg","/exercise-media/dumbbell-shoulder-press/1.jpg"],"source":"free-exercise-db","audio":{"nl":"/exercise-audio/dumbbell-shoulder-press/nl.mp3","en":"/exercise-audio/dumbbell-shoulder-press/en.mp3"}}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions": ["dumbbell-arnold-press", "band-overhead-press", "kettlebell-single-arm-press"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_db_tricep_kickback', 'dumbbell-tricep-kickback', 'Dumbbell Tricep Kickback', 'Dumbbell triceps kickback', 'strength', '["triceps"]', NULL, '["dumbbell","no_floor","low_impact","no_sweat","quiet","loads_shoulder"]', '["dumbbell"]', NULL, '{"steps":["Hold a dumbbell, hinge forward 45° and bring your upper arm parallel to the floor with your elbow bent","Extend your forearm back until your arm is straight","Squeeze your tricep at the top","Return slowly to the start"],"cues":["Keep upper arm still","Full extension"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Pak een dumbbell, scharnier 45° naar voren en breng je bovenarm horizontaal met je elleboog gebogen","Strek je onderarm naar achteren tot je arm recht is","Span bovenin je triceps aan","Kom langzaam terug naar de start"],"cues_nl":["Houd je bovenarm stil","Strek je arm volledig"]}', '{"images":["/exercise-media/dumbbell-tricep-kickback/0.jpg","/exercise-media/dumbbell-tricep-kickback/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions":["knee-push-up","wall-push-up"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_flutter_kicks', 'flutter-kicks', 'Flutter Kicks', 'Flutter kicks', 'strength', '["hip_flexors","rectus_abdominis","lower_abs"]', NULL, '["bodyweight","floor","low_impact","core","military","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie on your back, hands palms-down under your lower back for support","Lift both legs to roughly 30–45° off the floor — legs straight","Alternately kick one leg up and the other down in small, rapid movements","Maintain continuous motion throughout the set"],"cues":["Lower back stays pressed into your hands — don''t arch","Keep your head and shoulders relaxed on the floor","💡 Raise the legs higher to make it easier; lower to make it harder"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Core & Stability","steps_nl":["Ga op je rug liggen met je handen, palmen omlaag, onder je onderrug als steun","Til beide benen ongeveer 30–45° van de vloer — benen gestrekt","Trap afwisselend één been omhoog en het andere omlaag in kleine, snelle bewegingen","Blijf de hele set doorbewegen"],"cues_nl":["Je onderrug blijft in je handen gedrukt — maak geen holle rug","Laat je hoofd en schouders ontspannen op de vloer liggen","💡 Benen hoger maakt het makkelijker; lager maakt het zwaarder"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["dead-bug","heel-slides","hollow-body-hold"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('45fca5b0-545a-5ce0-a9fc-c245998d81fa', 'forward-lunge', 'Forward Lunge', 'Voorwaartse uitvalspas', 'strength', '["quadriceps","glutes","hamstrings"]', '["calves","core"]', '["strength","bodyweight","lower_body","unilateral","balance","no_floor","quiet","low_impact","loads_knee","loads_knee","loads_ankle"]', '["none"]', '["none"]', '{"steps":["Stand tall, step forward into a long stride.","Lower until front thigh is near parallel and rear knee approaches the floor.","Drive through front heel to return to start.","Repeat other side."],"cues":["Torso upright.","Front knee tracks over mid-foot."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Sta rechtop en zet een grote stap naar voren.","Zak tot je voorste dij bijna horizontaal is en je achterste knie bijna de vloer raakt.","Duw via je voorste hiel terug naar de start.","Herhaal aan de andere kant."],"cues_nl":["Romp rechtop.","Voorste knie boven het midden van je voet."]}', '{"images":["/exercise-media/forward-lunge/0.jpg","/exercise-media/forward-lunge/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","time"]}', '{"substitutions":["reverse-lunge","split-squat","step-up"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_front_squat', 'front-squat', 'Front Squat', 'Front squat', 'strength', '["quads","glutes","core","upper_back"]', NULL, '["bodyweight","no_floor","high_impact","military","loads_shoulder","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with feet shoulder-width; hold your arms crossed in front of your chest (or in clean-rack position if using a bar)","Keeping your elbows high and torso upright, push your hips back and squat","Descend until thighs are parallel — the front-loaded position demands a more upright torso than a back squat","Drive through your heels to stand, maintaining elbow height throughout"],"cues":["Elbows dropping = weight falls forward and form breaks. Practise with a light dumbbell held at your chest","More quad-dominant than back squat — great for military preparation","💡 If your wrists ache in rack position, use the crossed-arm variation"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Sta met je voeten op schouderbreedte en kruis je armen voor je borst (of neem de clean-rackpositie als je een stang gebruikt)","Houd je ellebogen hoog en je romp rechtop, duw je heupen naar achteren en zak in de squat","Zak tot je bovenbenen horizontaal zijn — met het gewicht voor je moet je romp rechter blijven dan bij een back squat","Duw via je hielen omhoog en houd je ellebogen de hele tijd hoog"],"cues_nl":["Zakkende ellebogen = het gewicht valt naar voren en je techniek gaat verloren. Oefen met een lichte dumbbell tegen je borst","Belast je quadriceps meer dan de back squat — sterk voor militaire voorbereiding","💡 Doen je polsen pijn in de rackpositie, kruis dan je armen"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions": ["back-squat", "squat", "dumbbell-goblet-squat", "goblet-squat"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_hip_circles', 'gentle-hip-circles', 'Gentle Hip Circles', 'Heupcirkels rustig', 'recovery', '["hips","lower_back"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","loads_lower_back"]', '["none"]', NULL, '{"steps":["Stand with your feet shoulder-width apart and your hands on your hips","Make 10 large circles with your hips clockwise","Reverse direction for 10 more circles"],"cues":["Move slowly","Great after sitting long periods"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Sta met je voeten op schouderbreedte en je handen op je heupen","Maak 10 grote cirkels met je heupen met de klok mee","Draai 10 cirkels de andere kant op"],"cues_nl":["Beweeg langzaam","Fijn na lang zitten"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["supine-knee-to-chest","happy-baby-pose"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('6009a4e3-4c30-5903-9a81-745ac253d38a', 'glute-bridge', 'Glute Bridge', 'Heupbrug', 'strength', '["glutes","hamstrings","core"]', '["lower_back"]', '["strength","bodyweight","posterior_chain","floor","quiet","low_impact","supine","postnatal_safe","sport_support:running","sport_support:swimming","sport_support:rowing","sport_support:football","sport_support:climbing","loads_lower_back"]', '["none"]', '["exercise_mat"]', '{"steps":["Lie on back with knees bent and feet flat.","Brace core and tuck pelvis slightly.","Drive through heels to lift hips.","Pause, squeeze glutes, then lower with control."],"cues":["Avoid over-arching the low back.","Knees stay in line with toes."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Lig op je rug met je knieën gebogen en voeten plat.","Span je core aan en kantel je bekken licht.","Duw via je hielen je heupen omhoog.","Pauzeer, span je bilspieren aan en zak gecontroleerd terug."],"cues_nl":["Maak geen holle onderrug.","Je knieën blijven in lijn met je tenen."]}', '{"images":["/exercise-media/glute-bridge/0.jpg","/exercise-media/glute-bridge/1.jpg"],"source":"free-exercise-db","audio":{"nl":"/exercise-audio/glute-bridge/nl.mp3","en":"/exercise-audio/glute-bridge/en.mp3"}}', '{"supports":["reps","sets","tempo","time_under_tension"]}', '{"substitutions":["single-leg-glute-bridge","good-morning-bodyweight"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('2b9f9857-49f2-5fbb-b30d-d8eb02bd31b5', 'goblet-squat', 'Goblet Squat', 'Goblet squat', 'strength', '["quadriceps","glutes","hamstrings","core"]', '["upper_back"]', '["strength","dumbbell","lower_body","squat","no_floor","quiet","low_impact","loads_knee","loads_knee"]', '["dumbbell"]', '["exercise_mat"]', '{"steps":["Hold a dumbbell vertically at chest height, both hands cupping the top end, elbows pointing down. Stand with feet shoulder-width apart, toes turned out 15-30 degrees.","Take a breath in. Push your hips back and bend your knees, lowering until your thighs reach parallel to the floor or deeper. Keep the dumbbell close to your chest throughout.","At the bottom, your elbows can press lightly against the inside of your knees — this helps keep them tracking outward over your toes.","Drive through your heels to stand. Squeeze your glutes firmly at the top and exhale. Repeat."],"cues":["The weight in front naturally counterbalances you — use it to sit into a deeper position than a regular squat.","Chest stays tall the entire way down and up. The moment the dumbbell pulls you forward, go lighter.","💡 💡 Beginner: squat only as deep as you can with a flat back. Advanced: pause 2 seconds at the bottom before driving up."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Houd een dumbbell verticaal op borsthoogte, beide handen om het bovenste uiteinde, ellebogen naar beneden. Sta met je voeten op schouderbreedte, tenen 15–30 graden naar buiten","Adem in. Duw je heupen naar achteren en buig je knieën tot je bovenbenen horizontaal zijn of dieper. Houd de dumbbell de hele tijd dicht bij je borst","Onderin mogen je ellebogen licht tegen de binnenkant van je knieën drukken — zo blijven je knieën naar buiten boven je tenen","Duw via je hielen omhoog. Span bovenin je bilspieren stevig aan en adem uit. Herhaal"],"cues_nl":["Het gewicht voor je werkt als tegenwicht — gebruik het om dieper te zakken dan bij een gewone squat","Je borst blijft de hele weg omlaag en omhoog rechtop. Trekt de dumbbell je naar voren, pak dan lichter","💡 💡 Beginner: zak alleen zo diep als je met een vlakke rug kunt. Gevorderd: pauzeer 2 seconden onderin voordat je omhoog duwt"]}', NULL, '{"supports":["weight","reps","sets","tempo"],"load_type":"dumbbell_single"}', '{"substitutions": ["air-squat", "front-squat"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_hand_release_pushup', 'hand-release-push-up', 'Hand Release Push-Up', 'Opdrukken met handen los', 'strength', '["chest","triceps","anterior_deltoid","core","upper_back"]', NULL, '["bodyweight","floor","high_impact","push","military","loads_shoulder"]', '["none"]', NULL, '{"steps":["Lower yourself fully to the floor in a push-up — chest and thighs touching the ground","Lift both hands briefly off the floor, keeping elbows slightly tucked","Replace your hands and press explosively back up to full arm extension","Reset and repeat — each rep starts with a full stop at the floor"],"cues":["The ground contact forces a full range of motion — no half-reps","Squeeze shoulder blades together when you lift your hands","💡 This is the standard Dutch military fitness test push-up — form counts"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Zak bij het opdrukken helemaal naar de vloer: borst en dijen raken de grond.","Til beide handen kort van de vloer en houd je ellebogen licht naar binnen.","Zet je handen terug en druk je explosief omhoog tot gestrekte armen.","Reset en herhaal: elke herhaling begint vanuit stilstand op de vloer."],"cues_nl":["Het grondcontact dwingt een volledige bewegingsuitslag af: geen halve herhalingen.","Knijp je schouderbladen samen als je je handen optilt.","💡 Dit is de standaard opdrukvariant van de Nederlandse militaire fitheidstest: techniek telt."]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions": ["push-up", "incline-push-up", "knee-push-up", "plyometric-push-up"]}', 1, 1767830400000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('dace5250-7566-5a2d-bdf4-ee8763e94f79', 'high-knees', 'High Knees', 'Knieheffen', 'cardio', '["hip_flexors","quadriceps","calves","core"]', '["glutes"]', '["cardio","conditioning","no_floor","high_impact","loud","loads_ankle","loads_ankle","loads_knee"]', '["none"]', '["running_shoes"]', '{"steps":["Run in place lifting knees toward hip height.","Pump arms naturally.","Maintain tall posture and quick cadence."],"cues":["Land softly under hips.","Keep core braced."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Ren op de plaats en til je knieën richting heuphoogte.","Beweeg je armen natuurlijk mee.","Blijf lang staan en houd een hoog tempo."],"cues_nl":["Land zacht, onder je heupen.","Houd je core aangespannen."]}', NULL, '{"supports": ["time", "intervals", "cadence"], "base_duration_sec": 30}', '{"substitutions": ["march-in-place", "jumping-jacks", "heel-dig-march", "mountain-climbers", "jumping-jack"]}', 1, 1767830400000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_high_pull', 'high-pull', 'High Pull', 'High pull', 'strength', '["traps","deltoids","biceps","upper_back","hamstrings"]', NULL, '["strength","no_floor","high_impact","military","loads_shoulder","loads_knee","loads_ankle"]', '["dumbbell"]', NULL, '{"steps":["Stand with your feet hip-width apart, holding the dumbbells with an overhand grip at thigh height","Bend your knees slightly, then drive your hips forward and shrug your shoulders hard","Pull your elbows high and wide as momentum carries the weight up to chin height","Lower under control back to thigh height and repeat"],"cues":["This is a power movement — drive from the lower body, don''t muscle it up with your arms","Elbows stay above wrists throughout the pull","💡 Simpler than a clean pull — great entry point to Olympic-style lifting"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Muscle & Strength","steps_nl":["Sta met je voeten op heupbreedte en houd de dumbbells in een bovenhandse greep op dijhoogte","Buig je knieën licht, duw dan je heupen naar voren en trek je schouders krachtig op","Trek je ellebogen hoog en wijd terwijl de vaart het gewicht tot kinhoogte brengt","Laat gecontroleerd zakken tot dijhoogte en herhaal"],"cues_nl":["Dit is een explosieve beweging — de kracht komt uit je onderlichaam, niet uit je armen","Je ellebogen blijven de hele beweging boven je polsen","💡 Eenvoudiger dan een clean pull — een mooie eerste stap naar olympisch gewichtheffen"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions":["clean-pull","dumbbell-upright-row","dumbbell-shrug"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_hip_flexor_stretch', 'hip-flexor-stretch', 'Hip Flexor Stretch', 'Heupbuigerstretch', 'mobility', '["hip_flexors","quadriceps"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","sport_support:cycling","sport_mobility:running","sport_mobility:cycling","sport_mobility:rowing","sport_mobility:skiing","loads_knee"]', '["none"]', NULL, '{"steps":["Step your right foot forward into a lunge","Lower your left knee toward the floor (or stay standing)","Shift your weight forward until you feel a stretch in your left hip","Hold the stretch, then switch sides"],"cues":["Tall spine","Squeeze back glute for deeper stretch"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Stap met je rechtervoet naar voren in een uitvalspas","Laat je linkerknie richting de vloer zakken (of blijf staan)","Breng je gewicht naar voren tot je een rek in je linkerheup voelt","Houd de rek vast en wissel dan van kant"],"cues_nl":["Houd je rug lang","Span je achterste bilspier aan voor een diepere rek"]}', '{"images":["/exercise-media/hip-flexor-stretch/0.jpg","/exercise-media/hip-flexor-stretch/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["90-90-stretch","couch-stretch","leg-swings-front-back","foam-roll-hip-flexors","standing-quad-stretch"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_incline_pushup', 'incline-push-up', 'Incline Push-up', 'Opdrukken verhoogd', 'strength', '["chest","triceps","shoulders"]', NULL, '["bodyweight","no_floor","low_impact","loads_shoulder","loads_shoulder"]', '["chair"]', NULL, '{"steps":["Place your hands on the edge of a chair or bench","Step your feet back until your body is straight from head to heels","Lower your chest to the surface","Push back up"],"cues":["Easier than floor push-up","Great for beginners"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Zet je handen op de rand van een stoel of bank","Stap met je voeten naar achteren tot je lichaam recht is van hoofd tot hielen","Laat je borst naar het oppervlak zakken","Druk jezelf weer omhoog"],"cues_nl":["Makkelijker dan opdrukken op de vloer","Heel geschikt voor beginners"]}', '{"images":["/exercise-media/incline-push-up/0.jpg","/exercise-media/incline-push-up/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets"]}', '{"substitutions": ["push-up", "dumbbell-floor-press", "hand-release-push-up", "plyometric-push-up"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('76366f52-09c2-585f-9ffe-12cab60a388e', 'jumping-jacks', 'Jumping Jacks', 'Jumping jacks', 'cardio', '["full_body","calves","shoulders"]', '["core"]', '["cardio","conditioning","no_floor","high_impact","loud","loads_knee","loads_ankle","loads_knee","loads_ankle","loads_shoulder","loads_lower_back"]', '["none"]', '["running_shoes"]', '{"steps":["Stand tall with feet together and hands at sides.","Jump feet out as arms sweep overhead.","Jump back to start, repeat rhythmically."],"cues":["Land softly.","Keep breathing steady."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta rechtop met je voeten tegen elkaar en je handen langs je lichaam.","Spring je voeten uit en zwaai je armen boven je hoofd.","Spring terug naar de start en herhaal in een vast ritme."],"cues_nl":["Land zacht.","Blijf rustig doorademen."]}', NULL, '{"supports": ["time", "intervals"], "base_duration_sec": 30}', '{"substitutions":["high-knees","low-impact-jumping-jacks"]}', 1, 1767830400000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_lunge', 'lunge', 'Lunge', 'Uitvalspas', 'strength', '["quads","hamstrings","glutes"]', NULL, '["bodyweight","no_floor","high_impact","unilateral","loads_knee","military","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with feet together, hands on hips or at sides","Step one foot forward roughly 60–70 cm, planting it flat","Lower your back knee toward the floor, front thigh nearly parallel","Push through your front heel to step back to the start position","Alternate legs each rep"],"cues":["Keep your torso upright — don''t lean forward","Front knee stays above your ankle, not over your toes","💡 For balance difficulty: hold onto a wall. To progress: add load or go walking lunge"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Sta met je voeten tegen elkaar, handen op je heupen of langs je lichaam","Stap met één voet zo''n 60–70 cm naar voren en zet hem plat neer","Laat je achterste knie richting de vloer zakken, voorste bovenbeen bijna horizontaal","Duw door je voorste hiel en stap terug naar de startpositie","Wissel elke herhaling van been"],"cues_nl":["Houd je bovenlichaam rechtop — leun niet naar voren","Je voorste knie blijft boven je enkel, niet voorbij je tenen","💡 Moeite met balans: houd een muur vast. Zwaarder maken: voeg gewicht toe of doe de wandelende uitvalspas"]}', '{"images":["/exercise-media/lunge/0.jpg","/exercise-media/lunge/1.jpg"],"source":"free-exercise-db","audio":{"nl":"/exercise-audio/lunge/nl.mp3","en":"/exercise-audio/lunge/en.mp3"}}', '{"supports":["reps","sets"]}', '{"substitutions": ["reverse-lunge", "walking-lunge", "lateral-lunge", "scissor-jump"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_march_in_place', 'march-in-place', 'March in Place', 'Marcheren op de plaats', 'cardio', '["legs","core"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand tall with your feet hip-width apart","Alternate lifting knees to hip height","Swing opposite arm","Keep steady rhythm"],"cues":["Great warm-up or low-impact cardio","No jumping required"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta rechtop met je voeten op heupbreedte","Til afwisselend je knieën op tot heuphoogte","Zwaai je andere arm mee","Houd een constant ritme aan"],"cues_nl":["Prima warming-up of cardio zonder impact","Je hoeft niet te springen"]}', NULL, '{"supports":["time","reps"]}', '{"substitutions":["high-knees","jumping-jack","heel-dig-march","standing-twist-march"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_mountain_climber', 'mountain-climber', 'Mountain Climber', 'Mountain climber', 'mixed', '["core","hip_flexors","anterior_deltoid","quads"]', NULL, '["bodyweight","floor","high_impact","cardio","core","loads_shoulder","military","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Start in a high plank position — hands under shoulders, body straight","Drive your right knee toward your chest, then quickly switch — right leg back, left knee forward","Alternate legs in a running motion, keeping your hips level","Keep a steady rhythm throughout"],"cues":["Hips stay flat — don''t bounce them up with each drive","The faster the pace, the more cardiovascular the demand","💡 Slow = core strength focus. Fast = conditioning. Start slow to nail the form"],"why":"Mixed-mode training challenges multiple energy systems and movement patterns simultaneously, building broad functional fitness.","muscle_target":"Core & Stability","steps_nl":["Begin in een hoge plank — handen onder je schouders, lichaam recht","Trek je rechterknie naar je borst en wissel dan snel — rechterbeen terug, linkerknie naar voren","Wissel je benen af in een loopbeweging en houd je heupen recht","Houd de hele tijd een vast ritme aan"],"cues_nl":["Je heupen blijven vlak — laat ze niet bij elke knie omhoog veren","Hoe hoger het tempo, hoe meer het van je hart en longen vraagt","💡 Langzaam = focus op kracht in je core. Snel = conditie. Begin langzaam om de techniek goed te krijgen"]}', NULL, '{"supports":["reps","sets","time"]}', '{"substitutions": ["plank", "dead-bug", "bird-dog", "bear-crawl"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('1cd70ca6-6293-5da7-92f0-9504c7e55e58', 'mountain-climbers', 'Mountain Climbers', 'Mountain climbers', 'cardio', '["core","shoulders","hip_flexors"]', '["chest"]', '["cardio","conditioning","floor","medium_impact","moderate_noise","loads_shoulder","loads_shoulder","loads_knee","loads_ankle"]', '["none"]', '["exercise_mat"]', '{"steps":["Start in a high plank with hands under shoulders.","Drive one knee toward chest, then switch quickly.","Keep hips level and spine neutral."],"cues":["Shoulders stacked over wrists.","Avoid bouncing hips."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Begin in een hoge plank met je handen onder je schouders.","Breng één knie naar je borst en wissel snel.","Houd je heupen recht en je rug neutraal."],"cues_nl":["Schouders recht boven je polsen.","Laat je heupen niet op en neer stuiteren."]}', NULL, '{"supports":["time","intervals","reps"]}', '{"substitutions": ["high-knees", "burpee"]}', 1, 1767830400000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_neck_stretch', 'neck-stretch', 'Neck Stretch', 'Nekstretch', 'mobility', '["neck","traps"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet"]', '["none"]', NULL, '{"steps":["Sit or stand tall with your shoulders relaxed","Tilt your right ear toward your right shoulder and hold for 20 seconds","Tilt your left ear toward your left shoulder and hold for 20 seconds","Drop your chin to your chest, hold for 20 seconds, then lift your head back to the centre"],"cues":["No rotation — only lateral tilt","Gentle pressure only"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Zit of sta rechtop met ontspannen schouders","Laat je rechteroor naar je rechterschouder zakken en houd 20 seconden vast","Laat je linkeroor naar je linkerschouder zakken en houd 20 seconden vast","Laat je kin naar je borst zakken, houd 20 seconden vast en breng je hoofd terug naar het midden"],"cues_nl":["Niet draaien — alleen opzij kantelen","Alleen zachte druk"]}', '{"images":["/exercise-media/neck-stretch/0.jpg","/exercise-media/neck-stretch/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["neck-half-circles","forearm-wrist-stretch"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pigeon_pose', 'pigeon-pose', 'Pigeon Pose', 'Duif', 'mobility', '["hip_flexors","glutes","piriformis"]', NULL, '["bodyweight","floor","low_impact","no_sweat","quiet","sport_mobility:running","sport_mobility:football","sport_mobility:skiing","sport_mobility:crossfit","loads_knee"]', '["none"]', NULL, '{"steps":["Start on all fours and bring your right knee forward behind your right wrist","Extend your left leg straight behind you","Sink your hips toward the floor","Hold the stretch, then return to all fours and switch sides"],"cues":["Use folded blanket under hip if tight","Breathe deeply"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Begin op handen en knieën en breng je rechterknie naar voren, achter je rechterpols","Strek je linkerbeen recht naar achteren","Laat je heupen richting de vloer zakken","Houd de rek vast, kom terug op handen en knieën en wissel van kant"],"cues_nl":["Leg een opgevouwen deken onder je heup als je stijf bent","Adem diep"]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions": ["90-90-stretch", "ninety-ninety-hip-switch", "supine-figure-four", "supine-knee-to-chest"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('f07deff3-a86b-51e0-93cf-2c20d2338938', 'plank', 'Plank', 'Plank', 'strength', '["core","shoulders","glutes"]', '["upper_back"]', '["core","bodyweight","isometric","floor","quiet","low_impact","loads_shoulder","military","loads_shoulder"]', '["none"]', '["exercise_mat"]', '{"steps":["Place forearms on the floor with elbows under shoulders.","Extend legs back and tuck pelvis slightly.","Hold a straight line head-to-heel.","Breathe slowly while maintaining tension."],"cues":["Ribs down.","Glutes tight.","Avoid sagging hips."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Core & Stability","steps_nl":["Zet je onderarmen op de vloer, ellebogen onder je schouders.","Strek je benen naar achteren en kantel je bekken licht.","Houd een rechte lijn van hoofd tot hielen.","Adem rustig door en houd de spanning vast."],"cues_nl":["Ribben omlaag.","Bilspieren aangespannen.","Laat je heupen niet doorzakken."]}', '{"images":["/exercise-media/plank/0.jpg","/exercise-media/plank/1.jpg"],"source":"free-exercise-db","audio":{"nl":"/exercise-audio/plank/nl.mp3","en":"/exercise-audio/plank/en.mp3"}}', '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions": ["side-plank", "dead-bug", "bird-dog", "mountain-climber"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_plyometric_pushup', 'plyometric-push-up', 'Plyometric Push-Up', 'Opdrukken plyometrisch', 'strength', '["chest","triceps","anterior_deltoid","core"]', NULL, '["bodyweight","floor","high_impact","push","plyometric","loads_shoulder","military"]', '["none"]', NULL, '{"steps":["Start in a standard push-up position — hands shoulder-width, body straight","Lower your chest to the floor with control","Drive up explosively so your hands leave the floor briefly at the top","Land with soft elbows and immediately lower into the next rep"],"cues":["Generate power from your chest — don''t push with wrists only","Land as softly as possible to protect your wrists and elbows","💡 Builds explosive upper body power — foundational for military fitness"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Start in een gewone opdrukpositie — handen op schouderbreedte, lichaam recht","Laat je borst gecontroleerd naar de vloer zakken","Duw explosief omhoog zodat je handen bovenin even van de vloer komen","Land met zachte ellebogen en zak direct in voor de volgende herhaling"],"cues_nl":["Haal de kracht uit je borst — duw niet alleen met je polsen","Land zo zacht mogelijk om je polsen en ellebogen te sparen","💡 Bouwt explosieve kracht in je bovenlichaam op — een basis voor militaire fitheid"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["push-up","hand-release-push-up","incline-push-up"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pmr', 'progressive-muscle-relaxation', 'Progressive Muscle Relaxation', NULL, 'recovery', '["full_body"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet"]', '["none"]', NULL, '{"steps":["Lie down or sit comfortably with eyes closed. Start at your feet: curl your toes tight for 5 seconds, then release completely. Notice the difference.","Work systematically upward — calves, thighs, glutes, abdomen, hands, forearms, shoulders, face. Tense each area for 5 seconds, then let go fully.","After the final release, lie still for 60 seconds. Breathe naturally and observe the heaviness in your body."],"cues":["💡 The contrast between tension and release is the mechanism — your nervous system learns what genuine relaxation feels like, then can reproduce it.","If your mind wanders, guide it back with the question: what is the least tense part of my body right now?"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery"}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', NULL, 0, 1767830400000, 1793483543000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('1c0ead14-ec38-5e21-b359-3ed936a0c7ac', 'push-up', 'Push-up', 'Opdrukken', 'strength', '["chest","triceps","shoulders","core"]', '["serratus_anterior"]', '["strength","bodyweight","upper_body","push","floor","classic","quiet","low_impact","loads_shoulder","military","measurable"]', '["none"]', '["exercise_mat"]', '{"steps":["Start in a high plank with hands under shoulders.","Brace core and keep body in a straight line.","Lower chest toward the floor with control.","Press back up to full lockout without shrugging."],"cues":["Ribs down, glutes tight.","Elbows ~30-45 degrees from torso.","Neck neutral."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Start in een hoge plank met je handen onder je schouders.","Span je core aan en houd je lichaam in een rechte lijn.","Laat je borst gecontroleerd naar de vloer zakken.","Druk terug tot gestrekte armen zonder je schouders op te trekken."],"cues_nl":["Ribben omlaag, bilspieren aangespannen.","Ellebogen op ~30-45 graden van je romp.","Nek neutraal."]}', '{"images":["/exercise-media/push-up/0.jpg","/exercise-media/push-up/1.jpg"],"source":"free-exercise-db","audio":{"nl":"/exercise-audio/push-up/nl.mp3","en":"/exercise-audio/push-up/en.mp3"}}', '{"supports":["reps","sets","tempo","time_under_tension"]}', '{"substitutions": ["incline-push-up", "knee-push-up", "dumbbell-floor-press", "hand-release-push-up", "plyometric-push-up"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_reverse_lunge', 'reverse-lunge', 'Reverse Lunge', 'Achterwaartse uitvalspas', 'strength', '["quadriceps","glutes","hamstrings"]', NULL, '["bodyweight","no_floor","low_impact","loads_knee","loads_knee"]', '["none"]', NULL, '{"steps":["Stand tall with your feet hip-width apart","Step back with your right foot","Lower your back knee toward the floor","Push through your front heel to return to standing"],"cues":["Keep front knee over ankle","Stay upright"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Sta rechtop met je voeten op heupbreedte","Stap met je rechtervoet naar achteren","Laat je achterste knie richting de vloer zakken","Duw door je voorste hiel om terug te komen tot stand"],"cues_nl":["Houd je voorste knie boven je enkel","Blijf rechtop"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions": ["reverse-lunge-kick", "walking-lunge", "forward-lunge", "dumbbell-bulgarian-split-squat", "pistol-squat-assist"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_scissor_jump', 'scissor-jump', 'Scissor Jump', 'Schaarsprong', 'strength', '["quads","hamstrings","glutes","calves"]', NULL, '["bodyweight","floor","high_impact","plyometric","loads_knee","military","loads_ankle"]', '["none"]', NULL, '{"steps":["Start in a lunge position — right foot forward, left foot back, both knees bent","Drive through both feet to jump explosively off the floor","While airborne, switch your feet so your left foot lands forward","Absorb the landing by bending both knees, immediately drop into the lunge and repeat"],"cues":["Soft landing — heel-to-toe, knees tracking over toes","Arms swing opposite to your legs for balance","💡 Impact is high — reduce height if your joints protest. Beginner: do slow alternating lunges"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Start in een uitvalspas — rechtervoet voor, linkervoet achter, beide knieën gebogen","Zet met beide voeten af en spring explosief van de vloer","Wissel in de lucht van voet, zodat je linkervoet voor landt","Vang de landing op door beide knieën te buigen, zak direct in de uitvalspas en herhaal"],"cues_nl":["Land zacht — van hiel naar teen, knieën in lijn met je tenen","Zwaai je armen tegengesteld aan je benen voor balans","💡 De impact is hoog — spring minder hoog als je gewrichten protesteren. Beginner: doe rustige afwisselende uitvalspassen"]}', '{"images":["/exercise-media/scissor-jump/0.jpg","/exercise-media/scissor-jump/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time","sets","reps"]}', '{"substitutions":["lunge","reverse-lunge","jump-squat"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_seated_twist', 'seated-spinal-twist', 'Seated Spinal Twist', 'Rugdraai zittend', 'mobility', '["spine","obliques","hips"]', NULL, '["bodyweight","floor","low_impact","no_sweat","quiet","loads_lower_back"]', '["none"]', NULL, '{"steps":["Sit on the floor cross-legged or with your legs extended","Place your right hand behind you and your left hand on your right knee","Twist to the right as you exhale","Hold, return to the centre and switch sides"],"cues":["Lengthen spine on inhale","Deepen twist on exhale"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Ga op de vloer zitten in kleermakerszit of met je benen gestrekt","Zet je rechterhand achter je en leg je linkerhand op je rechterknie","Draai naar rechts terwijl je uitademt","Houd vast, kom terug naar het midden en wissel van kant"],"cues_nl":["Maak je rug lang op de inademing","Draai verder op de uitademing"]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions": ["active-thoracic-rotation", "seated-straddle-stretch"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_shadow_boxing', 'shadow-boxing', 'Shadow Boxing', 'Schaduwboksen', 'cardio', '["shoulders","core","arms"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","loads_shoulder"]', '["none"]', NULL, '{"steps":["Stand with your feet shoulder-width apart and your knees slightly bent","Throw jab-cross combinations","Add hooks and uppercuts","Move feet between combinations"],"cues":["Stays in one spot","Good stress relief"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta met je voeten op schouderbreedte en je knieën licht gebogen","Sla combinaties van jab en cross","Voeg hoeken en uppercuts toe","Beweeg je voeten tussen de combinaties door"],"cues_nl":["Je blijft op één plek","Goed om stress kwijt te raken"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions": ["speed-bag-simulation", "boxing-combination"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_shoulder_roll', 'shoulder-roll-stretch', 'Shoulder Rolls', 'Schouders rollen', 'mobility', '["shoulders","traps","neck"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","loads_shoulder"]', '["none"]', NULL, '{"steps":["Stand or sit tall. Roll both shoulders forward in large, slow circles — feel the full range at the top and back of each circle. Complete 10 reps forward.","Reverse: roll both shoulders backward in the same large circles. Focus on pulling the shoulder blades together and down at the back of each circle.","Finish with a chest stretch: clasp your hands behind your back, squeeze your shoulder blades together, and lift your hands gently. Hold for 20 seconds."],"cues":["💡 Most people only roll the tops of their shoulders. Exaggerate the backward phase — pulling blades back and down is where desk-worker tension lives.","Slow down. Shoulder rolls done quickly produce zero mobility benefit."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Sta of zit rechtop. Rol beide schouders in grote, langzame cirkels naar voren — voel de volle beweging bovenin en achterin elke cirkel. Doe 10 herhalingen naar voren","Andersom: rol beide schouders in dezelfde grote cirkels naar achteren. Trek achterin elke cirkel je schouderbladen naar elkaar toe en omlaag","Sluit af met een borststretch: vouw je handen achter je rug, knijp je schouderbladen samen en til je handen rustig op. Houd 20 seconden vast"],"cues_nl":["💡 De meeste mensen rollen alleen de bovenkant van hun schouders. Overdrijf het stuk naar achteren — je schouderbladen naar achteren en omlaag trekken, daar zit de spanning van bureauwerk","Doe het rustig aan. Snel gerolde schouders leveren niets op voor je mobiliteit"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["shoulder-circles-active","neck-half-circles","cross-body-shoulder-stretch"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_single_leg_deadlift', 'single-leg-deadlift', 'Single-Leg Deadlift', 'Deadlift op één been', 'strength', '["hamstrings","glutes","core"]', NULL, '["bodyweight","no_floor","balance","unilateral","military","sport_support:running","loads_knee","loads_lower_back","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand on your right foot, slight bend in the knee, left foot just off the floor","Hinge forward at the hip, sending your left leg straight back as a counterbalance — your body forms a T","Reach your hands toward the floor (or hold a dumbbell in your right hand)","Squeeze your right glute to drive back to standing; complete all reps on one side before switching"],"cues":["Move as one unit — your torso and back leg travel together like a seesaw","Keep your hips square to the floor — don''t let the floating hip open out","💡 Wobbling is normal at first. Find a fixed spot to stare at for balance"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Sta op je rechtervoet met je knie licht gebogen, linkervoet net van de vloer.","Scharnier vanuit je heup naar voren en breng je linkerbeen gestrekt naar achteren als tegengewicht: je lichaam vormt een T.","Reik met je handen naar de vloer (of houd een dumbbell in je rechterhand).","Span je rechterbilspier aan om terug omhoog te komen. Doe alle herhalingen aan één kant voor je wisselt."],"cues_nl":["Beweeg als één geheel: je romp en achterste been gaan samen, als een wip.","Houd je heupen recht naar de vloer: laat de zwevende heup niet openklappen.","💡 Wiebelen is in het begin normaal. Kijk naar een vast punt voor je balans."]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["bird-dog","glute-bridge"]}', 1, 1767830400000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_skater_hop', 'skater-hop', 'Skater Hop', 'Schaatssprong', 'cardio', '["glutes","quadriceps","calves"]', NULL, '["bodyweight","no_floor","high_impact","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Jump laterally to the right, landing on right foot","Swing left leg behind","Jump left, landing on left foot","Repeat with rhythm"],"cues":["Keep chest up","Land softly"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Spring zijwaarts naar rechts en land op je rechtervoet","Zwaai je linkerbeen achter je langs","Spring naar links en land op je linkervoet","Herhaal in een vast ritme"],"cues_nl":["Houd je borst omhoog","Land zacht"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["speed-skater","squat-pulse","pogo-hops"]}', 1, 1767830400000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_squat', 'squat', 'Squat', 'Squat', 'strength', '["quads","hamstrings","glutes"]', NULL, '["bodyweight","no_floor","high_impact","military","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with feet shoulder-width apart, toes turned out slightly","Push your hips back and bend your knees, lowering until thighs are parallel to the floor","Keep your chest up and knees tracking over your toes throughout","Drive through your heels to stand back up"],"cues":["Weight stays on mid-foot to heel — don''t let heels rise","Knees stay in line with your second toe","💡 Beginner: squat to a chair height. Advanced: add a pause at the bottom"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Zet je voeten op schouderbreedte, tenen licht naar buiten.","Duw je heupen naar achteren en buig je knieën tot je dijen horizontaal zijn.","Houd je borst de hele tijd omhoog en je knieën in lijn met je tenen.","Duw via je hielen terug omhoog."],"cues_nl":["Je gewicht blijft op middenvoet en hiel: laat je hielen niet loskomen.","Je knieën blijven in lijn met je tweede teen.","💡 Beginner: zak tot stoelhoogte. Advanced: voeg onderin een pauze toe."]}', '{"images":["/exercise-media/squat/0.jpg","/exercise-media/squat/1.jpg"],"source":"free-exercise-db","audio":{"nl":"/exercise-audio/squat/nl.mp3","en":"/exercise-audio/squat/en.mp3"}}', '{"supports":["reps","sets"]}', '{"substitutions": ["jump-squat", "sumo-squat", "supported-wall-squat", "back-squat", "front-squat"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_forward_fold', 'standing-forward-fold', 'Standing Forward Fold', 'Vooroverbuiging staand', 'mobility', '["hamstrings","lower_back","calves"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","loads_lower_back","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with your feet hip-width apart","Hinge forward from your hips","Let your arms hang or hold your elbows","Hold and breathe into the stretch, then roll up slowly to standing"],"cues":["Bend knees if needed","Relax neck completely"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Sta met je voeten op heupbreedte","Buig naar voren vanuit je heupen","Laat je armen hangen of pak je ellebogen vast","Houd vast en adem naar de rek toe, rol daarna langzaam op tot je staat"],"cues_nl":["Buig je knieën als dat nodig is","Ontspan je nek helemaal"]}', '{"images":["/exercise-media/standing-forward-fold/0.jpg","/exercise-media/standing-forward-fold/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["lying-hamstring-stretch","seated-hamstring-stretch"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_quad_stretch', 'standing-quad-stretch', 'Standing Quad Stretch', 'Quadriceps stretch staand', 'mobility', '["quadriceps","hip_flexors"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","loads_knee"]', '["none"]', NULL, '{"steps":["Stand on one leg — rest your free hand on a wall, chair back, or doorframe for balance. Shift your weight solidly onto the supporting foot.","Bend your other knee and bring your heel toward your glute. Reach back with the same-side hand and hold your ankle — not your foot. If your hand cannot reach, use a strap or towel.","Gently pull your heel closer to your glutes while pressing your hip forward slightly on the stretching side. Your stretching knee should point straight down, not drift outward.","Hold 20-30 seconds with steady breathing, then slowly release and switch sides. Never force the range — let the stretch come to you."],"cues":["Knees together is the key cue — the stretch is significantly reduced if the bent knee drifts wide of the standing leg.","Stand tall with both hips level — hiking one hip ruins the quad alignment and reduces the stretch.","Pressing the stretching hip slightly forward adds a hip flexor component — valuable for anyone who sits for long periods."],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Sta op één been en steun met je vrije hand op een muur, rugleuning of deurpost voor balans. Breng je gewicht stevig op je standvoet","Buig je andere knie en breng je hiel naar je bil. Reik met de hand aan dezelfde kant naar achteren en pak je enkel vast — niet je voet. Kom je er niet bij, gebruik dan een band of handdoek","Trek je hiel rustig dichter naar je bil en duw je heup aan de rekkant iets naar voren. Je gebogen knie wijst recht omlaag en zwaait niet naar buiten","Houd 20-30 seconden vast en adem rustig door, laat dan langzaam los en wissel van kant. Forceer nooit — laat de rek vanzelf komen"],"cues_nl":["Knieën bij elkaar is hier de belangrijkste aanwijzing — de rek wordt veel kleiner als je gebogen knie wegdraait van je standbeen","Sta rechtop met beide heupen op gelijke hoogte — trek je één heup op, dan klopt de lijn van je bovenbeen niet meer en neemt de rek af","Je heup aan de rekkant iets naar voren duwen rekt ook je heupbuiger mee — waardevol voor iedereen die lang zit"]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["side-lying-quad-stretch","hip-flexor-stretch"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_step_touch', 'step-touch', 'Step Touch', 'Step touch', 'cardio', '["legs","glutes"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","loads_knee"]', '["none"]', NULL, '{"steps":["Stand tall with your feet together","Step your right foot to the right","Bring your left foot in to meet it","Step your left foot to the left and bring your right foot in to meet it","Swing your arms along to raise the intensity"],"cues":["Quiet movement — works well on days when you are not in workout clothes","Keep a comfortable pace"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Sta rechtop met je voeten bij elkaar","Stap met je rechtervoet naar rechts","Breng je linkervoet erbij","Stap met je linkervoet naar links en breng je rechtervoet erbij","Zwaai je armen mee voor meer intensiteit"],"cues_nl":["Stille beweging — handig op dagen dat je geen sportkleding aan hebt","Houd een comfortabel tempo aan"]}', NULL, '{"supports": ["time"], "base_duration_sec": 60}', '{"substitutions":["wide-step-touch","lateral-knee-raise"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_superman', 'superman-hold', 'Superman Hold', 'Superman houden', 'strength', '["lower_back","glutes","hamstrings"]', NULL, '["bodyweight","floor","low_impact","prone","loads_lower_back","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie face down, arms extended overhead","Lift arms, chest, and legs off floor simultaneously","Hold 2 seconds","Lower slowly"],"cues":["Keep neck neutral","Squeeze glutes at top"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Ga op je buik liggen met je armen gestrekt boven je hoofd","Til je armen, borst en benen tegelijk van de vloer","Houd 2 seconden vast","Zak langzaam terug"],"cues_nl":["Houd je nek neutraal","Span bovenin je bilspieren aan"]}', '{"images":["/exercise-media/superman-hold/0.jpg","/exercise-media/superman-hold/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","time"]}', '{"substitutions":["good-morning-bodyweight","glute-bridge"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_thread_needle', 'thread-the-needle', 'Thread the Needle', 'Draad door de naald', 'mobility', '["thoracic_spine","shoulders","neck"]', NULL, '["bodyweight","floor","low_impact","no_sweat","quiet","sport_support:cycling","sport_mobility:cycling","sport_mobility:swimming","sport_mobility:rowing","loads_shoulder"]', '["none"]', NULL, '{"steps":["Start on all fours","Slide your right arm under your left arm along the floor","Rest your right shoulder and cheek on the floor","Hold, return to all fours and switch sides"],"cues":["Keep hips high","Great for upper back tension"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Begin op handen en knieën","Schuif je rechterarm over de vloer onder je linkerarm door","Leg je rechterschouder en wang op de vloer","Houd vast, kom terug op handen en knieën en wissel van kant"],"cues_nl":["Houd je heupen hoog","Fijn bij spanning in je bovenrug"]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["cat-cow","shoulder-roll-stretch"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_tricep_dip', 'tricep-chair-dip', 'Tricep Chair Dip', 'Triceps dip op stoel', 'strength', '["triceps","shoulders"]', NULL, '["bodyweight","no_floor","low_impact","loads_shoulder"]', '["chair"]', NULL, '{"steps":["Sit on the edge of a chair and grip the edge with your hands","Slide your hips off the chair and support yourself on straight arms","Bend your elbows to 90° to lower your body","Push back up until your arms are straight"],"cues":["Keep back close to chair","Don''t shrug shoulders"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Ga op de rand van een stoel zitten en pak de rand vast met je handen","Schuif je heupen van de stoel en steun op gestrekte armen","Buig je ellebogen tot 90° om je lichaam te laten zakken","Duw jezelf terug omhoog tot je armen gestrekt zijn"],"cues_nl":["Houd je rug dicht bij de stoel","Trek je schouders niet op"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["knee-push-up","wall-push-up"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_wall_pushup', 'wall-push-up', 'Wall Push-up', 'Opdrukken tegen de muur', 'strength', '["chest","triceps","shoulders"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","loads_shoulder","measurable"]', '["none"]', NULL, '{"steps":["Stand at arm''s length from a wall","Place your palms flat on the wall at shoulder width","Lower your chest to the wall with your elbows at 45°","Push back to the start"],"cues":["Keep body straight","Breathe out on push"],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Ga op armlengte van een muur staan","Zet je handpalmen plat tegen de muur, op schouderbreedte","Laat je borst naar de muur zakken met je ellebogen in een hoek van 45°","Duw jezelf terug naar de start"],"cues_nl":["Houd je lichaam recht","Adem uit terwijl je duwt"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions":["knee-push-up","modified-plank"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_wall_sit', 'wall-sit', 'Wall Sit', 'Muurzit', 'strength', '["quadriceps","glutes"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","loads_knee","loads_knee"]', '["none"]', NULL, '{"steps":["Stand with your back flat against a smooth wall, feet roughly 60 cm out from the wall and shoulder-width apart, toes pointing forward.","Slide down the wall until your thighs are parallel to the floor and your knees form a 90-degree angle. Both your lower and upper back should stay in contact with the wall.","Press your heels into the floor and breathe steadily. Keep your arms relaxed at your sides or resting on your thighs — no pushing off with your hands.","When your knees creep above 90° or you lose contact with the wall, the set is done. Step up from the position rather than sliding further."],"cues":["Weight in your heels — you should be able to wiggle your toes without shifting forward.","Quads burning is normal and expected. Stop if you feel sharp pain in your knees, not just burn in your muscles.","💡 💡 Intermediate: hold dumbbells across your thighs to increase load. Advanced: add a slow calf raise hold while maintaining position."],"why":"Progressive strength training builds lean muscle, improves bone density, and raises your resting metabolism — the returns compound over time.","muscle_target":"Full Body Strength","steps_nl":["Ga met je rug plat tegen een gladde muur staan, je voeten ongeveer 60 cm van de muur en op schouderbreedte, tenen recht naar voren","Glijd langs de muur omlaag tot je dijen horizontaal zijn en je knieën een hoek van 90 graden maken. Je onderrug en bovenrug blijven allebei tegen de muur","Druk je hielen in de vloer en adem rustig door. Houd je armen ontspannen langs je lichaam of laat ze op je dijen rusten — niet afzetten met je handen","Komen je knieën boven de 90° of verlies je het contact met de muur, dan is de set klaar. Kom omhoog uit de positie in plaats van verder omlaag te glijden"],"cues_nl":["Gewicht op je hielen — je moet met je tenen kunnen wiebelen zonder naar voren te schuiven","Brandende bovenbenen zijn normaal en horen erbij. Stop als je scherpe pijn in je knieën voelt, niet alleen het branden in je spieren","💡 💡 Intermediate: houd dumbbells op je dijen om de belasting te verhogen. Advanced: voeg een langzame kuitheffing toe die je vasthoudt terwijl je in positie blijft"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["band-squat","sumo-squat","supported-wall-squat"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_warrior_i', 'warrior-i-pose', 'Warrior I', 'Krijger I', 'mobility', '["quadriceps","hip_flexors","shoulders"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","loads_shoulder","loads_knee"]', '["none"]', NULL, '{"steps":["Step right foot forward, left foot back at 45°","Bend front knee to 90°","Raise both arms overhead","Hold, switch sides"],"cues":["Square hips to front","Strong back leg"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Stap je rechtervoet naar voren, linkervoet achter je op 45°.","Buig je voorste knie tot 90°.","Breng beide armen boven je hoofd.","Houd vast en wissel van kant."],"cues_nl":["Heupen recht naar voren.","Achterste been sterk."]}', NULL, '{"supports": ["time"], "base_duration_sec": 40}', '{"substitutions":["hip-flexor-stretch","side-lying-quad-stretch"]}', 1, 1767830400000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_mil_weighted_march', 'weighted-march', 'Weighted March', 'Rugzakmars', 'cardio', '["quads","hamstrings","glutes","calves","core","upper_back"]', NULL, '["cardio","outdoor","military","weighted","low_impact","loads_lower_back","protocol","loads_shoulder","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Load your rucksack or vest to the prescribed weight; adjust straps so the pack sits high and snug","Set your pace: 5.5 km/h (military standard) or 6 km/h (advanced)","March with upright posture — chest up, shoulders back, core braced throughout","Swing your arms naturally; short, quick steps are more efficient than long strides","Monitor your pace with a GPS watch or app; stay within ±0.3 km/h of target speed"],"cues":["The load accumulates — what feels easy at minute 5 feels heavy at minute 20","Heel-to-toe foot strike at march pace — don''t shuffle","💡 Beginner (0 kg): focus on pace and posture. Progress: +5–10 kg every 2 weeks","💡 Intermediate (25 kg): standard Defensie preparation load","💡 Advanced (35–45 kg): matches Cluster 4–6 Opleiding targets"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Laad je rugzak of vest tot het voorgeschreven gewicht; stel de banden zo af dat de rugzak hoog en strak zit","Bepaal je tempo: 5,5 km/u (militaire norm) of 6 km/u (gevorderd)","Marcheer met een rechte houding — borst omhoog, schouders naar achteren, core de hele tijd aangespannen","Laat je armen vanzelf meezwaaien; korte, snelle passen zijn efficiënter dan lange passen","Houd je tempo bij met een gps-horloge of app; blijf binnen ±0,3 km/u van je doelsnelheid"],"cues_nl":["Het gewicht telt op — wat in minuut 5 licht voelt, voelt in minuut 20 zwaar","Rol je voet af van hiel naar teen op marstempo — niet sloffen","💡 Beginner (0 kg): let op tempo en houding. Opbouw: elke 2 weken +5–10 kg","💡 Gemiddeld (25 kg): standaardgewicht voor de voorbereiding op Defensie","💡 Gevorderd (35–45 kg): komt overeen met de doelen van Cluster 4–6 Opleiding"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 60}', '{"substitutions": ["march-in-place", "heel-dig-march"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_wrist_circles', 'wrist-ankle-circles', 'Wrist & Ankle Circles', 'Pols- en enkelcirkels', 'recovery', '["wrists","ankles","forearms"]', NULL, '["bodyweight","no_floor","low_impact","no_sweat","quiet","loads_ankle"]', '["none"]', NULL, '{"steps":["Extend your arms and rotate your wrists in circles, 10 times in each direction","Lift one foot and rotate your ankle 10 times in each direction","Switch feet and repeat"],"cues":["Good office break movement","Increases joint fluid circulation"],"why":"Active recovery accelerates tissue repair, keeps blood moving, and prepares your body to train again sooner.","muscle_target":"Full Body — Recovery","steps_nl":["Strek je armen en draai cirkels met je polsen, 10 keer in elke richting","Til één voet op en draai je enkel 10 keer in elke richting","Wissel van voet en herhaal"],"cues_nl":["Goede beweegpauze op kantoor","Brengt het gewrichtsvocht in beweging"]}', NULL, '{"supports":["reps","time"]}', '{"substitutions":["wrist-flexor-stretch","ankle-pumps"]}', 1, 1767830400000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000001-run0-4000-8000-run000000001', 'run-interval-level-1', 'Run/Walk — Gentle Start', 'Interval hardlopen niveau 1', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","run_interval","running","no_floor","hiit","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Run gently at an easy, controlled effort — think of it as a purposeful shuffle, not a sprint.","When the rest timer starts, walk briskly. Keep moving and breathe steadily.","Repeat for all rounds. If you need to stop early, that is your body giving you the right signal."],"cues":["💡 Effort target: 70–80% max — HR should reach 140–155 bpm during each run","💡 Pace guide: 6:00–8:30 min/km (7–10 km/h). On a treadmill: 7.5 km/h is a good start","💡 Walk recovery is not optional — full recovery between efforts is what makes HIIT work","💡 This is polarised training: the run is hard, the walk is truly easy"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop rustig op een makkelijke, beheerste inspanning — zie het als doelgericht dribbelen, niet als een sprint","Wandel stevig door zodra de rusttimer start. Blijf bewegen en adem rustig door","Herhaal dit alle rondes. Moet je eerder stoppen, dan geeft je lichaam je het juiste signaal"],"cues_nl":["💡 Doelinspanning: 70–80% van je maximum — je hartslag hoort tijdens elk loopblok 140–155 bpm te halen","💡 Richttempo: 6:00–8:30 min/km (7–10 km/u). Op de loopband is 7,5 km/u een goed begin","💡 Wandelherstel is niet vrijblijvend — volledig herstel tussen de inspanningen is wat HIIT laat werken","💡 Dit is gepolariseerd trainen: het lopen is zwaar, het wandelen echt rustig"]}', NULL, '{"supports":["time"],"base_duration_sec":30,"custom_rest_sec":90,"fixed_sets":6,"run_level":1}', '{"substitutions":["easy-jog-warmup","brisk-walk"]}', 1, 1775638556000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000002-run0-4000-8000-run000000002', 'run-interval-level-2', 'Run/Walk — 1 Min Intervals', 'Interval hardlopen niveau 2', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","run_interval","running","no_floor","hiit","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Run at a strong, controlled effort — not a sprint, but clearly working hard.","Walk steadily when the rest timer starts. Do not stop — keep your legs moving.","Complete all rounds. Equal time running and walking."],"cues":["💡 Effort target: 80–85% max — HR should reach 155–165 bpm during each interval","💡 Pace guide: 5:30–7:30 min/km (8–11 km/h). Treadmill: 9–10 km/h effort, 5 km/h walk","💡 Midfoot landing reduces joint stress — avoid landing heel-first","💡 If your breathing stops you from speaking at all, reduce pace by 0.5 km/h"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop op een stevige, beheerste inspanning — geen sprint, maar je werkt duidelijk hard","Wandel rustig door zodra de rusttimer start. Sta niet stil — houd je benen in beweging","Maak alle rondes af. Je loopt en wandelt even lang"],"cues_nl":["💡 Doelinspanning: 80–85% van je maximum — je hartslag hoort tijdens elk interval 155–165 bpm te halen","💡 Richttempo: 5:30–7:30 min/km (8–11 km/u). Loopband: 9–10 km/u bij inspanning, 5 km/u wandelen","💡 Landen op je middenvoet belast je gewrichten minder — land niet eerst op je hiel","💡 Kun je door je ademhaling helemaal niet meer praten, ga dan 0,5 km/u langzamer"]}', NULL, '{"supports":["time"],"base_duration_sec":60,"custom_rest_sec":60,"fixed_sets":6,"run_level":2}', '{"substitutions":["run-interval-level-1","trail-run-easy"]}', 1, 1775638556000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000003-run0-4000-8000-run000000003', 'run-interval-level-3', 'Run/Walk — Build 1', 'Interval hardlopen niveau 3', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","run_interval","running","no_floor","hiit","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Run at a hard, sustained effort — your breathing should be clearly laboured.","Walk when the rest timer begins. Breathe deep and settle your heart rate below 130 bpm.","Complete all rounds. Consistency over speed — every round at the same effort."],"cues":["💡 Effort target: 82–87% max — HR target 158–168 bpm during effort","💡 Pace guide: 5:00–7:00 min/km (8.5–12 km/h). Treadmill: 10 km/h effort, 5.5 km/h walk","💡 Relax your shoulders and hands — tension costs energy","💡 Recovery walk: HR should drop below 130 before the next effort starts"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop op een zware inspanning die je volhoudt — je ademhaling hoort duidelijk zwaar te zijn","Wandel zodra de rusttimer begint. Adem diep en laat je hartslag zakken tot onder 130 bpm","Maak alle rondes af. Regelmaat gaat boven snelheid — elke ronde op dezelfde inspanning"],"cues_nl":["💡 Doelinspanning: 82–87% van je maximum — doelhartslag 158–168 bpm tijdens de inspanning","💡 Richttempo: 5:00–7:00 min/km (8,5–12 km/u). Loopband: 10 km/u bij inspanning, 5,5 km/u wandelen","💡 Ontspan je schouders en handen — spanning kost energie","💡 Wandelherstel: je hartslag hoort onder 130 te zakken voordat de volgende inspanning begint"]}', NULL, '{"supports":["time"],"base_duration_sec":90,"custom_rest_sec":60,"fixed_sets":6,"run_level":3}', '{"substitutions":["run-interval-level-1","run-interval-level-2"]}', 1, 1775638556000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000004-run0-4000-8000-run000000004', 'run-interval-level-4', 'Run/Walk — Build 2', 'Interval hardlopen niveau 4', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","run_interval","running","no_floor","hiit","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Run at a strong, sustainable pace — hard enough that speech requires effort.","Walk when the rest timer starts. Drop your heart rate actively — breathe deep.","Complete all rounds. You are building real aerobic power now."],"cues":["💡 Effort target: 85–88% max — HR target 162–170 bpm during effort","💡 Pace guide: 5:00–6:30 min/km (9–12 km/h). Treadmill: 10–11 km/h effort, 5.5 km/h walk","💡 Short stride, quick turnover beats long slow strides for HIIT efficiency","💡 Hips forward, body upright — not hunched. Posture holds your pace."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop in een stevig tempo dat je volhoudt — zo zwaar dat praten moeite kost","Wandel zodra de rusttimer start. Breng je hartslag actief omlaag — adem diep","Maak alle rondes af. Je bouwt nu echt aeroob vermogen op"],"cues_nl":["💡 Doelinspanning: 85–88% van je maximum — doelhartslag 162–170 bpm tijdens de inspanning","💡 Richttempo: 5:00–6:30 min/km (9–12 km/u). Loopband: 10–11 km/u bij inspanning, 5,5 km/u wandelen","💡 Korte passen met een hoge pasfrequentie werken bij HIIT efficiënter dan lange, trage passen","💡 Heupen naar voren, lichaam rechtop — niet ingezakt. Je houding houdt je tempo vast"]}', NULL, '{"supports":["time"],"base_duration_sec":120,"custom_rest_sec":60,"fixed_sets":5,"run_level":4}', '{"substitutions":["run-interval-level-1","run-interval-level-2"]}', 1, 1775638556000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000005-run0-4000-8000-run000000005', 'run-interval-level-5', 'Run/Walk — Tempo Build', 'Interval hardlopen niveau 5', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","run_interval","running","no_floor","hiit","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Run at a pace that challenges your breathing — speaking takes real effort but one word is possible.","Walk when the rest timer starts. Heart rate should drop noticeably — aim for below 130.","Complete all rounds. You are building serious HIIT fitness."],"cues":["💡 Effort target: 87–90% max — HR target 165–175 bpm during effort","💡 Pace guide: 4:45–6:00 min/km (10–12.5 km/h). Treadmill: 11 km/h effort, 6 km/h walk","💡 Drive your arms forward — arm drive sets the rhythm for your legs","💡 Perceived effort: 8–9 out of 10. If it does not feel hard, push the pace."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop in een tempo dat je ademhaling uitdaagt — praten kost echt moeite, maar één woord lukt nog","Wandel zodra de rusttimer start. Je hartslag hoort merkbaar te zakken — mik op onder 130","Maak alle rondes af. Je bouwt serieuze HIIT-conditie op"],"cues_nl":["💡 Doelinspanning: 87–90% van je maximum — doelhartslag 165–175 bpm tijdens de inspanning","💡 Richttempo: 4:45–6:00 min/km (10–12,5 km/u). Loopband: 11 km/u bij inspanning, 6 km/u wandelen","💡 Zwaai je armen krachtig naar voren — je armen bepalen het ritme van je benen","💡 Ervaren inspanning: 8–9 op 10. Voelt het niet zwaar, voer dan het tempo op"]}', NULL, '{"supports":["time"],"base_duration_sec":180,"custom_rest_sec":60,"fixed_sets":5,"run_level":5}', '{"substitutions":["run-interval-level-1","run-interval-level-2"]}', 1, 1775638556000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000006-run0-4000-8000-run000000006', 'run-interval-level-6', 'Run/Walk — Extended Intervals', 'Interval hardlopen niveau 6', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","run_interval","running","no_floor","hiit","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Run at a strong, controlled pace. You are approaching lactate threshold — this should feel genuinely demanding.","Walk when the rest timer starts — use it actively to prepare for the next effort.","Complete all rounds. At this level the walks are strategic recovery, not a break."],"cues":["💡 Effort target: 88–92% max — HR target 168–178 bpm during effort","💡 Pace guide: 4:30–5:30 min/km (11–13 km/h). Treadmill: 11.5–12.5 km/h effort, 6 km/h walk","💡 5-minute efforts at this intensity build lactate threshold — this is where real fitness is made","💡 Keep form sharp even when tired — fatigue is when injury risk is highest"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop in een stevig, beheerst tempo. Je komt in de buurt van je lactaatdrempel — dit hoort echt zwaar te voelen","Wandel zodra de rusttimer start — gebruik het actief om je voor te bereiden op de volgende inspanning","Maak alle rondes af. Op dit niveau is wandelen strategisch herstel, geen pauze"],"cues_nl":["💡 Doelinspanning: 88–92% van je maximum — doelhartslag 168–178 bpm tijdens de inspanning","💡 Richttempo: 4:30–5:30 min/km (11–13 km/u). Loopband: 11,5–12,5 km/u bij inspanning, 6 km/u wandelen","💡 Inspanningen van 5 minuten op deze intensiteit verhogen je lactaatdrempel — hier bouw je echte conditie op","💡 Houd je techniek scherp, ook als je moe bent — bij vermoeidheid is de kans op blessures het grootst"]}', NULL, '{"supports":["time"],"base_duration_sec":300,"custom_rest_sec":60,"fixed_sets":4,"run_level":6}', '{"substitutions":["run-interval-level-1","run-interval-level-2"]}', 1, 1775638556000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000010-run0-4000-8000-run000000010', 'run-continuous-level-10', 'Continuous Run — 35 min', 'Hardlopen duurloop 35 min', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","running","no_floor","run_continuous","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Start at a conservative pace (HR 120–125) for the first 5 minutes, then let it settle to your Zone 2 band (125–135 bpm).","For 35 minutes of Zone 2, pacing strategy matters: start easy so the second half stays aerobic.","Target pace: 6:30–8:30 min/km (7–9 km/h) on flat terrain. Hills: reduce pace to keep HR below 135.","Last 5 minutes: check your form — relaxed shoulders, quiet foot strike, natural arm swing. This is your aerobic signature at work."],"cues":["💡 HR 130 bpm is your target. Under 125 = too easy, over 135 = too hard","💡 Treadmill reference: 8 km/h at 1% incline. Adjust by ±0.5 km/h to hit your HR zone","💡 At 35+ minutes, fuelling strategy begins to matter: hydrate before long Zone 2 runs","💡 Zone 2 at this duration significantly improves fat oxidation and running economy"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Begin de eerste 5 minuten in een voorzichtig tempo (hartslag 120–125) en laat het daarna uitkomen in je zone 2-bereik (125–135 bpm)","Bij 35 minuten in zone 2 telt je tempo-indeling: begin rustig, zodat de tweede helft aeroob blijft","Richttempo: 6:30–8:30 min/km (7–9 km/u) op vlak terrein. Heuvels: verlaag je tempo om je hartslag onder 135 te houden","Laatste 5 minuten: controleer je techniek — ontspannen schouders, stille voetlanding, natuurlijke armzwaai. Dit is je aerobe basis aan het werk"],"cues_nl":["💡 Een hartslag van 130 bpm is je doel. Onder 125 = te makkelijk, boven 135 = te zwaar","💡 Richtwaarde loopband: 8 km/u met 1% helling. Pas aan met ±0,5 km/u om in je hartslagzone te komen","💡 Vanaf 35 minuten gaat eten en drinken meetellen: drink voldoende voor lange zone 2-lopen","💡 Zone 2 van deze duur verbetert je vetverbranding en loopefficiëntie aanzienlijk"]}', NULL, '{"supports":["time"],"base_duration_sec":2100,"custom_rest_sec":0,"fixed_sets":1}', '{"substitutions":["run-continuous-level-7","run-continuous-level-8"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000011-run0-4000-8000-run000000011', 'run-continuous-level-11', 'Continuous Run — 40 min', 'Hardlopen duurloop 40 min', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","running","no_floor","run_continuous","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Warm up at very easy pace (HR below 120) for 5 minutes, then settle into Zone 2 (HR 125–135).","40 minutes of Zone 2 — pace target 6:30–8:30 min/km (7–9 km/h) on flat. Use HR as your only real guide.","Mid-run check (20 min): still speaking easily? Good. Still feel like you have a lot left? Good. That is Zone 2.","Cool down: last 5 minutes naturally ease off as your pace holds but effort reduces — this is training adaptation beginning."],"cues":["💡 Zone 2 HR: 125–135 bpm throughout. Treadmill: start at 8 km/h at 1% incline","💡 At 40 minutes your body is primarily running on fat as fuel — efficient and sustainable","💡 This session is worth more than a 20-minute harder effort for aerobic development","💡 If HR drifts above 135 in the second half, reduce pace by 10 sec/km — not a failure, a correction"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop je 5 minuten warm in een heel rustig tempo (hartslag onder 120) en kom daarna in zone 2 (hartslag 125–135)","40 minuten in zone 2 — richttempo 6:30–8:30 min/km (7–9 km/u) op vlak terrein. Gebruik je hartslag als enige echte leidraad","Controle halverwege (20 min): praat je nog makkelijk? Mooi. Voelt het alsof je nog veel over hebt? Mooi. Dat is zone 2","Cooling-down: in de laatste 5 minuten wordt het vanzelf lichter, omdat je tempo gelijk blijft maar de inspanning afneemt — hier begint de trainingsaanpassing"],"cues_nl":["💡 Hartslag in zone 2: de hele tijd 125–135 bpm. Loopband: begin op 8 km/u met 1% helling","💡 Na 40 minuten loopt je lichaam vooral op vet als brandstof — efficiënt en lang vol te houden","💡 Deze sessie levert voor je aerobe ontwikkeling meer op dan 20 minuten harder lopen","💡 Loopt je hartslag in de tweede helft op tot boven 135, verlaag dan je tempo met 10 sec/km — geen mislukking, maar een bijsturing"]}', NULL, '{"supports":["time"],"base_duration_sec":2400,"custom_rest_sec":0,"fixed_sets":1}', '{"substitutions":["run-continuous-level-10","run-continuous-level-7"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000012-run0-4000-8000-run000000012', 'run-continuous-level-12', 'Continuous Run — 45 min', 'Hardlopen duurloop 45 min', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","running","no_floor","run_continuous","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["45 minutes of Zone 2. Treat the first 10 minutes as a warm-up within the zone (HR 120–128), then settle at 130.","Pace: 6:30–8:30 min/km (7–9 km/h) on flat. On a treadmill: 7.5–8.5 km/h at 1% incline.","Strategy: split mentally into three 15-minute blocks. Each block: settle, hold, finish. Identical HR across all three.","The last 5 minutes should feel the same as minute 10 — that is your aerobic base working."],"cues":["💡 HR 130 bpm. Talk test still valid at 40+ minutes means you stayed aerobic — well done","💡 Treadmill: 8 km/h at 1% incline is the standard Zone 2 reference for most moderate-fitness runners","💡 45 minutes of Zone 2 per session is the training volume associated with significant VO2max gains","💡 Nutrition: for runs above 40 minutes, have a small carbohydrate snack 2 hours before"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop 45 minuten in zone 2. Gebruik de eerste 10 minuten als warming-up binnen de zone (hartslag 120–128) en blijf daarna rond 130","Tempo: 6:30–8:30 min/km (7–9 km/u) op vlak terrein. Op de loopband: 7,5–8,5 km/u met 1% helling","Strategie: verdeel de loop in gedachten in drie blokken van 15 minuten. Elk blok: inkomen, vasthouden, afmaken. Houd je hartslag in alle drie gelijk","De laatste 5 minuten horen hetzelfde te voelen als minuut 10 — dan doet je aerobe basis zijn werk"],"cues_nl":["💡 Hartslag 130 bpm. Kun je na ruim 40 minuten nog steeds praten, dan ben je aeroob gebleven — goed gedaan","💡 Loopband: 8 km/u met 1% helling is de gangbare zone 2-referentie voor de meeste lopers met een gemiddelde conditie","💡 45 minuten zone 2 per sessie is het trainingsvolume dat samenhangt met een duidelijke stijging van je VO2max","💡 Voeding: eet bij lopen van meer dan 40 minuten 2 uur van tevoren een kleine koolhydraatrijke snack"]}', NULL, '{"supports":["time"],"base_duration_sec":2700,"custom_rest_sec":0,"fixed_sets":1}', '{"substitutions":["run-continuous-level-10","run-continuous-level-11"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000013-run0-4000-8000-run000000013', 'run-continuous-level-13', 'Continuous Run — 50 min', 'Hardlopen duurloop 50 min', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","running","no_floor","run_continuous","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["50-minute Zone 2 run. Hydrate beforehand — at this duration, starting dehydrated affects HR and performance.","Settle at HR 125–135 bpm within the first 8 minutes. Pace: 6:30–8:30 min/km (7–9 km/h) on flat terrain.","Mid-point check (25 min): HR steady? Breathing easy? If HR has crept to 140+, you drifted — reduce pace 15 sec/km.","Finish strong in terms of form, not pace. Shoulders, stride, breathing — all relaxed."],"cues":["💡 50 minutes at HR 130 is a significant aerobic training dose — more effective than 25 minutes at HR 155","💡 Treadmill: 7.5–8.5 km/h at 1% incline. Adjust by ±0.3 km/h to hold your HR band","💡 Cardiac drift is normal: HR may rise 3–5 bpm over the session with pace unchanged","💡 Zone 2 pace will improve 20–30 sec/km over a 12-week training block at this volume"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop 50 minuten in zone 2. Drink vooraf genoeg — bij deze duur beïnvloedt een vochttekort bij de start je hartslag en je prestatie","Kom binnen de eerste 8 minuten uit op een hartslag van 125–135 bpm. Tempo: 6:30–8:30 min/km (7–9 km/u) op vlak terrein","Check halverwege (25 min): is je hartslag stabiel? Adem je rustig? Is je hartslag opgelopen tot 140 of hoger, dan ben je te hard gegaan — loop 15 sec/km langzamer","Eindig sterk in techniek, niet in tempo. Schouders, pas, ademhaling — alles ontspannen"],"cues_nl":["💡 50 minuten op hartslag 130 is een flinke aerobe trainingsprikkel — effectiever dan 25 minuten op hartslag 155","💡 Loopband: 7,5–8,5 km/u met 1% helling. Pas aan met ±0,3 km/u om binnen je hartslagzone te blijven","💡 Cardiale drift is normaal: je hartslag kan in de loop van de sessie 3–5 bpm stijgen bij gelijk tempo","💡 Je zone 2-tempo wordt bij dit volume 20–30 sec/km sneller over een trainingsblok van 12 weken"]}', NULL, '{"supports":["time"],"base_duration_sec":3000,"custom_rest_sec":0,"fixed_sets":1}', '{"substitutions":["run-continuous-level-10","run-continuous-level-11"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000014-run0-4000-8000-run000000014', 'run-continuous-level-14', 'Continuous Run — 55 min', 'Hardlopen duurloop 55 min', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","running","no_floor","run_continuous","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["55-minute Zone 2 run. Choose a route or treadmill setting you can sustain without interruption — continuous running delivers more aerobic stimulus than stop-start.","Target: HR 125–135 bpm throughout. Pace: 6:30–8:30 min/km (7–9 km/h). On treadmill: 8 km/h at 1% incline is the reference starting point.","At 30 minutes, assess: HR stable? Stride smooth? If effort feels the same as minute 10, your aerobic base is working.","Last 10 minutes: maintain form. Quiet feet, relaxed arms, upright posture. This is where the training adaptation is earned."],"cues":["💡 HR 130 is the sweet spot — enough stimulus to build base, low enough to recover fully in 24 hours","💡 A 55-minute Zone 2 run = more aerobic gain than two 25-minute moderate-effort runs","💡 Treadmill: 1% incline corrects for the lack of air resistance — never run flat on a treadmill","💡 You should finish this run feeling like you could do another 15 minutes. That is correct."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop 55 minuten in zone 2. Kies een route of loopbandinstelling die je zonder onderbreking volhoudt — aan één stuk lopen geeft meer aerobe prikkel dan stoppen en starten","Doel: de hele loop een hartslag van 125–135 bpm. Tempo: 6:30–8:30 min/km (7–9 km/u). Op de loopband is 8 km/u met 1% helling je startpunt","Check na 30 minuten: is je hartslag stabiel? Loop je soepel? Voelt de inspanning hetzelfde als in minuut 10, dan doet je aerobe basis zijn werk","Laatste 10 minuten: houd je techniek vast. Stille voeten, ontspannen armen, rechte houding. Hier verdien je het trainingseffect"],"cues_nl":["💡 Hartslag 130 is de gulden middenweg — genoeg prikkel om je basis op te bouwen, laag genoeg om binnen 24 uur volledig te herstellen","💡 Eén duurloop van 55 minuten in zone 2 = meer aerobe winst dan twee lopen van 25 minuten op gemiddelde inspanning","💡 Loopband: 1% helling compenseert het ontbreken van luchtweerstand — loop nooit vlak op een loopband","💡 Na deze loop hoor je het gevoel te hebben dat je nog 15 minuten door kunt. Dat klopt"]}', NULL, '{"supports":["time"],"base_duration_sec":3300,"custom_rest_sec":0,"fixed_sets":1}', '{"substitutions":["run-continuous-level-10","run-continuous-level-11"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000015-run0-4000-8000-run000000015', 'run-continuous-level-15', 'Continuous Run — 60 min', 'Hardlopen duurloop 60 min', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","running","no_floor","run_continuous","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["60-minute Zone 2 run — one full hour. Hydrate properly beforehand. Carry water if temperature is above 15°C.","Settle at HR 125–135 bpm within the first 8 minutes. Pace: 6:30–8:30 min/km (7–9 km/h). Treadmill: 8 km/h at 1% incline as your starting reference.","Divide into four 15-minute blocks. Block 1: settle in. Block 2: find your rhythm. Block 3: manage fatigue. Block 4: finish with intent.","At 45 minutes, your mental game matters as much as your physical fitness. Stay present — one kilometre at a time."],"cues":["💡 60 minutes at HR 130 is one of the most effective single aerobic training sessions available","💡 Cardiac drift: HR may rise 5 bpm in the final 20 minutes with pace unchanged — this is normal","💡 An hour of Zone 2 running significantly elevates VO2max over a training cycle","💡 Eat a small carbohydrate snack (banana, oats) 2 hours before runs of this duration"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop 60 minuten in zone 2 — een vol uur. Drink vooraf goed. Neem water mee als het warmer is dan 15 °C","Kom binnen de eerste 8 minuten uit op een hartslag van 125–135 bpm. Tempo: 6:30–8:30 min/km (7–9 km/u). Loopband: 8 km/u met 1% helling als startpunt","Verdeel de loop in vier blokken van 15 minuten. Blok 1: inkomen. Blok 2: je ritme vinden. Blok 3: omgaan met vermoeidheid. Blok 4: bewust afmaken","Na 45 minuten telt je hoofd net zo zwaar als je conditie. Blijf erbij — één kilometer tegelijk"],"cues_nl":["💡 60 minuten op hartslag 130 is een van de meest effectieve aerobe trainingen die je in één sessie kunt doen","💡 Cardiale drift: je hartslag kan in de laatste 20 minuten 5 bpm stijgen bij gelijk tempo — dat is normaal","💡 Een uur hardlopen in zone 2 verhoogt je VO2max duidelijk over een trainingscyclus","💡 Eet 2 uur voor een loop van deze duur een kleine koolhydraatrijke snack (banaan, havermout)"]}', NULL, '{"supports":["time"],"base_duration_sec":3600,"custom_rest_sec":0,"fixed_sets":1}', '{"substitutions":["run-continuous-level-10","run-continuous-level-11"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000016-run0-4000-8000-run000000016', 'run-continuous-level-16', 'Long Run — 75 min', 'Hardlopen lange duurloop 75 min', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","running","no_floor","run_continuous","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["75-minute Zone 2 run. This is a serious long run — plan your route, carry water, and eat a carbohydrate snack 2 hours before.","HR target: 125–135 bpm. Pace: 6:30–8:30 min/km. On treadmill: 8 km/h at 1% incline, adjusting by ±0.5 to hold your zone.","For runs above 60 minutes, managing HR drift matters: if HR rises above 135 after 45 minutes, reduce pace — do not push through.","Last 15 minutes: check your form actively. Fatigue affects posture first — shoulders drop, stride shortens. Correct it consciously."],"cues":["💡 HR 130 × 75 minutes = maximum polarised training stimulus without significant recovery debt","💡 Fat is your primary fuel at Zone 2. Glycogen stores last 90+ minutes at this intensity — no fuelling needed for most runners","💡 Treadmill at this duration: check the fan, keep a water bottle in reach, accept that it is mentally demanding","💡 After this run, 36 hours of easy activity maximises aerobic adaptation"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop 75 minuten in zone 2. Dit is een serieuze lange duurloop — plan je route, neem water mee en eet 2 uur vooraf een koolhydraatrijke snack","Doelhartslag: 125–135 bpm. Tempo: 6:30–8:30 min/km. Op de loopband: 8 km/u met 1% helling, pas aan met ±0,5 om in je zone te blijven","Bij lopen van meer dan 60 minuten moet je de hartslagdrift in de gaten houden: stijgt je hartslag na 45 minuten boven 135, loop dan langzamer — niet doorduwen","Laatste 15 minuten: controleer actief je techniek. Vermoeidheid zie je het eerst aan je houding — je schouders zakken, je pas wordt korter. Corrigeer dat bewust"],"cues_nl":["💡 Hartslag 130 × 75 minuten = maximale gepolariseerde trainingsprikkel zonder grote herstelschuld","💡 Vet is in zone 2 je belangrijkste brandstof. Je glycogeenvoorraad gaat op deze intensiteit ruim 90 minuten mee — de meeste lopers hoeven onderweg niets te eten","💡 Loopband bij deze duur: check de ventilator, houd een bidon binnen handbereik en accepteer dat het mentaal zwaar is","💡 Na deze loop haal je met 36 uur rustige activiteit het meeste uit de aerobe aanpassing"]}', NULL, '{"supports":["time"],"base_duration_sec":4500,"custom_rest_sec":0,"fixed_sets":1}', '{"substitutions":["run-continuous-level-10","run-continuous-level-11"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000017-run0-4000-8000-run000000017', 'run-continuous-level-17', 'Long Run — 90 min', 'Hardlopen lange duurloop 90 min', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","running","no_floor","run_continuous","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["90-minute Zone 2 run. Fuel and hydrate before you start — at 90 minutes, even Zone 2 depletes glycogen stores in some runners.","Hold HR 125–135 bpm throughout. Pace: 6:30–8:30 min/km. After 60 minutes, pace may need to slow 10–15 sec/km to hold the same HR — this is correct, not failure.","Mental strategy: break into three 30-minute segments. Each has its own challenge: warmup, build, hold. The final 30 minutes is where endurance is built.","Last 10 minutes: active cool down within the run — same pace, conscious relaxation of effort."],"cues":["💡 Cardiac drift at 90 minutes can add 8–10 bpm to HR at the same pace — slow down, not push through","💡 If you have running gels or blocks, one at 60 minutes helps maintain Zone 2 without bonking","💡 90 minutes at Zone 2 is the backbone of distance runner training — this is what marathon pace is built on","💡 Recovery: full rest day tomorrow, or very light mobility only"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop 90 minuten in zone 2. Eet en drink voordat je begint — bij 90 minuten raakt bij sommige lopers zelfs in zone 2 de glycogeenvoorraad leeg","Houd de hele loop een hartslag van 125–135 bpm aan. Tempo: 6:30–8:30 min/km. Na 60 minuten moet je misschien 10–15 sec/km langzamer lopen voor dezelfde hartslag — dat klopt, het is geen falen","Mentale strategie: verdeel de loop in drie delen van 30 minuten. Elk deel heeft zijn eigen uitdaging: opwarmen, opbouwen, vasthouden. In de laatste 30 minuten bouw je uithoudingsvermogen op","Laatste 10 minuten: actieve cooling-down binnen de loop — zelfde tempo, bewust de inspanning loslaten"],"cues_nl":["💡 Cardiale drift kan na 90 minuten 8–10 bpm aan je hartslag toevoegen bij gelijk tempo — ga langzamer lopen, niet doorduwen","💡 Heb je hardloopgels of -blokjes, dan helpt er één na 60 minuten om in zone 2 te blijven zonder de man met de hamer tegen te komen","💡 90 minuten in zone 2 is de ruggengraat van de training van afstandslopers — hier wordt je marathontempo op gebouwd","💡 Herstel: morgen een volledige rustdag, of alleen heel lichte mobiliteit"]}', NULL, '{"supports":["time"],"base_duration_sec":5400,"custom_rest_sec":0,"fixed_sets":1}', '{"substitutions":["run-continuous-level-10","run-continuous-level-11"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000018-run0-4000-8000-run000000018', 'run-continuous-level-18', 'Long Run — 105 min', 'Hardlopen lange duurloop 105 min', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","running","no_floor","run_continuous","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["105-minute Zone 2 run. Mandatory preparation: hydrate the day before, eat a proper carbohydrate meal, carry water or plan a water stop.","HR 125–135 bpm. Pace: 6:30–8:30 min/km. Expect your sustainable pace to drop by 15–20 sec/km versus your shorter runs — this is normal at this duration.","First 20 minutes: resist the urge to run faster than HR 130. The last 40 minutes will thank you.","From 75 minutes onward: run on your aerobic system alone. HR steady, mind focused on form."],"cues":["💡 At 1 hour 45 minutes, this is genuine long-run territory. Your pace does not matter — time on feet at Zone 2 does.","💡 Fuel at 60 minutes and 90 minutes: 25–35g of fast carbohydrate (gel, banana, dates)","💡 After this run, active recovery for 48 hours — no HIIT, no strength. Let the aerobic adaptation consolidate.","💡 This is where your aerobic engine gets built. The discomfort is the signal."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop 105 minuten in zone 2. Verplichte voorbereiding: drink de dag ervoor genoeg, eet een goede koolhydraatrijke maaltijd en neem water mee of plan een waterstop","Hartslag 125–135 bpm. Tempo: 6:30–8:30 min/km. Reken erop dat je houdbare tempo 15–20 sec/km lager ligt dan bij je kortere lopen — dat is normaal bij deze duur","Eerste 20 minuten: weersta de neiging om harder te lopen dan hartslag 130. In de laatste 40 minuten ben je er blij om","Vanaf 75 minuten: loop puur op je aerobe systeem. Hartslag stabiel, aandacht bij je techniek"],"cues_nl":["💡 Met 1 uur en 45 minuten is dit een echte lange duurloop. Je tempo doet er niet toe — de tijd die je in zone 2 op de been bent wel","💡 Eet na 60 en na 90 minuten: 25–35 g snelle koolhydraten (gel, banaan, dadels)","💡 Na deze loop 48 uur actief herstel — geen HIIT, geen krachttraining. Geef de aerobe aanpassing de tijd","💡 Hier bouw je je aerobe motor. Het ongemak is het signaal"]}', NULL, '{"supports":["time"],"base_duration_sec":6300,"custom_rest_sec":0,"fixed_sets":1}', '{"substitutions":["run-continuous-level-10","run-continuous-level-11"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000019-run0-4000-8000-run000000019', 'run-continuous-level-19', 'Long Run — 120 min', 'Hardlopen lange duurloop 120 min', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","running","no_floor","run_continuous","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["120-minute Zone 2 run. Full preparation required: hydrate 24 hours before, eat carbohydrates the morning of, carry or plan for fluids.","HR 125–135 bpm throughout. Pace will naturally be 20–25 sec/km slower than your shorter Zone 2 runs by the final 30 minutes — hold the HR, not the pace.","First 30 minutes: disciplined patience. Your legs want to run faster. Resist — you are building an aerobic engine.","Final 30 minutes: these minutes are the most valuable of the entire session. Stay present, hold form, complete the run."],"cues":["💡 2 hours at Zone 2 is the signature long run of half-marathon preparation","💡 Fuelling strategy: 30–40g carbohydrate at 45, 90 minutes. Hydrate every 20 minutes.","💡 Your fat-burning efficiency improves most dramatically from runs above 90 minutes at Zone 2","💡 Post-run: protein + carbohydrates within 30 minutes, full rest day tomorrow"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop 120 minuten in zone 2. Volledige voorbereiding is nodig: drink vanaf 24 uur vooraf genoeg, eet ''s ochtends koolhydraten en neem drinken mee of plan het in","De hele loop een hartslag van 125–135 bpm. In de laatste 30 minuten ligt je tempo vanzelf 20–25 sec/km lager dan bij je kortere zone 2-lopen — houd je hartslag vast, niet je tempo","Eerste 30 minuten: gedisciplineerd geduld. Je benen willen harder. Geef niet toe — je bouwt een aerobe motor","Laatste 30 minuten: dit zijn de waardevolste minuten van de hele sessie. Blijf erbij, houd je techniek vast en maak de loop af"],"cues_nl":["💡 2 uur in zone 2 is dé lange duurloop in de voorbereiding op een halve marathon","💡 Voedingsstrategie: 30–40 g koolhydraten na 45 en na 90 minuten. Drink elke 20 minuten","💡 Je vetverbranding wordt het sterkst efficiënter door lopen van meer dan 90 minuten in zone 2","💡 Na de loop: eiwitten + koolhydraten binnen 30 minuten, morgen een volledige rustdag"]}', NULL, '{"supports":["time"],"base_duration_sec":7200,"custom_rest_sec":0,"fixed_sets":1}', '{"substitutions":["run-continuous-level-10","run-continuous-level-11"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000020-run0-4000-8000-run000000020', 'run-continuous-level-20', 'Long Run — 150 min', 'Hardlopen lange duurloop 150 min', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","running","no_floor","run_continuous","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["150-minute Zone 2 run. This is a significant athletic undertaking — treat it as a training event, not just a run.","HR 125–133 bpm. Expect pace to drift significantly in the second half — this is correct. Let HR govern entirely.","Nutrition required: eat 30–40g carbohydrate every 45 minutes (gel, banana, bar). Hydrate every 20 minutes.","Last 30 minutes: fatigue is real. Focus entirely on form — quiet feet, upright posture, relaxed hands. The aerobic adaptation is happening right now."],"cues":["💡 2.5 hours at Zone 2 is approaching marathon long-run territory — few non-athletes attempt this. You are building something significant.","💡 Pace at 2+ hours: 7:00–9:00 min/km is normal even for trained runners. Let go of pace ego.","💡 Cardiac drift at this duration can add 10–12 bpm — reduce pace proactively, do not wait for it to force you","💡 Recovery: 48 hours easy activity minimum. Sleep is the most important training adaptation tool."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop 150 minuten in zone 2. Dit is een serieuze sportieve onderneming — behandel het als een trainingsevenement, niet als zomaar een loop","Hartslag 125–133 bpm. Reken erop dat je tempo in de tweede helft flink terugloopt — dat klopt. Laat je volledig leiden door je hartslag","Voeding is nodig: eet elke 45 minuten 30–40 g koolhydraten (gel, banaan, reep). Drink elke 20 minuten","Laatste 30 minuten: de vermoeidheid is echt. Richt je volledig op je techniek — stille voeten, rechte houding, ontspannen handen. De aerobe aanpassing gebeurt nu"],"cues_nl":["💡 2,5 uur in zone 2 komt in de buurt van de lange duurloop voor een marathon — weinig niet-sporters proberen dit. Je bouwt iets groots op","💡 Tempo na ruim 2 uur: 7:00–9:00 min/km is normaal, ook voor getrainde lopers. Laat je tempo-ego los","💡 Cardiale drift kan bij deze duur 10–12 bpm toevoegen — ga op tijd langzamer lopen, wacht niet tot je wel moet","💡 Herstel: minimaal 48 uur rustige activiteit. Slaap is het belangrijkste middel voor trainingsaanpassing"]}', NULL, '{"supports":["time"],"base_duration_sec":9000,"custom_rest_sec":0,"fixed_sets":1}', '{"substitutions":["run-continuous-level-10","run-continuous-level-11"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000021-run0-4000-8000-run000000021', 'run-continuous-level-21', 'Long Run — 180 min', 'Hardlopen lange duurloop 180 min', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","running","no_floor","run_continuous","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["180-minute Zone 2 run — 3 hours. This is elite-range long run volume. Prepare as you would for a race: sleep, nutrition, hydration, gear.","HR 120–130 bpm. Pace expectations: 7:00–9:00 min/km. After 90 minutes, pace will likely be slower — this is correct and expected at this duration.","Nutrition: 30–40g carbohydrate every 40 minutes from the start. Hydrate every 20 minutes. Consider electrolytes (sodium) for runs above 2 hours.","This run is not about pace, speed, or distance. It is about 3 hours of continuous aerobic work at Zone 2. The adaptation from this single session is extraordinary."],"cues":["💡 3-hour Zone 2 runs are the foundation of marathon and ultra training. You are training your body to run on fat.","💡 At 2+ hours: fat oxidation is near-maximum. Your body is learning to spare glycogen — this takes weeks to express.","💡 HR will drift. At 2.5 hours, 128–133 bpm at a walk/jog is still Zone 2 work. Do not push harder.","💡 Recovery: full rest day tomorrow, protein-focused nutrition, 9+ hours sleep if possible."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Loop 180 minuten in zone 2 — 3 uur. Dit is een duurloopvolume op eliteniveau. Bereid je voor als op een wedstrijd: slaap, voeding, drinken, uitrusting","Hartslag 120–130 bpm. Verwacht tempo: 7:00–9:00 min/km. Na 90 minuten loop je waarschijnlijk langzamer — dat klopt en hoort bij deze duur","Voeding: vanaf de start elke 40 minuten 30–40 g koolhydraten. Drink elke 20 minuten. Overweeg elektrolyten (natrium) bij lopen van meer dan 2 uur","Deze loop gaat niet om tempo, snelheid of afstand. Het gaat om 3 uur aaneengesloten aeroob werk in zone 2. De aanpassing die deze ene sessie oplevert is uitzonderlijk"],"cues_nl":["💡 Duurlopen van 3 uur in zone 2 zijn de basis van marathon- en ultratraining. Je leert je lichaam om op vet te lopen","💡 Na ruim 2 uur is je vetverbranding bijna maximaal. Je lichaam leert glycogeen te sparen — het duurt weken voordat je dat merkt","💡 Je hartslag gaat oplopen. Na 2,5 uur is 128–133 bpm bij wandelen en dribbelen nog steeds zone 2-werk. Ga niet harder","💡 Herstel: morgen een volledige rustdag, eiwitrijk eten en als het kan 9 uur slaap of meer"]}', NULL, '{"supports":["time"],"base_duration_sec":10800,"custom_rest_sec":0,"fixed_sets":1}', '{"substitutions":["run-continuous-level-10","run-continuous-level-11"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000007-run0-4000-8000-run000000007', 'run-continuous-level-7', 'Continuous Run — 20 min', 'Hardlopen duurloop 20 min', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","running","no_floor","run_continuous","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Set your pace so your heart rate settles at 130 bpm — this is Zone 2, your aerobic base zone.","Target pace: 6:30–8:30 min/km (7–9 km/h). On a treadmill, start at 7.5 km/h at 1% incline and adjust. Slower is better than faster — HR governs, not pace.","If your HR rises above 135 bpm, reduce pace by 5–10 sec/km and hold there. This is not failure — it is exactly correct Zone 2 training.","Last 5 minutes: notice how stable your breathing feels. This is your aerobic engine working at its optimal intensity."],"cues":["💡 Talk test: say a full sentence out loud. If you cannot, slow down — you have left Zone 2","💡 Zone 2 builds mitochondrial density and fat-burning efficiency. Most runners go too fast on easy days.","💡 HR 130 = roughly 65–70% of max HR. Adjust target by ±5 bpm based on your age and fitness","💡 Polarised rule: this session should feel almost too easy. Save the hard effort for HIIT days."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Kies je tempo zo dat je hartslag uitkomt op 130 bpm — dit is zone 2, de zone voor je aerobe basis","Richttempo: 6:30–8:30 min/km (7–9 km/u). Begin op de loopband met 7,5 km/u en 1% helling en pas aan. Langzamer is beter dan sneller — je hartslag bepaalt, niet je tempo","Stijgt je hartslag boven 135 bpm, loop dan 5–10 sec/km langzamer en blijf daar. Dat is geen falen — het is precies goede zone 2-training","Laatste 5 minuten: merk op hoe stabiel je ademhaling voelt. Dit is je aerobe motor op zijn optimale intensiteit"],"cues_nl":["💡 Praattest: zeg hardop een hele zin. Lukt dat niet, loop dan langzamer — je bent uit zone 2","💡 Zone 2 vergroot je mitochondriale dichtheid en maakt je vetverbranding efficiënter. De meeste lopers gaan te hard op rustige dagen","💡 Hartslag 130 = ongeveer 65–70% van je maximale hartslag. Pas je doel aan met ±5 bpm op basis van je leeftijd en conditie","💡 Gepolariseerde regel: deze sessie hoort bijna te makkelijk te voelen. Bewaar de zware inspanning voor je HIIT-dagen"]}', NULL, '{"supports":["time"],"base_duration_sec":1200,"custom_rest_sec":0,"fixed_sets":1}', '{"substitutions":["easy-jog-warmup","easy-run-outdoor"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000008-run0-4000-8000-run000000008', 'run-continuous-level-8', 'Continuous Run — 25 min', 'Hardlopen duurloop 25 min', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","running","no_floor","run_continuous","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Start at a pace where your heart rate settles at 130 bpm. For most runners this is 7–9 km/h (6:40–8:30 min/km).","Maintain this effort for the full 25 minutes. Ignore your pace — if HR climbs above 135 on a hill, shorten your stride and power-walk the top.","You should be able to hold a conversation throughout. If you cannot say 3–4 words without gasping, you are running too fast.","After the session: your easy pace will improve over weeks as your aerobic base builds."],"cues":["💡 Zone 2 HR target: 125–135 bpm throughout","💡 Treadmill: 7.5–9 km/h at 1% incline. Outdoor: let HR govern, ignore pace","💡 The aerobic engine runs on fat at this intensity — this is where your base is built","💡 Feeling slow is correct. Most runners spend too much time in the inefficient middle zone."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Begin in een tempo waarbij je hartslag uitkomt op 130 bpm. Voor de meeste lopers is dat 7–9 km/u (6:40–8:30 min/km)","Houd deze inspanning de volle 25 minuten vast. Negeer je tempo — loopt je hartslag op een heuvel op tot boven 135, maak dan je pas korter en wandel het laatste stuk stevig door","Je hoort de hele loop een gesprek te kunnen voeren. Kun je geen 3–4 woorden zeggen zonder naar adem te happen, dan loop je te hard","Na de sessie: je rustige tempo wordt in de loop van weken sneller naarmate je aerobe basis groeit"],"cues_nl":["💡 Doelhartslag zone 2: de hele loop 125–135 bpm","💡 Loopband: 7,5–9 km/u met 1% helling. Buiten: laat je hartslag bepalen, negeer je tempo","💡 Op deze intensiteit draait je aerobe motor op vet — hier bouw je je basis","💡 Je langzaam voelen klopt. De meeste lopers zitten te vaak in de inefficiënte middenzone"]}', NULL, '{"supports":["time"],"base_duration_sec":1500,"custom_rest_sec":0,"fixed_sets":1}', '{"substitutions":["run-continuous-level-7","easy-jog-warmup"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('a1000009-run0-4000-8000-run000000009', 'run-continuous-level-9', 'Continuous Run — 30 min', 'Hardlopen duurloop 30 min', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","outdoor","running","no_floor","run_continuous","zone2","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["running_shoes"]', NULL, '{"steps":["Settle into Zone 2 within the first 5 minutes — HR 125–135 bpm, pace that allows easy conversation.","Hold this steady state for the full 30 minutes. Adjust pace by terrain: uphill = slower stride, downhill = let it flow naturally.","Target pace: 6:30–8:30 min/km (7–9 km/h) on flat terrain. On treadmill: 8 km/h at 1% incline is a good reference.","Mental check at 20 minutes: if your breathing has changed significantly since minute 5, you are drifting into Zone 3 — slow down."],"cues":["💡 Zone 2 HR: 125–135 bpm. If a hill pushes you to 140+, walk the top.","💡 30 minutes of Zone 2 is a complete aerobic stimulus — no need to go faster","💡 Your Zone 2 pace will improve significantly over 8–12 weeks of consistent easy running","💡 Easy days easy, hard days hard. This is the foundation of polarised training."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Kom binnen de eerste 5 minuten in zone 2 — hartslag 125–135 bpm, een tempo waarbij je makkelijk kunt praten","Houd dit gelijkmatige tempo de volle 30 minuten vast. Pas je tempo aan het terrein aan: heuvelop = rustigere pas, heuvelaf = laat het vanzelf lopen","Richttempo: 6:30–8:30 min/km (7–9 km/u) op vlak terrein. Op de loopband is 8 km/u met 1% helling een goed richtpunt","Mentale check na 20 minuten: is je ademhaling duidelijk veranderd sinds minuut 5, dan schuif je op naar zone 3 — loop langzamer"],"cues_nl":["💡 Hartslag zone 2: 125–135 bpm. Duwt een heuvel je naar 140 of hoger, wandel dan het laatste stuk","💡 30 minuten zone 2 is een volledige aerobe prikkel — harder hoeft niet","💡 Je zone 2-tempo wordt duidelijk sneller na 8–12 weken regelmatig rustig hardlopen","💡 Rustige dagen rustig, zware dagen zwaar. Dat is de basis van gepolariseerd trainen"]}', NULL, '{"supports":["time"],"base_duration_sec":1800,"custom_rest_sec":0,"fixed_sets":1}', '{"substitutions":["run-continuous-level-7","run-continuous-level-8"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('b2000002-warm-4000-8000-wrup00000002', 'run-warmup-calf-raises', 'Calf Raises', 'Kuitheffen (hardloop-warming-up)', 'mobility', '["calves","soleus"]', NULL, '["cardio","low_impact","no_floor","outdoor","bodyweight","run_warmup","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with feet hip-width apart, toes pointing forward. You can rest fingertips on a wall for balance.","Rise onto your toes as high as you comfortably can and hold for 1 second at the top.","Lower slowly and with control — aim for a 2-second descent. Repeat continuously for the full duration."],"cues":["💡 The slow lowering phase is where the calf strength is built — do not rush it","💡 Rise from the big toe side of your foot for better ankle stability when running"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Sta met je voeten op heupbreedte, tenen naar voren. Je mag je vingertoppen tegen een muur zetten voor balans","Kom zo hoog als prettig voelt op je tenen en houd bovenaan 1 seconde vast","Zak langzaam en gecontroleerd — neem 2 seconden voor de weg omlaag. Blijf herhalen tot de tijd om is"],"cues_nl":["💡 In het langzame zakken bouw je de kracht in je kuiten op — haast je niet","💡 Kom omhoog over de kant van je grote teen voor stabielere enkels bij het hardlopen"]}', NULL, '{"supports":["time"],"base_duration_sec":30,"fixed_sets":1}', '{"substitutions":["calf-stretch-wall","run-warmup-high-knees-march"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('b2000003-warm-4000-8000-wrup00000003', 'run-warmup-high-knees-march', 'High Knees March', 'Mars met knieheffen', 'mobility', '["hip_flexors","quadriceps","calves"]', NULL, '["cardio","low_impact","no_floor","outdoor","bodyweight","run_warmup","loads_knee","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["March in place at a steady rhythm, lifting each knee to hip height with each step.","Pump your arms in opposition — left arm forward with right knee up, right arm with left knee.","Keep your torso tall and your gaze forward. Breathe rhythmically with your movement."],"cues":["💡 This primes your hip flexors and gets your cardiovascular system online before the run","💡 Exaggerate the arm drive — your arms set the pace for your legs"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Marcheer op de plaats in een vast ritme en til bij elke stap je knie tot heuphoogte","Zwaai je armen tegengesteld mee: linkerarm naar voren als je rechterknie omhoogkomt, rechterarm bij je linkerknie","Houd je romp lang en kijk recht vooruit. Adem in het ritme van je beweging"],"cues_nl":["💡 Dit maakt je heupbuigers wakker en brengt je hart en longen op gang voor het hardlopen","💡 Overdrijf je armzwaai — je armen bepalen het tempo van je benen"]}', NULL, '{"supports":["time"],"base_duration_sec":30,"fixed_sets":1}', '{"substitutions":["supported-wall-squat","run-warmup-calf-raises"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('b2000004-warm-4000-8000-wrup00000004', 'run-warmup-hip-circles', 'Hip Circles', 'Heupcirkels (hardloop-warming-up)', 'mobility', '["glutes","hip_flexors","adductors"]', NULL, '["cardio","low_impact","no_floor","outdoor","bodyweight","run_warmup","loads_knee","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with feet shoulder-width apart and place both hands on your hips.","Draw large, slow circles with your hips — 5 clockwise, then 5 counter-clockwise. Make each circle bigger than the last.","Keep your knees soft and your upper body as still as possible — the movement comes only from the hips and pelvis."],"cues":["💡 This opens the hip joint before impact loading — do not rush it","💡 Tightness or restriction in one direction tells you which side needs more mobility work"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Sta met je voeten op schouderbreedte en zet beide handen op je heupen","Draai grote, langzame cirkels met je heupen: 5 met de klok mee, dan 5 tegen de klok in. Maak elke cirkel groter dan de vorige","Houd je knieën los en je bovenlichaam zo stil mogelijk — de beweging komt alleen uit je heupen en bekken"],"cues_nl":["💡 Dit maakt je heupgewricht los voordat de schokbelasting begint — haast je niet","💡 Voelt één richting stijf of beperkt, dan weet je welke kant meer mobiliteitswerk nodig heeft"]}', NULL, '{"supports":["time"],"base_duration_sec":45,"fixed_sets":1}', '{"substitutions":["run-warmup-leg-swings","half-kneeling-hip-opener"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('b2000001-warm-4000-8000-wrup00000001', 'run-warmup-leg-swings', 'Leg Swings', 'Beenzwaaien (hardloop-warming-up)', 'mobility', '["hip_flexors","hamstrings","glutes"]', NULL, '["cardio","low_impact","no_floor","outdoor","bodyweight","run_warmup","loads_knee","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Stand at arm''s length from a wall, resting one hand lightly on it for balance.","Swing your right leg forward and back in a controlled arc — 10 smooth repetitions, gradually increasing the range.","Switch legs and repeat. Keep your core lightly braced and your standing foot flat on the ground."],"cues":["💡 Let momentum do the work — this is a dynamic stretch, not a kick","💡 If your hip flexors feel tight, that is exactly what this is for — keep going"],"why":"Mobility work keeps joints healthy, reduces injury risk, and improves the quality of every strength and cardio movement you do.","muscle_target":"Flexibility & Joints","steps_nl":["Sta op armlengte van een muur en zet er één hand licht tegenaan voor balans","Zwaai je rechterbeen gecontroleerd naar voren en naar achteren — 10 vloeiende herhalingen, met een steeds grotere zwaai","Wissel van been en herhaal. Houd je core licht aangespannen en je standvoet plat op de grond"],"cues_nl":["💡 Laat de vaart het werk doen — dit is een dynamische stretch, geen trap","💡 Voelen je heupbuigers stijf? Daar is deze oefening juist voor — ga door"]}', NULL, '{"supports":["time"],"base_duration_sec":30,"fixed_sets":1}', '{"substitutions":["supported-glute-bridge","run-warmup-hip-circles"]}', 1, 1775659079000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('c3000006-obke-4000-8000-hiit00000006', 'outdoor-bike-hiit', 'Road Bike — HIIT Intervals', 'Fietsen HIIT (racefiets)', 'cardio', '["quadriceps","hamstrings","glutes","calves","hip_flexors"]', NULL, '["cardio","low_impact","outdoor","no_floor","hiit","cycling","loads_knee","loads_ankle"]', '["road_bike"]', NULL, '{"steps":["Choose a route with clear sprint sections — flat straights or consistent climbs of 2–4 minutes. Warm up at easy pace for 10 minutes (HR below 125, 80 RPM).","Effort interval: sprint at 85–95% effort. Speed target on flat: 30–45 km/h. Power meter: 85–100% of FTP. Standing sprints on climbs, seated sprints on flat. HR target: 165–178 bpm.","Recovery: easy spin at 15–22 km/h, 70–80 RPM. Let HR drop below 130 before the next effort. Do not stop pedalling during recovery.","Repeat the effort/recovery pattern throughout the session. Final 10 minutes: easy cool-down spin."],"cues":["💡 Power meter targets: effort 85–100% FTP (e.g. 170–200W for a 200W FTP). Recovery 40–55% FTP.","💡 Cadence in sprints: flat sprints 90–110 RPM. Climbing efforts 75–90 RPM. Match cadence to terrain.","💡 Outdoor HIIT: natural terrain resistance — hills and headwinds give you variable, effective overload","💡 Use full warm-up before first effort. Outdoor conditions (cold, wind) mean muscles need longer preparation."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Kies een route met duidelijke sprintstukken — vlakke rechte stukken of gelijkmatige klimmen van 2–4 minuten. Fiets je 10 minuten warm in een rustig tempo (hartslag onder 125, 80 RPM)","Inspanningsinterval: sprint op 85–95% inspanning. Richtsnelheid op vlak terrein: 30–45 km/u. Vermogensmeter: 85–100% van je FTP. Sprint staand op klimmen en zittend op het vlakke. Richthartslag: 165–178 bpm","Herstel: trap rustig door op 15–22 km/u, 70–80 RPM. Laat je hartslag onder 130 zakken voor de volgende inspanning. Blijf trappen tijdens het herstel","Herhaal het patroon van inspanning en herstel de hele sessie. Laatste 10 minuten: rustig uitfietsen als cooling-down"],"cues_nl":["💡 Richtwaarden vermogensmeter: inspanning 85–100% FTP (bijv. 170–200 W bij een FTP van 200 W). Herstel 40–55% FTP","💡 Cadans in sprints: vlakke sprints 90–110 RPM, klimmen 75–90 RPM. Stem je cadans af op het terrein","💡 HIIT buiten: het terrein geeft natuurlijke weerstand — heuvels en tegenwind zorgen voor wisselende, effectieve belasting","💡 Doe een volledige warming-up voor de eerste inspanning. Buiten (kou, wind) hebben je spieren meer voorbereiding nodig"]}', NULL, '{"supports":["time"],"base_duration_sec":2700}', '{"substitutions":["outdoor-bike-zone2","cycling-outdoor-easy"]}', 1, 1775661357000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('c3000005-obke-4000-8000-zone20000005', 'outdoor-bike-zone2', 'Road Bike — Zone 2 Ride', 'Fietsen zone 2 (racefiets)', 'cardio', '["quadriceps","hamstrings","glutes","calves"]', NULL, '["cardio","low_impact","outdoor","no_floor","zone2","cycling","loads_knee","loads_ankle"]', '["road_bike"]', NULL, '{"steps":["Choose a flat-to-gently-rolling route. Settle into Zone 2 within the first 10 minutes: HR 125–135 bpm, cadence 80–90 RPM.","Speed target on flat terrain: 20–28 km/h. If you have a power meter, hold 50–65% of your FTP (Functional Threshold Power). Both are Zone 2 markers.","Climbs: shift down and maintain cadence (80–90 RPM) rather than grinding. If HR exceeds 138 bpm on climbs, accept slower speed — HR governs.","Descents: recover actively. Let HR drop back toward 120 bpm on long descents, then re-engage at Zone 2 effort on the flat."],"cues":["💡 Talk test at 25 km/h: if you cannot speak in phrases, you are above Zone 2 — ease off the power","💡 Cadence 80–90 RPM is more efficient than grinding at 60–70 RPM at the same wattage","💡 Power meter riders: Zone 2 = 55–75% FTP (e.g. if FTP is 200W, Zone 2 = 110–150W)","💡 Outdoor Zone 2: terrain variability is fine — manage HR to stay in zone across hills and flats"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Kies een vlakke tot licht glooiende route. Kom binnen de eerste 10 minuten in zone 2: hartslag 125–135 bpm, cadans 80–90 RPM","Richtsnelheid op vlak terrein: 20–28 km/u. Heb je een vermogensmeter, houd dan 50–65% van je FTP (Functional Threshold Power) aan. Beide zijn kenmerken van zone 2","Klimmen: schakel terug en houd je cadans vast (80–90 RPM) in plaats van zwaar te stampen. Komt je hartslag op een klim boven 138 bpm, accepteer dan een lagere snelheid — je hartslag bepaalt","Afdalingen: herstel actief. Laat je hartslag op lange afdalingen zakken richting 120 bpm en pak op het vlakke je zone 2-inspanning weer op"],"cues_nl":["💡 Praattest bij 25 km/u: kun je niet meer in korte zinnen praten, dan zit je boven zone 2 — trap wat minder hard","💡 Een cadans van 80–90 RPM is efficiënter dan zwaar trappen op 60–70 RPM bij hetzelfde wattage","💡 Rijd je met een vermogensmeter: zone 2 = 55–75% FTP (bijv. bij een FTP van 200 W is zone 2 110–150 W)","💡 Zone 2 buiten: wisselend terrein is prima — stuur op je hartslag om op heuvels en vlakke stukken in je zone te blijven"]}', NULL, '{"supports":["time"],"base_duration_sec":2700}', '{"substitutions":["cycling-outdoor-easy","cooldown-walk"]}', 1, 1775661357000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('c3000004-bike-4000-8000-hiit00000004', 'static-bike-hiit', 'Static Bike — HIIT Intervals', 'Fietsen HIIT (hometrainer)', 'cardio', '["quadriceps","hamstrings","glutes","calves","hip_flexors"]', NULL, '["cardio","low_impact","indoor","no_floor","hiit","cycling","loads_knee","loads_ankle"]', '["exercise_bike"]', NULL, '{"steps":["Warm up at 70–90W, 80 RPM for 5 minutes — HR should reach 110–120 before intervals.","Effort interval: increase resistance to target wattage. Beginners: 130–170W. Intermediate: 170–230W. Advanced: 230–300W+. Cadence 90–110 RPM. This should feel like 8–9 out of 10 effort — HR 165–178 bpm.","Recovery interval: drop to 60–90W at 70–80 RPM. Let HR fall to 120–130 bpm before the next effort. Do not stop pedalling.","Repeat effort/recovery. Cool down 5 minutes at 60–80W, 75 RPM."],"cues":["💡 Watt progression: beginners 130–170W effort / 60–80W recovery. Intermediate 170–230W / 70–90W. Advanced 230–300W+ / 80–100W.","💡 Cadence during efforts: 90–110 RPM. High cadence trains your cardiovascular system; high resistance trains your legs. Do both.","💡 Static bike HIIT is among the safest high-intensity cardio options — zero impact, consistent resistance.","💡 HR target during effort: 165–178 bpm. If you cannot reach 160 bpm, increase resistance by 2–3 levels."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Doe een warming-up van 5 minuten op 70–90 W en 80 rpm — je hartslag hoort voor de intervallen 110–120 te halen","Inspanningsinterval: verhoog de weerstand tot je doelvermogen. Beginners: 130–170 W. Gemiddeld: 170–230 W. Gevorderd: 230–300 W of meer. Trapfrequentie 90–110 rpm. Dit hoort te voelen als een 8–9 op 10 — hartslag 165–178 bpm","Herstelinterval: zak terug naar 60–90 W op 70–80 rpm. Laat je hartslag zakken tot 120–130 bpm voor de volgende inspanning. Blijf trappen","Herhaal inspanning en herstel. Doe een cooling-down van 5 minuten op 60–80 W en 75 rpm"],"cues_nl":["💡 Opbouw in watt: beginners 130–170 W inspanning / 60–80 W herstel. Gemiddeld 170–230 W / 70–90 W. Gevorderd 230–300 W of meer / 80–100 W","💡 Trapfrequentie tijdens de inspanning: 90–110 rpm. Een hoge trapfrequentie traint je hart en longen, een hoge weerstand traint je benen. Doe allebei","💡 HIIT op de hometrainer is een van de veiligste vormen van intensieve cardio — geen impact, gelijkmatige weerstand","💡 Doelhartslag tijdens de inspanning: 165–178 bpm. Haal je 160 bpm niet, zet de weerstand dan 2–3 standen hoger"]}', '{"images":["/exercise-media/static-bike-hiit/0.jpg","/exercise-media/static-bike-hiit/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":1800}', '{"substitutions":["static-bike-zone2","stationary-bike-steady"]}', 1, 1775661357000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('c3000003-bike-4000-8000-zone20000003', 'static-bike-zone2', 'Static Bike — Zone 2', 'Fietsen zone 2 (hometrainer)', 'cardio', '["quadriceps","hamstrings","glutes","calves"]', NULL, '["cardio","low_impact","indoor","no_floor","zone2","cycling","loads_knee","loads_ankle"]', '["exercise_bike"]', NULL, '{"steps":["Set resistance so you spin smoothly at 80–90 RPM without bouncing in the saddle. Start conservative — adjust resistance up if HR stays below 120 after 5 minutes.","Target wattage: 80–100W for beginners, 100–150W for intermediate, 150–180W for trained cyclists. Let HR be your guide: settle at 125–135 bpm.","Hold this steady state for the full session. RPM should stay in the 80–90 range — smooth, controlled pedal circles, not choppy punches.","Check HR at 10, 20, 30 minutes. It should remain within 5 bpm of your Zone 2 target. Adjust resistance by 1–2 levels if needed."],"cues":["💡 RPM 80–90 is Zone 2 cadence — spinning smoothly at moderate resistance trains aerobic efficiency","💡 Watt targets: beginners 80–100W, intermediate 100–140W, advanced 140–180W. These align with HR 125–135 for most people.","💡 Talk test: you should be able to speak full sentences throughout. The bike should feel like light work.","💡 Zone 2 cycling is low-impact but high-stimulus. 45 minutes delivers aerobic adaptation equivalent to 35 minutes of Zone 2 running."],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Stel de weerstand zo in dat je soepel trapt op 80–90 rpm zonder te stuiteren op het zadel. Begin voorzichtig — verhoog de weerstand als je hartslag na 5 minuten onder 120 blijft","Doelvermogen: 80–100 W voor beginners, 100–150 W voor gemiddelde en 150–180 W voor getrainde fietsers. Laat je hartslag leidend zijn: kom uit op 125–135 bpm","Houd dit gelijkmatige tempo de hele sessie vast. Je trapfrequentie blijft tussen 80 en 90 rpm — soepele, beheerste trapcirkels, geen hakkende halen","Check je hartslag na 10, 20 en 30 minuten. Die hoort binnen 5 bpm van je zone 2-doel te blijven. Pas de weerstand zo nodig 1–2 standen aan"],"cues_nl":["💡 80–90 rpm is de trapfrequentie voor zone 2 — soepel trappen op gemiddelde weerstand traint je aerobe efficiëntie","💡 Doelen in watt: beginners 80–100 W, gemiddeld 100–140 W, gevorderd 140–180 W. Bij de meeste mensen hoort daar een hartslag van 125–135 bij","💡 Praattest: je hoort de hele tijd in hele zinnen te kunnen praten. Het fietsen hoort licht te voelen","💡 Fietsen in zone 2 heeft weinig impact maar geeft veel prikkel. 45 minuten levert een aerobe aanpassing op die gelijkstaat aan 35 minuten hardlopen in zone 2"]}', '{"images":["/exercise-media/static-bike-zone2/0.jpg","/exercise-media/static-bike-zone2/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":1800}', '{"substitutions":["stationary-bike-steady","cooldown-walk"]}', 1, 1775661357000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('c3000002-tdml-4000-8000-hiit00000002', 'treadmill-hiit', 'Treadmill — HIIT Intervals', 'Hardlopen loopband HIIT', 'cardio', '["quadriceps","calves","hamstrings","glutes","hip_flexors"]', NULL, '["cardio","high_impact","indoor","running","no_floor","hiit","treadmill","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["treadmill"]', NULL, '{"steps":["Set incline to 1%. Warm up at 6 km/h for 3 minutes — HR should reach 110–120 bpm before intervals begin.","Effort interval: increase to 11–14 km/h. Target effort: 85–90% max, HR 160–175 bpm. Beginners start at 10–11 km/h — increase over sessions.","Recovery interval: reduce to 5.5–6.5 km/h (brisk walk). Let HR drop below 130 bpm before the next effort. Full recovery is what makes HIIT work.","Repeat effort/recovery pattern. Final 3 minutes: cool down at 5.5 km/h. Never stop abruptly after hard intervals."],"cues":["💡 Speed targets: effort 11–14 km/h (4:17–5:27 min/km equivalent). Recovery 5.5–6 km/h walking pace","💡 HR during effort: 160–175 bpm. If you cannot reach 158 bpm, increase speed by 0.5 km/h","💡 Pre-programme your effort and recovery speeds before starting — transitions must be fast (under 10 seconds)","💡 HIIT treadmill: 2:1 recovery ratio (e.g. 1 min effort / 2 min walk) is standard for beginners"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Zet de helling op 1%. Doe een warming-up van 3 minuten op 6 km/u — je hartslag hoort 110–120 bpm te halen voordat de intervallen beginnen","Inspanningsinterval: verhoog naar 11–14 km/u. Doelinspanning: 85–90% van je maximum, hartslag 160–175 bpm. Beginners starten op 10–11 km/u en bouwen dat per sessie op","Herstelinterval: ga terug naar 5,5–6,5 km/u (stevig wandelen). Laat je hartslag onder 130 bpm zakken voor de volgende inspanning. Volledig herstel is wat HIIT laat werken","Herhaal het patroon van inspanning en herstel. Laatste 3 minuten: cooling-down op 5,5 km/u. Stop nooit abrupt na zware intervallen"],"cues_nl":["💡 Doelsnelheden: inspanning 11–14 km/u (gelijk aan 4:17–5:27 min/km). Herstel 5,5–6 km/u wandeltempo","💡 Hartslag tijdens de inspanning: 160–175 bpm. Haal je 158 bpm niet, ga dan 0,5 km/u sneller","💡 Programmeer je inspannings- en herstelsnelheid voordat je begint — wisselen moet snel gaan (binnen 10 seconden)","💡 HIIT op de loopband: een herstelverhouding van 2:1 (bijv. 1 min inspanning / 2 min wandelen) is gangbaar voor beginners"]}', '{"images":["/exercise-media/treadmill-hiit/0.jpg","/exercise-media/treadmill-hiit/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":1800}', '{"substitutions":["easy-jog-warmup","treadmill-zone2"]}', 1, 1775661357000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('c3000001-tdml-4000-8000-zone20000001', 'treadmill-zone2', 'Treadmill — Zone 2 Run', 'Hardlopen loopband zone 2', 'cardio', '["quadriceps","calves","hamstrings","glutes"]', NULL, '["cardio","high_impact","indoor","running","no_floor","zone2","treadmill","loads_knee","loads_ankle","loads_knee","loads_ankle"]', '["treadmill"]', NULL, '{"steps":["Set treadmill to 1% incline — this compensates for the absence of air resistance and more closely matches outdoor running effort.","Start at 7.5 km/h and let your HR settle over 3–5 minutes. Target zone: 125–135 bpm. Adjust speed in 0.3 km/h increments until you find your personal Zone 2 speed.","Hold your Zone 2 speed for the full session. Speed guide: beginners 7–8 km/h, intermediate 8–9.5 km/h, trained 9.5–11 km/h. HR governs — not pace.","If HR rises above 135 at any point (especially on long sessions), reduce speed by 0.3 km/h and hold. Cardiac drift over 30+ minutes is normal."],"cues":["💡 Talk test: say 5 words comfortably without gasping. If you cannot, you are above Zone 2 — reduce speed.","💡 Treadmill Zone 2 reference: 8 km/h at 1% incline suits most recreational runners (HR ~125–135)","💡 Never run flat on a treadmill for Zone 2 — 1% incline is not optional for accurate training","💡 Zone 2 pace will improve 15–25 sec/km over 8 weeks of consistent training without increasing perceived effort"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Zet de loopband op 1% helling — dat compenseert het ontbreken van luchtweerstand en komt dichter bij de inspanning van buiten lopen","Begin op 7,5 km/u en laat je hartslag in 3–5 minuten stabiliseren. Doelzone: 125–135 bpm. Pas de snelheid aan in stappen van 0,3 km/u tot je je eigen zone 2-snelheid hebt gevonden","Houd je zone 2-snelheid de hele sessie vast. Richtsnelheden: beginners 7–8 km/u, gemiddeld 8–9,5 km/u, getraind 9,5–11 km/u. Je hartslag bepaalt — niet je tempo","Komt je hartslag op enig moment boven 135 (vooral bij lange sessies), ga dan 0,3 km/u langzamer en blijf daar. Cardiale drift na ruim 30 minuten is normaal"],"cues_nl":["💡 Praattest: zeg 5 woorden op je gemak, zonder naar adem te happen. Lukt dat niet, dan zit je boven zone 2 — ga langzamer","💡 Zone 2-referentie op de loopband: 8 km/u met 1% helling past bij de meeste recreatieve lopers (hartslag ~125–135)","💡 Loop voor zone 2 nooit vlak op een loopband — 1% helling is nodig om nauwkeurig te trainen","💡 Je zone 2-tempo wordt 15–25 sec/km sneller na 8 weken regelmatig trainen, zonder dat het zwaarder voelt"]}', '{"images":["/exercise-media/treadmill-zone2/0.jpg","/exercise-media/treadmill-zone2/1.jpg"],"source":"free-exercise-db"}', '{"supports":["time"],"base_duration_sec":1800}', '{"substitutions":["easy-jog-warmup","treadmill-hiit"]}', 1, 1775661357000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('df61815885120e083aa9f95ff54c6195', 'cooldown-walk', 'Cool-down Walk', 'Uitwandelen (cooling-down)', 'cardio', '["quads","hamstrings","glutes","calves","core"]', NULL, '["cardio","low_impact","outdoor","no_floor","recovery","session_phase","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Walk at a comfortable, relaxed pace — do not stop abruptly after an intensive effort","Let your heart rate come down naturally over 5 minutes","Focus on slow, deep breathing: inhale through the nose, exhale through the mouth","Shake out your legs gently and note how they feel — useful data for your next session"],"cues":["💡 Stopping abruptly after maximal effort can cause dizziness — keep moving","Your heart rate should drop below 120 bpm within 2–3 minutes at walking pace"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Wandel in een rustig, ontspannen tempo — stop niet abrupt na een zware inspanning","Laat je hartslag in 5 minuten vanzelf zakken","Let op een langzame, diepe ademhaling: adem in door je neus en uit door je mond","Schud je benen rustig los en voel hoe ze aanvoelen — handige informatie voor je volgende training"],"cues_nl":["💡 Abrupt stoppen na een maximale inspanning kan je duizelig maken — blijf bewegen","Op wandeltempo hoort je hartslag binnen 2–3 minuten onder de 120 slagen per minuut te zakken"]}', NULL, '{"supports":["time"],"base_duration_sec":300,"fixed_sets":1}', '{"substitutions":["march-in-place","heel-dig-march"]}', 1, 1777114247000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('46502d1ff3109bf8b8a1311886ddf3d2', 'easy-jog-warmup', 'Easy Jog Warm-up', 'Rustig inlopen', 'cardio', '["quads","hamstrings","calves","glutes","cardiovascular_system"]', NULL, '["cardio","low_impact","outdoor","no_floor","zone1","session_phase","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Jog at a very easy, conversational pace — Zone 1 only (you could hold a full conversation)","Keep your breathing relaxed and posture tall, eyes looking ahead","This is preparation, not training — slow to a walk immediately if you feel breathless","After 7 minutes you should feel warm and loose, not winded"],"cues":["💡 Zone 1 means you can speak full sentences without effort — if you cannot, slow down","Use this time to mentally rehearse your pacing strategy for the effort ahead"],"why":"Cardiovascular training strengthens your heart and lungs, expands aerobic capacity, and burns energy efficiently — the base that makes everything else feel easier.","muscle_target":"Cardiovascular System","steps_nl":["Jog in een heel rustig tempo waarbij je kunt praten — alleen zone 1 (je kunt een heel gesprek voeren)","Houd je ademhaling ontspannen, loop rechtop en kijk vooruit","Dit is voorbereiding, geen training — ga meteen wandelen als je buiten adem raakt","Na 7 minuten voel je je warm en los, niet buiten adem"],"cues_nl":["💡 Zone 1 betekent dat je zonder moeite hele zinnen kunt zeggen — lukt dat niet, ga dan langzamer","Gebruik deze tijd om in gedachten je tempoverdeling voor de inspanning straks door te nemen"]}', NULL, '{"supports":["time"],"base_duration_sec":420,"fixed_sets":1}', '{"substitutions":["march-in-place","cooldown-walk"]}', 1, 1777114247000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pull_assisted_band', 'assisted-pull-up-band', 'Band-Assisted Pull-Up', 'Optrekken met weerstandsband', 'strength', '["lats", "upper_back", "biceps"]', '["core", "forearms"]', '["strength", "pull", "upper_body", "pull_up_bar", "resistance_bands", "no_floor", "low_impact", "loads_shoulder"]', '["pull_up_bar", "resistance_bands"]', NULL, '{"steps":["Loop a band over the bar and put one knee or foot in the loop.","Grip the bar shoulder-width.","Pull until your chin clears the bar.","Lower under control."],"cues":["A thicker band gives more help \u2014 drop down as you get stronger","Chest to the bar, not chin craned over it","\ud83d\udca1 Keep the ribs down so it does not become a swing"],"steps_nl":["Hang een weerstandsband over de stang en zet één knie of voet in de lus","Pak de stang vast op schouderbreedte","Trek jezelf op tot je kin boven de stang komt","Zak gecontroleerd terug"],"cues_nl":["Een dikkere band helpt meer — kies een dunnere naarmate je sterker wordt","Borst naar de stang, niet je kin eroverheen rekken","💡 Houd je ribben omlaag, zodat het geen zwaai wordt"]}', '{"images":["/exercise-media/assisted-pull-up-band/0.jpg","/exercise-media/assisted-pull-up-band/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["reps", "sets"]}', '{"substitutions":["band-row-seated","band-seated-row"]}', 1, 1789300000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pull_assisted_machine', 'assisted-pull-up-machine', 'Assisted Pull-Up (Machine)', 'Optrekken ondersteund (machine)', 'strength', '["lats", "upper_back", "biceps"]', '["core"]', '["strength", "pull", "upper_body", "machine", "gym", "no_floor", "low_impact", "loads_shoulder"]', '["machine"]', NULL, '{"steps":["Set the assistance weight \u2014 more weight means more help.","Kneel or stand on the pad and grip the handles.","Pull until your chin clears the bar.","Lower under control."],"cues":["Reduce the assistance as you get stronger","Full range every rep","\ud83d\udca1 Lets you train the real movement long before an unassisted rep"],"steps_nl":["Stel het hulpgewicht in — meer gewicht betekent meer hulp","Kniel of sta op het steunkussen en pak de handgrepen vast","Trek jezelf op tot je kin boven de stang komt","Zak gecontroleerd terug"],"cues_nl":["Verminder de hulp naarmate je sterker wordt","Elke herhaling de volledige beweging","💡 Zo train je de echte beweging lang voordat je een herhaling zonder hulp kunt"]}', NULL, '{"supports":["weight","reps","sets"],"load_type":"machine_stack"}', '{"substitutions":["assisted-pull-up-band","band-row-seated"]}', 1, 1789300000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pull_band_row', 'band-bent-over-row', 'Band Bent-Over Row', 'Bent-over row met weerstandsband', 'strength', '["lats", "upper_back", "rhomboids"]', '["biceps", "core"]', '["strength","pull","upper_body","resistance_bands","no_floor","quiet","low_impact","loads_lower_back","loads_shoulder"]', '["resistance_bands"]', NULL, '{"steps":["Stand on the middle of the band, feet hip-width.","Hinge forward about 45\u00b0 with a flat back, band ends in each hand.","Row both hands to your lower ribs.","Lower under control until your arms are straight."],"cues":["Keep your back flat \u2014 hinge from the hips, not the spine","Elbows brush past your sides","\ud83d\udca1 Stand wider on the band for more resistance"],"steps_nl":["Ga op het midden van de band staan, voeten op heupbreedte","Buig vanuit je heupen ongeveer 45° naar voren met een rechte rug, een uiteinde van de band in elke hand","Trek beide handen naar je onderste ribben","Zak gecontroleerd terug tot je armen gestrekt zijn"],"cues_nl":["Houd je rug recht — buig vanuit je heupen, niet vanuit je rug","Je ellebogen strijken langs je zij","💡 Zet je voeten wijder op de band voor meer weerstand"]}', NULL, '{"supports": ["reps", "sets", "tempo"]}', '{"substitutions":["dumbbell-row","band-seated-row"]}', 1, 1789300000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pull_band_pulldown', 'band-lat-pulldown', 'Band Lat Pulldown', 'Lat pulldown met weerstandsband', 'strength', '["lats", "upper_back"]', '["biceps", "rear_delts"]', '["strength", "pull", "upper_body", "resistance_bands", "no_floor", "quiet", "low_impact", "loads_shoulder"]', '["resistance_bands"]', NULL, '{"steps":["Anchor a band above head height \u2014 a door anchor or closed door hinge works.","Kneel or sit tall, arms overhead, holding one end in each hand.","Pull your elbows down and back until your hands reach chest height.","Control the band all the way back up."],"cues":["Lead with the elbows, not the hands","Squeeze your shoulder blades down and together","\ud83d\udca1 If the band snaps back fast, step closer to the anchor"],"steps_nl":["Maak een band vast boven hoofdhoogte — een deuranker of het scharnier van een dichte deur werkt","Kniel of zit rechtop, armen boven je hoofd, een uiteinde in elke hand","Trek je ellebogen omlaag en naar achteren tot je handen op borsthoogte zijn","Laat de band gecontroleerd helemaal terug omhoog gaan"],"cues_nl":["Leid met je ellebogen, niet met je handen","Trek je schouderbladen omlaag en naar elkaar toe","💡 Schiet de band snel terug, ga dan dichter bij het ankerpunt staan"]}', NULL, '{"supports": ["reps", "sets", "tempo"]}', '{"substitutions":["band-seated-row","doorway-isometric-row"]}', 1, 1789300000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pull_band_seated_row', 'band-seated-row', 'Band Seated Row', 'Zittende row met weerstandsband', 'strength', '["upper_back", "rhomboids", "lats"]', '["biceps"]', '["strength","pull","upper_body","resistance_bands","floor","quiet","low_impact","loads_shoulder"]', '["resistance_bands"]', NULL, '{"steps":["Sit on the floor, legs straight, band looped around both feet.","Sit tall with a long spine, holding one end in each hand.","Pull your hands to your waist, elbows close to your body.","Straighten the arms slowly."],"cues":["Chest up throughout","Do not lean back to move the band","\ud83d\udca1 Bend the knees slightly if your hamstrings are tight"],"steps_nl":["Ga op de vloer zitten met gestrekte benen en de band om beide voeten","Zit rechtop met een lange rug en houd in elke hand een uiteinde vast","Trek je handen naar je taille, ellebogen dicht langs je lichaam","Strek je armen langzaam"],"cues_nl":["Borst de hele tijd omhoog","Leun niet achterover om de band te bewegen","💡 Buig je knieën licht als je hamstrings strak zijn"]}', NULL, '{"supports": ["reps", "sets", "tempo"]}', '{"substitutions":["band-row-seated","assisted-pull-up-band"]}', 1, 1789300000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pull_band_single_row', 'band-single-arm-row', 'Band Single-Arm Row', 'Eenarmige row met weerstandsband', 'strength', '["lats", "upper_back"]', '["biceps", "core"]', '["strength","pull","upper_body","resistance_bands","no_floor","quiet","low_impact","unilateral","loads_shoulder"]', '["resistance_bands"]', NULL, '{"steps":["Anchor a band at waist height, or stand on one end.","Stand side-on, holding the band in one hand, arm extended.","Row the hand to your ribs, keeping your torso still.","Repeat, then change sides."],"cues":["Do not rotate your torso to help the pull","Even reps both sides","\ud83d\udca1 Catches the side-to-side difference a two-arm row hides"],"steps_nl":["Maak een weerstandsband vast op taillehoogte, of ga op één uiteinde staan","Ga zijwaarts staan en houd de band in één hand, arm gestrekt","Trek je hand naar je ribben en houd je romp stil","Herhaal en wissel dan van kant"],"cues_nl":["Draai je romp niet mee om het trekken makkelijker te maken","Evenveel herhalingen aan beide kanten","💡 Laat het verschil tussen links en rechts zien dat een row met twee armen verbergt"]}', NULL, '{"supports": ["reps", "sets"]}', '{"substitutions":["band-seated-row","doorway-isometric-row"]}', 1, 1789300000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pull_door_iso', 'doorway-isometric-row', 'Doorway Isometric Row', 'Isometrische row in deuropening', 'strength', '["lats", "upper_back", "rhomboids"]', '["biceps"]', '["strength","pull","upper_body","bodyweight","no_floor","quiet","low_impact","isometric","loads_shoulder"]', '["none"]', NULL, '{"steps":["Stand facing a door frame, feet either side of it.","Grip both sides at chest height, arms straight, lean back.","Pull yourself towards the frame and hold, squeezing the shoulder blades.","Hold, then release slowly."],"cues":["Body stays in a straight line from heel to head","Breathe through the hold","\ud83d\udca1 The simplest way to train pulling with nothing at all"],"steps_nl":["Ga met je gezicht naar een deurpost staan, je voeten aan weerszijden ervan","Pak beide kanten op borsthoogte vast, strek je armen en leun naar achteren","Trek jezelf naar de deurpost toe en houd vast, met je schouderbladen samengeknepen","Houd vast en laat dan langzaam los"],"cues_nl":["Je lichaam blijft één rechte lijn van hiel tot hoofd","Adem door terwijl je vasthoudt","💡 De eenvoudigste manier om trekken te trainen zonder enig materiaal"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["dumbbell-row","inverted-row-feet-elevated","towel-door-row"]}', 1, 1789300000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pull_inverted_elev', 'inverted-row-feet-elevated', 'Inverted Row (Feet Elevated)', 'Inverted row voeten verhoogd', 'strength', '["lats", "rhomboids", "upper_back"]', '["biceps", "core"]', '["strength","pull","upper_body","bodyweight","floor","low_impact","loads_shoulder"]', '["none"]', NULL, '{"steps":["Set up under a sturdy table as for an inverted row, with your feet on a chair.","Grip the edge, body straight from heels to head.","Pull your chest to the edge.","Lower slowly."],"cues":["Harder than the floor version \u2014 progress here once table rows feel easy","Squeeze the shoulder blades at the top","\ud83d\udca1 Stop the set when your hips start to drop"],"steps_nl":["Ga onder een stevige tafel liggen zoals bij een inverted row, met je voeten op een stoel.","Pak de rand vast en maak je lichaam recht van hielen tot hoofd.","Trek je borst naar de rand.","Zak langzaam terug."],"cues_nl":["Zwaarder dan de versie op de vloer: stap hierop over zodra rows aan tafel makkelijk gaan.","Knijp bovenin je schouderbladen samen.","💡 Stop de set zodra je heupen gaan zakken."]}', NULL, '{"supports": ["reps", "sets"]}', '{"substitutions":["doorway-isometric-row","towel-door-row"]}', 1, 1789300000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pull_lat_pulldown', 'lat-pulldown', 'Lat Pulldown', 'Lat pulldown', 'strength', '["lats", "upper_back"]', '["biceps", "rear_delts"]', '["strength", "pull", "upper_body", "machine", "gym", "no_floor", "low_impact", "loads_shoulder"]', '["lat_pulldown"]', NULL, '{"steps":["Set the thigh pad so your legs are held down.","Grip the bar wider than shoulder-width, palms away.","Pull the bar to your upper chest, leaning back very slightly.","Let it rise slowly until your arms are straight."],"cues":["Lead with the elbows","Do not pull behind your neck","\ud83d\udca1 The most scalable pull there is \u2014 start light and add weight weekly"],"steps_nl":["Stel het dijkussen zo in dat je benen vastzitten","Pak de stang breder dan schouderbreedte vast, handpalmen van je af","Trek de stang naar je bovenborst en leun daarbij heel licht achterover","Laat hem langzaam omhoog gaan tot je armen gestrekt zijn"],"cues_nl":["Leid met je ellebogen","Trek de stang niet achter je nek","💡 De trekoefening die het makkelijkst mee te schalen is — begin licht en voeg elke week gewicht toe"]}', '{"images":["/exercise-media/lat-pulldown/0.jpg","/exercise-media/lat-pulldown/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"machine_stack"}', '{"substitutions":["doorway-isometric-row","inverted-row-feet-elevated"]}', 1, 1789300000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pull_negative', 'negative-pull-up', 'Negative Pull-Up', 'Negatief optrekken', 'strength', '["lats", "upper_back", "biceps"]', '["core", "forearms"]', '["strength", "pull", "upper_body", "pull_up_bar", "no_floor", "low_impact", "loads_shoulder"]', '["pull_up_bar"]', NULL, '{"steps":["Use a chair to get your chin above the bar.","Take your feet off and lower yourself as slowly as you can.","Step back up and repeat."],"cues":["Aim for a 3-5 second descent","Stop the set when you can no longer control the lowering","\ud83d\udca1 The fastest honest route to a first pull-up"],"steps_nl":["Gebruik een stoel om met je kin boven de stang te komen","Haal je voeten van de stoel en laat jezelf zo langzaam mogelijk zakken","Stap weer omhoog en herhaal"],"cues_nl":["Mik op 3-5 seconden zakken","Stop de set zodra je het zakken niet meer onder controle hebt","💡 De snelste eerlijke weg naar je eerste pull-up"]}', '{"images":["/exercise-media/negative-pull-up/0.jpg","/exercise-media/negative-pull-up/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["reps", "sets"]}', '{"substitutions":["pull-up","scapular-pull-up"]}', 1, 1789300000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pull_scap', 'scapular-pull-up', 'Scapular Pull-Up', 'Scapula pull-up', 'strength', '["lats", "upper_back", "rhomboids"]', '["traps"]', '["strength", "pull", "upper_body", "pull_up_bar", "no_floor", "low_impact", "loads_shoulder"]', '["pull_up_bar"]', NULL, '{"steps":["Hang from the bar with straight arms.","Without bending your elbows, pull your shoulder blades down and together so your body rises slightly.","Lower back to a full hang."],"cues":["The elbows stay straight the whole time","Small movement \u2014 a few centimetres is right","\ud83d\udca1 This is the missing step between a hang and a pull-up"],"steps_nl":["Hang aan de stang met gestrekte armen","Trek zonder je ellebogen te buigen je schouderbladen omlaag en naar elkaar toe, zodat je lichaam iets omhoogkomt","Zak terug naar een volledige hang"],"cues_nl":["Je ellebogen blijven de hele tijd gestrekt","Kleine beweging — een paar centimeter is goed","💡 Dit is de ontbrekende stap tussen hangen en een pull-up"]}', '{"images":["/exercise-media/scapular-pull-up/0.jpg","/exercise-media/scapular-pull-up/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["reps", "sets"]}', '{"substitutions":["doorway-isometric-row","inverted-row-feet-elevated","negative-pull-up"]}', 1, 1789300000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pull_seated_cable_row', 'seated-cable-row', 'Seated Cable Row', 'Kabel row zittend', 'strength', '["upper_back", "rhomboids", "lats"]', '["biceps", "rear_delts"]', '["strength","pull","upper_body","machine","gym","no_floor","low_impact","loads_lower_back","loads_shoulder"]', '["seated_row_machine"]', NULL, '{"steps":["Sit with your feet on the platform and knees slightly bent.","Take the handle with a long spine and chest up.","Pull to your waist, elbows close to your sides.","Return slowly without letting your back round."],"cues":["Move the weight with your back, not by rocking","Pause for a beat at the squeeze","\ud83d\udca1 If your lower back rounds, drop the weight"],"steps_nl":["Ga zitten met je voeten op het platform en je knieën licht gebogen","Pak de handgreep vast met een lange rug en je borst omhoog","Trek naar je middel, ellebogen dicht langs je lichaam","Ga langzaam terug zonder je rug bol te laten worden"],"cues_nl":["Verplaats het gewicht met je rug, niet door te wiegen","Houd even vast op het punt van aanspannen","💡 Wordt je onderrug bol, pak dan minder gewicht"]}', '{"images":["/exercise-media/seated-cable-row/0.jpg","/exercise-media/seated-cable-row/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"machine_stack"}', '{"substitutions":["band-seated-row","assisted-pull-up-band"]}', 1, 1789300000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pull_straight_arm', 'straight-arm-pulldown', 'Straight-Arm Pulldown', 'Straight-arm pulldown', 'strength', '["lats"]', '["core", "rear_delts"]', '["strength", "pull", "upper_body", "machine", "gym", "no_floor", "low_impact", "loads_shoulder"]', '["cable"]', NULL, '{"steps":["Stand facing a high cable, bar or rope in both hands.","Keep your arms straight and hinge very slightly at the hips.","Sweep the bar down to your thighs.","Return slowly overhead."],"cues":["The elbows stay straight \u2014 this is not a triceps pushdown","Feel it along the side of your back","\ud83d\udca1 Good for learning to feel the lats before heavier pulling"],"steps_nl":["Ga met je gezicht naar een hoge kabel staan, met de stang of het touw in beide handen","Houd je armen gestrekt en buig heel licht voorover vanuit je heupen","Veeg de stang omlaag naar je bovenbenen","Ga langzaam terug tot boven je hoofd"],"cues_nl":["Je ellebogen blijven gestrekt — dit is geen triceps pushdown","Voel het langs de zijkant van je rug","💡 Goed om je lats te leren voelen voordat je zwaarder gaat trekken"]}', '{"images":["/exercise-media/straight-arm-pulldown/0.jpg","/exercise-media/straight-arm-pulldown/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"machine_stack"}', '{"substitutions":["doorway-isometric-row","inverted-row-feet-elevated"]}', 1, 1789300000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_pull_towel_row', 'towel-door-row', 'Towel Row (Door)', 'Row met handdoek aan deur', 'strength', '["lats", "upper_back", "rhomboids"]', '["biceps", "core"]', '["strength","pull","upper_body","bodyweight","no_floor","low_impact","loads_shoulder"]', '["none"]', NULL, '{"steps":["Loop a towel around a secure door handle on a closed, latched door.","Hold one end in each hand and walk your feet towards the door, leaning back.","Pull your chest towards the handle.","Lower under control."],"cues":["Test the door holds your weight first","The further your feet, the harder it gets","\ud83d\udca1 Keep the hips in line \u2014 do not let them sag"],"steps_nl":["Leg een handdoek om een stevige deurklink van een gesloten deur die in het slot zit.","Pak in elke hand een uiteinde, loop met je voeten naar de deur en leun achterover.","Trek je borst naar de klink.","Zak gecontroleerd terug."],"cues_nl":["Test eerst of de deur je gewicht houdt.","Hoe verder je voeten naar voren, hoe zwaarder.","💡 Houd je heupen in lijn: laat ze niet doorzakken."]}', NULL, '{"supports": ["reps", "sets"]}', '{"substitutions":["doorway-isometric-row","inverted-row-feet-elevated"]}', 1, 1789300000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_bb_back_squat', 'barbell-back-squat', 'Barbell Back Squat', 'Barbell back squat', 'strength', '["quads", "glutes"]', '["hamstrings", "core", "lower_back"]', '["strength", "legs", "barbell", "gym", "no_floor", "loads_knee", "loads_lower_back"]', '["barbell", "squat_rack"]', NULL, '{"steps":["Set the bar at upper-chest height in the rack. Step under it, bar resting across your upper back \u2014 not your neck.","Brace, stand it up, step back two steps.","Sit down and back until your thighs reach parallel.","Drive through the whole foot to stand."],"cues":["Knees track over the toes","Chest stays proud out of the hole","\ud83d\udca1 Always use the safety pins \u2014 set them just below your bottom position"],"steps_nl":["Leg de stang in het rek op de hoogte van je bovenborst. Stap eronder en laat de stang op je bovenrug rusten — niet op je nek","Span je romp aan, til de stang uit het rek en doe twee stappen naar achteren","Zak naar achteren en omlaag tot je bovenbenen horizontaal zijn","Duw door je hele voet om te gaan staan"],"cues_nl":["Je knieën blijven in lijn met je tenen","Houd je borst trots vooruit als je uit het diepste punt komt","💡 Gebruik altijd de veiligheidspennen — zet ze net onder je laagste positie"]}', '{"images":["/exercise-media/barbell-back-squat/0.jpg","/exercise-media/barbell-back-squat/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"barbell"}', '{"substitutions":["wall-sit","sumo-squat","barbell-front-squat"]}', 1, 1789301000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_bb_bench', 'barbell-bench-press', 'Barbell Bench Press', 'Barbell bankdrukken', 'strength', '["chest"]', '["triceps", "front_delts"]', '["strength", "push", "upper_body", "barbell", "gym", "no_floor", "loads_shoulder"]', '["barbell", "bench_press_rack", "bench"]', NULL, '{"steps":["Lie on the bench, eyes under the bar, feet flat on the floor.","Grip slightly wider than shoulder-width and unrack.","Lower to your mid-chest, elbows about 45\u00b0 from your body.","Press back up."],"cues":["Shoulder blades pinched into the bench the whole set","Wrists stacked over the elbows","\ud83d\udca1 Never bench heavy alone without safety arms or a spotter"],"steps_nl":["Ga op de bank liggen met je ogen onder de stang en je voeten plat op de vloer","Pak de stang iets breder dan schouderbreedte vast en til hem uit het rek","Laat de stang zakken naar het midden van je borst, ellebogen zo''n 45° van je lichaam","Druk de stang weer omhoog"],"cues_nl":["Houd je schouderbladen de hele set samengeknepen tegen de bank","Polsen recht boven je ellebogen","💡 Druk nooit zwaar in je eentje zonder veiligheidsarmen of iemand die je helpt"]}', '{"images":["/exercise-media/barbell-bench-press/0.jpg","/exercise-media/barbell-bench-press/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"barbell"}', '{"substitutions":["knee-push-up","wall-push-up"]}', 1, 1789301000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_bb_row', 'barbell-bent-over-row', 'Barbell Bent-Over Row', 'Barbell bent-over row', 'strength', '["lats", "upper_back", "rhomboids"]', '["biceps", "lower_back"]', '["strength","pull","upper_body","barbell","gym","no_floor","loads_lower_back","loads_shoulder"]', '["barbell"]', NULL, '{"steps":["Hold the bar with an overhand grip, hands shoulder-width.","Hinge to roughly 45\u00b0, flat back, bar hanging at your shins.","Row to your lower ribs.","Lower under control without letting the back round."],"cues":["Torso angle stays fixed \u2014 do not row by standing up","Elbows drive back, not out","\ud83d\udca1 Lighter than you think; form breaks fast on this one"],"steps_nl":["Pak de stang bovenhands vast, handen op schouderbreedte","Scharnier vanuit je heupen tot ongeveer 45°, met een vlakke rug en de stang hangend bij je schenen","Trek de stang naar je onderste ribben","Laat gecontroleerd zakken zonder je rug bol te maken"],"cues_nl":["De hoek van je romp blijft gelijk — row niet door overeind te komen","Trek je ellebogen naar achteren, niet naar buiten","💡 Lichter dan je denkt: je techniek gaat bij deze oefening snel achteruit"]}', '{"images":["/exercise-media/barbell-bent-over-row/0.jpg","/exercise-media/barbell-bent-over-row/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"barbell"}', '{"substitutions":["doorway-isometric-row","inverted-row-feet-elevated"]}', 1, 1789301000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_bb_calf', 'barbell-calf-raise', 'Barbell Calf Raise', 'Barbell kuitheffen', 'strength', '["calves"]', '[]', '["strength","legs","barbell","gym","no_floor","loads_ankle","loads_knee","loads_lower_back"]', '["barbell", "squat_rack"]', NULL, '{"steps":["Rest the bar on your upper back and stand tall, on a step if you have one","Rise onto the balls of your feet as high as you can","Pause at the top","Lower slowly until you feel a stretch"],"cues":["Slow on the way down — that is where the work is","Do not bounce","💡 Calf capacity is the main protector against running injuries"],"steps_nl":["Leg de stang op je bovenrug en sta rechtop, op een opstapje als je er een hebt","Kom zo hoog mogelijk omhoog op de bal van je voeten","Houd bovenin even vast","Zak langzaam tot je rek voelt"],"cues_nl":["Zak langzaam — daar zit het echte werk","Niet veren","💡 Sterke kuiten zijn de belangrijkste bescherming tegen hardloopblessures"]}', '{"images":["/exercise-media/barbell-calf-raise/0.jpg","/exercise-media/barbell-calf-raise/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"barbell"}', '{"substitutions":["bent-knee-calf-raise","calf-raise"]}', 1, 1789301000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_bb_deadlift', 'barbell-deadlift', 'Barbell Deadlift', 'Barbell deadlift', 'strength', '["hamstrings", "glutes", "lower_back"]', '["lats", "traps", "core"]', '["strength","hinge","barbell","gym","floor","loads_lower_back","loads_knee","loads_shoulder"]', '["barbell", "weight_plates"]', NULL, '{"steps":["Stand with the bar over your mid-foot, feet hip-width.","Hinge and grip just outside your legs; drop the hips until your shins touch the bar.","Take the slack out, brace, and stand by pushing the floor away.","Lower by hinging back, keeping the bar close."],"cues":["Flat back from first pull to lockout","The bar stays in contact with your legs","\ud83d\udca1 Stop the set the moment your back rounds \u2014 this is not a lift to grind"],"steps_nl":["Ga staan met de stang boven het midden van je voeten, voeten op heupbreedte","Scharnier vanuit je heupen en pak de stang net buiten je benen vast; laat je heupen zakken tot je schenen de stang raken","Trek de speling uit de stang, span je romp aan en kom overeind door de vloer weg te duwen","Laat de stang zakken door je heupen naar achteren te brengen en houd hem dicht bij je"],"cues_nl":["Vlakke rug van het begin van de lift tot je helemaal rechtop staat","De stang blijft contact houden met je benen","💡 Stop de set zodra je rug bol wordt — dit is geen lift om doorheen te worstelen"]}', '{"images":["/exercise-media/barbell-deadlift/0.jpg","/exercise-media/barbell-deadlift/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets"],"load_type":"barbell"}', '{"substitutions":["good-morning-bodyweight","glute-bridge"]}', 1, 1789301000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_bb_front_squat', 'barbell-front-squat', 'Barbell Front Squat', 'Barbell front squat', 'strength', '["quads"]', '["glutes", "core", "upper_back"]', '["strength","legs","barbell","gym","no_floor","loads_knee","loads_lower_back"]', '["barbell", "squat_rack"]', NULL, '{"steps":["Rest the bar across the front of your shoulders, elbows high.","Stand it up and step back.","Squat down with an upright torso until your thighs reach parallel.","Stand, keeping the elbows up throughout."],"cues":["Elbows drop, bar drops \u2014 keep them high","More upright than a back squat","\ud83d\udca1 Easier on the lower back than a back squat at the same effort"],"steps_nl":["Laat de stang op de voorkant van je schouders rusten, ellebogen hoog","Til de stang uit het rek en stap naar achteren","Zak met een rechte romp in een squat tot je bovenbenen horizontaal zijn","Kom omhoog en houd je ellebogen de hele tijd hoog"],"cues_nl":["Zakken je ellebogen, dan zakt de stang — houd ze hoog","Je staat rechter op dan bij een back squat","💡 Vriendelijker voor je onderrug dan een back squat bij dezelfde inspanning"]}', '{"images":["/exercise-media/barbell-front-squat/0.jpg","/exercise-media/barbell-front-squat/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"barbell"}', '{"substitutions":["wall-sit","barbell-back-squat"]}', 1, 1789301000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_bb_good_morning', 'barbell-good-morning', 'Barbell Good Morning', 'Barbell good morning', 'strength', '["hamstrings", "lower_back"]', '["glutes", "core"]', '["strength","hinge","barbell","gym","no_floor","loads_lower_back","loads_knee"]', '["barbell", "squat_rack"]', NULL, '{"steps":["Rest the bar on your upper back with your feet hip-width and your knees softly bent","Hinge forward at the hips with a flat back until your torso is near parallel","Drive the hips forward to stand"],"cues":["Very light to start — this loads the lower back directly","Back stays flat throughout","💡 Skip this if you have any lower-back history; use an RDL instead"],"steps_nl":["Leg de stang op je bovenrug, voeten op heupbreedte en knieën licht gebogen","Scharnier vanuit je heupen naar voren met een vlakke rug tot je romp bijna horizontaal is","Duw je heupen naar voren om weer te gaan staan"],"cues_nl":["Begin heel licht — deze oefening belast je onderrug direct","Je rug blijft de hele tijd vlak","💡 Sla deze over als je ooit onderrugklachten hebt gehad; doe dan een RDL"]}', '{"images":["/exercise-media/barbell-good-morning/0.jpg","/exercise-media/barbell-good-morning/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"barbell"}', '{"substitutions":["good-morning-bodyweight","glute-bridge"]}', 1, 1789301000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_bb_hip_thrust', 'barbell-hip-thrust', 'Barbell Hip Thrust', 'Barbell hip thrust', 'strength', '["glutes"]', '["hamstrings", "core"]', '["strength", "hinge", "barbell", "gym", "floor", "loads_lower_back"]', '["barbell", "bench", "weight_plates"]', NULL, '{"steps":["Sit on the floor with your upper back against a bench, bar across your hips on a pad","Place your feet flat so that your shins are vertical at the top","Drive through your heels until your hips are level with your knees","Lower under control"],"cues":["Tuck the chin and keep the ribs down","Squeeze the glutes hard at the top for a beat","💡 Shins vertical at lockout — walk the feet in or out until they are"],"steps_nl":["Ga op de vloer zitten met je bovenrug tegen een bank en de stang op een kussentje over je heupen","Zet je voeten plat neer, zo dat je schenen bovenin verticaal staan","Duw door je hielen tot je heupen op gelijke hoogte met je knieën zijn","Zak gecontroleerd"],"cues_nl":["Kin naar je borst en ribben omlaag","Span je bilspieren bovenin even hard aan","💡 Schenen verticaal als je heupen gestrekt zijn — zet je voeten dichterbij of verder weg tot dat klopt"]}', '{"images":["/exercise-media/barbell-hip-thrust/0.jpg","/exercise-media/barbell-hip-thrust/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"barbell"}', '{"substitutions":["glute-bridge","good-morning-bodyweight"]}', 1, 1789301000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_bb_ohp', 'barbell-overhead-press', 'Barbell Overhead Press', 'Barbell overhead press', 'strength', '["shoulders"]', '["triceps", "core", "upper_back"]', '["strength","push","upper_body","barbell","gym","no_floor","loads_shoulder","loads_lower_back","loads_knee"]', '["barbell", "squat_rack"]', NULL, '{"steps":["Take the bar at collarbone height, hands just outside the shoulders.","Squeeze your glutes and brace so you do not lean back.","Press overhead, moving your head back slightly to let the bar pass.","Lower under control to the collarbone."],"cues":["Finish with the bar over the middle of your foot","Ribs down \u2014 do not arch the lower back","\ud83d\udca1 If you have to lean back to finish, it is too heavy"],"steps_nl":["Pak de stang op sleutelbeenhoogte, handen net buiten je schouders","Span je bilspieren en je romp aan zodat je niet achterover leunt","Druk de stang boven je hoofd en beweeg je hoofd iets naar achteren om hem te laten passeren","Laat de stang gecontroleerd zakken tot je sleutelbeen"],"cues_nl":["Eindig met de stang boven het midden van je voet","Ribben omlaag — maak je onderrug niet hol","💡 Moet je achterover leunen om hem omhoog te krijgen, dan is hij te zwaar"]}', '{"images":["/exercise-media/barbell-overhead-press/0.jpg","/exercise-media/barbell-overhead-press/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"barbell"}', '{"substitutions":["knee-push-up","wall-push-up"]}', 1, 1789301000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_bb_lunge', 'barbell-reverse-lunge', 'Barbell Reverse Lunge', 'Barbell achterwaartse uitvalspas', 'strength', '["quads", "glutes"]', '["hamstrings", "core"]', '["strength","legs","barbell","gym","no_floor","unilateral","loads_knee","loads_lower_back","loads_ankle"]', '["barbell", "squat_rack"]', NULL, '{"steps":["Rest the bar on your upper back as for a squat","Step one foot back and lower until the back knee is just off the floor","Drive through the front heel to stand","Alternate legs"],"cues":["Front shin close to vertical","Step back far enough that the front knee does not shoot forward","💡 Kinder to the knees than a forward lunge"],"steps_nl":["Leg de stang op je bovenrug, net als bij een squat","Stap met één voet naar achteren en zak tot je achterste knie net boven de vloer is","Duw door je voorste hiel om weer te gaan staan","Wissel van been"],"cues_nl":["Voorste scheen bijna verticaal","Stap ver genoeg naar achteren, zodat je voorste knie niet naar voren schiet","💡 Vriendelijker voor je knieën dan een uitvalspas naar voren"]}', NULL, '{"supports":["weight","reps","sets"],"load_type":"barbell"}', '{"substitutions":["walking-lunges","split-squat"]}', 1, 1789301000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_bb_rdl', 'barbell-romanian-deadlift', 'Barbell Romanian Deadlift', 'Barbell Romanian deadlift', 'strength', '["hamstrings", "glutes"]', '["lower_back", "core"]', '["strength","hinge","barbell","gym","no_floor","loads_lower_back","loads_knee"]', '["barbell"]', NULL, '{"steps":["Stand tall holding the bar at your thighs, knees softly bent.","Push your hips back, letting the bar slide down your legs.","Stop when you feel a strong hamstring stretch \u2014 usually mid-shin.","Drive the hips forward to stand."],"cues":["The knees barely move \u2014 this is a hip movement","Bar stays against the legs","\ud83d\udca1 Range is set by your hamstrings, not by touching the floor"],"steps_nl":["Sta rechtop met de stang tegen je bovenbenen, knieën licht gebogen","Duw je heupen naar achteren en laat de stang langs je benen omlaag glijden","Stop als je een flinke rek in je hamstrings voelt — meestal halverwege je schenen","Duw je heupen naar voren om weer te gaan staan"],"cues_nl":["Je knieën bewegen nauwelijks — dit is een heupbeweging","De stang blijft tegen je benen","💡 Je hamstrings bepalen hoe diep je gaat, niet het raken van de vloer"]}', '{"images":["/exercise-media/barbell-romanian-deadlift/0.jpg","/exercise-media/barbell-romanian-deadlift/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"barbell"}', '{"substitutions":["glute-bridge","good-morning-bodyweight"]}', 1, 1789301000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_ez_curl', 'ez-bar-biceps-curl', 'EZ-Bar Biceps Curl', 'EZ-bar biceps curl', 'strength', '["biceps"]', '["forearms"]', '["strength","pull","upper_body","barbell","gym","no_floor","quiet","loads_shoulder"]', '["ez_bar"]', NULL, '{"steps":["Hold the EZ bar at the angled grips, arms straight.","Curl to shoulder height, keeping the elbows pinned to your sides.","Lower slowly to full extension."],"cues":["The elbows do not travel forward","Full extension at the bottom each rep","\ud83d\udca1 The angled grip is easier on the wrists than a straight bar"],"steps_nl":["Pak de EZ-bar vast bij de schuine grepen, armen gestrekt","Curl tot schouderhoogte en houd je ellebogen tegen je zij","Laat langzaam zakken tot je armen volledig gestrekt zijn"],"cues_nl":["Je ellebogen gaan niet naar voren","Strek je armen onderin bij elke herhaling volledig","💡 De schuine greep is vriendelijker voor je polsen dan een rechte stang"]}', '{"images":["/exercise-media/ez-bar-biceps-curl/0.jpg","/exercise-media/ez-bar-biceps-curl/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"barbell"}', '{"substitutions":["inverted-row-table","doorway-isometric-row"]}', 1, 1789301000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_m_cable_curl', 'cable-biceps-curl', 'Cable Biceps Curl', 'Kabel biceps curl', 'strength', '["biceps"]', '["forearms"]', '["strength","pull","upper_body","machine","gym","no_floor","low_impact","quiet","loads_shoulder"]', '["cable"]', NULL, '{"steps":["Attach a bar to a low pulley, hold with palms up.","Curl to shoulder height, elbows pinned to your sides.","Lower slowly to full extension."],"cues":["The cable keeps tension at the bottom, unlike a dumbbell","Elbows do not drift forward","\ud83d\udca1 Good finisher when free weights have tired the grip"],"steps_nl":["Bevestig een stang aan een lage katrol en pak hem vast met je handpalmen omhoog","Curl tot schouderhoogte en houd je ellebogen tegen je zij","Laat langzaam zakken tot je armen helemaal gestrekt zijn"],"cues_nl":["De kabel houdt onderin spanning, anders dan een dumbbell","Je ellebogen schuiven niet naar voren","💡 Goede afsluiter als je grip moe is van de losse gewichten"]}', '{"images":["/exercise-media/cable-biceps-curl/0.jpg","/exercise-media/cable-biceps-curl/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"machine_stack"}', '{"substitutions":["inverted-row-table","doorway-isometric-row"]}', 1, 1789302000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_m_triceps_pushdown', 'cable-triceps-pushdown', 'Cable Triceps Pushdown', 'Kabel triceps pushdown', 'strength', '["triceps"]', '[]', '["strength", "push", "upper_body", "machine", "gym", "no_floor", "low_impact", "quiet", "loads_shoulder"]', '["cable"]', NULL, '{"steps":["Attach a bar or rope to a high pulley.","Elbows tucked at your sides, push down until your arms are straight.","Return to about 90\u00b0 under control."],"cues":["Only the forearms move","Do not lean over the bar to press it down","\ud83d\udca1 Rope attachment lets the wrists sit more naturally"],"steps_nl":["Bevestig een stang of touw aan een hoge katrol","Houd je ellebogen tegen je zij en duw omlaag tot je armen gestrekt zijn","Ga gecontroleerd terug tot ongeveer 90°"],"cues_nl":["Alleen je onderarmen bewegen","Hang niet over de stang om hem omlaag te duwen","💡 Met een touw staan je polsen in een natuurlijkere stand"]}', '{"images":["/exercise-media/cable-triceps-pushdown/0.jpg","/exercise-media/cable-triceps-pushdown/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"machine_stack"}', '{"substitutions":["knee-push-up","wall-push-up"]}', 1, 1789302000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_m_cable_woodchop', 'cable-woodchop', 'Cable Woodchop', 'Kabel wood chop', 'strength', '["obliques", "core"]', '["shoulders"]', '["strength","core","machine","gym","no_floor","low_impact","rotation","loads_shoulder","loads_lower_back"]', '["cable"]', NULL, '{"steps":["Set the pulley high, stand side-on, both hands on the handle.","Pull diagonally across your body towards the opposite hip, pivoting the back foot.","Return under control. Repeat, then change sides."],"cues":["Rotate through the torso, not just the arms","Keep the arms fairly straight","💡 Rotate from your hips and trunk together; your arms only guide the cable"],"steps_nl":["Zet de katrol hoog, ga zijwaarts staan en pak het handvat met beide handen","Trek schuin voor je lichaam langs naar je andere heup en draai mee op je achterste voet","Ga gecontroleerd terug. Herhaal en wissel dan van kant"],"cues_nl":["Draai vanuit je romp, niet alleen met je armen","Houd je armen vrijwel gestrekt","💡 Draai vanuit je heupen en romp tegelijk; je armen geleiden alleen de kabel"]}', '{"images":["/exercise-media/cable-woodchop/0.jpg","/exercise-media/cable-woodchop/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets"],"load_type":"machine_stack"}', '{"substitutions":["modified-plank","side-plank"]}', 1, 1789302000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_m_chest_press', 'chest-press-machine', 'Chest Press (Machine)', 'Chest press (machine)', 'strength', '["chest"]', '["triceps", "front_delts"]', '["strength", "push", "upper_body", "machine", "gym", "no_floor", "low_impact", "beginner_friendly", "loads_shoulder"]', '["chest_press_machine"]', NULL, '{"steps":["Set the seat so the handles are at mid-chest height.","Press forward until your arms are almost straight.","Return slowly until you feel a stretch across the chest."],"cues":["Shoulder blades stay back against the pad","Do not lock the elbows hard","\ud83d\udca1 The safest way to press heavy with nobody spotting you"],"steps_nl":["Stel de zitting zo in dat de handvatten halverwege je borst zitten","Druk naar voren tot je armen bijna gestrekt zijn","Ga langzaam terug tot je rek over je borst voelt"],"cues_nl":["Je schouderbladen blijven naar achteren tegen het kussen","Klap je ellebogen niet hard op slot","💡 De veiligste manier om zwaar te drukken als niemand je kan helpen"]}', '{"images":["/exercise-media/chest-press-machine/0.jpg","/exercise-media/chest-press-machine/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"machine_stack"}', '{"substitutions":["knee-push-up","wall-push-up"]}', 1, 1789302000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_m_dip', 'dip-station-dip', 'Dip (Parallel Bars)', 'Dip aan de brug', 'strength', '["chest", "triceps"]', '["front_delts"]', '["strength", "push", "upper_body", "gym", "no_floor", "loads_shoulder"]', '["dip_station"]', NULL, '{"steps":["Grip the parallel bars and press up to straight arms.","Lower until your upper arms are roughly parallel to the floor.","Press back to the top."],"cues":["Lean slightly forward for the chest, stay upright for the triceps","Do not drop below a comfortable shoulder position","\ud83d\udca1 Stop the set well before the shoulders start to ache"],"steps_nl":["Pak de stangen van de brug vast en druk jezelf op tot je armen gestrekt zijn","Zak tot je bovenarmen ongeveer horizontaal zijn","Druk jezelf terug omhoog"],"cues_nl":["Leun iets naar voren voor je borst, blijf rechtop voor je triceps","Zak niet dieper dan prettig is voor je schouders","💡 Stop de set ruim voordat je schouders gaan zeuren"]}', '{"images":["/exercise-media/dip-station-dip/0.jpg","/exercise-media/dip-station-dip/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["reps", "sets"]}', '{"substitutions":["knee-push-up","wall-push-up"]}', 1, 1789302000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_m_leg_curl', 'leg-curl-machine', 'Leg Curl (Machine)', 'Leg curl (machine)', 'strength', '["hamstrings"]', '["calves"]', '["strength","legs","machine","gym","no_floor","low_impact","beginner_friendly","loads_knee","loads_ankle"]', '["leg_curl_machine"]', NULL, '{"steps":["Set the pad just above your heels.","Curl your heels towards your glutes.","Pause briefly at the top.","Lower slowly to a straight leg."],"cues":["Hips stay down on the bench","Slow on the lowering","\ud83d\udca1 Directly trains the muscle most often strained in sprinting"],"steps_nl":["Zet het kussen net boven je hielen","Buig je hielen richting je billen","Pauzeer kort bovenin","Laat langzaam zakken tot je benen gestrekt zijn"],"cues_nl":["Je heupen blijven op de bank","Neem de tijd voor de weg terug","💡 Traint direct de spier die bij sprinten het vaakst verrekt"]}', '{"images":["/exercise-media/leg-curl-machine/0.jpg","/exercise-media/leg-curl-machine/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"machine_stack"}', '{"substitutions":["leg-extension-machine","nordic-hamstring-curl"]}', 1, 1789302000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_m_leg_ext', 'leg-extension-machine', 'Leg Extension (Machine)', 'Leg extension (machine)', 'strength', '["quads"]', '[]', '["strength", "legs", "machine", "gym", "no_floor", "low_impact", "beginner_friendly", "loads_knee"]', '["leg_extension_machine"]', NULL, '{"steps":["Sit with your knees at the machine''s pivot, pad on your shins.","Extend until your legs are almost straight.","Pause, then lower under control."],"cues":["Do not swing the weight up","Stop short of snapping the knee straight","\ud83d\udca1 Go light if your knees are sensitive \u2014 this loads them directly"],"steps_nl":["Ga zitten met je knieën bij het draaipunt van de machine en het kussen op je schenen","Strek je benen tot ze bijna recht zijn","Pauzeer en laat dan gecontroleerd zakken"],"cues_nl":["Zwaai het gewicht niet omhoog","Stop net voordat je knie op slot klapt","💡 Pak licht als je knieën gevoelig zijn — deze oefening belast ze direct"]}', '{"images":["/exercise-media/leg-extension-machine/0.jpg","/exercise-media/leg-extension-machine/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"machine_stack"}', '{"substitutions":["leg-press","wall-sit"]}', 1, 1789302000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_m_leg_press', 'leg-press', 'Leg Press', 'Leg press', 'strength', '["quads", "glutes"]', '["hamstrings"]', '["strength", "legs", "machine", "gym", "no_floor", "low_impact", "beginner_friendly", "loads_knee"]', '["leg_press"]', NULL, '{"steps":["Sit with your back flat against the pad, feet shoulder-width on the platform.","Release the safety catches.","Lower until your knees reach about 90\u00b0.","Press back without locking the knees out hard."],"cues":["Keep your lower back against the pad the whole way","Do not let the knees cave inward","\ud83d\udca1 A safe way to load the legs heavily without balancing a bar"],"steps_nl":["Ga zitten met je rug plat tegen het kussen en je voeten op schouderbreedte op het platform","Haal de veiligheidspal eraf","Laat zakken tot je knieën ongeveer 90° gebogen zijn","Duw terug zonder je knieën hard op slot te zetten"],"cues_nl":["Houd je onderrug de hele beweging tegen het kussen","Laat je knieën niet naar binnen vallen","💡 Een veilige manier om je benen zwaar te belasten zonder een stang te hoeven balanceren"]}', '{"images":["/exercise-media/leg-press/0.jpg","/exercise-media/leg-press/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"machine_stack"}', '{"substitutions":["wall-sit","sumo-squat"]}', 1, 1789302000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_m_calf_press', 'machine-calf-press', 'Calf Press (Machine)', 'Kuitpress (machine)', 'strength', '["calves"]', '[]', '["strength","legs","machine","gym","no_floor","low_impact","loads_ankle","loads_knee"]', '["leg_press"]', NULL, '{"steps":["Sit in the leg press with the balls of your feet on the bottom edge of the platform.","Press out and release the safeties.","Push through the toes to full extension, then lower into a stretch."],"cues":["Full range \u2014 deep stretch, full squeeze","Slow tempo beats heavy weight here","\ud83d\udca1 Do not let the platform drop uncontrolled"],"steps_nl":["Ga in de leg press zitten met de bal van je voeten op de onderrand van het platform","Duw het platform weg en haal de veiligheidspal eraf","Duw via je tenen tot je volledig gestrekt bent en laat dan zakken tot je rek voelt"],"cues_nl":["Volledige beweging — diep rekken, volledig aanspannen","Een rustig tempo werkt hier beter dan veel gewicht","💡 Laat het platform niet ongecontroleerd terugvallen"]}', '{"images":["/exercise-media/machine-calf-press/0.jpg","/exercise-media/machine-calf-press/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"machine_stack"}', '{"substitutions":["bent-knee-calf-raise","calf-raise"]}', 1, 1789302000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_m_hack_squat', 'machine-hack-squat', 'Hack Squat (Machine)', 'Hack squat (machine)', 'strength', '["quads", "glutes"]', '["hamstrings"]', '["strength", "legs", "machine", "gym", "no_floor", "low_impact", "loads_knee"]', '["multi_gym"]', NULL, '{"steps":["Stand on the platform with your back and shoulders against the pads.","Release the safeties and lower until your thighs reach parallel.","Drive back up through the whole foot."],"cues":["Feet slightly forward to spare the knees","Back stays flat on the pad","\ud83d\udca1 Loads the quads hard without asking your spine to stabilise it"],"steps_nl":["Ga op het platform staan met je rug en schouders tegen de kussens","Haal de veiligheidspal eraf en zak tot je bovenbenen horizontaal zijn","Duw jezelf omhoog via je hele voet"],"cues_nl":["Zet je voeten iets naar voren om je knieën te sparen","Je rug blijft plat tegen het kussen","💡 Belast je quadriceps flink zonder dat je rug het gewicht hoeft te stabiliseren"]}', '{"images":["/exercise-media/machine-hack-squat/0.jpg","/exercise-media/machine-hack-squat/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"machine_stack"}', '{"substitutions":["wall-sit","sumo-squat"]}', 1, 1789302000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_m_seated_shoulder', 'machine-shoulder-press', 'Shoulder Press (Machine)', 'Schouderpress (machine)', 'strength', '["shoulders"]', '["triceps"]', '["strength", "push", "upper_body", "machine", "gym", "no_floor", "low_impact", "beginner_friendly", "loads_shoulder"]', '["multi_gym"]', NULL, '{"steps":["Set the seat so the handles start at shoulder height.","Press overhead until your arms are almost straight.","Lower under control to the start."],"cues":["Ribs down, back against the pad","Do not lock out sharply","\ud83d\udca1 The fixed path makes this far safer than a barbell press when training alone"],"steps_nl":["Stel de stoel zo in dat de handgrepen op schouderhoogte beginnen","Druk de handgrepen omhoog tot je armen bijna gestrekt zijn","Laat gecontroleerd zakken naar de start"],"cues_nl":["Ribben omlaag, rug tegen de rugleuning","Klap je ellebogen niet hard op slot","💡 Door de vaste baan is dit veel veiliger dan een barbell press als je alleen traint"]}', '{"images":["/exercise-media/machine-shoulder-press/0.jpg","/exercise-media/machine-shoulder-press/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"machine_stack"}', '{"substitutions":["knee-push-up","wall-push-up"]}', 1, 1789302000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_m_pec_deck', 'pec-deck-fly', 'Pec Deck Fly', 'Pec deck fly', 'strength', '["chest"]', '["front_delts"]', '["strength", "push", "upper_body", "machine", "gym", "no_floor", "low_impact", "loads_shoulder"]', '["pec_deck"]', NULL, '{"steps":["Set the seat so the handles are at chest height.","Bring the handles together in front of your chest with a soft elbow bend.","Open slowly until you feel a stretch, no further."],"cues":["Do not force the stretch behind the body line","Move from the shoulder, not the elbow","\ud83d\udca1 Stop if you feel it in the front of the shoulder joint"],"steps_nl":["Stel de stoel zo in dat de handgrepen op borsthoogte zitten","Breng de handgrepen voor je borst naar elkaar toe met licht gebogen ellebogen","Open langzaam tot je rek voelt, niet verder"],"cues_nl":["Forceer de rek niet tot achter de lijn van je lichaam","Beweeg vanuit je schouder, niet vanuit je elleboog","💡 Stop als je het voelt aan de voorkant van je schoudergewricht"]}', '{"images":["/exercise-media/pec-deck-fly/0.jpg","/exercise-media/pec-deck-fly/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"machine_stack"}', '{"substitutions":["knee-push-up","wall-push-up"]}', 1, 1789302000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_bench_hip_thrust_bw', 'bench-hip-thrust-bodyweight', 'Bench Hip Thrust (Bodyweight)', 'Hip thrust op bank zonder gewicht', 'strength', '["glutes"]', '["hamstrings", "core"]', '["strength","hinge","bench","floor","low_impact","beginner_friendly","loads_lower_back"]', '["bench"]', NULL, '{"steps":["Sit on the floor with your upper back against a bench","Place your feet flat and hip-width apart, so that your shins are vertical at the top","Drive through your heels until your hips are level with your knees","Lower under control"],"cues":["Chin tucked, ribs down","Hold the top for a beat","💡 Learn the pattern here before adding a barbell"],"steps_nl":["Ga op de vloer zitten met je bovenrug tegen een bank","Zet je voeten plat op heupbreedte, zo dat je schenen bovenin verticaal staan","Duw door je hielen tot je heupen op gelijke hoogte met je knieën zijn","Zak gecontroleerd"],"cues_nl":["Kin naar je borst, ribben omlaag","Houd bovenin even vast","💡 Leer de beweging hier voordat je een barbell toevoegt"]}', NULL, '{"supports": ["reps", "sets", "time"]}', '{"substitutions":["glute-bridge","good-morning-bodyweight"]}', 1, 1789303000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_bench_step_up', 'bench-step-up', 'Bench Step-Up', 'Opstap op bank', 'strength', '["quads", "glutes"]', '["hamstrings", "calves"]', '["strength","legs","bench","no_floor","unilateral","loads_knee","loads_ankle"]', '["bench"]', NULL, '{"steps":["Stand facing a flat bench.","Step one foot fully onto it and drive up to standing.","Step down under control with the same leg leading.","Complete the reps, then change sides."],"cues":["Drive through the heel of the top foot","Do not push off the bottom foot","\ud83d\udca1 Lower the step if your knee travels far past your toes"],"steps_nl":["Ga met je gezicht naar een vlakke bank staan","Zet één voet helemaal op de bank en duw jezelf omhoog tot je rechtop staat","Stap gecontroleerd weer af, met hetzelfde been eerst","Maak je herhalingen af en wissel dan van kant"],"cues_nl":["Duw door de hiel van je bovenste voet","Zet niet af met je onderste voet","💡 Kies een lagere opstap als je knie ver voorbij je tenen komt"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"bodyweight_plus"}', '{"substitutions":["step-up","walking-lunges"]}', 1, 1789303000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_jr_basic', 'jump-rope-basic', 'Jump Rope — Steady', 'Touwspringen constant', 'cardio', '["calves", "conditioning"]', '["shoulders", "core"]', '["cardio","conditioning","jump_rope","high_impact","no_floor","loads_ankle","loads_knee","loads_shoulder"]', '["jump_rope"]', NULL, '{"steps":["Hold the rope handles at hip height with your elbows close to your sides","Turn the rope from your wrists, not your shoulders","Jump with small bounces, just high enough to clear the rope","Keep a steady rhythm"],"cues":["Land softly through the balls of the feet","Stay tall — do not pike at the hips","💡 Stop if your calves start cramping rather than pushing on"],"steps_nl":["Houd de handvatten van het touw op heuphoogte, met je ellebogen dicht langs je lichaam","Draai het touw vanuit je polsen, niet vanuit je schouders","Maak kleine sprongetjes, net hoog genoeg om over het touw te komen","Houd een constant ritme aan"],"cues_nl":["Land zacht op je voorvoeten","Blijf rechtop — knik niet in je heupen","💡 Stop als je kuiten gaan verkrampen in plaats van door te zetten"]}', '{"images":["/exercise-media/jump-rope-basic/0.jpg","/exercise-media/jump-rope-basic/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["time", "sets"], "base_duration_sec": 30}', '{"substitutions":["jumping-jack","jump-rope-simulation"]}', 1, 1789303000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_jr_intervals', 'jump-rope-intervals', 'Jump Rope — Intervals', 'Touwspringen intervallen', 'cardio', '["conditioning", "calves"]', '["shoulders"]', '["cardio","conditioning","hiit","jump_rope","high_impact","no_floor","loads_ankle","loads_knee","loads_shoulder"]', '["jump_rope"]', NULL, '{"steps":["Skip hard for the work interval.","Rest or step in place for the recovery.","Repeat for the prescribed rounds."],"cues":["Pace the first round \u2014 it always feels easy","Trips are normal; pick the rope straight back up","\ud83d\udca1 High impact: swap for march-in-place if your knees complain"],"steps_nl":["Spring hard touw tijdens het werkinterval","Rust of stap op de plaats tijdens het herstel","Herhaal voor het opgegeven aantal rondes"],"cues_nl":["Doseer de eerste ronde — die voelt altijd makkelijk","Struikelen hoort erbij; pak het touw meteen weer op","💡 Hoge impact: wissel naar marcheren op de plaats als je knieën protesteren"]}', '{"images":["/exercise-media/jump-rope-intervals/0.jpg","/exercise-media/jump-rope-intervals/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["time", "sets"], "base_duration_sec": 30}', '{"substitutions":["jump-rope-basic","jumping-jack"]}', 1, 1789303000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_mat_hip_bridge_march', 'mat-hip-bridge-march', 'Hip Bridge March', 'Heupbrug met marsbeweging', 'strength', '["glutes", "core"]', '["hamstrings"]', '["strength","hinge","yoga_mat","floor","low_impact","beginner_friendly","unilateral","loads_lower_back"]', '["yoga_mat"]', NULL, '{"steps":["Lie on your back on the mat with your knees bent and your feet flat","Lift your hips into a bridge and hold them there","Without dropping your hips, lift one knee towards your chest","Put the foot back down and repeat with the other leg, alternating sides"],"cues":["The hips must not tilt when the foot leaves the floor","Slow and even","💡 Exposes a weak side quickly — expect one to feel harder"],"steps_nl":["Ga op je rug op de mat liggen met je knieën gebogen en je voeten plat","Til je heupen op tot een brug en houd ze daar","Til één knie richting je borst zonder je heupen te laten zakken","Zet je voet terug en herhaal met je andere been, om en om"],"cues_nl":["Je heupen mogen niet kantelen als je voet van de vloer komt","Langzaam en gelijkmatig","💡 Laat snel zien welke kant zwakker is — reken erop dat één kant zwaarder voelt"]}', NULL, '{"supports": ["reps", "sets"]}', '{"substitutions":["glute-bridge","bench-hip-thrust-bodyweight"]}', 1, 1789303000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_mat_prone_swimmer', 'mat-prone-swimmer', 'Prone Swimmer', 'Zwemmer op de buik', 'strength', '["lower_back", "rear_delts"]', '["glutes", "upper_back"]', '["mobility","strength","yoga_mat","floor","low_impact","shoulder_health","loads_shoulder","loads_lower_back"]', '["yoga_mat"]', NULL, '{"steps":["Lie face down on the mat, arms overhead.","Lift your chest and arms slightly.","Sweep the arms back towards your hips and return, as if swimming backstroke.","Stay lifted throughout."],"cues":["Small lift \u2014 this is not a big back extension","Keep the neck long, eyes down","\ud83d\udca1 Counteracts hours of sitting forward"],"steps_nl":["Ga op je buik op de mat liggen met je armen gestrekt boven je hoofd","Til je borst en armen een klein stukje op","Veeg je armen naar achteren richting je heupen en weer terug, alsof je rugslag zwemt","Blijf de hele tijd opgetild"],"cues_nl":["Kleine lift — dit is geen grote rugstrekking","Houd je nek lang, kijk naar de vloer","💡 Compenseert urenlang voorovergebogen zitten"]}', NULL, '{"supports": ["reps", "sets"]}', '{"substitutions":["good-morning-bodyweight","sphinx-hold"]}', 1, 1789303000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_mat_supine_twist', 'mat-supine-spinal-twist', 'Supine Spinal Twist', 'Rugdraai liggend', 'mobility', '["lower_back", "obliques"]', '["glutes"]', '["mobility","stretch","yoga_mat","floor","low_impact","recovery","loads_lower_back"]', '["yoga_mat"]', NULL, '{"steps":["Lie on your back on the mat, arms out in a T.","Draw one knee to your chest, then let it fall across your body.","Turn your head the other way and breathe.","Hold, then change sides."],"cues":["Both shoulders stay on the mat","Do not force the knee down","\ud83d\udca1 Good last thing at night"],"steps_nl":["Lig op je rug op de mat met je armen wijd in een T","Trek één knie naar je borst en laat hem dan over je lichaam heen zakken","Draai je hoofd de andere kant op en adem rustig","Houd vast en wissel dan van kant"],"cues_nl":["Beide schouders blijven op de mat","Duw je knie niet omlaag","💡 Fijn als laatste oefening voor het slapengaan"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["seated-spinal-twist","seated-straddle-stretch"]}', 1, 1789303000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_sb_deadbug', 'stability-ball-dead-bug', 'Stability Ball Dead Bug', 'Dead bug met fitnessbal', 'strength', '["core", "abs"]', '["hip_flexors"]', '["strength", "core", "stability_ball", "floor", "low_impact", "beginner_friendly"]', '["stability_ball"]', NULL, '{"steps":["Lie on your back holding the ball between your hands and knees.","Press into the ball to create tension.","Extend the opposite arm and leg away, keeping the ball pinned.","Return and alternate."],"cues":["Lower back stays flat on the floor","Move slowly \u2014 the tension is the point","\ud83d\udca1 Stop extending where your back would start to arch"],"steps_nl":["Ga op je rug liggen en klem de bal tussen je handen en knieën","Druk tegen de bal om spanning op te bouwen","Strek je tegenovergestelde arm en been uit en houd de bal op zijn plek geklemd","Kom terug en wissel van kant"],"cues_nl":["Je onderrug blijft plat op de vloer","Beweeg langzaam — het gaat om de spanning","💡 Strek niet verder dan het punt waar je rug hol zou gaan trekken"]}', NULL, '{"supports": ["reps", "sets"]}', '{"substitutions":["dead-bug","band-dead-bug"]}', 1, 1789303000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_sb_hamstring_curl', 'stability-ball-hamstring-curl', 'Stability Ball Hamstring Curl', 'Hamstring curl met fitnessbal', 'strength', '["hamstrings", "glutes"]', '["core"]', '["strength","hinge","stability_ball","floor","low_impact","loads_knee","loads_lower_back"]', '["stability_ball"]', NULL, '{"steps":["Lie on your back, heels on the ball, arms flat on the floor.","Lift your hips into a bridge.","Pull the ball towards you by bending the knees.","Push it back out slowly, keeping the hips up."],"cues":["Hips stay lifted the whole set","Slow on the way out","\ud83d\udca1 One of the best hamstring exercises needing no weight at all"],"steps_nl":["Ga op je rug liggen met je hielen op de bal en je armen plat op de vloer","Til je heupen op tot een brug","Trek de bal naar je toe door je knieën te buigen","Duw hem langzaam terug en houd je heupen omhoog"],"cues_nl":["Je heupen blijven de hele set omhoog","Langzaam op de weg terug","💡 Een van de beste hamstringoefeningen waarvoor je geen gewicht nodig hebt"]}', '{"images":["/exercise-media/stability-ball-hamstring-curl/0.jpg","/exercise-media/stability-ball-hamstring-curl/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["reps", "sets"]}', '{"substitutions":["glute-bridge","good-morning-bodyweight"]}', 1, 1789303000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_sb_plank', 'stability-ball-plank', 'Stability Ball Plank', 'Plank op fitnessbal', 'strength', '["core", "abs"]', '["shoulders"]', '["strength","core","stability_ball","floor","low_impact","isometric","loads_shoulder"]', '["stability_ball"]', NULL, '{"steps":["Place your forearms on the ball, feet back, body in a straight line.","Brace and hold, resisting the ball''s wobble.","Keep breathing."],"cues":["Squeeze the glutes so the hips do not sag","Small circles with the forearms make it harder","\ud83d\udca1 Far more demanding than a floor plank \u2014 start with less time"],"steps_nl":["Zet je onderarmen op de bal, voeten naar achteren, lichaam in een rechte lijn","Span aan en houd vast, en vang het wiebelen van de bal op","Blijf doorademen"],"cues_nl":["Span je bilspieren aan zodat je heupen niet doorzakken","Kleine cirkels met je onderarmen maken het zwaarder","💡 Veel zwaarder dan een plank op de vloer — begin met minder tijd"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["stability-ball-dead-bug","modified-plank"]}', 1, 1789303000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_trail_hike_steady', 'trail-hike-steady', 'Trail Hike — Steady', 'Wandelen trail (constant tempo)', 'cardio', '["legs", "conditioning"]', '["glutes", "calves"]', '["cardio","conditioning","outdoor","trail_shoes","low_impact","zone2","loads_ankle","loads_knee"]', '["trail_shoes"]', NULL, '{"steps":["Head out on uneven ground at a pace you could hold a conversation at.","Shorten your stride on the climbs.","Take the descents slowly \u2014 that is where ankles turn."],"cues":["Watch your footing rather than the view when moving","Poles help on longer descents","\ud83d\udca1 Zone 2 work that does not feel like training"],"steps_nl":["Ga op pad over oneffen terrein in een tempo waarbij je een gesprek kunt voeren","Maak je passen korter op de klimmen","Daal rustig af — daar verzwik je je enkels"],"cues_nl":["Kijk tijdens het lopen waar je je voeten zet, niet naar het uitzicht","Stokken helpen bij langere afdalingen","💡 Zone 2-werk dat niet als training voelt"]}', NULL, '{"supports": ["time", "distance"], "base_duration_sec": 60}', '{"substitutions":["heel-dig-march","march-in-place"]}', 1, 1789303000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_trail_hill_repeats', 'trail-hill-repeats', 'Trail Hill Repeats', 'Hardlopen trail heuvelherhalingen', 'cardio', '["legs", "conditioning"]', '["glutes", "calves"]', '["cardio", "conditioning", "hiit", "outdoor", "trail_shoes", "high_impact", "loads_knee", "loads_ankle"]', '["trail_shoes"]', NULL, '{"steps":["Find a hill that takes 60\u201390 seconds to climb at effort.","Work hard to the top.","Walk down to recover fully.","Repeat for the prescribed rounds."],"cues":["Short strides, quick feet on the climb","Walk \u2014 do not run \u2014 the descent","\ud83d\udca1 Builds running strength with far less impact than flat speed work"],"steps_nl":["Zoek een heuvel waar je op inspanning 60–90 seconden over doet om boven te komen","Werk hard tot aan de top","Wandel naar beneden en herstel volledig","Herhaal dit voor het opgegeven aantal rondes"],"cues_nl":["Korte passen en snelle voeten op de klim","Wandel de afdaling — niet rennen","💡 Bouwt loopkracht op met veel minder impact dan snelheidswerk op vlak terrein"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 30}', '{"substitutions":["trail-hike-steady","heel-dig-march"]}', 1, 1789303000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_core_deadbug_band', 'band-dead-bug', 'Band Dead Bug', 'Dead bug met weerstandsband', 'strength', '["core", "abs"]', '["hip_flexors"]', '["strength", "core", "anti_extension", "resistance_bands", "floor", "low_impact"]', '["resistance_bands"]', NULL, '{"steps":["Anchor a band low behind your head. Lie on your back holding it with straight arms over your chest","Bring your knees over your hips with your shins parallel to the floor","Extend one leg away while holding the band steady","Bring the leg back and alternate sides"],"cues":["The band pulls your arms back — resist it","Lower back stays flat on the floor","💡 Adds load to a movement that gets easy fast"],"steps_nl":["Maak een band laag achter je hoofd vast. Ga op je rug liggen en houd hem met gestrekte armen boven je borst","Breng je knieën boven je heupen met je schenen evenwijdig aan de vloer","Strek één been van je af terwijl je de band stilhoudt","Breng je been terug en wissel van kant"],"cues_nl":["De band trekt je armen naar achteren — bied weerstand","Je onderrug blijft plat op de vloer","💡 Maakt een beweging zwaarder die snel te makkelijk wordt"]}', NULL, '{"supports": ["reps", "sets"]}', '{"substitutions":["dead-bug","stability-ball-dead-bug"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_core_pallof_band', 'band-pallof-press', 'Band Pallof Press', 'Pallof press met weerstandsband', 'strength', '["core", "obliques"]', '["shoulders"]', '["strength","core","anti_rotation","resistance_bands","no_floor","low_impact","quiet","loads_shoulder"]', '["resistance_bands"]', NULL, '{"steps":["Anchor a band at chest height. Stand side-on, both hands on the band at your sternum.","Step out until the band is taut.","Press your hands straight out in front of you and hold — the band will try to rotate you.","Return to the chest. Complete the reps, then change sides."],"cues":["Do not let your torso twist — that is the whole exercise","Squeeze the glutes to stop the hips rotating","💡 Resisting the pull trains your core to stay steady when a force tries to turn you"],"steps_nl":["Maak een band vast op borsthoogte. Ga er zijwaarts naast staan met beide handen aan de band bij je borstbeen","Stap opzij tot de band strak staat","Druk je handen recht voor je uit en houd vast — de band probeert je te draaien","Breng je handen terug naar je borst. Doe alle herhalingen en wissel dan van kant"],"cues_nl":["Laat je romp niet draaien — dat is de hele oefening","Span je bilspieren aan zodat je heupen niet meedraaien","💡 Weerstand bieden tegen de trek leert je core stabiel te blijven als een kracht je wil laten draaien"]}', NULL, '{"supports": ["reps", "sets", "time"]}', '{"substitutions":["modified-plank","side-plank"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_core_wood_chop_band', 'band-wood-chop', 'Band Wood Chop', 'Wood chop met weerstandsband', 'strength', '["obliques", "core"]', '["shoulders"]', '["strength","core","rotation","resistance_bands","no_floor","low_impact","loads_shoulder","loads_lower_back"]', '["resistance_bands"]', NULL, '{"steps":["Anchor a band high. Stand side-on, both hands on the end.","Pull diagonally across your body to the opposite hip, pivoting the back foot.","Return under control. Change sides."],"cues":["Rotate through the ribs, not just the arms","Keep the arms fairly straight","\ud83d\udca1 Pairs with the Pallof press: one trains rotation, the other resists it"],"steps_nl":["Maak een band hoog vast. Ga zijwaarts staan met beide handen aan het uiteinde","Trek de band schuin voor je lichaam langs naar je andere heup en draai mee op je achterste voet","Ga gecontroleerd terug. Wissel van kant"],"cues_nl":["Draai vanuit je ribbenkast, niet alleen met je armen","Houd je armen vrijwel gestrekt","💡 Past goed bij de Pallof press: de ene traint rotatie, de andere weerstaat die"]}', NULL, '{"supports": ["reps", "sets"]}', '{"substitutions":["modified-plank","side-plank"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_core_bear_hold', 'bear-crawl-hold', 'Bear Crawl Hold', 'Berenkruip houden', 'strength', '["core", "abs"]', '["shoulders", "quads"]', '["strength","core","anti_extension","bodyweight","floor","low_impact","isometric","beginner_friendly","loads_shoulder","loads_knee"]', '["none"]', NULL, '{"steps":["Start on hands and knees with your toes tucked, then lift your knees an inch off the floor","Hold the position with a flat back","Breathe steadily throughout the hold, then lower your knees to finish"],"cues":["Back stays flat enough to balance a glass on","Knees hover — do not rest them down","💡 A gentler entry to core work than a full plank"],"steps_nl":["Begin op handen en knieën met je tenen op de vloer gezet en til je knieën een paar centimeter van de vloer","Houd deze houding vast met een vlakke rug","Adem rustig door zolang je vasthoudt en zet daarna je knieën weer neer"],"cues_nl":["Je rug blijft zo vlak dat er een glas op kan staan","Je knieën zweven — laat ze niet rusten","💡 Een rustigere instap in coretraining dan een volledige plank"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["modified-plank","donkey-kick"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_calf_bent_knee_bw', 'bent-knee-calf-raise', 'Bent-Knee Calf Raise', 'Kuitheffen met gebogen knie', 'strength', '["calves"]', '[]', '["strength", "legs", "calf", "soleus", "bodyweight", "no_floor", "low_impact", "quiet", "loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with knees bent about 20\u00b0, feet hip-width.","Keeping the knees bent, rise onto the balls of your feet.","Lower slowly."],"cues":["Do not straighten the knees \u2014 that turns it back into a standard raise","Hold a wall for balance","\ud83d\udca1 No equipment needed to train the soleus"],"steps_nl":["Sta met je knieën ongeveer 20° gebogen, voeten op heupbreedte","Houd je knieën gebogen en kom omhoog op de bal van je voeten","Zak langzaam"],"cues_nl":["Strek je knieën niet — dan wordt het weer gewoon kuitheffen","Houd een muur vast voor balans","💡 Zo train je je soleus zonder materiaal"]}', NULL, '{"supports": ["reps", "sets", "time"]}', '{"substitutions":["calf-raise","toe-walk","heel-walk"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_core_pallof_cable', 'cable-pallof-press', 'Cable Pallof Press', 'Kabel Pallof press', 'strength', '["core", "obliques"]', '["shoulders"]', '["strength","core","anti_rotation","machine","gym","no_floor","low_impact","loads_shoulder"]', '["cable"]', NULL, '{"steps":["Set a cable to chest height and stand side-on, both hands on the handle at your sternum.","Step away until there is tension.","Press straight out and hold.","Return under control, then change sides."],"cues":["Resist the pull \u2014 do not rotate","Heavier is not better here; control is","\ud83d\udca1 Add a pause at full extension to make it much harder"],"steps_nl":["Zet een kabel op borsthoogte en ga er zijwaarts naast staan, beide handen aan het handvat tegen je borstbeen","Stap opzij tot er spanning op de kabel staat","Druk je handen recht naar voren en houd vast","Ga gecontroleerd terug en wissel daarna van kant"],"cues_nl":["Weersta de trekkracht — niet meedraaien","Zwaarder is hier niet beter; controle wel","💡 Pauzeer met gestrekte armen om het een stuk zwaarder te maken"]}', '{"images":["/exercise-media/cable-pallof-press/0.jpg","/exercise-media/cable-pallof-press/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","time"],"load_type":"machine_stack"}', '{"substitutions":["modified-plank","side-plank"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_core_copenhagen', 'copenhagen-plank', 'Copenhagen Plank', 'Copenhagen plank', 'strength', '["adductors", "obliques", "core"]', '["glutes"]', '["strength","core","anti_lateral_flexion","bodyweight","floor","low_impact","groin_health","loads_shoulder","loads_knee"]', '["none"]', NULL, '{"steps":["Lie on your side with your top foot resting on a chair or bench.","Prop up on your forearm and lift your hips so your body is straight.","Hold, keeping the bottom leg off the floor if you can.","Change sides."],"cues":["Start with the bottom knee down \u2014 it is much easier","Stop the moment the hips drop","\ud83d\udca1 The best-evidenced groin-injury preventer there is"],"steps_nl":["Ga op je zij liggen met je bovenste voet op een stoel of bank","Steun op je onderarm en til je heupen op tot je lichaam een rechte lijn vormt","Houd vast en houd je onderste been van de vloer als dat lukt","Wissel van kant"],"cues_nl":["Begin met je onderste knie op de vloer — dat is veel makkelijker","Stop zodra je heupen zakken","💡 De best onderbouwde oefening om liesblessures te voorkomen"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["modified-plank","side-plank"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_calf_db_raise', 'dumbbell-calf-raise', 'Dumbbell Calf Raise', 'Dumbbell kuitheffen', 'strength', '["calves"]', '[]', '["strength", "legs", "calf", "dumbbell", "no_floor", "low_impact", "loads_ankle"]', '["dumbbell"]', NULL, '{"steps":["Hold a dumbbell in each hand, standing on a step if you have one.","Rise onto the toes as high as you can.","Lower slowly into a stretch."],"cues":["Full range beats heavy weight","Pause at the top","\ud83d\udca1 The simplest way to progress calf raises once bodyweight is easy"],"steps_nl":["Houd in elke hand een dumbbell en ga op een opstapje staan als je er een hebt","Kom zo hoog mogelijk omhoog op je tenen","Zak langzaam tot je rek voelt"],"cues_nl":["Een volledige beweging is belangrijker dan zwaar gewicht","Houd bovenin even vast","💡 De eenvoudigste manier om kuitheffen zwaarder te maken zodra het met lichaamsgewicht makkelijk gaat"]}', '{"images":["/exercise-media/dumbbell-calf-raise/0.jpg","/exercise-media/dumbbell-calf-raise/1.jpg"],"source":"free-exercise-db"}', '{"supports":["weight","reps","sets","tempo"],"load_type":"dumbbell_pair"}', '{"substitutions":["bent-knee-calf-raise","calf-raise"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_calf_eccentric', 'eccentric-calf-raise-step', 'Eccentric Calf Raise (Step)', 'Kuitheffen excentrisch (trede)', 'strength', '["calves"]', '["achilles"]', '["strength", "legs", "calf", "eccentric", "bodyweight", "no_floor", "low_impact", "loads_ankle", "rehab"]', '["none"]', NULL, '{"steps":["Stand with the balls of both feet on a step, heels hanging off.","Rise onto both toes.","Shift your weight to one leg and lower that heel slowly below the step over 3-5 seconds.","Use both legs to rise again."],"cues":["Up with two, down with one","The slow lowering is the whole exercise","\ud83d\udca1 The best-evidenced protocol for Achilles tendon resilience"],"steps_nl":["Sta met de bal van beide voeten op een trede en laat je hielen over de rand hangen","Kom op beide voeten omhoog op je tenen","Breng je gewicht naar één been en laat die hiel in 3–5 seconden langzaam tot onder de trede zakken","Gebruik beide benen om weer omhoog te komen"],"cues_nl":["Met twee omhoog, met één omlaag","Het langzame zakken is de hele oefening","💡 Het best onderbouwde protocol voor een belastbare achillespees"]}', NULL, '{"supports": ["reps", "sets", "tempo"]}', '{"substitutions":["bent-knee-calf-raise","calf-raise"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_core_hanging_knee', 'hanging-knee-raise', 'Hanging Knee Raise', 'Hangend knieheffen', 'strength', '["abs", "core"]', '["hip_flexors", "forearms"]', '["strength", "core", "flexion", "pull_up_bar", "no_floor", "low_impact", "loads_shoulder"]', '["pull_up_bar"]', NULL, '{"steps":["Hang from a bar with straight arms, shoulders active.","Curl your knees up towards your chest.","Lower slowly without swinging."],"cues":["Tuck the pelvis at the top \u2014 do not just lift the legs","If you swing, pause between reps","\ud83d\udca1 The step below a hanging leg raise"],"steps_nl":["Hang met gestrekte armen aan een stang, schouders actief","Trek je knieën op richting je borst","Laat langzaam zakken zonder te zwaaien"],"cues_nl":["Kantel bovenin je bekken — til niet alleen je benen op","Ga je zwaaien, pauzeer dan tussen de herhalingen","💡 De stap vóór hangend beenheffen"]}', '{"images":["/exercise-media/hanging-knee-raise/0.jpg","/exercise-media/hanging-knee-raise/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["reps", "sets"]}', '{"substitutions":["modified-plank","dead-bug"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_calf_heel_walk', 'heel-walk', 'Heel Walk', 'Lopen op de hakken', 'strength', '["tibialis", "shins"]', '[]', '["strength", "legs", "shin", "bodyweight", "no_floor", "low_impact", "quiet", "rehab", "loads_ankle"]', '["none"]', NULL, '{"steps":["Lift your toes so you are standing on your heels.","Walk forward keeping the toes off the floor.","Continue for the prescribed time."],"cues":["Toes stay up throughout","Short bouts \u2014 this fatigues fast","\ud83d\udca1 Pairs with the tibialis raise for shin resilience"],"steps_nl":["Til je tenen op zodat je op je hakken staat","Loop vooruit en houd je tenen van de vloer","Ga door voor de opgegeven tijd"],"cues_nl":["Je tenen blijven de hele tijd omhoog","Korte stukken — dit vermoeit snel","💡 Past goed bij de tibialis raise voor sterke schenen"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["toe-walk","bent-knee-calf-raise"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_kb_clean', 'kettlebell-clean', 'Kettlebell Clean', 'Kettlebell clean', 'strength', '["glutes", "hamstrings"]', '["shoulders", "core", "forearms"]', '["strength","kettlebell","hinge","power","no_floor","loads_lower_back","loads_shoulder"]', '["kettlebell"]', NULL, '{"steps":["Start with the bell between your feet, hinge and grip it.","Hike it back, then drive the hips to bring it up the body.","Guide it around the wrist into the front rack rather than letting it flip over.","Lower back into the hinge."],"cues":["Keep the bell close \u2014 it should not swing away from you","A banged wrist means you let it travel too far","\ud83d\udca1 Learn the swing first; the clean is a swing that finishes in the rack"],"steps_nl":["Begin met de kettlebell tussen je voeten, scharnier vanuit je heupen en pak hem vast","Zwaai hem naar achteren en duw dan je heupen naar voren om hem langs je lichaam omhoog te brengen","Leid hem om je pols heen naar de rackpositie in plaats van hem te laten omklappen","Laat hem terugzakken in het heupscharnier"],"cues_nl":["Houd de kettlebell dicht bij je — hij mag niet van je af zwaaien","Een klap op je pols betekent dat je hem te ver liet doorgaan","💡 Leer eerst de swing; de clean is een swing die eindigt in de rackpositie"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_single"}', '{"substitutions":["glute-bridge","good-morning-bodyweight"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_kb_clean_press', 'kettlebell-clean-and-press', 'Kettlebell Clean & Press', 'Kettlebell clean & press', 'strength', '["shoulders", "glutes"]', '["core", "triceps", "hamstrings"]', '["strength", "kettlebell", "full_body", "no_floor", "loads_shoulder", "loads_lower_back"]', '["kettlebell"]', NULL, '{"steps":["Clean the bell to the front rack.","Brace, then press it overhead.","Lower to the rack, then back to the hinge."],"cues":["Full breath before each press","Do not lean back to finish the press","\ud83d\udca1 A complete strength session in one movement when time is short"],"steps_nl":["Breng de kettlebell met een clean naar de rackpositie","Span je core aan en druk hem boven je hoofd","Laat zakken naar de rackpositie en daarna terug in het heupscharnier"],"cues_nl":["Adem volledig in voor elke press","Leun niet achterover om de press af te maken","💡 Een complete krachttraining in één beweging als je weinig tijd hebt"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_single"}', '{"substitutions":["knee-push-up","modified-plank"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_kb_carry', 'kettlebell-farmers-carry', 'Kettlebell Farmer''s Carry', 'Kettlebell farmer''s carry', 'strength', '["forearms", "traps", "core"]', '["glutes"]', '["strength","kettlebell","carry","no_floor","low_impact","grip","loads_shoulder","loads_lower_back"]', '["kettlebell"]', NULL, '{"steps":["Hold a bell in each hand at your sides.","Stand tall and walk for the prescribed time.","Set them down under control."],"cues":["Shoulders back and down","Breathe normally \u2014 do not hold your breath","\ud83d\udca1 Grip usually fails first; that is the adaptation"],"steps_nl":["Houd in elke hand een kettlebell langs je lichaam","Sta rechtop en loop voor de opgegeven tijd","Zet ze gecontroleerd neer"],"cues_nl":["Schouders naar achteren en omlaag","Adem gewoon door — houd je adem niet in","💡 Je grip geeft het meestal als eerste op; dat is precies de trainingsprikkel"]}', NULL, '{"supports": ["weight", "time", "sets"], "load_type": "dumbbell_single", "base_duration_sec": 40}', '{"substitutions":["modified-plank","donkey-kick"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_kb_front_squat', 'kettlebell-front-rack-squat', 'Kettlebell Front Rack Squat', 'Kettlebell front rack squat', 'strength', '["quads", "glutes"]', '["core", "upper_back"]', '["strength", "kettlebell", "legs", "no_floor", "loads_knee"]', '["kettlebell"]', NULL, '{"steps":["Clean one or two bells into the front rack.","Squat down with an upright torso until your thighs reach parallel.","Drive up through the whole foot."],"cues":["Elbows stay in, bells resting on the forearms","Chest tall \u2014 the rack position will try to fold you forward","\ud83d\udca1 The rack position makes your core work far harder than a goblet squat"],"steps_nl":["Breng één of twee kettlebells met een clean naar de rackpositie","Zak met een rechte romp in de squat tot je bovenbenen horizontaal zijn","Duw jezelf omhoog via je hele voet"],"cues_nl":["Je ellebogen blijven binnen, de kettlebells rusten op je onderarmen","Borst omhoog — de rackpositie wil je naar voren laten klappen","💡 Door de rackpositie werkt je core veel harder dan bij een goblet squat"]}', '{"images":["/exercise-media/kettlebell-front-rack-squat/0.jpg","/exercise-media/kettlebell-front-rack-squat/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","tempo","weight"],"load_type":"dumbbell_single"}', '{"substitutions":["wall-sit","kettlebell-goblet-squat"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_kb_high_pull', 'kettlebell-high-pull', 'Kettlebell High Pull', 'Kettlebell high pull', 'strength', '["upper_back", "shoulders"]', '["glutes", "hamstrings", "traps"]', '["strength", "kettlebell", "pull", "power", "no_floor", "loads_shoulder", "loads_lower_back"]', '["kettlebell"]', NULL, '{"steps":["Set up as for a swing, bell hiked back.","Drive the hips and pull the elbow high and wide as the bell rises.","Let it fall back into the hinge."],"cues":["Elbow leads, above the wrist","The hips do the work; the arm only steers","\ud83d\udca1 The bridge between a swing and a snatch"],"steps_nl":["Sta klaar zoals bij een swing, met de kettlebell naar achteren gezwaaid","Duw je heupen naar voren en trek je elleboog hoog en wijd terwijl de kettlebell omhoogkomt","Laat hem terugvallen in het heupscharnier"],"cues_nl":["Je elleboog leidt en blijft boven je pols","Je heupen doen het werk; je arm stuurt alleen","💡 De brug tussen een swing en een snatch"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_single"}', '{"substitutions":["doorway-isometric-row","inverted-row-feet-elevated"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_kb_row', 'kettlebell-row', 'Kettlebell Row', 'Kettlebell row', 'strength', '["lats", "upper_back"]', '["biceps", "core"]', '["strength","kettlebell","pull","upper_body","no_floor","low_impact","loads_lower_back","loads_shoulder"]', '["kettlebell"]', NULL, '{"steps":["Hold the kettlebell in one hand, hinge forward with a flat back and rest your free hand on your thigh","Let the bell hang straight down, then row it to your ribs","Lower under control","Change sides after your reps"],"cues":["Do not rotate the torso to lift it higher","Elbow brushes past your side","💡 Pull your elbow towards your hip, not straight up, so your back does the work and not your arm"],"steps_nl":["Houd de kettlebell in één hand, scharnier met een vlakke rug naar voren en steun met je vrije hand op je bovenbeen","Laat de kettlebell recht naar beneden hangen en trek hem dan naar je ribben","Laat gecontroleerd zakken","Wissel na je herhalingen van kant"],"cues_nl":["Draai je romp niet mee om hem hoger te krijgen","Je elleboog strijkt langs je zij","💡 Trek je elleboog naar je heup, niet recht omhoog, zodat je rug het werk doet en niet je arm"]}', '{"images":["/exercise-media/kettlebell-row/0.jpg","/exercise-media/kettlebell-row/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","tempo","weight"],"load_type":"dumbbell_single"}', '{"substitutions":["doorway-isometric-row","inverted-row-feet-elevated"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_kb_snatch', 'kettlebell-snatch', 'Kettlebell Snatch', 'Kettlebell snatch', 'strength', '["shoulders", "glutes", "hamstrings"]', '["core", "forearms"]', '["strength", "kettlebell", "power", "hinge", "no_floor", "loads_shoulder", "loads_lower_back"]', '["kettlebell"]', NULL, '{"steps":["Hike the bell back between your legs.","Drive the hips hard and pull the bell up close to the body.","Punch your hand through at the top so the bell settles rather than flips.","Lower under control back into the hinge."],"cues":["Power comes from the hips, not the arm","Build up slowly \u2014 this is hard on the shoulder if rushed","\ud83d\udca1 Learn the clean and the high pull first"],"steps_nl":["Zwaai de kettlebell naar achteren tussen je benen","Duw je heupen krachtig naar voren en trek de kettlebell dicht langs je lichaam omhoog","Stoot je hand bovenin door, zodat de kettlebell rustig landt en niet omklapt","Laat gecontroleerd terugzakken in het heupscharnier"],"cues_nl":["De kracht komt uit je heupen, niet uit je arm","Bouw rustig op — te snel is dit zwaar voor je schouder","💡 Leer eerst de clean en de high pull"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_single"}', '{"substitutions":["glute-bridge","good-morning-bodyweight"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_kb_press', 'kettlebell-strict-press', 'Kettlebell Strict Press', 'Kettlebell strict press', 'strength', '["shoulders"]', '["triceps", "core"]', '["strength", "kettlebell", "push", "upper_body", "no_floor", "loads_shoulder"]', '["kettlebell"]', NULL, '{"steps":["Hold a bell in the front rack, elbow tucked.","Press overhead without leaning back.","Lower under control to the rack."],"cues":["Squeeze the glutes to stop the lower back arching","The bell finishes over the middle of your foot","\ud83d\udca1 The offset weight makes this harder than a dumbbell press"],"steps_nl":["Houd een kettlebell in de rackpositie, elleboog tegen je lichaam","Druk hem boven je hoofd zonder achterover te leunen","Laat gecontroleerd zakken naar de rackpositie"],"cues_nl":["Span je bilspieren aan zodat je onderrug niet hol trekt","De kettlebell eindigt boven het midden van je voet","💡 Doordat het gewicht buiten het midden hangt, is dit zwaarder dan een dumbbell press"]}', NULL, '{"supports":["reps","sets","tempo","weight"],"load_type":"dumbbell_single"}', '{"substitutions":["knee-push-up","wall-push-up"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_kb_tgu', 'kettlebell-turkish-get-up', 'Kettlebell Turkish Get-Up', 'Kettlebell Turkish get-up', 'strength', '["shoulders", "core"]', '["glutes", "quads", "obliques"]', '["strength","kettlebell","full_body","floor","low_impact","skill","loads_shoulder","loads_knee"]', '["kettlebell"]', NULL, '{"steps":["Lie on your back, one kettlebell pressed straight up, same-side knee bent.","Roll to your elbow, then your hand.","Bridge the hips, sweep the straight leg back to a lunge, and stand.","Reverse every step to return."],"cues":["The bell stays locked overhead and your eyes on it the whole time","Learn it with no weight first, then a shoe, then a bell","\ud83d\udca1 Slow and deliberate \u2014 this is a skill, not a conditioning drill"],"steps_nl":["Ga op je rug liggen met één kettlebell recht omhoog gedrukt en de knie aan dezelfde kant gebogen","Rol naar je elleboog en dan naar je hand","Til je heupen op, zwaai je gestrekte been naar achteren tot een uitvalspas en ga staan","Doe elke stap in omgekeerde volgorde om terug te komen"],"cues_nl":["De kettlebell blijft gestrekt boven je en je blijft er de hele tijd naar kijken","Leer het eerst zonder gewicht, dan met een schoen, dan met een kettlebell","💡 Langzaam en bewust — dit is een vaardigheid, geen conditieoefening"]}', '{"images":["/exercise-media/kettlebell-turkish-get-up/0.jpg","/exercise-media/kettlebell-turkish-get-up/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_single"}', '{"substitutions":["modified-plank","knee-push-up"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_kb_windmill', 'kettlebell-windmill', 'Kettlebell Windmill', 'Kettlebell windmill', 'strength', '["obliques", "shoulders"]', '["hamstrings", "core"]', '["strength", "kettlebell", "core", "mobility", "no_floor", "low_impact", "loads_shoulder"]', '["kettlebell"]', NULL, '{"steps":["Press a bell overhead and turn your feet away from that side.","Keeping the arm locked and your eyes on the bell, hinge sideways and reach the free hand towards the floor.","Stand back up under control."],"cues":["The overhead arm stays vertical throughout","Go only as low as you can without the shoulder shifting","\ud83d\udca1 Mobility and strength at once \u2014 start very light"],"steps_nl":["Druk een kettlebell boven je hoofd en draai je voeten weg van die kant","Houd je arm gestrekt en je ogen op de kettlebell, scharnier zijwaarts en reik met je vrije hand naar de vloer","Kom gecontroleerd weer omhoog"],"cues_nl":["De arm boven je hoofd blijft de hele tijd verticaal","Ga alleen zo laag als lukt zonder dat je schouder verschuift","💡 Mobiliteit en kracht tegelijk — begin heel licht"]}', '{"images":["/exercise-media/kettlebell-windmill/0.jpg","/exercise-media/kettlebell-windmill/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","weight"],"load_type":"dumbbell_single"}', '{"substitutions":["modified-plank","plank"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_core_plank_pull', 'plank-pull-through', 'Plank Pull-Through', 'Plank pull-through', 'strength', '["core", "obliques"]', '["shoulders", "back"]', '["strength","core","anti_rotation","dumbbell","floor","low_impact","loads_shoulder","loads_lower_back"]', '["dumbbell"]', NULL, '{"steps":["Start in a high plank with a dumbbell on the floor just outside one hand","Reach under your body with the opposite hand and drag the dumbbell across","Put that hand back on the floor and repeat the other way"],"cues":["Widen the feet for stability","Hips stay dead level — no rocking","💡 Anti-rotation with a load, without needing a cable"],"steps_nl":["Start in een hoge plank met een dumbbell op de vloer, net naast één hand","Reik met je andere hand onder je lichaam door en sleep de dumbbell naar de andere kant","Zet die hand terug op de vloer en herhaal de andere kant op"],"cues_nl":["Zet je voeten breder voor meer stabiliteit","Je heupen blijven volledig recht — niet wiebelen","💡 Anti-rotatie met gewicht, zonder dat je een kabel nodig hebt"]}', NULL, '{"supports":["reps","sets","weight"],"load_type":"dumbbell_pair"}', '{"substitutions":["modified-plank","side-plank"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_calf_pogo', 'pogo-hops', 'Pogo Hops', 'Pogosprongen', 'cardio', '["calves"]', '["conditioning"]', '["cardio", "plyometric", "legs", "calf", "bodyweight", "high_impact", "no_floor", "loads_ankle", "loads_knee"]', '["none"]', NULL, '{"steps":["Stand tall, knees almost straight.","Hop on the spot using only the ankles, staying off the heels.","Keep the contacts short and springy."],"cues":["Stiff ankles, quiet landings","Knees barely bend \u2014 this is an ankle drill","\ud83d\udca1 Builds the tendon stiffness that makes running economical"],"steps_nl":["Sta rechtop, knieën bijna gestrekt.","Spring op de plaats met alleen je enkels en blijf van je hielen af.","Houd het grondcontact kort en veerkrachtig."],"cues_nl":["Stevige enkels, stille landingen","Je knieën buigen nauwelijks — dit is een enkeloefening","💡 Bouwt de peesstijfheid op die je hardlopen zuiniger maakt"]}', NULL, '{"supports": ["reps", "sets", "time"]}', '{"substitutions":["heel-dig-march","skater-hop"]}', 1, 1789400000000, 1794873600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_core_reverse_crunch', 'reverse-crunch', 'Reverse Crunch', 'Reverse crunch', 'strength', '["abs", "core"]', '["hip_flexors"]', '["strength","core","flexion","bodyweight","floor","low_impact","crunch","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie on your back, hands by your sides, knees bent over your hips.","Curl your pelvis off the floor, bringing the knees towards your chest.","Lower slowly without letting your feet touch down."],"cues":["The movement is the pelvis lifting, not the legs swinging","Lower back presses into the floor","\ud83d\udca1 Targets the lower abs the plank family misses"],"steps_nl":["Ga op je rug liggen met je handen langs je lichaam en je knieën gebogen boven je heupen","Rol je bekken van de vloer en breng je knieën richting je borst","Zak langzaam terug zonder je voeten de vloer te laten raken"],"cues_nl":["De beweging is je bekken dat omhoogkomt, niet je benen die zwaaien","Je onderrug drukt in de vloer","💡 Traint je onderste buikspieren, die de plank-varianten overslaan"]}', '{"images":["/exercise-media/reverse-crunch/0.jpg","/exercise-media/reverse-crunch/1.jpg"],"source":"free-exercise-db"}', '{"supports": ["reps", "sets"]}', '{"substitutions":["bent-knee-sit-up","bicycle-crunch"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_calf_seated', 'seated-calf-raise', 'Seated Calf Raise (Soleus)', 'Kuitheffen zittend (soleus)', 'strength', '["calves"]', '[]', '["strength", "legs", "calf", "soleus", "bench", "no_floor", "low_impact", "loads_ankle"]', '["bench"]', NULL, '{"steps":["Sit with your knees bent at 90°, balls of the feet on a step or block.","Rest a weight on your thighs if you have one.","Rise onto the toes, pause, lower into a stretch."],"cues":["Bent knee targets the soleus — the calf muscle that matters most to running","Slow lowering is the point","💡 The bent knee shifts the work to the deeper calf muscle (soleus)"],"steps_nl":["Ga zitten met je knieën in een hoek van 90° en je voorvoeten op een opstapje of blok","Leg een gewicht op je bovenbenen als je dat hebt","Kom omhoog op je tenen, pauzeer en zak tot je rek voelt"],"cues_nl":["Met gebogen knie train je de soleus — de kuitspier die bij hardlopen het zwaarst telt","Het gaat om het langzame zakken","💡 Door de gebogen knie verschuift het werk naar de diepe kuitspier (soleus)"]}', NULL, '{"supports":["weight","reps","sets","tempo"],"load_type":"bodyweight_plus"}', '{"substitutions":["bent-knee-calf-raise","calf-raise"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_core_side_plank_dip', 'side-plank-hip-dip', 'Side Plank Hip Dip', 'Side plank met heupdip', 'strength', '["obliques", "core"]', '["glutes", "shoulders"]', '["strength","core","anti_lateral_flexion","bodyweight","floor","low_impact","loads_shoulder"]', '["none"]', NULL, '{"steps":["Set up in a side plank on your forearm, body in a straight line.","Lower your hip towards the floor without touching.","Drive back up until your body is straight again.","Complete the reps, then change sides."],"cues":["Stack the shoulders and hips \u2014 do not roll forward","Small controlled range beats a big sloppy one","\ud83d\udca1 Progresses the static side plank once 45 seconds feels easy"],"steps_nl":["Neem een side plank op je onderarm aan, met je lichaam in een rechte lijn","Laat je heup richting de vloer zakken zonder hem te raken","Duw terug omhoog tot je lichaam weer recht is","Maak je herhalingen af en wissel dan van kant"],"cues_nl":["Houd schouders en heupen recht boven elkaar — rol niet naar voren","Klein en gecontroleerd is beter dan groot en slordig","💡 De vervolgstap op de statische side plank zodra 45 seconden makkelijk voelt"]}', NULL, '{"supports": ["reps", "sets"]}', '{"substitutions":["modified-plank","side-plank"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_calf_soleus_wallsit', 'soleus-wall-sit', 'Soleus Wall Sit', 'Soleus muurzit', 'strength', '["calves"]', '["quads"]', '["strength","legs","calf","soleus","isometric","bodyweight","no_floor","low_impact","loads_knee","loads_ankle"]', '["none"]', NULL, '{"steps":["Sit against a wall with knees at 90\u00b0.","Lift both heels and hold them up.","Keep the heels raised for the full hold."],"cues":["Heels stay up the whole time \u2014 that is the exercise","Quads will burn too; that is fine","\ud83d\udca1 Builds the endurance that fails late in a long run"],"steps_nl":["Ga tegen een muur zitten met je knieën in een hoek van 90°","Til beide hielen op en houd ze omhoog","Houd je hielen de hele houdtijd van de vloer"],"cues_nl":["Je hielen blijven de hele tijd omhoog — dat is de oefening","Je bovenbenen gaan ook branden; dat is prima","💡 Bouwt het uithoudingsvermogen op dat laat in een lange duurloop tekortschiet"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["wall-sit","bent-knee-calf-raise"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_core_stir_pot', 'stability-ball-stir-the-pot', 'Stability Ball Stir the Pot', 'Stir the pot op fitnessbal', 'strength', '["core", "abs"]', '["shoulders"]', '["strength","core","anti_extension","stability_ball","floor","low_impact","loads_shoulder"]', '["stability_ball"]', NULL, '{"steps":["Place your forearms on the ball and hold a plank position","Keeping your body rigid, draw slow circles with your forearms","Reverse direction halfway through"],"cues":["The hips must not move at all","Small circles first, wider as you get stronger","💡 One of the hardest anti-extension drills once the circles widen"],"steps_nl":["Zet je onderarmen op de bal en neem een plankpositie aan","Houd je lichaam stijf en maak langzame cirkels met je onderarmen","Wissel halverwege van richting"],"cues_nl":["Je heupen mogen helemaal niet bewegen","Eerst kleine cirkels, groter naarmate je sterker wordt","💡 Een van de zwaarste anti-extensie-oefeningen zodra de cirkels groter worden"]}', NULL, '{"supports": ["reps", "sets", "time"]}', '{"substitutions":["stability-ball-dead-bug","modified-plank"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_core_suitcase_carry', 'suitcase-carry', 'Suitcase Carry', 'Suitcase carry', 'strength', '["obliques", "core"]', '["forearms", "traps"]', '["strength","core","carry","anti_lateral_flexion","dumbbell","no_floor","low_impact","unilateral","loads_shoulder","loads_lower_back"]', '["dumbbell"]', NULL, '{"steps":["Hold one heavy dumbbell at your side.","Stand tall \u2014 shoulders level, ribs down.","Walk in a straight line for the prescribed time.","Change sides."],"cues":["Do not lean away from the weight","Shoulders stay square the whole walk","\ud83d\udca1 If you are leaning, the weight is too heavy"],"steps_nl":["Houd één zware dumbbell langs je zij","Sta rechtop — schouders op gelijke hoogte, ribben omlaag","Loop de opgegeven tijd in een rechte lijn","Wissel van kant"],"cues_nl":["Leun niet weg van het gewicht","Je schouders blijven de hele wandeling recht","💡 Als je scheef hangt, is het gewicht te zwaar"]}', NULL, '{"supports": ["weight", "time", "sets"], "load_type": "dumbbell_single", "base_duration_sec": 40}', '{"substitutions":["dumbbell-suitcase-carry","modified-plank"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_calf_tib_raise', 'tibialis-raise', 'Tibialis Raise', 'Tibialis heffen', 'strength', '["tibialis", "shins"]', '[]', '["strength", "legs", "shin", "bodyweight", "no_floor", "low_impact", "quiet", "rehab", "loads_ankle"]', '["none"]', NULL, '{"steps":["Stand with your back against a wall, feet a step forward.","Keeping the heels down, pull your toes up towards your shins as far as possible.","Lower slowly."],"cues":["Slow on the way down","Expect it to burn quickly — that is normal","💡 Trains the muscle on the front of your shin, which lifts your toes with every step"],"steps_nl":["Sta met je rug tegen een muur, voeten een stap naar voren","Houd je hielen op de vloer en trek je tenen zo ver mogelijk omhoog richting je schenen","Laat langzaam zakken"],"cues_nl":["Langzaam op de weg omlaag","Reken erop dat het snel gaat branden — dat is normaal","💡 Traint de spier aan de voorkant van je scheen, die bij elke stap je tenen optilt"]}', NULL, '{"supports": ["reps", "sets"]}', '{"substitutions":["heel-walk","bent-knee-calf-raise"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_calf_toe_walk', 'toe-walk', 'Toe Walk', 'Lopen op de tenen', 'strength', '["calves"]', '["tibialis"]', '["strength", "legs", "calf", "bodyweight", "no_floor", "low_impact", "quiet", "loads_ankle"]', '["none"]', NULL, '{"steps":["Rise onto the balls of your feet.","Walk forward staying as high as you can.","Keep going for the prescribed time."],"cues":["Stay tall \u2014 do not shuffle","Turn around rather than lowering the heels","\ud83d\udca1 Easy calf volume you can do in a hallway"],"steps_nl":["Kom omhoog op je voorvoeten","Loop vooruit en blijf zo hoog mogelijk","Ga door voor de opgegeven tijd"],"cues_nl":["Blijf lang — niet sloffen","Draai liever om dan dat je je hielen laat zakken","💡 Makkelijke extra kuittraining die je in de gang kunt doen"]}', NULL, '{"supports": ["time", "sets"], "base_duration_sec": 40}', '{"substitutions":["heel-walk","bent-knee-calf-raise","calf-raise"]}', 1, 1789400000000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_situp_anchored', 'anchored-sit-up', 'Anchored Sit-Up', 'Sit-up met voeten vast', 'strength', '["rectus_abdominis","hip_flexors"]', '["obliques"]', '["bodyweight","floor","low_impact","core","military","dcp","measurable","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie on your back with your knees bent about 90 degrees","Hook your feet under something solid, or have a partner hold them","Curl up until your torso is vertical","Lower under control until your shoulder blades touch the floor"],"cues":["Anchoring lets the hip flexors help — most DCP protocols allow it","Check which version your test uses before relying on it"],"why":"The anchored DCP variant. Usually allows more repetitions than feet-free.","steps_nl":["Ga op je rug liggen met je knieën ongeveer 90 graden gebogen","Haak je voeten onder iets stevigs, of laat een partner ze vasthouden","Rol op tot je bovenlichaam rechtop is","Zak gecontroleerd terug tot je schouderbladen de vloer raken"],"cues_nl":["Met je voeten vast helpen je heupbuigers mee — de meeste DCP-protocollen staan het toe","Controleer welke versie jouw test gebruikt voordat je erop vertrouwt"]}', '{"images":["/exercise-media/anchored-sit-up/0.jpg","/exercise-media/anchored-sit-up/1.jpg"],"source":"free-exercise-db"}', '{"supports":["reps","sets","time"],"base_duration_sec":120}', '{"substitutions": ["sit-up", "bent-knee-sit-up", "weighted-sit-up"]}', 1, 1790812800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_situp_bent_knee', 'bent-knee-sit-up', 'Bent-Knee Sit-Up', 'Sit-up met gebogen knieën', 'strength', '["rectus_abdominis"]', '["hip_flexors","obliques"]', '["bodyweight","floor","low_impact","core","military","dcp","measurable","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie on your back with your heels drawn close to your seat","Reach your arms forward past your knees","Curl up until your forearms pass your knees","Lower under control"],"cues":["The shorter lever makes this easier — use it to build volume","Reps here should be clean, not grinding"],"why":"Volume rung. When your max sit-up count is low, this builds the repetitions that move it.","steps_nl":["Ga op je rug liggen met je hielen dicht bij je billen","Reik met je armen naar voren, voorbij je knieën","Rol omhoog tot je onderarmen voorbij je knieën komen","Zak gecontroleerd terug"],"cues_nl":["Door de kortere hefboom is dit makkelijker — gebruik het om volume op te bouwen","Maak hier nette herhalingen, zonder te worstelen"]}', NULL, '{"supports":["reps","sets"]}', '{"substitutions": ["sit-up", "reverse-crunch", "anchored-sit-up"]}', 1, 1790812800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_situp', 'sit-up', 'Sit-Up', 'Sit-up', 'strength', '["rectus_abdominis","hip_flexors"]', '["obliques"]', '["bodyweight","floor","low_impact","core","military","dcp","measurable","loads_lower_back"]', '["none"]', NULL, '{"steps":["Lie on your back with your knees bent about 90 degrees and your feet flat","Cross your hands on your chest or place your fingertips at your temples","Curl up until your torso is vertical, chest toward your knees","Lower under control until your shoulder blades touch the floor","Count that as one repetition and breathe out on the way up"],"cues":["Do not pull on your neck","A steady pace beats a fast start — this is a two-minute test"],"why":"The DCP test movement. Trains trunk flexion through full range, which planks and dead bugs do not.","steps_nl":["Ga op je rug liggen met je knieën ongeveer 90 graden gebogen en je voeten plat","Kruis je handen op je borst of zet je vingertoppen tegen je slapen","Rol omhoog tot je bovenlichaam rechtop is, borst richting je knieën","Zak gecontroleerd terug tot je schouderbladen de vloer raken","Dat telt als één herhaling; adem uit terwijl je omhoogkomt"],"cues_nl":["Trek niet aan je nek","Een gelijkmatig tempo wint het van een snelle start — dit is een test van twee minuten"]}', '{"images":["/exercise-media/sit-up/0.jpg","/exercise-media/sit-up/1.jpg"],"source":"free-exercise-db","audio":{"nl":"/exercise-audio/sit-up/nl.mp3","en":"/exercise-audio/sit-up/en.mp3"}}', '{"supports":["reps","sets","time"],"base_duration_sec":120}', '{"substitutions": ["bent-knee-sit-up", "anchored-sit-up", "bicycle-crunch", "weighted-sit-up"]}', 1, 1790812800000, 1795305600000);
INSERT OR IGNORE INTO exercises (id, slug, name, name_nl, category, primary_muscles_json, secondary_muscles_json, tags_json, equipment_required_json, equipment_advised_json, instructions_json, media_json, metrics_json, alternatives_json, is_active, created_at_ms, updated_at_ms) VALUES
  ('ex_situp_weighted', 'weighted-sit-up', 'Weighted Sit-Up', 'Sit-up met gewicht', 'strength', '["rectus_abdominis","hip_flexors"]', '["obliques"]', '["core","military","dcp","weighted","loads_lower_back"]', '["dumbbell"]', NULL, '{"steps":["Lie on your back with your knees bent and your feet flat","Hold a dumbbell against your chest with both hands","Curl up until your torso is vertical, keeping the weight on your chest","Lower under control"],"cues":["Start lighter than you expect — the leverage is unforgiving","Stop the set the moment your lower back starts leading"],"why":"Overshoot rung. Training the pattern loaded makes the unloaded test version feel easy.","steps_nl":["Ga op je rug liggen met je knieën gebogen en je voeten plat","Houd met beide handen een dumbbell tegen je borst","Rol omhoog tot je bovenlichaam rechtop is en houd het gewicht op je borst","Zak gecontroleerd terug"],"cues_nl":["Begin lichter dan je denkt — de hefboom is genadeloos","Stop de set zodra je onderrug de beweging gaat leiden"]}', NULL, '{"supports":["weight","reps","sets"],"load_type":"dumbbell_single"}', '{"substitutions":["sit-up","anchored-sit-up"]}', 1, 1790812800000, 1795305600000);

